#!/usr/bin/env python3
"""Manage the helpdesk.System Azure deployment: deploy | down | destroy.

Generated by CruftFree -- do not edit manually. See DEPLOYMENT.md for details.

This is the project's front door -- its ONE operator-facing deployment CLI. The
lifecycle vocabulary is shared with every other CruftFree-generated deployment
CLI, whichever platform emitted it, so the same word means the same thing on
every profile; ``--help`` lists this platform's own commands apart from it, and
names the one lifecycle verb this profile does not implement.

Run it through the generated shell entrypoints, which activate the project
virtual environment first::

    scripts/deploy.sh  [command] [options]     # bash / zsh
    .\\scripts\\deploy.ps1 [command] [options]   # PowerShell

This module is the ONE implementation of the deployment. Both entrypoints are
thin wrappers around it, so a bash operator and a PowerShell operator run
byte-identical logic: the same preflight, the same retry rules, the same
content-hash algorithm, the same skip decisions. It uses only the Python
standard library and drives the Azure CLI (``az``) and, in container mode,
``docker`` as subprocesses -- no SDK install step stands between an operator
and a deployment.
"""

