#: Bring the deployment to its declared state. Idempotent.
VERB_DEPLOY = "deploy"

#: Stop the running workload. All data survives.
VERB_DOWN = "down"

#: Remove the workload and the data stores this project provisioned. The infrastructure hosting them stays.
VERB_RESET = "reset"

#: Delete the provisioned infrastructure itself.
VERB_DESTROY = "destroy"

#: Print a block's live catalog, read with the engine's own client, as one verified document. Changes nothing.
VERB_SCHEMA_READ = "schema-read"

#: Apply one SQL file the plan wrote to a block, in one transaction with the engine's own client; stops before any change when the catalog changed since the plan, and a failed statement leaves the schema as it was.
VERB_SCHEMA_APPLY = "schema-apply"

#: With 'deploy': print, for every block, the plan a deploy would apply to its live catalog. Changes nothing.
FLAG_PLAN = "--plan"

