def _normalize_argv(argv: list[str], switch_aliases: dict[str, str]) -> list[str]:
    """Translate PowerShell-style switches into this script's own flags.

    Only whole arguments are translated, and only when they match a declared
    alias case-insensitively: a value that merely looks like a switch (a path,
    a negative number, an argument to another flag) passes through untouched.

    Args:
        argv: The arguments as the shell handed them over.
        switch_aliases: PowerShell switch spelling -> this script's own flag.

    Returns:
        The same arguments with every recognized PowerShell switch replaced by
        this script's own flag spelling.
    """
    return [switch_aliases.get(token.lower(), token) for token in argv]


def _help_block(heading: str, entries: dict[str, str]) -> list[str]:
    """Render one aligned ``name  description`` block for the --help epilog.

    Args:
        heading: The block's heading line.
        entries: Name -> description, in the order they should be listed.

    Returns:
        The block's lines, or an empty list when there is nothing to list.
    """
    if not entries:
        return []
    width = max(len(name) for name in entries)
    return ["", heading] + [
        f"  {name.ljust(width)}  {text}" for name, text in entries.items()
    ]


def _schema_usage(verb: str, operands: tuple[str, ...]) -> str:
    """Spell a schema verb's command line: the verb, ``<block>``, then its operands.

    Args:
        verb: The schema verb.
        operands: The operands it takes after its block, by attribute name.

    Returns:
        The usage, e.g. ``schema-apply <block> <sql-file>``.
    """
    names = ("block", *operands)
    return " ".join([verb, *(f"<{name.replace('_', '-')}>" for name in names)])


def _lifecycle_epilog(
    verb_help: dict[str, str],
    unrealized_verbs: dict[str, str],
    schema_help: dict[str, str],
    schema_blocks: tuple[str, ...],
    extra_commands: dict[str, str] | None = None,
    *,
    schema_operands: dict[str, tuple[str, ...]],
    deploy_verb: str,
    deploy_step_help: dict[str, str],
    client_step_help: dict[str, str],
    unrealized_client_members: dict[str, str],
) -> str:
    """Return the --help epilog: what this profile does, and what it does not.

    The unrealized half is the part that matters. The vocabulary is shared
    across every CruftFree target, so an operator arriving from another profile
    will type verbs this one does not implement; telling them WHY, and what to
    use instead, is the difference between a usable CLI and a dead end.

    Args:
        verb_help: One help line per realized lifecycle verb.
        unrealized_verbs: Vocabulary verb -> why this profile lacks it.
        schema_help: One help line per schema verb this profile implements.
        schema_blocks: The block keys a schema verb accepts.
        extra_commands: Platform-specific commands this CLI also accepts, which
            are NOT lifecycle verbs -- a read-only check, a partial rollout, an
            escape hatch. Listed separately so the shared vocabulary stays
            recognizable next to them.
        schema_operands: The operands each schema verb of *schema_help* takes
            after its block, by attribute name.
        deploy_verb: The verb the schema steps belong to.
        deploy_step_help: One help line per schema step every *deploy_verb*
            runs. A step is no command and no flag: it is listed under the
            deploy verb so the operator knows what a deploy does.
        client_step_help: One help line per client step *deploy_verb* runs,
            listed after the schema steps, which is the order a deploy runs them.
        unrealized_client_members: Client member -> why this profile lacks it,
            listed with the unrealized verbs.

    Returns:
        The epilog text.
    """
    lines = _help_block("lifecycle commands:", dict(verb_help))[1:]
    lines += _help_block(
        f"steps of '{deploy_verb}':", {**deploy_step_help, **client_step_help}
    )
    lines += _help_block(
        "schema commands:",
        {
            _schema_usage(verb, schema_operands[verb]): text
            for verb, text in schema_help.items()
        },
    )
    if schema_help:
        lines += ["", "blocks:"] + [f"  {key}" for key in schema_blocks]
    lines += _help_block("platform-specific commands:", extra_commands or {})
    lines += _help_block(
        "not implemented on this deployment profile:",
        {**unrealized_verbs, **unrealized_client_members},
    )
    return "\n".join(lines)


def _verbs_phrase(verbs: tuple[str, ...]) -> str:
    """Name *verbs* for a message: ``'deploy'``, ``'deploy' or 'down'``."""
    quoted = [f"'{verb}'" for verb in verbs]
    if len(quoted) == 1:
        return quoted[0]
    return f"{', '.join(quoted[:-1])} or {quoted[-1]}"


def _flag_help(verbs: tuple[str, ...], help_line: str) -> str:
    """The --help text of a flag: the verbs it is accepted with, then *help_line*.

    A ``%`` in the profile's line reaches --help verbatim, never as a format error.
    """
    return f"(with {_verbs_phrase(verbs)}) {help_line}".replace("%", "%%")


class _LifecycleArgumentParser(argparse.ArgumentParser):
    """The lifecycle parser: argparse, plus the operands and flags each command takes.

    One optional command positional cannot say "a schema verb takes its block
    and its own operands, a lifecycle verb takes nothing", so every operand is
    collected into ``args`` and checked here once argparse is done. A schema verb
    gets its block as ``block``, one of the keys this deployment's blocks have,
    and each further operand it declares (``schema-apply``'s ``sql_file``) under
    that operand's name, exactly as many as it declares; every other command
    gets ``block = None`` and ``None`` for every schema operand and, unless the
    platform asked for operands of its own, a stray operand is rejected exactly
    as argparse would reject it.

    A schema flag (:meth:`add_deploy_flag`) is accepted with the deploy verb
    alone, a client flag (:meth:`add_value_flag`) with the verbs it declares:
    given with any other command it is rejected by name, never quietly ignored.
    """

    def __init__(
        self,
        program_name: str,
        description: str,
        epilog: str,
        schema_verbs: tuple[str, ...],
        schema_blocks: tuple[str, ...],
        schema_operands: dict[str, tuple[str, ...]],
        takes_platform_operands: bool,
        deploy_verb: str,
    ) -> None:
        super().__init__(
            prog=program_name,
            description=description,
            epilog=epilog,
            formatter_class=argparse.RawDescriptionHelpFormatter,
        )
        self._schema_verbs = schema_verbs
        self._schema_blocks = schema_blocks
        self._schema_operands = schema_operands
        self._takes_platform_operands = takes_platform_operands
        self._deploy_verb = deploy_verb
        self._flag_verbs: dict[str, tuple[tuple[str, ...], str]] = {}

    def add_deploy_flag(self, flag: str, help_line: str) -> None:
        """Add *flag* as a switch the deploy verb alone accepts.

        Args:
            flag: The flag's spelling, e.g. ``--plan``.
            help_line: The profile's help line for it, shown by --help after the
                verb it is accepted with.
        """
        verbs = (self._deploy_verb,)
        action = self.add_argument(
            flag, action="store_true", help=_flag_help(verbs, help_line)
        )
        self._flag_verbs[flag] = (verbs, action.dest)

    def add_value_flag(
        self,
        flag: str,
        help_line: str,
        values: tuple[str, ...],
        verbs: tuple[str, ...],
    ) -> None:
        """Add *flag* as an option taking one value, accepted with *verbs* alone.

        Args:
            flag: The flag's spelling, e.g. ``--scope``.
            help_line: The profile's help line for it, shown by --help after the
                verbs it is accepted with.
            values: The values it accepts, any other being rejected by name;
                empty when it takes any value.
            verbs: The commands it is accepted with; never empty.
        """
        if not verbs:
            raise ValueError(
                f"{flag}: a flag needs at least one verb to be accepted with"
            )
        action = self.add_argument(
            flag, choices=values or None, help=_flag_help(verbs, help_line)
        )
        self._flag_verbs[flag] = (verbs, action.dest)

    def _refuse_misplaced_flags(self, parsed: argparse.Namespace) -> None:
        """Reject, by name, every given flag the chosen command does not accept."""
        refused: dict[tuple[str, ...], list[str]] = {}
        for flag, (verbs, dest) in self._flag_verbs.items():
            if getattr(parsed, dest) in (None, False) or parsed.command in verbs:
                continue
            refused.setdefault(verbs, []).append(flag)
        if refused:
            reasons = "; ".join(
                f"{' '.join(flags)}: accepted with {_verbs_phrase(verbs)} alone"
                for verbs, flags in refused.items()
            )
            self.error(f"{reasons}, not with '{parsed.command}'")

    def parse_known_args(  # type: ignore[override]
        self,
        args: list[str] | None = None,
        namespace: argparse.Namespace | None = None,
    ) -> tuple[argparse.Namespace, list[str]]:
        """Parse *args*, then check the operands and flags the chosen command takes."""
        parsed, extras = super().parse_known_args(args, namespace)
        self._refuse_misplaced_flags(parsed)
        operands = list(getattr(parsed, "args", None) or [])
        for names in self._schema_operands.values():
            for name in names:
                setattr(parsed, name, None)
        if parsed.command in self._schema_verbs:
            names = self._schema_operands[parsed.command]
            if (
                len(operands) != 1 + len(names)
                or operands[0] not in self._schema_blocks
            ):
                self.error(
                    f"'{parsed.command}' takes exactly "
                    f"'{_schema_usage(parsed.command, names)}', the block one of: "
                    f"{', '.join(self._schema_blocks)} (got: {' '.join(operands) or 'none'})"
                )
            parsed.block = operands[0]
            for name, value in zip(names, operands[1:], strict=True):
                setattr(parsed, name, value)
            return parsed, extras
        if operands and not self._takes_platform_operands:
            self.error(f"unrecognized arguments: {' '.join(operands)}")
        parsed.block = None
        return parsed, extras


def _build_lifecycle_parser(
    program_name: str,
    default_verb: str,
    realized_verbs: tuple[str, ...],
    verb_help: dict[str, str],
    unrealized_verbs: dict[str, str],
    schema_verbs: tuple[str, ...],
    schema_help: dict[str, str],
    schema_blocks: tuple[str, ...],
    description: str,
    extra_commands: dict[str, str] | None = None,
    positional_help: str | None = None,
    extra_epilog: str | None = None,
    *,
    schema_operands: dict[str, tuple[str, ...]],
    deploy_verb: str,
    deploy_flags: tuple[str, ...],
    deploy_flag_help: dict[str, str],
    deploy_step_help: dict[str, str],
    client_flags: dict[str, tuple[str, ...]],
    client_flag_verbs: dict[str, tuple[str, ...]],
    client_flag_help: dict[str, str],
    client_step_help: dict[str, str],
    unrealized_client_members: dict[str, str],
) -> argparse.ArgumentParser:
    """Build the argument parser carrying the shared lifecycle surface.

    The caller adds whatever FLAGS are specific to its own platform; the
    command positional, the schema verbs' operands, the schema flags of the
    deploy verb, ``--force`` and the epilog are the same everywhere. A schema
    step of the deploy verb adds no command and no flag: the epilog lists it.

    Args:
        program_name: The ``prog`` argparse reports in usage.
        default_verb: The verb used when the operator names none. Always the
            safe end of the blast-radius order.
        realized_verbs: The verbs this profile implements, in order.
        verb_help: One help line per realized verb.
        unrealized_verbs: Vocabulary verb -> why this profile lacks it.
        schema_verbs: The schema verbs this profile implements; empty when the
            deployment has no RDBMS block.
        schema_help: One help line per schema verb.
        schema_blocks: The block keys a schema verb accepts, and only these.
        description: One-line description of this deployment, shown by --help.
        extra_commands: Platform-specific commands (name -> help line) accepted
            alongside the lifecycle verbs. They widen the choice set, so a
            platform command is rejected by name on a profile that has none --
            never silently accepted and ignored.
        positional_help: When a platform command takes positional arguments,
            the help line for them. Omitted entirely when none does, so a stray
            argument is an error rather than something quietly collected.
        extra_epilog: Further --help text for this platform (environment
            overrides and the like), appended after the command listing.
        schema_operands: The operands each schema verb takes after its block,
            by the attribute the parsed arguments carry each under.
        deploy_verb: The verb the schema flags belong to.
        deploy_flags: The schema flags of *deploy_verb* this profile implements
            (``--plan``, ``--approved``); empty when the deployment has no RDBMS
            block, and then none is accepted. Each is read from the command line
            alone and has no environment twin.
        deploy_flag_help: One help line per schema flag.
        deploy_step_help: One help line per schema step of *deploy_verb*; empty
            when the deployment has no RDBMS block.
        client_flags: The client flags this profile implements, each taking one
            value, with the values it accepts (empty: any value); empty when the
            deployment hosts no client, and then none is accepted.
        client_flag_verbs: The verbs each client flag is accepted with; every
            other command refuses it by name.
        client_flag_help: One help line per client flag.
        client_step_help: One help line per client step of *deploy_verb*; empty
            when the deployment hosts no client.
        unrealized_client_members: Client member -> why this profile lacks it.

    Returns:
        A parser accepting this profile's realized verbs, its schema verbs with
        one block and their own operands each, its schema flags with the deploy
        verb alone and its client flags with their own verbs, plus any extras.
    """
    epilog = _lifecycle_epilog(
        verb_help,
        unrealized_verbs,
        schema_help,
        schema_blocks,
        extra_commands,
        schema_operands=schema_operands,
        deploy_verb=deploy_verb,
        deploy_step_help=deploy_step_help,
        client_step_help=client_step_help,
        unrealized_client_members=unrealized_client_members,
    )
    if extra_epilog is not None:
        epilog = f"{epilog}\n\n{extra_epilog}"
    parser = _LifecycleArgumentParser(
        program_name,
        description,
        epilog,
        schema_verbs,
        schema_blocks,
        schema_operands,
        positional_help is not None,
        deploy_verb,
    )
    parser.add_argument(
        "command",
        nargs="?",
        default=default_verb,
        choices=(*realized_verbs, *schema_verbs, *(extra_commands or {})),
        help=f"what to do (default: {default_verb})",
    )
    if positional_help is not None or schema_verbs:
        parser.add_argument(
            "args",
            nargs="*",
            help=positional_help
            or "the block a schema command acts on, then that command's operands",
        )
    parser.add_argument(
        "--force",
        action="store_true",
        help="skip the confirmation prompt for a destructive command.",
    )
    for flag in deploy_flags:
        parser.add_deploy_flag(flag, deploy_flag_help[flag])
    for flag, values in client_flags.items():
        parser.add_value_flag(
            flag, client_flag_help[flag], values, client_flag_verbs[flag]
        )
    return parser


def force_requested(parsed_force: bool) -> bool:
    """True when the operator has waived the confirmation prompt.

    Args:
        parsed_force: Whether ``--force`` was given on the command line.

    Returns:
        True when the prompt is waived, by the flag or by the environment.
    """
    return (
        parsed_force
        or os.environ.get(FORCE_ENV_VAR, "").strip().lower() in _TRUTHY_FORCE_VALUES
    )


def confirm_destructive(verb: str, what_is_lost: str, token: str, forced: bool) -> bool:
    """Gate a destructive command behind an explicit, typed confirmation.

    Fails CLOSED. When the prompt cannot be shown -- no terminal on stdin, as in
    a pipeline or a remote run-command channel -- this refuses rather than
    assuming consent, and names the flag that grants it deliberately. A
    destructive default that proceeds because nobody could answer is the worst
    possible reading of silence.

    Args:
        verb: The lifecycle verb being confirmed, for the message.
        what_is_lost: Plain description of what this removes, listed before the
            prompt so the operator confirms against facts rather than a verb.
        token: The exact string the operator must type. Deliberately the name of
            the thing being destroyed, so muscle memory cannot answer for them.
        forced: Whether --force (or the FORCE environment variable) was given.

    Returns:
        True when the command may proceed, False when the operator declined.
    """
    if forced:
        print(f"==> '{verb}' confirmed by --force. {what_is_lost}", flush=True)
        return True
    print("", flush=True)
    print(f"WARNING: '{verb}' is irreversible. {what_is_lost}", flush=True)
    if not sys.stdin.isatty():
        print(
            f"ERROR: '{verb}' needs confirmation, but there is no terminal to "
            f"ask at (stdin is not a TTY). Nothing has been changed. Re-run "
            f"with --force (PowerShell: -Force), or set "
            f"{FORCE_ENV_VAR}=true, to state the intent explicitly.",
            file=sys.stderr,
        )
        return False
    answer = input(f"Type '{token}' to confirm: ").strip()
    if answer != token:
        print("Aborted. Nothing has been changed.", flush=True)
        return False
    return True


# ---------------------------------------------------------------------------
# This profile's bindings
# ---------------------------------------------------------------------------
# The runtime above takes every profile-specific value as a parameter, so it can
# be unit tested by calling it. These wrappers bind this deployment's constants
# to it, keeping the names a platform's own script calls exactly as they were.


def normalize_argv(argv: list[str]) -> list[str]:
    """Translate this profile's PowerShell-style switches into its own flags."""
    return _normalize_argv(argv, POWERSHELL_SWITCH_ALIASES)


def lifecycle_epilog(extra_commands: dict[str, str] | None = None) -> str:
    """Return the --help epilog for this profile's realized surface."""
    return _lifecycle_epilog(
        VERB_HELP,
        UNREALIZED_VERBS,
        SCHEMA_VERB_HELP,
        SCHEMA_BLOCKS,
        extra_commands,
        schema_operands=SCHEMA_VERB_OPERANDS,
        deploy_verb=VERB_DEPLOY,
        deploy_step_help=SCHEMA_DEPLOY_STEP_HELP,
        client_step_help=CLIENT_DEPLOY_STEP_HELP,
        unrealized_client_members=UNREALIZED_CLIENT_MEMBERS,
    )


def build_lifecycle_parser(
    description: str,
    extra_commands: dict[str, str] | None = None,
    positional_help: str | None = None,
    extra_epilog: str | None = None,
) -> argparse.ArgumentParser:
    """Build this profile's parser over the shared lifecycle surface."""
    return _build_lifecycle_parser(
        "deploy.py",
        VERB_DEPLOY,
        REALIZED_VERBS,
        VERB_HELP,
        UNREALIZED_VERBS,
        SCHEMA_VERBS,
        SCHEMA_VERB_HELP,
        SCHEMA_BLOCKS,
        description,
        extra_commands,
        positional_help,
        extra_epilog,
        schema_operands=SCHEMA_VERB_OPERANDS,
        deploy_verb=VERB_DEPLOY,
        deploy_flags=SCHEMA_DEPLOY_FLAGS,
        deploy_flag_help=SCHEMA_DEPLOY_FLAG_HELP,
        deploy_step_help=SCHEMA_DEPLOY_STEP_HELP,
        client_flags=CLIENT_DEPLOY_FLAGS,
        client_flag_verbs=CLIENT_FLAG_VERBS,
        client_flag_help=CLIENT_DEPLOY_FLAG_HELP,
        client_step_help=CLIENT_DEPLOY_STEP_HELP,
        unrealized_client_members=UNREALIZED_CLIENT_MEMBERS,
    )


