class Service(NamedTuple):
    """One generated service and the Azure resources that carry it."""

    display_name: str
    service_dir: str
    image_name: str
    web_app_name: str
    #: True when the service serves HTTP and so runs a web site. A service whose
    #: only App Service compute is its workers has none.
    has_web_site: bool
    #: The App Service worker sites of the service's external-queue blocks.
    workers: tuple[Worker, ...]
    #: The web app's readiness route 'verify' polls after a deploy or code push:
    #: the route the service's own language mounts, so it can never drift from
    #: the route the application itself serves.
    health_check_path: str
    #: How the web-app payload gets its dependencies, as the service's language
    #: declares it: WEB_PACKAGE_MANIFEST_RESOLVED or WEB_PACKAGE_PREBUILT.
    web_package_mode: str
    #: Build commands run (as argument vectors, never a shell) in the service
    #: directory before a PREBUILT payload is staged.
    web_build_steps: tuple[tuple[str, ...], ...]
    #: What the payload ships, relative to the service directory (glob patterns).
    web_payload_paths: tuple[str, ...]
    #: The inputs whose content decides that the deployed payload is stale,
    #: relative to the service directory (glob patterns), in hash order.
    web_hash_inputs: tuple[str, ...]
    #: The dependency manifest a MANIFEST_RESOLVED payload resolves through the
    #: shared dependency layer, relative to the service directory ("" otherwise).
    web_dependency_manifest: str
    has_function_app: bool
    function_app_name: str
    function_package_name: str
    #: How the Function App package is produced, as the target language declares
    #: it: FUNCTION_PACKAGE_REMOTE_BUILD or FUNCTION_PACKAGE_PREBUILT ("" when the
    #: service has no Function App).
    function_package_mode: str
    #: The package source root, relative to the project root.
    function_source_dir: str
    #: Build commands run (as argument vectors, never a shell) in the source root
    #: before a PREBUILT package is zipped.
    function_build_steps: tuple[tuple[str, ...], ...]
    #: The directory zipped as the package, relative to the source root.
    function_package_dir: str
    #: The package's dependency manifest, relative to the source root.
    function_manifest_file: str
    #: The canonical function names the package registers -- the set the
