# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

#: Resource providers the generated infrastructure may use. An unregistered
#: provider fails the deployment deep into the run, so preflight registers any
#: that are missing up front. Listed unconditionally, including namespaces only
#: some applications need (Communication is ACS-only, Cdn front-door-only):
#: registration is idempotent, subscription-wide and free, so a superset costs
#: nothing while a missing entry fails the deploy. ContainerRegistry backs
#: container mode's shared ACR; ContainerInstance backs every
#: Microsoft.Resources/deploymentScripts (secret seeding, in-VNet bootstrap)
#: and the containerGroups subnet delegation; App backs the environments
#: subnet delegation. None of the three is registered by default on a fresh
#: subscription.
REQUIRED_PROVIDERS: tuple[str, ...] = (
    "Microsoft.Web",
    "Microsoft.KeyVault",
    "Microsoft.Storage",
    "Microsoft.DBforPostgreSQL",
    "Microsoft.AppConfiguration",
    "Microsoft.Cache",
    "Microsoft.ServiceBus",
    "Microsoft.EventHub",
    "Microsoft.DocumentDB",
    "Microsoft.Communication",
    "Microsoft.Network",
    "Microsoft.Cdn",
    "Microsoft.ApiManagement",
    "Microsoft.OperationalInsights",
    "Microsoft.Insights",
    "Microsoft.AlertsManagement",
    "Microsoft.ManagedIdentity",
    "Microsoft.ContainerRegistry",
    "Microsoft.ContainerInstance",
    "Microsoft.App",
)

#: Transient Azure control-plane errors that reflect eventual-consistency
#: propagation lag, NOT a real template/quota/parameter fault. A stage that
#: fails with ONLY these is safe to re-run idempotently once propagation
#: catches up (ARM incremental mode skips already-succeeded resources). This is
#: the deployment's systemic defense against Azure's eventually-consistent
#: control plane: rather than point-patching each race as it is discovered, any
#: stage whose failures are all transient is retried with backoff.
#:
#: 'RoleAssignmentUpdateNotPermitted' is intentionally absent -- it means a
#: deterministically-named assignment already exists with a different
#: principalId/scope (an immutable property), which waiting never resolves.
#: A resource provider's own 5xx is not listed here either: its codes are
#: ARM_TRANSIENT_SERVER_CODES, shared with every Azure deploy CLI.
TRANSIENT_DEPLOYMENT_CODES: frozenset[str] = frozenset(
    {
        "AadAuthPrincipalCreationFailed",  # Postgres AAD admin: bootstrap SP not yet visible in Entra
        "PrincipalNotFound",  # RBAC role assignment: principal not yet propagated
        "ReferencedResourceNotProvisioned",  # dependency provisioned but not yet globally visible
        "AnotherOperationInProgress",
        "TooManyRequests",  # control-plane throttling (429)
        "RequestTimeout",
        "RetryableError",
    }
)

#: Message fragments that mark a transient failure whose ARM error code is too
#: generic to match on (e.g. BadRequest for a metric that is not yet in the
#: catalog of a just-created resource).
TRANSIENT_DEPLOYMENT_MESSAGES: tuple[str, ...] = (
    "Couldn't find a metric named",
    "is not found in Azure Active Directory",
    "was not found in the directory",
    "does not exist in the directory",
    "Failed to perform resource identity operation",
)

#: Scoped Graph rule: a leaf failure on a Microsoft.Graph/* resource (the
#: trusted-caller backend-audience app registration / service principal, or a
#: declared identity provider's) with one of these not-found codes is directory
#: replication lag, NOT a template fault -- but ONLY for that resource TYPE. A
#: bare 'NotFound' on any other resource type stays non-transient.
GRAPH_RESOURCE_TYPE_PREFIX = "Microsoft.Graph/"
GRAPH_TRANSIENT_NOTFOUND_CODES: frozenset[str] = frozenset(
    {
        "NotFound",
        "Request_ResourceNotFound",
        "ResourceNotFound",
    }
)

#: Scoped RBAC rule: a role assignment created against a BRAND-NEW target scope
#: can transiently fail with 'RoleDefinitionDoesNotExist' even though the
#: referenced role is a valid built-in. Azure's RBAC control plane has not
#: finished replicating the new scope's role-definition catalog when a burst of
#: concurrent roleAssignment PUTs lands. This is the role-catalog analog of
#: PrincipalNotFound and, exactly like it, self-heals on retry. Scoped to the
#: roleAssignments type: the same code elsewhere stays non-transient.
ROLE_ASSIGNMENT_RESOURCE_TYPE = "Microsoft.Authorization/roleAssignments"
ROLE_ASSIGNMENT_TRANSIENT_CODES: frozenset[str] = frozenset(
    {
        "RoleDefinitionDoesNotExist",
    }
)

#: The deploy principal lacks the Graph permission grant required to create the
#: app registration / service principal. Never self-heals by retry -- always
#: fail loud with the deployer-kind-specific remediation.
GRAPH_AUTHORIZATION_DENIED_CODE = "Authorization_RequestDenied"

#: Error codes that mean the subscription cannot host a resource in this
#: region/SKU at all -- worth naming explicitly, since the remedy (another
#: region, or a quota increase) differs from every other failure class.
OFFER_QUOTA_CODE_PATTERN = re.compile(
    "OfferRestricted|QuotaExceeded|SkuNotAvailable|LocationNotAvailable"
    "|NotAvailableForSubscription"
)

#: Bicep stage retry budget and its backoff schedule (seconds). Propagation
#: typically clears in 1-5 minutes; the last value repeats if attempts outrun
#: the schedule.
BICEP_STAGE_MAX_ATTEMPTS = 6
BICEP_STAGE_BACKOFFS: tuple[int, ...] = (30, 45, 60, 90, 120)

#: Registry-facing operations (docker pull / buildx build / push, and the ACR
#: login they depend on) retry budget. Registry traffic over the public
#: internet fails transiently as a matter of course -- OAuth token endpoints
#: time out, TLS handshakes stall, connections reset mid-upload -- and one such
#: fault must not discard every image already pushed. The retry is deliberately
#: NOT gated on an error signature: docker surfaces transient registry faults
#: only as free text, so the exit code is the only reliable signal. Retrying
#: blind is safe because every wrapped operation is idempotent and
#: content-addressed, so a deterministic failure (broken Dockerfile, bad
#: credentials, real outage) re-fails in seconds and still exits loud.
DOCKER_MAX_ATTEMPTS = 4
DOCKER_BACKOFFS: tuple[int, ...] = (10, 30, 60)

#: Per-attempt push retry budget for a code push (web app or function app).
CODE_PUSH_MAX_ATTEMPTS = 3
CODE_PUSH_RETRY_SECONDS = 20

#: How long to wait for a server-side Kudu build to reach a terminal state
#: before treating the attempt as failed, and how often to poll/heartbeat.
KUDU_TERMINAL_DEADLINE_SECONDS = 20 * 60
KUDU_POLL_SECONDS = 15
KUDU_HEARTBEAT_SECONDS = 60

#: Clock-skew allowance between the deploy host and the Kudu server. An entry
#: stamped up to this far BEFORE the push watermark still counts as this push's.
KUDU_CLOCK_SKEW_SECONDS = 180

#: App-setting the deployed content hash is stamped on, so an unchanged re-run
#: can skip a service entirely.
DEPLOY_HASH_SETTING = "CRUFTFREE_DEPLOY_HASH"
DEPLOY_HASH_STAMP_ATTEMPTS = 3
DEPLOY_HASH_STAMP_RETRY_SECONDS = 5

#: Resource-group tag name the infrastructure content hash is stamped under.
#: Hyphenated like every other Azure tag key in this script; the read/write
#: paths below are written specifically to handle that correctly (see their
#: docstrings).
INFRA_HASH_TAG = "cruftfree-infra-hash"

#: Default concurrency of each code-push leg. Web apps share ONE App Service
#: plan worker, so concurrent Oryx builds contend for that single worker's
#: CPU/memory -- sequencing them buys real safety, hence a default of 1. Each
#: Flex Consumption Function App builds on its OWN remote-build infrastructure,
#: so sequencing those buys no safety, only wall-clock.
DEFAULT_WEB_WAVE_SIZE = 1
DEFAULT_FUNCTION_WAVE_SIZE = 6

#: Default concurrency of the container-mode image-supply wave. Builds share
#: ONE docker daemon and the base-image layer cache, and a push is I/O-bound,
#: so several service builds proceed usefully in parallel; the dominant win is
#: the all-rebuild case after a shared-code change touches every service.
#: DEPLOY_IMAGE_WAVE=1 restores the previous strictly-serial behavior exactly.
DEFAULT_IMAGE_WAVE_SIZE = 4

#: SKU the shared App Service plan is temporarily scaled to during the
#: code-push phase when turbo scale is requested. A script-level constant, not
#: an override: generality demands no per-application tuning of the target SKU.
TURBO_SCALE_SKU = "P2v3"

#: How long to wait for a resource type to drain during teardown before letting
#: the resource-group delete reclaim the stragglers.
DESTROY_DRAIN_DEADLINE_SECONDS = 20 * 60
DESTROY_DRAIN_POLL_SECONDS = 10

#: Polls a --no-wait deployment can report no provisioning state at all before
#: it is treated as rejected rather than running (10s apart -- about 2 minutes).
DEPLOYMENT_ABSENT_POLL_LIMIT = 12
DEPLOYMENT_POLL_SECONDS = 10
DEPLOYMENT_HEARTBEAT_SECONDS = 30

#: How long preflight waits for a provider registration to take effect.
PROVIDER_REGISTRATION_TIMEOUT_SECONDS = 180
PROVIDER_REGISTRATION_POLL_SECONDS = 10

#: Default budget for the `verify` command to wait for one app to become
#: healthy. Both an image-swap cold pull and Function App trigger indexing can
#: take minutes with no documented upper bound, hence a generous default.
DEFAULT_VERIFY_APP_TIMEOUT_SECONDS = 300

#: How often `verify` re-probes an app that has not yet answered healthy.
VERIFY_POLL_INTERVAL_SECONDS = 10

#: Per-request socket timeout for one health-check HTTP call, so a single hung
#: connection cannot stall past the next poll tick.
VERIFY_REQUEST_TIMEOUT_SECONDS = 10

#: Scheme used to probe a web app's readiness route. A named constant (not an
#: inline literal) because Azure App Service always terminates TLS on the
#: default hostname -- there is no plain-HTTP variant to fall back to.
WEB_APP_PROBE_SCHEME = "https"

#: The ARM operations API populates a failed deployment's NESTED leaf
#: operations slightly AFTER the top deployment flips to 'Failed', so an
#: immediate drill can return nothing even though real leaf errors exist below.
#: Empty would misclassify a retryable race as a hard failure, so the drill is
#: retried before an empty result is trusted.
LEAF_DRILL_ATTEMPTS = 6
LEAF_DRILL_RETRY_SECONDS = 5
LEAF_DRILL_MAX_DEPTH = 8

#: A valid Docker tag: leading alphanumeric or underscore, then
#: alphanumerics/dot/underscore/hyphen, 128 characters at most.
DOCKER_TAG_PATTERN = re.compile(r"^[a-zA-Z0-9_][a-zA-Z0-9._-]{0,127}$")

#: Placeholder each service's image-tag parameter carries in the generated
#: .bicepparam until this script resolves the real, pushed tag.
IMAGE_TAG_PLACEHOLDER_PREFIX = "CRUFTFREE_IMAGE_TAG_PLACEHOLDER_"

#: The one platform every image is built for: Azure App Service Linux and the
#: ACI-backed deployment scripts all run linux/amd64.
CONTAINER_PLATFORM = "linux/amd64"

#: pip flags that resolve Linux wheels from this (possibly non-Linux) deploy
#: host. Wheel-only by design: a source distribution would be built for the
#: WRONG platform.
PIP_PLATFORM_TAGS: tuple[str, ...] = (
    "manylinux_2_17_x86_64",
    "manylinux2014_x86_64",
    "any",
)

#: Files and directories never included in a content hash or a deploy zip:
#: byte-compiled output is a build artifact of the source already covered.
HASH_EXCLUDED_DIR = "__pycache__"
HASH_EXCLUDED_SUFFIX = ".pyc"


class DeployError(RuntimeError):
    """A fatal, operator-actionable deployment failure.

    Raised instead of exiting in place so a failure inside a concurrently
    dispatched wave item is reported by the parent with the item's own message,
    and so every command has exactly one place that renders a failure.
    """


# ---------------------------------------------------------------------------
# Runtime settings
# ---------------------------------------------------------------------------


def _env_flag(name: str) -> bool:
    """Return True when environment variable ``name`` is exactly ``'true'``.

    Args:
        name: Environment variable name.

    Returns:
        True iff the variable is set to ``"true"`` (case-insensitive).
    """
    return os.environ.get(name, "").strip().lower() == "true"


def _env_wave_size(name: str, default: int) -> int:
    """Return a positive wave size from environment variable ``name``.

    Args:
        name: Environment variable name.
        default: Value to use when the variable is unset or empty.

    Returns:
        The configured wave size.

    Raises:
        DeployError: If the variable is set to something that is not a positive
            integer -- a silently-ignored typo here would change deployment
            concurrency without telling anyone.
    """
    raw = os.environ.get(name, "").strip()
    if not raw:
        return default
    if not raw.isdigit() or int(raw) < 1:
        raise DeployError(
            f"{name} must be a positive integer (got '{raw}'). "
            f"It bounds how many code pushes run concurrently; leave it unset "
            f"for the default of {default}."
        )
    return int(raw)


def _env_timeout_seconds(name: str, default: int) -> int:
    """Return a positive timeout in seconds from environment variable ``name``.

    Args:
        name: Environment variable name.
        default: Value to use when the variable is unset or empty.

    Returns:
        The configured timeout, in seconds.

    Raises:
        DeployError: If the variable is set to something that is not a
            positive integer -- a silently-ignored typo here would change how
            long 'verify' waits for an app without telling anyone.
    """
    raw = os.environ.get(name, "").strip()
    if not raw:
        return default
    if not raw.isdigit() or int(raw) < 1:
        raise DeployError(
            f"{name} must be a positive integer number of seconds (got "
            f"'{raw}'). It bounds how long 'verify' waits for each app to "
            f"become healthy; leave it unset for the default of {default}."
        )
    return int(raw)


@dataclass
class Settings:
    """Resolved deployment settings for one invocation.

    Environment variables provide the defaults (so a CI job can set them once);
    command-line flags override the three booleans.
    """

    resource_group: str
    location: str
    environment: str
    force: bool
    no_purge: bool
    turbo_scale: bool
    build_dir: Path
    web_wave_size: int
    function_wave_size: int
    image_wave_size: int
    verify_timeout_seconds: int

    @classmethod
    def from_environment(cls) -> Settings:
        """Build settings from the environment and the generated defaults."""
        environment = os.environ.get("ENVIRONMENT") or DEFAULT_ENVIRONMENT
        default_build_dir = (
            Path(os.environ.get("TMPDIR") or os.environ.get("TEMP") or "/tmp")
            / f"{APP_PREFIX}-deploy-build-{environment}"
        )
        configured_build_dir = os.environ.get("DEPLOY_BUILD_DIR")
        return cls(
            resource_group=os.environ.get("RESOURCE_GROUP") or DEFAULT_RESOURCE_GROUP,
            location=os.environ.get("LOCATION") or DEFAULT_LOCATION,
            environment=environment,
            force=_env_flag("FORCE"),
            no_purge=_env_flag("NO_PURGE"),
            turbo_scale=_env_flag("TURBO_SCALE"),
            build_dir=(
                Path(configured_build_dir)
                if configured_build_dir
                else default_build_dir
            ),
            web_wave_size=_env_wave_size("DEPLOY_WEB_WAVE", DEFAULT_WEB_WAVE_SIZE),
            function_wave_size=_env_wave_size(
                "DEPLOY_FUNCTION_WAVE", DEFAULT_FUNCTION_WAVE_SIZE
            ),
            image_wave_size=_env_wave_size(
                "DEPLOY_IMAGE_WAVE", DEFAULT_IMAGE_WAVE_SIZE
            ),
            verify_timeout_seconds=_env_timeout_seconds(
                "VERIFY_APP_TIMEOUT_SECONDS", DEFAULT_VERIFY_APP_TIMEOUT_SECONDS
            ),
        )

    @property
    def param_file(self) -> str:
        """Path of the full-infrastructure .bicepparam for this environment."""
        return self._param_file("main")

    @property
    def canary_param_file(self) -> str:
        """Path of the canary .bicepparam for this environment."""
        return self._param_file("canary")

    @property
    def foundation_param_file(self) -> str:
        """Path of the foundation .bicepparam for this environment."""
        return self._param_file("foundation")

    def _param_file(self, stem: str) -> str:
        """Return ``infra/<stem>[.<environment>].bicepparam``.

        The dev environment's files carry no suffix; every other environment's
        do, matching what the generator emits.
        """
        if self.environment == DEV_ENVIRONMENT_LABEL:
            return f"infra/{stem}.bicepparam"
        return f"infra/{stem}.{self.environment}.bicepparam"

    @property
    def key_vault_name(self) -> str:
        """Key Vault name -- the same composition key-vault.bicep names it by."""
        return f"{KEY_VAULT_NAME_STEM}{KEY_VAULT_NAME_INFIX}{self.environment}"

    @property
    def acr_name(self) -> str:
        """The shared container registry's name -- the same composition container-registry.bicep names it by."""
        return f"{ACR_NAME_STEM}{self.environment.replace('-', '')}"

    @property
    def acr_login_server(self) -> str:
        """The shared container registry's login server."""
        return f"{self.acr_name}{ACR_LOGIN_SERVER_SUFFIX}"

    @property
    def app_config_name(self) -> str:
        """App Configuration store name, matching the Bicep naming."""
        return f"{APP_PREFIX}-appconfig-{self.environment}"

    @property
    def apim_name(self) -> str:
        """API Management service name, matching the Bicep naming."""
        return f"{APP_PREFIX}-apim-{self.environment}"

    @property
    def plan_name(self) -> str:
        """Shared App Service plan name, matching the Bicep naming."""
        return "-".join((APP_PREFIX, "plan", self.environment))

    @property
    def secret_seeding_script_name(self) -> str:
        """Name of the secret-seeding deploymentScript resource.

        Built from APP_PREFIX (the resource-name slug), matching how the Bicep
        module names the resource -- NOT from APP_NAME, which is the raw
        application name and can carry characters the slug strips.
        """
        return f"{APP_PREFIX}-secret-seeding-{self.environment}"


def require_generated_environment(environment: str) -> None:
    """Refuse to deploy under a label this project was not generated for.

    The generated services have the Key Vault and App Configuration endpoints
    of DEFAULT_ENVIRONMENT baked in, and the API gateway's TLS certificate
    store is named for it: deploying under any other label creates resources
    the services never look up.
    """
    if environment == DEFAULT_ENVIRONMENT:
        return
    raise DeployError(
        f"ENVIRONMENT={environment!r}, but this project was generated for the "
        f"'{DEFAULT_ENVIRONMENT}' environment: its services look up the Key "
        f"Vault and App Configuration store named for '{DEFAULT_ENVIRONMENT}', "
        f"so a '{environment}' deployment would create resources they never "
        f"read. Fix: unset ENVIRONMENT (or set it to '{DEFAULT_ENVIRONMENT}'), "
        f"or regenerate the project for the profile that deploys as "
        f"'{environment}'."
    )


#: Settings for this invocation. Populated by ``main`` before any command runs;
#: every function reads it rather than threading a dozen values through call
#: chains. Tests construct their own and assign it.
SETTINGS = Settings.from_environment()


# ---------------------------------------------------------------------------
# Output helpers
# ---------------------------------------------------------------------------

_ANSI = {
    "head": "\033[1;36m",
    "danger": "\033[1;31m",
    "ok": "\033[0;32m",
    "warn": "\033[0;33m",
    "dim": "\033[0;90m",
    "off": "\033[0m",
}

#: Directory (relative to PROJECT_ROOT unless DEPLOY_LOG_DIR overrides it)
#: that per-run transcripts are written under.
TRANSCRIPT_LOG_DIRNAME = ".deploy-logs"

#: Environment variable overriding where transcripts are written.
TRANSCRIPT_LOG_DIR_ENV = "DEPLOY_LOG_DIR"

#: strftime format for the transcript FILENAME's timestamp component.
TRANSCRIPT_FILENAME_TIME_FORMAT = "%Y%m%d-%H%M%S"

#: strftime format for the timestamp prefixed to each transcript LINE.
TRANSCRIPT_LINE_TIME_FORMAT = "%H:%M:%S"

#: Matches an ANSI SGR color escape sequence, e.g. "\x1b[1;36m" or "\x1b[0m".
_ANSI_ESCAPE_RE = re.compile(r"\x1b\[[0-9;]*m")


@dataclass
class OutputState:
    """Console styling and the per-thread capture buffers waves rely on."""

    color: bool = field(default_factory=lambda: sys.stdout.isatty())
    step_color: str = "head"
    started_at: float = field(default_factory=time.monotonic)
    #: Set on a worker thread while it runs a wave item, so that item's output
    #: is buffered and replayed in list order instead of interleaving with the
    #: other concurrently-running items.
    local: threading.local = field(default_factory=threading.local)
    #: Open transcript file for this run. None when no run is in progress,
    #: when the sink could not be opened (an unwritable DEPLOY_LOG_DIR), or
    #: after main() has closed it at the end of a run.
    sink: TextIO | None = None
    #: Set by main() for a command whose standard output is its result alone:
    #: every console line then goes to standard error.
    progress_to_stderr: bool = False


OUTPUT = OutputState()


def _paint(text: str, color: str) -> str:
    """Wrap ``text`` in an ANSI color when the console supports it."""
    if not OUTPUT.color:
        return text
    return f"{_ANSI[color]}{text}{_ANSI['off']}"


def emit(line: str) -> None:
    """Write one already-formatted line to the console or the wave buffer.

    When a transcript sink is open, the console-bound line -- never a
    buffered one -- is additionally appended to it. This is why a wave
    item's output reaches the transcript exactly once, in its replayed
    order: the buffered branch below does not touch the sink; only the
    parent thread's later ``emit()`` call, made while replaying the buffer
    in ``run_deploy_wave``, does.
    """
    buffer = getattr(OUTPUT.local, "buffer", None)
    if buffer is None:
        print(
            line,
            flush=True,
            file=sys.stderr if OUTPUT.progress_to_stderr else sys.stdout,
        )
        _write_to_sink(line)
    else:
        buffer.append(line)


def _write_to_sink(line: str) -> None:
    """Append one ANSI-stripped, UTC-timestamped line to the open transcript.

    A no-op when no sink is open. Called from :func:`emit` for every line
    that reaches the console, and directly from ``main``'s failure handling
    for the one line that goes to ``sys.stderr`` instead of through
    ``emit`` -- so there are exactly two call sites, both of which route
    through this one function, and no third place formats a transcript line.
    """
    if OUTPUT.sink is None:
        return
    timestamp = dt.datetime.now(dt.timezone.utc).strftime(TRANSCRIPT_LINE_TIME_FORMAT)
    stripped = _ANSI_ESCAPE_RE.sub("", line)
    print(f"{timestamp} {stripped}", file=OUTPUT.sink, flush=True)


def _open_transcript_sink(command: str) -> Path | None:
    """Open this run's transcript file and store it on ``OUTPUT.sink``.

    Args:
        command: The command name being run; part of the transcript's
            filename so a directory of past runs stays self-describing.

    Returns:
        The transcript's path, or ``None`` when logging could not be
        enabled -- a loud ``note`` has already been emitted in that case,
        and the run proceeds stdout-only, exactly as if this feature did
        not exist.
    """
    override = os.environ.get(TRANSCRIPT_LOG_DIR_ENV)
    log_dir = Path(override) if override else PROJECT_ROOT / TRANSCRIPT_LOG_DIRNAME
    timestamp = dt.datetime.now(dt.timezone.utc).strftime(
        TRANSCRIPT_FILENAME_TIME_FORMAT
    )
    log_path = log_dir / f"{command}-{timestamp}.log"
    try:
        log_dir.mkdir(parents=True, exist_ok=True)
        OUTPUT.sink = log_path.open("w", encoding="utf-8")
    except OSError as error:
        OUTPUT.sink = None
        note(f"Transcript logging disabled ({error}); continuing stdout-only.")
        return None
    return log_path


def _close_transcript_sink() -> None:
    """Close the transcript sink, if one is open."""
    if OUTPUT.sink is not None:
        OUTPUT.sink.close()
        OUTPUT.sink = None


def elapsed() -> str:
    """Return the time since this run started, as ``<m>m<ss>s``."""
    seconds = int(time.monotonic() - OUTPUT.started_at)
    return f"{seconds // 60}m{seconds % 60:02d}s"


def step(message: str) -> None:
    """Announce a new phase of the run."""
    emit("")
    emit(_paint(f"==> {message}", OUTPUT.step_color))


def item(index: int, total: int, message: str) -> None:
    """Report one numbered item of a known-size batch."""
    emit(f"    {_paint(f'[{index}/{total}]', 'dim')} {message}")


def item1(message: str) -> None:
    """Report one item of an unnumbered list."""
    emit(f"    {_paint('-', 'dim')} {message}")


def ok(message: str) -> None:
    """Report a successful outcome."""
    emit(f"    {_paint(message, 'ok')}")


def note(message: str) -> None:
    """Report something the operator should notice but that is not fatal."""
    emit(f"    {_paint(message, 'warn')}")


def sub(message: str) -> None:
    """Report a detail underneath the current item."""
    emit(f"      {_paint(message, 'dim')}")


def banner(lines: Sequence[str], color: str = "head") -> None:
    """Print a boxed banner in the given color."""
    rule = "=" * 60
    for line in (rule, *lines, rule):
        emit(_paint(line, color))


# ---------------------------------------------------------------------------
# Subprocess helpers
# ---------------------------------------------------------------------------


class CommandResult(NamedTuple):
    """Outcome of one external command."""

    returncode: int
    stdout: str
    stderr: str

    @property
    def succeeded(self) -> bool:
        """True when the command exited zero."""
        return self.returncode == 0

    @property
    def output(self) -> str:
        """Combined stdout and stderr, for error reporting."""
        return "\n".join(part for part in (self.stdout, self.stderr) if part).strip()


_EXECUTABLE_CACHE: dict[str, str] = {}
_EXECUTABLE_LOCK = threading.Lock()


def resolve_executable(name: str, install_hint: str) -> str:
    """Return the absolute path of an external command, or fail loud.

    The absolute path matters on Windows, where the Azure CLI is a ``.cmd``
    shim: a bare name is resolved through PATHEXT only by a shell, which this
    script deliberately does not use (no shell means no quoting hazards).

    Args:
        name: Command name to look up on PATH.
        install_hint: Operator-facing sentence explaining how to install it.

    Returns:
        Absolute path to the executable.

    Raises:
        DeployError: If the command is not on PATH.
    """
    with _EXECUTABLE_LOCK:
        cached = _EXECUTABLE_CACHE.get(name)
        if cached is not None:
            return cached
        resolved = shutil.which(name)
        if resolved is None:
            raise DeployError(f"'{name}' not found. {install_hint}")
        _EXECUTABLE_CACHE[name] = resolved
        return resolved


def _resolve_build_argv(argv: Sequence[str]) -> tuple[str, ...]:
    """Return *argv* with its executable (first element) resolved to an
    absolute path -- same Windows .cmd-shim rationale as every other
    resolve_executable call site (az, docker): a bare name is resolved
    through PATHEXT only by a shell, which this script deliberately does
    not use.
    """
    return (resolve_executable(argv[0], NODE_TOOLCHAIN_INSTALL_HINT), *argv[1:])


AZ_INSTALL_HINT = "Install the Azure CLI (https://aka.ms/install-azure-cli)."
DOCKER_INSTALL_HINT = (
    "Container-mode deploys build images with 'docker buildx build' -- install "
    "Docker Desktop (or the Docker Engine plus the buildx plugin) and retry."
)
NODE_TOOLCHAIN_INSTALL_HINT = (
    "Static Web App deploys build the client with the app's own web toolchain "
    "(npm/npx) -- install Node.js (https://nodejs.org/) and retry."
)

#: Pinned Static Web Apps CLI version. Every
#: deploy uploads with this exact version, never a floating 'latest'.
SWA_CLI_VERSION = "2.0.10"


def run_command(
    argv: Sequence[str],
    *,
    stdin_text: str | None = None,
    stream: bool = False,
    cwd: Path | None = None,
    env: dict[str, str] | None = None,
) -> CommandResult:
    """Run an external command. Never raises on a nonzero exit.

    Args:
        argv: Full argument vector, executable path first. Passed straight to
            ``subprocess.run`` -- never a shell string, so there is no
            quoting hazard to defend against.
        stdin_text: Optional text piped to the command's stdin.
        stream: When True the command's output goes straight to the console
            instead of being captured, which is what a long image build needs --
            an operator watching a ten-minute build must see it progressing.
        cwd: Working directory for the child process. Defaults to
            ``PROJECT_ROOT`` (every existing call site's behaviour,
            unchanged) -- pass an explicit directory to run a command
            rooted somewhere else (e.g. one client target's own directory).
        env: Full environment for the child process. ``None`` (the default)
            inherits this process's own environment unchanged, identical to
            omitting the argument entirely -- pass an explicit mapping only
            to ADD a value (e.g. a deployment token) that must never be
            written to this process's own environment or to disk.

    Returns:
        The command's exit code and, unless streamed, its captured output.
    """
    completed = subprocess.run(
        list(argv),
        input=stdin_text,
        capture_output=not stream,
        text=True,
        encoding="utf-8",
        errors="replace",
        cwd=cwd if cwd is not None else PROJECT_ROOT,
        env=env,
    )
    if stream:
        return CommandResult(returncode=completed.returncode, stdout="", stderr="")
    return CommandResult(
        returncode=completed.returncode,
        stdout=(completed.stdout or "").strip(),
        stderr=(completed.stderr or "").strip(),
    )


def az(*args: str, stream: bool = False) -> CommandResult:
    """Run one ``az`` invocation and capture its result.

    Args:
        *args: Arguments after ``az``.
        stream: Send the invocation's output to the console instead of
            capturing it. Overridden to capturing when this call happens
            inside a wave item (``OUTPUT.local.buffer`` is set) regardless of
            what the caller asked for: several wave items streaming raw
            output concurrently onto one console interleaves into an
            unreadable mess, so every call site keeps its own literal
            ``stream=`` argument unchanged and the override happens here.

    Returns:
        The invocation's exit code and captured output.
    """
    in_wave = getattr(OUTPUT.local, "buffer", None) is not None
    return run_command(
        [resolve_executable("az", AZ_INSTALL_HINT), *args],
        stream=stream and not in_wave,
    )


def az_text(*args: str) -> str:
    """Run ``az ... -o tsv`` style and return stdout, or '' if it failed.

    Mirrors the intent of every "read a value, tolerate its absence" query in
    this script: an unreadable value is reported as absent, and the caller
    decides whether absence is fatal.
    """
    result = az(*args)
    return result.stdout if result.succeeded else ""


def az_lines(*args: str) -> list[str]:
    """Run an ``az ... -o tsv`` query and return its non-empty output lines."""
    return [line for line in az_text(*args).splitlines() if line.strip()]


def az_rows(*args: str) -> list[list[str]]:
    """Run a multi-column ``az ... -o tsv`` query and return split rows."""
    return [line.split("\t") for line in az_lines(*args)]


def az_json(*args: str) -> object:
    """Run an ``az ... -o json`` query and parse it. Returns None on any failure.

    A failed call, empty output, or unparseable JSON all resolve to ``None``:
    every caller treats "no data" the same way, and an az error has already
    been surfaced through the command's own stderr when it matters.
    """
    result = az(*args)
    if not result.succeeded or not result.stdout:
        return None
    try:
        return json.loads(result.stdout)
    except json.JSONDecodeError:
        return None


def az_json_list(*args: str) -> list[dict[str, object]]:
    """Run an ``az ... -o json`` query expected to return a list of objects."""
    parsed = az_json(*args)
    if not isinstance(parsed, list):
        return []
    return [entry for entry in parsed if isinstance(entry, dict)]


def docker(*args: str, stream: bool = False) -> CommandResult:
    """Run one ``docker`` invocation.

    Args:
        *args: Arguments after ``docker``.
        stream: Send the invocation's output to the console instead of
            capturing it -- what every build and push does, so the operator can
            watch a long image build progress. Overridden to capturing when
            this call happens inside a wave item (``OUTPUT.local.buffer`` is
            set) regardless of what the caller asked for: several wave items
            streaming raw build output concurrently onto one console
            interleaves into an unreadable mess, so every call site keeps its
            own literal ``stream=`` argument unchanged and the override
            happens here.
    """
    in_wave = getattr(OUTPUT.local, "buffer", None) is not None
    return run_command(
        [resolve_executable("docker", DOCKER_INSTALL_HINT), *args],
        stream=stream and not in_wave,
    )


def pip(*args: str) -> CommandResult:
    """Run ``pip`` from THIS interpreter (the project virtual environment)."""
    return run_command([sys.executable, "-m", "pip", *args])


def pip_cloud_wheel_flags() -> list[str]:
    """Return the pip flags that resolve Linux wheels for the App Service runtime.

    Wheel-only, cross-platform, pinned to the App Service interpreter version:
    resolving against the deploy host instead would bundle binaries that cannot
    import on the Linux App Service.
    """
    flags = ["--only-binary=:all:"]
    for tag in PIP_PLATFORM_TAGS:
        flags.extend(["--platform", tag])
    flags.extend(
        ["--python-version", DEPENDENCY_RUNTIME_VERSION, "--implementation", "cp"]
    )
    return flags


# ---------------------------------------------------------------------------
# Content hashing and the skip decision
# ---------------------------------------------------------------------------


def _sha256_file(path: Path) -> str:
    """Return the lowercase hex SHA-256 of a file's bytes."""
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _hashable_files(root: Path) -> list[tuple[str, Path]]:
    """Return ``(relative posix path, file)`` pairs under ``root``, sorted.

    Byte-compiled output is excluded so a tree that has been imported hashes
    the same as one that has not.
    """
    files: list[tuple[str, Path]] = []
    for path in root.rglob("*"):
        if not path.is_file():
            continue
        if HASH_EXCLUDED_DIR in path.parts or path.suffix == HASH_EXCLUDED_SUFFIX:
            continue
        files.append((path.relative_to(root).as_posix(), path))
    return sorted(files, key=lambda pair: pair[0])


# @canonical(azure/deploy-content-hash): Deterministic content hash of a service's
#   deploy-determining inputs
# @rule: One implementation for every entrypoint -- a per-shell reimplementation makes
#   the same unchanged service hash differently and redeploy needlessly
# @rule: Byte-compiled output (__pycache__, *.pyc) is always excluded
def deploy_content_hash(roots: Sequence[str | Path]) -> str:
    """Return a deterministic hash of the given files and directory trees.

    Each root contributes ``<root index>:<relative path>|<file sha256>`` lines
    (a directory contributes one line per file, in relative-path order); the
    joined manifest is hashed. The root index is part of every line, so moving
    a file between roots changes the hash even when the file set does not.
    Missing roots contribute nothing, which is what makes the optional inputs
    (a service without migrations) hash consistently.

    Args:
        roots: Files and/or directory trees, in a stable caller-defined order.

    Returns:
        Lowercase hex SHA-256 of the manifest.
    """
    lines: list[str] = []
    for index, raw_root in enumerate(roots):
        root = Path(raw_root)
        if root.is_dir():
            for relative, path in _hashable_files(root):
                lines.append(f"{index}:{relative}|{_sha256_file(path)}")
        elif root.is_file():
            lines.append(f"{index}:{root.name}|{_sha256_file(root)}")
    manifest = "".join(f"{line}\n" for line in lines)
    return hashlib.sha256(manifest.encode("utf-8")).hexdigest()


def service_deploy_needed(current_hash: str, stored_hash: str, force: bool) -> bool:
    """Decide whether a service must be (re)deployed.

    Pure -- no Azure calls -- so the decision is independently testable.

    Args:
        current_hash: Hash of the service's current deploy-determining inputs.
        stored_hash: Hash stamped by the last successful deploy; empty when no
            prior deploy is recorded.
        force: True to redeploy regardless.

    Returns:
        True when a deploy is needed, False when the service can be skipped.
    """
    if force:
        return True
    if not stored_hash:
        return True
    return stored_hash != current_hash


def read_stored_deploy_hash(app_name: str) -> str:
    """Return the deploy hash stamped on an app, or '' when there is none."""
    return az_text(
        "webapp",
        "config",
        "appsettings",
        "list",
        "--name",
        app_name,
        "--resource-group",
        SETTINGS.resource_group,
        "--query",
        f"[?name=='{DEPLOY_HASH_SETTING}'].value | [0]",
        "-o",
        "tsv",
        "--only-show-errors",
    )


def set_deploy_hash_stamp(app_name: str, content_hash: str) -> None:
    """Stamp the deployed content hash on an app so an unchanged re-run skips it.

    Best-effort but never silent: ``az webapp config appsettings set`` can fail
    without a useful nonzero exit, leaving the stored hash empty so the very
    next run needlessly redeploys a service that had not changed. The setting
    is therefore read back after every attempt, and a stamp that never takes
    ends in a loud warning rather than a silent one. It is not fatal -- the
    deploy itself already succeeded, and a missed stamp only costs one extra
    rebuild next run.
    """
    for attempt in range(1, DEPLOY_HASH_STAMP_ATTEMPTS + 1):
        az(
            "webapp",
            "config",
            "appsettings",
            "set",
            "--name",
            app_name,
            "--resource-group",
            SETTINGS.resource_group,
            "--settings",
            f"{DEPLOY_HASH_SETTING}={content_hash}",
            "-o",
            "none",
            "--only-show-errors",
        )
        if read_stored_deploy_hash(app_name) == content_hash:
            return
        if attempt < DEPLOY_HASH_STAMP_ATTEMPTS:
            time.sleep(DEPLOY_HASH_STAMP_RETRY_SECONDS)
    note(
        f"could not stamp {DEPLOY_HASH_SETTING} for '{app_name}' -- the service "
        f"will redeploy on the next run (harmless but slow); check "
        f"'az webapp config appsettings set' permissions"
    )


# ---------------------------------------------------------------------------
# Infrastructure content hash, guard decisions, and resource-group stamp
# ---------------------------------------------------------------------------


def infra_content_hash() -> str:
    """Return a deterministic content hash of this project's `infra/` inputs.

    Hashes every file under `infra/` EXCEPT:
      - the whole `infra/functions/` subtree -- function packages are delivered
        by the function-app push leg and already carry their own
        `CRUFTFREE_DEPLOY_HASH` app-setting stamp, so including them here would
        invalidate this stamp on every function-code edit.
      - any `*.deploy.bicepparam` file -- a deploy-time DERIVED artifact
        (written by `deploy_param_file` / mutated by
        `set_container_image_tag_placeholder`), not an operator input; it
        changes on every container deploy even when nothing the operator wrote
        changed.

    `infra/main.bicepparam` (and any other non-excluded file under `infra/`) IS
    included with placeholders intact -- the generator never consumes them in
    place -- so a genuine parameter edit invalidates the stamp, which is
    correct: a parameter change is an infrastructure input change.

    The qualifying files are explicitly enumerated and sorted here, then handed
    to the existing `deploy_content_hash` as a literal file list (never a bare
    directory root) -- `deploy_content_hash`'s directory-root behavior has no
    way to express these two exclusions, and there must be exactly one hashing
    implementation (see the `@canonical(azure/deploy-content-hash)` marker
    above `deploy_content_hash`).

    Pure and side-effect-free: no Azure calls, only local filesystem reads.

    Returns:
        Lowercase hex SHA-256 of the qualifying file manifest.
    """
    infra_root = PROJECT_ROOT / "infra"
    qualifying: list[Path] = []
    for path in infra_root.rglob("*"):
        if not path.is_file():
            continue
        relative = path.relative_to(infra_root)
        if relative.parts[0] == "functions":
            continue
        if path.name.endswith(".deploy.bicepparam"):
            continue
        qualifying.append(path)
    qualifying.sort(key=lambda candidate: candidate.relative_to(infra_root).as_posix())
    return deploy_content_hash(qualifying)


def code_deploy_allowed(stored: str | None, current: str) -> bool:
    """Decide whether `code` may push application code without a Bicep stage.

    Pure -- no Azure calls -- so this decision is independently testable.
    `--force` deliberately does NOT bypass this guard anywhere in the script: a
    stale-infra code push is exactly the silent-drift failure mode the `code`
    command must make impossible.

    Args:
        stored: The `cruftfree-infra-hash` tag's value, or None when the resource
            group has never completed a full `deploy` (or the tag is absent).
        current: This run's `infra_content_hash()`.

    Returns:
        True only when a stamp exists and matches the current infra hash.
    """
    if stored is None:
        return False
    return stored == current


def preflight_trim_allowed(stored: str | None, current: str, force: bool) -> bool:
    """Decide whether `deploy` may skip the advisory what-if and foundation stage.

    Pure -- no Azure calls -- so this decision is independently testable.

    Args:
        stored: The `cruftfree-infra-hash` tag's value, or None when absent.
        current: This run's `infra_content_hash()`.
        force: True when the operator passed `--force`, which always wins.

    Returns:
        True only when `force` is False, a stamp exists, and it matches.
    """
    if force:
        return False
    if stored is None:
        return False
    return stored == current


def read_infra_hash_stamp() -> str | None:
    """Return the resource group's `cruftfree-infra-hash` tag, or None when absent.

    Reads the whole tag bag as JSON (never `--query tags.<hyphenated-key>`,
    which JMESPath rejects at argument-parsing time because unquoted JMESPath
    identifiers permit only letters/digits/underscore -- a hyphen is illegal)
    and indexes into it defensively, so a resource group with no tags, or with
    tags but not this one, both resolve to a real `None` rather than a string
    that looks empty.

    Returns:
        The stamped hex digest, or None when the resource group, its tag bag,
        or this specific tag is absent.
    """
    parsed = az_json(
        "group",
        "show",
        "--name",
        SETTINGS.resource_group,
        "-o",
        "json",
        "--only-show-errors",
    )
    if not isinstance(parsed, dict):
        return None
    tags = parsed.get("tags")
    if not isinstance(tags, dict):
        return None
    value = tags.get(INFRA_HASH_TAG)
    return value if isinstance(value, str) else None


def write_infra_hash_stamp(digest: str) -> None:
    """Stamp the resource group with the infrastructure content hash.

    Uses `--set tags.<key>=<value>`, which MERGES one key into the
    already-fetched tags dict (unlike `--tags`, which REPLACES the whole bag
    and must never be used here). `--force-string` is required: the generic
    update path's value parser tries `shell_safe_json_parse` first and would
    otherwise coerce an all-digit hex digest to a JSON number.

    Best-effort but not silent: a failed write leaves the next `code` push
    refused and the next `deploy` unable to trim its fixed overhead, both
    recoverable by re-running `deploy`. Not fatal -- the infrastructure deploy
    itself already succeeded by the time this is called.

    Args:
        digest: This run's `infra_content_hash()`.
    """
    result = az(
        "group",
        "update",
        "--name",
        SETTINGS.resource_group,
        "--set",
        f"tags.{INFRA_HASH_TAG}={digest}",
        "--force-string",
        "--only-show-errors",
    )
    if not result.succeeded:
        note(
            f"could not stamp '{INFRA_HASH_TAG}' on resource group "
            f"'{SETTINGS.resource_group}' -- the next code push will be refused "
            f"and the next deploy will re-run its full fixed overhead (harmless "
            f"but slow); check 'az group update' permissions. az reported: "
            f"{result.output}"
        )


# ---------------------------------------------------------------------------
# Deployment failure classification
# ---------------------------------------------------------------------------


class LeafFailure(NamedTuple):
    """One real (non-wrapper) resource failure under a deployment."""

    code: str
    resource_type: str
    resource: str
    message: str


def get_failed_leaf_ops(deploy_name: str, depth: int = 0) -> list[LeafFailure]:
    """Collect the real leaf failures under a deployment.

    Descends into nested module deployments and skips the 'DeploymentFailed'
    wrappers, so what is reported is the resource that actually failed rather
    than the deployment that contained it. Scoped to the passed deployment's
    subtree (never the whole resource group) so a retry judges only THIS
    attempt's failures.

    Args:
        deploy_name: Name of the deployment to drill into.
        depth: Current recursion depth; the traversal stops past
            ``LEAF_DRILL_MAX_DEPTH`` so a pathological template cannot hang it.

    Returns:
        Every leaf failure found, in ARM's own order.
    """
    if depth > LEAF_DRILL_MAX_DEPTH:
        return []
    operations = az_json_list(
        "deployment",
        "operation",
        "group",
        "list",
        "--resource-group",
        SETTINGS.resource_group,
        "--name",
        deploy_name,
        "--query",
        "[?properties.provisioningState=='Failed'].{"
        "res:properties.targetResource.resourceName, "
        "type:properties.targetResource.resourceType, "
        "code:properties.statusMessage.error.code, "
        "msg:properties.statusMessage.error.message}",
        "-o",
        "json",
        "--only-show-errors",
    )
    leaves: list[LeafFailure] = []
    for operation in operations:
        for row in _expand_operation_rows(operation):
            resource_type = str(operation.get("type") or "")
            is_nested = (
                resource_type == "Microsoft.Resources/deployments"
                or row.code == "DeploymentFailed"
            )
            if is_nested and row.resource:
                leaves.extend(get_failed_leaf_ops(row.resource, depth + 1))
            elif row.code:
                leaves.append(row._replace(resource_type=resource_type))
    return leaves


def _expand_operation_rows(operation: dict[str, object]) -> list[LeafFailure]:
    """Split one ARM operation into one row per underlying failure.

    A single operation can carry PARALLEL arrays -- many sibling resources
    failing at once under one nested deployment (e.g. ten API Management APIs).
    When the code/resource fields line up as equal-length lists, each failure
    becomes its own row so it prints as its own line; otherwise the fields are
    joined into a single row, which is the only faithful reading of an
    irregular shape.
    """
    codes = _as_str_list(operation.get("code"))
    resources = _as_str_list(operation.get("res"))
    messages = _as_str_list(operation.get("msg"))
    if len(codes) > 1 and len(resources) == len(codes):
        rows: list[LeafFailure] = []
        for index, code in enumerate(codes):
            if index < len(messages):
                message = messages[index]
            else:
                message = messages[-1] if messages else ""
            rows.append(LeafFailure(code, "", resources[index], message))
        return rows
    return [
        LeafFailure(
            code=", ".join(codes),
            resource_type="",
            resource=", ".join(resources),
            message=" ".join(messages),
        )
    ]


def _as_str_list(value: object) -> list[str]:
    """Normalize an ARM field that may be a scalar, a list, or absent."""
    if value is None:
        return []
    if isinstance(value, list):
        return [str(entry) for entry in value if entry]
    return [str(value)] if value else []


def resolve_failed_leaf_ops(deploy_name: str) -> list[LeafFailure]:
    """Drill a failed deployment for leaf failures, retrying while empty.

    The operations API lags the deployment's own state flip, so an immediate
    drill can return nothing even though real leaf errors exist below. An empty
    result would misclassify a retryable transient race as a hard failure AND
    print "no leaf error surfaced", so the drill is retried before an empty
    result is believed.
    """
    for _ in range(LEAF_DRILL_ATTEMPTS):
        leaves = get_failed_leaf_ops(deploy_name)
        if leaves:
            return leaves
        time.sleep(LEAF_DRILL_RETRY_SECONDS)
    return []


def failure_is_transient(leaves: Sequence[LeafFailure]) -> bool:
    """Return True only when EVERY leaf failure is a known transient race.

    An empty set (no leaf surfaced) is deliberately NOT transient: failing loud
    is right when the failure could not even be identified. A Graph
    authorization denial is always terminal, whatever else matched.
    """
    if not leaves:
        return False
    return all(_leaf_is_transient(leaf) for leaf in leaves)


def _leaf_is_transient(leaf: LeafFailure) -> bool:
    """Return True when one leaf failure is a known eventual-consistency race."""
    if leaf.code == GRAPH_AUTHORIZATION_DENIED_CODE:
        return False
    if leaf.code in TRANSIENT_DEPLOYMENT_CODES or is_arm_server_fault_code(leaf.code):
        return True
    if leaf.resource_type.startswith(GRAPH_RESOURCE_TYPE_PREFIX):
        if leaf.code in GRAPH_TRANSIENT_NOTFOUND_CODES:
            return True
    if leaf.resource_type == ROLE_ASSIGNMENT_RESOURCE_TYPE:
        if leaf.code in ROLE_ASSIGNMENT_TRANSIENT_CODES:
            return True
    if is_arm_server_fault_message(leaf.message):
        return True
    return any(fragment in leaf.message for fragment in TRANSIENT_DEPLOYMENT_MESSAGES)


def has_graph_authorization_denied(leaves: Sequence[LeafFailure]) -> bool:
    """Return True when a Graph resource failed with an authorization denial.

    Distinct from :func:`failure_is_transient` (which already treats the code
    as terminal) -- this drives the actionable remediation message.
    """
    return any(
        leaf.resource_type.startswith(GRAPH_RESOURCE_TYPE_PREFIX)
        and leaf.code == GRAPH_AUTHORIZATION_DENIED_CODE
        for leaf in leaves
    )


def show_graph_authorization_hint() -> None:
    """Print the Graph permission grant the deploy principal is missing.

    Which grant depends on who is deploying, so the deployer kind is read back
    from the signed-in account rather than guessed. Never added to the
    transient allowlist: an authorization failure never self-heals by waiting.
    """
    deployer_type = az_text(
        "account", "show", "--query", "user.type", "-o", "tsv", "--only-show-errors"
    )
    if deployer_type == "servicePrincipal":
        grant = (
            "app-only 'Application.ReadWrite.OwnedBy' (or the broader "
            "'Application.ReadWrite.All')"
        )
        principal = "the deploy service principal"
    else:
        grant = (
            "delegated 'Application.ReadWrite.All' (an Entra admin can grant it "
            "with 'az ad app permission admin-consent' or in the Entra portal)"
        )
        principal = "the deploying user"
    print(
        f"ERROR: Microsoft Graph resource creation was denied "
        f"({GRAPH_AUTHORIZATION_DENIED_CODE}): {principal} lacks the required "
        f"Graph permission. Grant it {grant} on Microsoft Graph, then re-run. "
        f"This never self-heals by retrying.",
        file=sys.stderr,
    )


def show_deployment_failure(
    deploy_name: str, label: str, leaves: Sequence[LeafFailure]
) -> None:
    """Print the real leaf errors of a failed stage, with a quota/offer hint.

    Takes the already-resolved leaves so the drill (with its retry-on-empty)
    runs once per failure, not twice.
    """
    print(f"ERROR: {label} deployment '{deploy_name}' failed.", file=sys.stderr)
    print("Root-cause failures (drilling into nested deployments):", file=sys.stderr)
    seen: set[tuple[str, str]] = set()
    for leaf in leaves:
        key = (leaf.code, leaf.resource)
        if key in seen:
            continue
        seen.add(key)
        print(f"  [{leaf.code}] {leaf.resource}", file=sys.stderr)
        print(f"      {leaf.message}", file=sys.stderr)
    if not seen:
        print(
            f"  (no leaf error surfaced -- check the portal Deployments blade "
            f"for '{deploy_name}')",
            file=sys.stderr,
        )
    if OFFER_QUOTA_CODE_PATTERN.search(" ".join(code for code, _ in seen)):
        note(
            "This is a region/SKU offer or quota restriction for your "
            "subscription. Try another region (set LOCATION) or request a "
            "quota increase, then re-run."
        )
    show_secret_seeding_log(leaves)


def show_secret_seeding_log(leaves: Sequence[LeafFailure]) -> None:
    """Print the secret-seeding script's own log when that resource failed.

    A failed secret-seeding deploymentScript carries its actionable detail in
    its OWN log, not in the ARM error message: which required config keys,
    CruftFree-owned secrets, and operator-owned secrets have no usable value, each
    with the exact command that sets it. ARM surfaces only a generic
    script-failure code. Never prints a secret value -- the seeder logs
    identities, effects, and fix commands only.
    """
    script_name = SETTINGS.secret_seeding_script_name
    if not any(leaf.resource == script_name for leaf in leaves):
        return
    print(
        "Secret-seeding script log (every unsatisfied requirement is listed here):",
        file=sys.stderr,
    )
    result = az(
        "deployment-scripts",
        "show-log",
        "--resource-group",
        SETTINGS.resource_group,
        "--name",
        script_name,
        "--only-show-errors",
    )
    if result.succeeded:
        print(result.stdout, file=sys.stderr)
        return
    note(
        f"Could not read the secret-seeding script log. Retrieve it manually: "
        f"az deployment-scripts show-log --resource-group "
        f"{SETTINGS.resource_group} --name {script_name}"
    )


# ---------------------------------------------------------------------------
# az transport failures
# ---------------------------------------------------------------------------
# Inlined from cruftfree_codegen_azure/az_transport_runtime.py, shared with every
# generated Azure deploy CLI: the markers of az's own connection to Azure
# failing, as opposed to Azure refusing.
#: Text az's HTTP stack prints when the connection to Azure failed, not when
#: Azure refused. Each marker is spelled exactly as the Azure CLI's bundled
#: transport libraries emit it (azure-core, urllib3), so it matches az's output
#: rather than a paraphrase of it.
#:
#: Deliberately absent: urllib3's "Max retries exceeded". It wraps an SSLError
#: -- a certificate that failed verification -- exactly as it wraps a refused
#: connection, and a verification failure is never something to re-send
#: through. A dropped connection surfaces as one of the markers below instead.
AZ_TRANSPORT_FAILURE_MARKERS = (
    # azure-core's transport logs this when the response body stream breaks
    # after the request was sent. OBSERVED on `az deployment group create`: az
    # then crashed with "'NoneType' object has no attribute 'json'", and the
    # resource group's activity log showed ARM had validated the deployment and
    # never received the write.
    "Unable to stream download",
    # urllib3: the socket failed before any response arrived -- a reset, or the
    # remote end closing without answering. A TLS or certificate failure is
    # raised as an SSLError instead, so it never carries this text.
    "Connection aborted.",
    # urllib3: the socket failed while the response body was being read.
    "Connection broken",
    # urllib3: the request was sent and no answer arrived within the client's
    # read timeout.
    "Read timed out",
)


def is_az_transport_failure(output: str) -> bool:
    """Whether az's output says its own connection to Azure failed.

    A transport failure says nothing about the request itself: it is safe to
    re-send only when the operation is idempotent, which every caller decides
    for its own operation.

    Args:
        output: az's combined stdout and stderr from one failed invocation.

    Returns:
        True when the output carries a marker of a dropped or timed-out
        connection; False for every answer Azure itself returned.
    """
    return any(marker in output for marker in AZ_TRANSPORT_FAILURE_MARKERS)


# ---------------------------------------------------------------------------
# Resource-provider 5xx, by ARM's code or by its message alone
# ---------------------------------------------------------------------------
# Inlined from cruftfree_codegen_azure/arm_server_fault_runtime.py, shared with
# every generated Azure deploy CLI: ARM's codes for a provider's own 5xx, and
# its message, which survives when an outer resource re-wraps it under its own
# error code.
#: ARM's error codes for an HTTP 5xx a resource provider answered on its own
#: side. OBSERVED: the PostgreSQL RP answered a Flexible Server create with a bare
#:   InternalServerError: An unexpected error occured while processing the
#:   request. Tracking ID: '<guid>'
#: on a server whose tier/version/SKU had already been checked against the
#: region's capability set, from a template ARM had already validated, and it
#: left no resource behind. There is nothing to diagnose and nothing to fix in
#: the template -- the remedy is to ask again. The other two are the same HTTP
#: 5xx class (503, 504); retrying 500 while failing on 503 would be arbitrary.
ARM_TRANSIENT_SERVER_CODES = (
    "InternalServerError",
    "ServiceUnavailable",
    "GatewayTimeout",
)

#: ARM's fixed message text for an HTTP 5xx answered on a resource provider's
#: behalf, spelled exactly as ARM emits it so it matches the failure rather than
#: a paraphrase of it. Each entry has been observed surviving a wrapping outer
#: error code; a text that has not been observed is not listed, because a marker
#: that matches more than the provider's own failure turns a real fault into
#: three deployments' worth of waiting.
ARM_SERVER_FAULT_MESSAGES = (
    # ARM's gateway timeout (HTTP 504): the gateway forwarded the request to a
    # resource provider and no answer came back in time. OBSERVED wrapped by a
    # deploymentScripts resource whose container-group write timed out three
    # times in a row:
    #   {"code":"DeploymentScriptOperationFailed","message":"The gateway did not
    #   receive a response from 'Microsoft.ContainerInstance' within the
    #   specified time period."}
    # The container group never came up and the script never ran, so a re-run
    # cannot apply anything twice.
    "The gateway did not receive a response from",
)

#: How ``az rest`` reports an HTTP 5xx: the response's reason phrase directly followed by
#: its body, ``<reason>(<body>)``. The body's ARM code is the provider's own and need not be
#: one of ``ARM_TRANSIENT_SERVER_CODES``, so the HTTP status is the signal. OBSERVED on a
#: container group PUT that left no group behind:
#:   ERROR: Service Unavailable({"error":{"code":"ServerTimeout","message":"The request
#:   timed out. ..."}})
#: The other three are the same HTTP 5xx class (500, 502, 504), spelled as the HTTP
#: library az uses emits their reason phrases.
AZ_REST_SERVER_FAULT_REASONS = (
    "Internal Server Error(",
    "Bad Gateway(",
    "Service Unavailable(",
    "Gateway Timeout(",
)


def is_arm_server_fault_code(code: str) -> bool:
    """Whether one ARM error code names a resource provider's own 5xx.

    For a classifier that reads each failed operation's code (the App Service
    CLI's leaf failures).

    Args:
        code: One ARM error code, exactly as ARM reports it.

    Returns:
        True when the code is one of ``ARM_TRANSIENT_SERVER_CODES``.
    """
    return code in ARM_TRANSIENT_SERVER_CODES


def carries_arm_server_fault_code(text: str) -> bool:
    """Whether failure text names a resource provider's own 5xx by its ARM code.

    For a classifier that reads az's combined output rather than parsed
    operations (the azure-vm CLI's provision step).

    Args:
        text: az's combined output from one failed deployment attempt.

    Returns:
        True when the text carries one of ``ARM_TRANSIENT_SERVER_CODES``.
    """
    return any(code in text for code in ARM_TRANSIENT_SERVER_CODES)


def is_arm_server_fault_message(text: str) -> bool:
    """Whether failure text carries ARM's message for a provider's own 5xx.

    Matches the message alone, never an outer error code: a wrapping code such
    as ``DeploymentScriptOperationFailed`` also reports a script that ran and
    failed, which is not transient.

    Args:
        text: An ARM error message, or az's combined output carrying one.

    Returns:
        True when the text names a resource provider's own server-side fault;
        False for every failure the composition or a script caused.
    """
    return any(message in text for message in ARM_SERVER_FAULT_MESSAGES)


def is_az_rest_server_fault(text: str) -> bool:
    """Whether ``az rest``'s output reports an HTTP 5xx Azure answered.

    For a caller that sends its own ARM request through ``az rest`` (the schema run
    channel's container group writes and reads), whose failure carries the HTTP
    status, not a deployment's operation codes.

    Args:
        text: ``az rest``'s combined output from one failed request.

    Returns:
        True when the output carries one of ``AZ_REST_SERVER_FAULT_REASONS``; False
        for a 4xx (an authorization failure, a bad request, a missing resource).
    """
    return any(reason in text for reason in AZ_REST_SERVER_FAULT_REASONS)


# ---------------------------------------------------------------------------
# The identity running the deploy
# ---------------------------------------------------------------------------
# Inlined from cruftfree_codegen_azure/operator_identity_runtime.py, shared with
# every generated Azure deploy CLI whose composition grants the deploying
# identity a role: how the signed-in identity is resolved, and the variables
# the parameter files read it from.
#: Environment variables the parameter file reads the deploying operator's
#: directory identity from. The deploy CLI that exports them and the parameter
#: file that reads them are rendered by different generators; a typo on either
#: side would surface only at deploy time, as an unset-variable failure.
OPERATOR_PRINCIPAL_ID_ENV_VAR = "CRUFTFREE_OPERATOR_PRINCIPAL_ID"
OPERATOR_PRINCIPAL_TYPE_ENV_VAR = "CRUFTFREE_OPERATOR_PRINCIPAL_TYPE"

#: az's own spelling of the signed-in account kind, mapped to the spelling an
#: Azure role assignment's principalType requires.
PRINCIPAL_TYPE_BY_ACCOUNT_KIND = {
    "user": "User",
    "servicePrincipal": "ServicePrincipal",
}


def operator_principal_type(
    account_kind: str, error: Callable[[str], Exception]
) -> str:
    """The role-assignment principal type of a signed-in account of *account_kind*.

    Args:
        account_kind: What ``az account show --query user.type`` reported.
        error: The host's operator-facing error type.

    Raises:
        The *error* type: the kind is not one a role assignment can name. Never
            falls back to a guess, which Azure would reject only at the grant.
    """
    principal_type = PRINCIPAL_TYPE_BY_ACCOUNT_KIND.get(account_kind)
    if principal_type is None:
        raise error(
            f"Cannot classify the signed-in Azure account (az reported "
            f"user.type={account_kind!r}). The deployment must declare whether the "
            f"operator is a User or a ServicePrincipal, because Azure rejects "
            f"a role assignment whose principalType does not match the "
            f"directory object. Fix: sign in with `az login` as a user or a "
            f"service principal."
        )
    return principal_type


def export_operator_identity(
    az_text: Callable[..., str], error: Callable[[str], Exception]
) -> tuple[str, str]:
    """Resolve the signed-in identity and export it for the parameter file.

    Resolved at deploy time rather than baked in at generation time because who
    deploys is not knowable when the project is generated, and may differ
    between runs.

    Args:
        az_text: The host's ``az`` runner returning plain stdout ('' on failure).
        error: The host's operator-facing error type.

    Returns:
        The principal type and object id exported.

    Raises:
        The *error* type: the account kind is unrecognized, or its object id
            cannot be resolved. Never falls back to skipping the grants, which
            would defer the failure to the first step that needs them.
    """
    kind = az_text("account", "show", "--query", "user.type", "-o", "tsv")
    principal_type = operator_principal_type(kind, error)
    if principal_type == "User":
        principal_id = az_text(
            "ad", "signed-in-user", "show", "--query", "id", "-o", "tsv"
        )
    else:
        app_id = az_text("account", "show", "--query", "user.name", "-o", "tsv")
        principal_id = az_text(
            "ad", "sp", "show", "--id", app_id, "--query", "id", "-o", "tsv"
        )
    if not principal_id:
        raise error(
            "Could not resolve the signed-in identity's directory object id. "
            "The deployment grants that identity the rights its deploy needs, "
            "so it cannot proceed without it. Fix: confirm `az ad signed-in-user "
            "show` succeeds for this account; a guest or federated identity may "
            "need directory read permission."
        )
    os.environ[OPERATOR_PRINCIPAL_ID_ENV_VAR] = principal_id
    os.environ[OPERATOR_PRINCIPAL_TYPE_ENV_VAR] = principal_type
    return principal_type, principal_id


def resolve_operator_identity() -> None:
    """Export the signed-in identity for the run store's operator grants.

    The composition grants that identity the rights each schema run needs --
    the run store's blobs, one container group per run, presenting each
    block's schema identity, joining the schema-run subnet -- so the
    parameter files of main.bicep and canary.bicep read it from the
    environment.

    Raises:
        DeployError: The signed-in identity cannot be resolved.
    """
    principal_type, principal_id = export_operator_identity(az_text, DeployError)
    note(f"Deploying as {principal_type.lower()} {principal_id}.")


# ---------------------------------------------------------------------------
# Bicep stages
# ---------------------------------------------------------------------------

#: Name of the deployment the most recent successful stage created. The
#: code-push phase reads that deployment's outputs.
LAST_STAGE_DEPLOYMENT_NAME = ""

#: The stage that provisions everything the release runs on; its deployment
#: publishes every output the release and the client contract read.
INFRASTRUCTURE_STAGE = "infrastructure"


def stage_deployment_prefix(label: str) -> str:
    """The name every deployment of the stage *label* starts with: ``cruftfree-<slug>-a``,
    followed by the attempt and the time it was submitted."""
    return f"cruftfree-{re.sub(r'[^a-zA-Z0-9]', '', label).lower()}-a"


def resume_last_infrastructure_deployment() -> None:
    """Take the newest succeeded deployment of the infrastructure stage as this run's last
    stage, so the clients are released against its outputs without deploying anything.

    Raises:
        DeployError: The resource group holds no succeeded deployment of the stage.
    """
    global LAST_STAGE_DEPLOYMENT_NAME
    prefix = stage_deployment_prefix(INFRASTRUCTURE_STAGE)
    result = az(
        "deployment",
        "group",
        "list",
        "--resource-group",
        SETTINGS.resource_group,
        "--query",
        f"[?starts_with(name, '{prefix}') && properties.provisioningState == 'Succeeded']"
        " | sort_by(@, &properties.timestamp) | [-1].name",
        "-o",
        "tsv",
        "--only-show-errors",
    )
    name = result.stdout.strip() if result.succeeded else ""
    if not name:
        raise DeployError(
            f"Resource group '{SETTINGS.resource_group}' holds no succeeded "
            f"'{INFRASTRUCTURE_STAGE}' deployment to read the client contract from. Deploy the "
            f"backend first ('{VERB_DEPLOY}' with no '{FLAG_SCOPE}', or "
            f"'{VERB_DEPLOY} {FLAG_SCOPE} {SCOPE_BACKEND}'). az reported: {result.output}"
        )
    LAST_STAGE_DEPLOYMENT_NAME = name


def backoff_seconds(attempt: int) -> int:
    """Return the backoff before retry attempt ``attempt`` (1-based).

    The schedule's last value repeats once the attempts outrun it.
    """
    index = min(attempt, len(BICEP_STAGE_BACKOFFS)) - 1
    return BICEP_STAGE_BACKOFFS[max(index, 0)]


def unregistered_stage_error(
    label: str, deploy_name: str, submission: CommandResult
) -> DeployError:
    """Return the error for a stage deployment ARM never registered.

    Two different stories end here, and the remedy differs: ARM rejected the
    submission at validation (fix the template), or az lost its connection
    while submitting and ARM never received it (re-run).

    Args:
        label: Human-readable stage name.
        deploy_name: Name of the deployment that never registered.
        submission: The ``az deployment group create --no-wait`` result.

    Returns:
        The operator-facing error.
    """
    if not submission.succeeded:
        return DeployError(
            f"The '{label}' deployment '{deploy_name}' never registered a "
            f"provisioning state after az lost its connection to Azure while "
            f"submitting it, and the stage's attempt budget is spent. ARM never "
            f"received it. Fix: check this machine's route to "
            f"management.azure.com, then re-run -- the deployment is "
            f"idempotent. az reported: {submission.output}"
        )
    return DeployError(
        f"The '{label}' deployment '{deploy_name}' never registered a "
        f"provisioning state. It was rejected at validation (no "
        f"deployment was created). Review the errors above, fix them, "
        f"and re-run."
    )


def should_retry_stage(attempt: int, leaves: Sequence[LeafFailure]) -> bool:
    """Decide whether a failed stage is worth re-running.

    Pure -- no Azure calls -- so the retry policy is testable on its own: a
    stage retries only while every leaf failure is a known transient
    eventual-consistency race AND the attempt budget still has room. An empty
    leaf set never retries (failing loud is right when the failure could not
    even be identified), and neither does a budget-exhausted final attempt.

    Args:
        attempt: The 1-based attempt that just failed.
        leaves: That attempt's resolved leaf failures.

    Returns:
        True when the caller should back off and re-run the stage.
    """
    if attempt >= BICEP_STAGE_MAX_ATTEMPTS:
        return False
    return failure_is_transient(leaves)


def wait_bicep_deployment(deploy_name: str) -> str:
    """Poll a ``--no-wait`` deployment, reporting each resource as it provisions.

    Args:
        deploy_name: Name of the submitted deployment.

    Returns:
        ``"Succeeded"``, ``"Failed"``, or ``"Rejected"`` -- the last meaning the
        deployment never registered a provisioning state at all, so it was
        rejected at or just after submission rather than running. The
        retry/terminal decision belongs to the caller.
    """
    reported: set[str] = set()
    last_beat = time.monotonic()
    absent_polls = 0
    while True:
        state = az_text(
            "deployment",
            "group",
            "show",
            "--resource-group",
            SETTINGS.resource_group,
            "--name",
            deploy_name,
            "--query",
            "properties.provisioningState",
            "-o",
            "tsv",
            "--only-show-errors",
        )
        operations = az_json_list(
            "deployment",
            "operation",
            "group",
            "list",
            "--resource-group",
            SETTINGS.resource_group,
            "--name",
            deploy_name,
            "--query",
            "[].{n:properties.targetResource.resourceName,"
            "s:properties.provisioningState}",
            "-o",
            "json",
            "--only-show-errors",
        )
        for operation in operations:
            name = str(operation.get("n") or "")
            operation_state = str(operation.get("s") or "")
            if not name or name in reported:
                continue
            if operation_state == "Succeeded":
                reported.add(name)
                ok(f"provisioned {name}")
            elif operation_state == "Failed":
                reported.add(name)
                note(f"FAILED {name}")
        if time.monotonic() - last_beat >= DEPLOYMENT_HEARTBEAT_SECONDS:
            done = sum(1 for op in operations if op.get("s") == "Succeeded")
            running = sum(1 for op in operations if op.get("s") == "Running")
            sub(f"elapsed {elapsed()} -- {done} provisioned, {running} in progress")
            last_beat = time.monotonic()
        if state == "Succeeded":
            return "Succeeded"
        if state in ("Failed", "Canceled"):
            return "Failed"
        if not state:
            absent_polls += 1
            if absent_polls >= DEPLOYMENT_ABSENT_POLL_LIMIT:
                return "Rejected"
        else:
            absent_polls = 0
        time.sleep(DEPLOYMENT_POLL_SECONDS)


def invoke_bicep_stage(param_file: str, label: str) -> None:
    """Deploy one Bicep stage, streaming progress and retrying transient races.

    ARM pre-deploy validation runs first: it takes seconds and rejects
    template/parameter and resource-provider FIELD errors before committing to
    a provisioning run that can last an hour. The deployment itself is then
    submitted asynchronously and polled. A stage that fails with ONLY transient
    eventual-consistency errors is retried with backoff -- the deployment is
    idempotent (ARM incremental mode skips already-succeeded resources), so
    re-running once propagation catches up is safe, and it is the systemic
    answer to control-plane races. A stage with ANY non-transient leaf failure,
    or a submission/validation rejection, fails loud immediately.

    A submission az lost its connection on is neither: ARM may or may not have
    received it. The deployment is followed by name, which answers the
    question -- it either registers and is polled like any other, or it never
    registers and is re-submitted as the next attempt.

    Args:
        param_file: The ``.bicepparam`` file to deploy.
        label: Human-readable stage name used in messages and deployment names.

    Raises:
        DeployError: On validation rejection, submission rejection, a
            non-transient failure, or an exhausted retry budget.
    """
    global LAST_STAGE_DEPLOYMENT_NAME
    name_prefix = stage_deployment_prefix(label)

    item1(f"pre-deploy validation ({label})")
    validation = az(
        "deployment",
        "group",
        "validate",
        "--resource-group",
        SETTINGS.resource_group,
        "--parameters",
        param_file,
        "-o",
        "none",
        "--only-show-errors",
    )
    if not validation.succeeded:
        raise DeployError(
            f"The '{label}' deployment failed ARM pre-deploy validation "
            f"(az deployment group validate exited {validation.returncode}). Fix "
            f"the reported error before deploying -- it would otherwise surface "
            f"only after provisioning began. az reported: {validation.output}"
        )
    ok(f"pre-deploy validation passed ({label}).")

    for attempt in range(1, BICEP_STAGE_MAX_ATTEMPTS + 1):
        stamp = dt.datetime.now().strftime("%Y%m%d%H%M%S")
        deploy_name = f"{name_prefix}{attempt}-{stamp}"
        submission = az(
            "deployment",
            "group",
            "create",
            "--no-wait",
            "--name",
            deploy_name,
            "--resource-group",
            SETTINGS.resource_group,
            "--parameters",
            param_file,
            "-o",
            "none",
        )
        if not submission.succeeded:
            if not is_az_transport_failure(submission.output):
                raise DeployError(
                    f"The '{label}' deployment was rejected at submission (az "
                    f"deployment group create exited {submission.returncode}). No "
                    f"deployment was created -- this is usually a template/"
                    f"parameter or offer/quota error. az reported: "
                    f"{submission.output}"
                )
            note(
                f"az lost its connection to Azure while submitting "
                f"'{deploy_name}', so whether ARM received it is unknown. "
                f"Following it by name to find out."
            )
        status = wait_bicep_deployment(deploy_name)
        if status == "Succeeded":
            if attempt > 1:
                ok(
                    f"Stage '{label}' succeeded on attempt {attempt} (after "
                    f"transient-error backoff)."
                )
            LAST_STAGE_DEPLOYMENT_NAME = deploy_name
            return
        if status == "Rejected":
            if not submission.succeeded and attempt < BICEP_STAGE_MAX_ATTEMPTS:
                note(
                    f"ARM never registered '{deploy_name}', so the lost "
                    f"submission did not reach it. Re-submitting the stage "
                    f"(attempt {attempt + 1}/{BICEP_STAGE_MAX_ATTEMPTS})."
                )
                continue
            raise unregistered_stage_error(label, deploy_name, submission)
        leaves = resolve_failed_leaf_ops(deploy_name)
        if should_retry_stage(attempt, leaves):
            codes = ", ".join(sorted({leaf.code for leaf in leaves}))
            wait = backoff_seconds(attempt)
            note(
                f"Stage '{label}' failed with only transient Azure "
                f"eventual-consistency errors [{codes}] (attempt {attempt}/"
                f"{BICEP_STAGE_MAX_ATTEMPTS}). This is control-plane propagation "
                f"lag, not a template fault -- backing off {wait}s and re-running "
                f"idempotently (succeeded resources are skipped)."
            )
            time.sleep(wait)
            continue
        show_deployment_failure(deploy_name, label, leaves)
        if has_graph_authorization_denied(leaves):
            show_graph_authorization_hint()
            raise DeployError(
                f"Stage '{label}' failed: the deploy principal lacks the required "
                f"Microsoft Graph permission (see the grant named above)."
            )
        if failure_is_transient(leaves):
            raise DeployError(
                f"Stage '{label}' still failing after {BICEP_STAGE_MAX_ATTEMPTS} "
                f"attempts with only transient errors -- Azure control-plane "
                f"propagation exceeded the retry budget. Wait a few minutes and "
                f"re-run (the deployment is idempotent)."
            )
        raise DeployError(
            f"Stage '{label}' failed with a non-transient error (reported above)."
        )


# ---------------------------------------------------------------------------
# Preflight
# ---------------------------------------------------------------------------


def require_azure_login() -> None:
    """Fail loud unless the Azure CLI is installed and signed in."""
    result = az("account", "show", "--only-show-errors")
    if not result.succeeded:
        raise DeployError(
            f"Not logged in to Azure. Run 'az login'. az reported: {result.output}"
        )


def register_required_providers() -> None:
    """Register any resource provider the generated infrastructure needs."""
    item1("resource providers registered")
    missing = [
        namespace
        for namespace in REQUIRED_PROVIDERS
        if az_text(
            "provider",
            "show",
            "--namespace",
            namespace,
            "--query",
            "registrationState",
            "-o",
            "tsv",
            "--only-show-errors",
        )
        != "Registered"
    ]
    if not missing:
        ok("all required providers registered")
        return
    note(f"registering {len(missing)} provider(s): {', '.join(missing)}")
    for namespace in missing:
        az(
            "provider",
            "register",
            "--namespace",
            namespace,
            "-o",
            "none",
            "--only-show-errors",
        )
    for namespace in missing:
        waited = 0
        while waited < PROVIDER_REGISTRATION_TIMEOUT_SECONDS:
            state = az_text(
                "provider",
                "show",
                "--namespace",
                namespace,
                "--query",
                "registrationState",
                "-o",
                "tsv",
                "--only-show-errors",
            )
            if state == "Registered":
                break
            time.sleep(PROVIDER_REGISTRATION_POLL_SECONDS)
            waited += PROVIDER_REGISTRATION_POLL_SECONDS
        final = az_text(
            "provider",
            "show",
            "--namespace",
            namespace,
            "--query",
            "registrationState",
            "-o",
            "tsv",
            "--only-show-errors",
        )
        if final == "Registered":
            sub(f"{namespace} registered")
        else:
            note(
                f"{namespace} still '{final}' after {waited}s -- deployment may "
                f"fail; register it manually with 'az provider register "
                f"--namespace {namespace}'"
            )


@dataclass(frozen=True)
class SoftDeletedBlocker:
    """A soft-deleted resource whose name blocks a fresh deployment."""

    kind: str
    name: str
    purge_hint: str
    recover_hint: str
    purge_argv: tuple[str, ...]
    detect_argv: tuple[str, ...]

    def describe(self) -> list[str]:
        """Return the operator-facing report lines for this blocker."""
        return [
            f"  - {self.kind} '{self.name}'",
            f"      purge:   {self.purge_hint}",
            f"      recover: {self.recover_hint}",
        ]

    def purge(self) -> None:
        """Attempt the purge. Never raises -- the verify step is the judge."""
        az(*self.purge_argv)

    def still_present(self) -> bool:
        """Return True when the name is still soft-deleted after a purge."""
        return bool(az_text(*self.detect_argv))


def _rg_segment() -> str:
    """Return the ``/resourceGroups/<name>/`` segment used to match ARM ids."""
    return f"/resourceGroups/{SETTINGS.resource_group}/"


def _originated_here(arm_id: object) -> bool:
    """Return True when an ARM id names this deployment's resource group."""
    if not isinstance(arm_id, str):
        return False
    return _rg_segment().lower() in arm_id.lower()


def _arm_id_segment(arm_id: str, key: str) -> str:
    """Return the path segment following *key* in an ARM id, or "" when absent."""
    segments = arm_id.strip("/").split("/")
    if key in segments:
        index = segments.index(key) + 1
        if index < len(segments):
            return segments[index]
    return ""


def find_soft_deleted_blockers() -> list[SoftDeletedBlocker]:
    """Enumerate every soft-deleted name collision from THIS resource group.

    Key Vault, App Configuration, API Management and Cognitive Services (the
    Azure AI Foundry account a managed agents model handle provisions)
    soft-delete to a SUBSCRIPTION scope, so a same-named remnant survives a
    resource-group delete and blocks a fresh deploy with NameUnavailable /
    AlreadyExistsInSoftDeletedState. Every remnant still records its original
    resource group in its ARM id, so filtering on that segment covers a project
    with more than one vault or store -- and a name that has since changed --
    where a single-name probe silently misses it, while never touching another
    project's residue.
    """
    blockers: list[SoftDeletedBlocker] = []
    tls_vault_name = apim_tls_vault_name()
    for vault in az_json_list(
        "keyvault",
        "list-deleted",
        "--query",
        "[].{name:name,id:properties.vaultId}",
        "-o",
        "json",
        "--only-show-errors",
    ):
        if not _originated_here(vault.get("id")):
            continue
        name = str(vault.get("name"))
        if name == tls_vault_name:
            # Purge-protected by design and RECOVERED (with its certificate)
            # by provision_apim_tls_certificate_store -- never a blocker to
            # purge.
            continue
        blockers.append(
            SoftDeletedBlocker(
                kind="Key Vault",
                name=name,
                purge_hint=f"az keyvault purge --name {name}",
                recover_hint=f"az keyvault recover --name {name}",
                purge_argv=(
                    "keyvault",
                    "purge",
                    "--name",
                    name,
                    "-o",
                    "none",
                    "--only-show-errors",
                ),
                detect_argv=(
                    "keyvault",
                    "list-deleted",
                    "--query",
                    f"[?name=='{name}'].name",
                    "-o",
                    "tsv",
                    "--only-show-errors",
                ),
            )
        )
    # The resource-group-bearing field for a soft-deleted App Configuration
    # store is configurationStoreId (the original store's ARM id). Its own `id`
    # is the location-scoped '.../deletedConfigurationStores/<name>' path, which
    # has NO /resourceGroups/ segment -- filtering on it would skip every store.
    for store in az_json_list(
        "appconfig",
        "list-deleted",
        "--query",
        "[].{name:name,id:configurationStoreId}",
        "-o",
        "json",
        "--only-show-errors",
    ):
        if not _originated_here(store.get("id")):
            continue
        name = str(store.get("name"))
        blockers.append(
            SoftDeletedBlocker(
                kind="App Configuration store",
                name=name,
                purge_hint=f"az appconfig purge --name {name}",
                recover_hint=f"az appconfig recover --name {name}",
                purge_argv=(
                    "appconfig",
                    "purge",
                    "--name",
                    name,
                    "--yes",
                    "--only-show-errors",
                ),
                detect_argv=(
                    "appconfig",
                    "list-deleted",
                    "--query",
                    f"[?name=='{name}'].name",
                    "-o",
                    "tsv",
                    "--only-show-errors",
                ),
            )
        )
    for service in az_json_list(
        "apim",
        "deletedservice",
        "list",
        "--query",
        "[].{name:name,loc:location,id:serviceId}",
        "-o",
        "json",
        "--only-show-errors",
    ):
        if not _originated_here(service.get("id")):
            continue
        name = str(service.get("name"))
        location = str(service.get("loc"))
        blockers.append(
            SoftDeletedBlocker(
                kind="API Management service",
                name=name,
                purge_hint=(
                    f"az apim deletedservice purge --service-name {name} "
                    f'--location "{location}"'
                ),
                recover_hint=(
                    "redeploy with the same name to restore it (APIM recover is "
                    "implicit on create)"
                ),
                purge_argv=(
                    "apim",
                    "deletedservice",
                    "purge",
                    "--service-name",
                    name,
                    "--location",
                    location,
                    "-o",
                    "none",
                    "--only-show-errors",
                ),
                detect_argv=(
                    "apim",
                    "deletedservice",
                    "list",
                    "--query",
                    f"[?name=='{name}'].name",
                    "-o",
                    "tsv",
                    "--only-show-errors",
                ),
            )
        )
    # A soft-deleted Cognitive Services account is addressed by a
    # location-scoped id ('.../locations/<region>/resourceGroups/<group>/
    # deletedAccounts/<name>') that DOES carry the original resource-group
    # segment; the region and group the purge needs are read from that same
    # id, never from a display-name `location` field.
    for account in az_json_list(
        "cognitiveservices",
        "account",
        "list-deleted",
        "--query",
        "[].{name:name,id:id}",
        "-o",
        "json",
        "--only-show-errors",
    ):
        arm_id = account.get("id")
        if not _originated_here(arm_id):
            continue
        name = str(account.get("name"))
        region = _arm_id_segment(str(arm_id), "locations")
        group = _arm_id_segment(str(arm_id), "resourceGroups")
        blockers.append(
            SoftDeletedBlocker(
                kind="Azure AI Foundry account",
                name=name,
                purge_hint=(
                    f"az cognitiveservices account purge --name {name} "
                    f"--resource-group {group} --location {region}"
                ),
                recover_hint=(
                    f"az cognitiveservices account recover --name {name} "
                    f"--resource-group {group} --location {region}"
                ),
                purge_argv=(
                    "cognitiveservices",
                    "account",
                    "purge",
                    "--name",
                    name,
                    "--resource-group",
                    group,
                    "--location",
                    region,
                    "-o",
                    "none",
                    "--only-show-errors",
                ),
                detect_argv=(
                    "cognitiveservices",
                    "account",
                    "list-deleted",
                    "--query",
                    f"[?name=='{name}'].name",
                    "-o",
                    "tsv",
                    "--only-show-errors",
                ),
            )
        )
    return blockers


def clear_soft_deleted_blockers() -> None:
    """Purge (or report) every soft-deleted name collision blocking this deploy.

    A same-name collision is nearly always the operator's own teardown residue,
    so by default every blocker is purged and each purge is verified with a
    name-scoped re-query before continuing. Azure's purge protection is the real
    safety net for resources that must not be purged (typically production): a
    purge-protected vault or store REJECTS the purge, is therefore still present
    at the verify step, and fails preflight loud with its own recover/purge
    hints -- a human must recover it or wait out the retention window.
    ``NO_PURGE`` / ``--no-purge`` restores the conservative behavior: report
    every blocker with hints and purge nothing.

    Raises:
        DeployError: When blockers remain (all of them under no-purge; the
            purge-protected ones otherwise). The FULL list is reported at once,
            never one at a time.
    """
    item1("soft-deleted name collisions")
    blockers = find_soft_deleted_blockers()
    if blockers and SETTINGS.no_purge:
        lines: list[str] = []
        for blocker in blockers:
            lines.extend(blocker.describe())
        raise DeployError(
            f"{len(blockers)} soft-deleted resource(s) of the same name will "
            f"block deployment (NameUnavailable / "
            f"AlreadyExistsInSoftDeletedState). Purge ALL of them (or recover), "
            f"then re-run -- or drop the no-purge flag to let preflight purge "
            f"every blocking collision automatically:\n" + "\n".join(lines)
        )
    still_blocking: list[SoftDeletedBlocker] = []
    for blocker in blockers:
        note(
            f"purging soft-deleted {blocker.kind} '{blocker.name}' (same-name "
            f"teardown residue blocks redeploy; purge-protected resources are "
            f"never purged -- Azure rejects the attempt)"
        )
        blocker.purge()
        if blocker.still_present():
            still_blocking.append(blocker)
    if still_blocking:
        lines = []
        for blocker in still_blocking:
            lines.extend(blocker.describe())
        raise DeployError(
            f"{len(still_blocking)} soft-deleted resource(s) rejected purge and "
            f"still block deployment (NameUnavailable / "
            f"AlreadyExistsInSoftDeletedState). This is Azure's purge protection "
            f"(typically production) -- a human must recover the resource or wait "
            f"out the retention window:\n" + "\n".join(lines)
        )
    ok("no blocking soft-deleted vaults/stores/gateways/accounts")


def reconcile_diagnostic_settings() -> None:
    """Delete diagnostic settings stranded on a surviving resource by a rename.

    ARM incremental deploys never delete a diagnostic setting renamed OUT of
    the template, so when a setting's name changes between generator versions
    while its target resource survives, the OLD setting lingers. Azure permits
    only one diagnostic setting per (resource, category, workspace sink), so the
    stranded setting keeps its sink reservation and the next deploy fails with
    "Data sink '<workspace>' is already used in diagnostic setting '<old-name>'".

    A setting is removed only when all three gates hold: it carries this
    generator's naming signature, it sinks to a Log Analytics workspace in THIS
    resource group, and it is NOT in the expected set. A hand-authored or
    third-party setting therefore is never touched.

    The sink is matched on the resource-group segment of the setting's
    workspaceId, NOT on a workspace that exists right now: the orphan routinely
    points at a workspace that was torn down (soft-deleted) while its namespace
    survived, and that workspace is recreated -- same id -- DURING this deploy,
    which is exactly what reactivates the stale reservation. Gating on a
    currently-existing workspace would skip the one orphan that must be cleared.
    """
    manifest_path = PROJECT_ROOT / "infra" / "diagnostic-settings.json"
    if not manifest_path.is_file():
        return
    if az_text("group", "exists", "--name", SETTINGS.resource_group) != "true":
        return
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as error:
        raise DeployError(
            f"Could not parse '{manifest_path}': {error}. It lists the "
            f"diagnostic settings this deployment owns; without it the "
            f"stranded-setting reconcile cannot tell an orphan from a current "
            f"setting. Re-generate the project to restore the file."
        ) from error
    settings = manifest.get("settings") if isinstance(manifest, dict) else None
    if not settings:
        return

    item1("diagnostic-setting reconcile (clear renamed-away orphans)")
    suffix = f"-diag-{SETTINGS.environment}"
    expected = {
        f"{entry.get('settingName')}-{SETTINGS.environment}" for entry in settings
    }
    resource_types = sorted(
        {str(entry.get("resourceType", "")).split("@")[0] for entry in settings}
    )
    sink_segment = (
        f"/resourceGroups/{SETTINGS.resource_group}/providers/"
        f"Microsoft.OperationalInsights/workspaces/"
    ).lower()

    removed = 0
    for resource_type in resource_types:
        if not resource_type:
            continue
        for resource_id in az_lines(
            "resource",
            "list",
            "--resource-group",
            SETTINGS.resource_group,
            "--resource-type",
            resource_type,
            "--query",
            "[].id",
            "-o",
            "tsv",
            "--only-show-errors",
        ):
            removed += _remove_stranded_settings(
                resource_id, suffix, expected, sink_segment
            )
    if removed:
        ok(f"removed {removed} stranded diagnostic setting(s)")
    else:
        ok("no stranded diagnostic settings")


def _remove_stranded_settings(
    resource_id: str, suffix: str, expected: set[str], sink_segment: str
) -> int:
    """Remove stranded diagnostic settings from one resource; return the count."""
    removed = 0
    for setting in az_json_list(
        "monitor",
        "diagnostic-settings",
        "list",
        "--resource",
        resource_id,
        "--query",
        "[].{name:name,ws:workspaceId}",
        "-o",
        "json",
        "--only-show-errors",
    ):
        name = str(setting.get("name") or "")
        workspace = str(setting.get("ws") or "")
        if not name.endswith(suffix):
            continue  # not this generator's naming signature
        if name in expected:
            continue  # a current setting, keep it
        if sink_segment not in workspace.lower():
            continue  # sink is not a workspace in THIS resource group
        sub(
            f"removing stranded diagnostic setting '{name}' (renamed out of the "
            f"template; it reserves the workspace sink and blocks redeploy)"
        )
        result = az(
            "monitor",
            "diagnostic-settings",
            "delete",
            "--name",
            name,
            "--resource",
            resource_id,
            "-o",
            "none",
            "--only-show-errors",
        )
        if result.succeeded:
            removed += 1
        else:
            note(
                f"could not delete stranded diagnostic setting '{name}' on "
                f"'{resource_id}'; remove it manually: az monitor "
                f"diagnostic-settings delete --name '{name}' --resource "
                f"'{resource_id}'"
            )
    return removed


#: Manifest of the Service Bus subscriptions this template declares, per topic,
#: written at generation time from the rendered Bicep modules (see
#: ``generators/servicebus_subscription_manifest.py``).
_SERVICEBUS_MANIFEST_PATH = PROJECT_ROOT / "infra" / "servicebus-subscriptions.json"


def _servicebus_expected_subscriptions() -> dict[str, set[str]]:
    """Return ``{topic_name: {subscription_name, …}}`` from the manifest.

    Empty when this deployment provisions no Service Bus topic at all.

    Raises:
        DeployError: If the manifest exists but cannot be read or parsed, or
            carries an entry without a topic name. The reconcile DELETES, so an
            unreadable manifest must never degrade to an empty expected set --
            that would make every live subscription on every managed topic look
            like an orphan.
    """
    if not _SERVICEBUS_MANIFEST_PATH.is_file():
        return {}
    try:
        manifest = json.loads(_SERVICEBUS_MANIFEST_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        raise DeployError(
            f"Could not read '{_SERVICEBUS_MANIFEST_PATH}': {error}. It lists the "
            f"Service Bus subscriptions this deployment declares; without it the "
            f"orphan reconcile cannot tell an orphan from a live subscription, so "
            f"it refuses to run rather than delete on a guess. Re-generate the "
            f"project to restore the file."
        ) from error
    topics = manifest.get("topics") if isinstance(manifest, dict) else None
    if not topics:
        return {}
    expected: dict[str, set[str]] = {}
    for entry in topics:
        topic_name = str(entry.get("topicName") or "")
        if not topic_name:
            raise DeployError(
                f"'{_SERVICEBUS_MANIFEST_PATH}' has a topic entry with no "
                f"'topicName'. Re-generate the project."
            )
        expected[topic_name] = {str(name) for name in entry.get("subscriptions", [])}
    return expected


def _servicebus_az_json(*args: str) -> list[dict[str, object]]:
    """Run an az command expected to return a JSON array, failing loud.

    ``az_json_list`` degrades a failed call to ``[]``, which is right for its
    read-only callers and wrong here: this list feeds a DELETION decision, so an
    empty result means "this topic has no subscriptions". Swallowing an error
    would report "no orphans found" for a sweep that never looked -- a clean
    bill of health produced by a broken command, indistinguishable in the log
    from a real one.

    Raises:
        DeployError: If the command failed or its output is not a JSON array.
    """
    result = az(*args)
    if not result.succeeded:
        raise DeployError(
            f"'az {' '.join(args)}' failed while reconciling Service Bus "
            f"subscriptions: {result.output}. The reconcile cannot tell an "
            f"orphan from a live subscription without this listing, so it stops "
            f"rather than reporting a clean sweep it did not perform."
        )
    if not result.stdout:
        return []
    try:
        parsed = json.loads(result.stdout)
    except json.JSONDecodeError as error:
        raise DeployError(
            f"'az {' '.join(args)}' returned output that is not JSON while "
            f"reconciling Service Bus subscriptions: {error}."
        ) from error
    if not isinstance(parsed, list):
        raise DeployError(
            f"'az {' '.join(args)}' returned {type(parsed).__name__}, expected a "
            f"JSON array, while reconciling Service Bus subscriptions."
        )
    return parsed


def _servicebus_az_names(*args: str) -> list[str]:
    """Run an az command listing names as TSV, failing loud on a failed call.

    Same reasoning as :func:`_servicebus_az_json`: an empty result is a
    meaningful answer, so it must never also be what a failed command looks like.

    Raises:
        DeployError: If the command failed.
    """
    result = az(*args)
    if not result.succeeded:
        raise DeployError(
            f"'az {' '.join(args)}' failed while reconciling Service Bus "
            f"subscriptions: {result.output}."
        )
    return [line.strip() for line in result.stdout.splitlines() if line.strip()]


def _reconcile_servicebus_topic(
    namespace: str, topic: str, expected: set[str]
) -> tuple[int, int]:
    """Delete this topic's subscriptions the template no longer declares.

    Returns ``(inspected, removed)``. The inspected count is reported so a
    "no orphans" result is distinguishable from a sweep that examined nothing.
    """
    removed = 0
    inspected = 0
    for subscription in _servicebus_az_json(
        "servicebus",
        "topic",
        "subscription",
        "list",
        "--resource-group",
        SETTINGS.resource_group,
        "--namespace-name",
        namespace,
        "--topic-name",
        topic,
        "--query",
        "[].{name:name,active:countDetails.activeMessageCount}",
        "-o",
        "json",
        "--only-show-errors",
    ):
        name = str(subscription.get("name") or "")
        if not name:
            continue
        inspected += 1
        if name in expected:
            continue
        sub(
            f"removing orphaned Service Bus subscription '{name}' on topic "
            f"'{topic}' (backlog {subscription.get('active')} message(s); the "
            f"template no longer declares it, and every message published to "
            f"the topic is still copied into it)"
        )
        result = az(
            "servicebus",
            "topic",
            "subscription",
            "delete",
            "--resource-group",
            SETTINGS.resource_group,
            "--namespace-name",
            namespace,
            "--topic-name",
            topic,
            "--name",
            name,
            "-o",
            "none",
            "--only-show-errors",
        )
        if result.succeeded:
            removed += 1
        else:
            sub(
                f"could not remove orphaned subscription '{name}' on topic "
                f"'{topic}': {result.output}"
            )
    return inspected, removed


def reconcile_servicebus_subscriptions() -> None:
    """Delete Service Bus subscriptions this template no longer declares.

    An ARM incremental deploy creates and updates what the template declares and
    NEVER deletes what it stopped declaring. A subscription a superseded
    generator version provisioned therefore survives every later deploy -- and
    it is not inert: Service Bus copies every message published to a topic into
    EVERY subscription on that topic, so an orphan accrues a full copy of the
    topic's traffic with nothing consuming it until each message reaches the
    namespace TTL, while consuming the tier's per-topic subscription quota and
    the namespace entity quota.

    Scope is the TOPIC set the manifest names, never the namespace: a pooled
    namespace hosts several members' topics, and a namespace may hold entities
    this deployment does not own. A topic absent from the manifest is left
    entirely alone.
    """
    expected = _servicebus_expected_subscriptions()
    if not expected:
        return
    item1("Service Bus subscription reconcile (remove template-orphaned entities)")
    removed = 0
    inspected = 0
    reconciled_topics = 0
    for namespace in _servicebus_az_names(
        "servicebus",
        "namespace",
        "list",
        "--resource-group",
        SETTINGS.resource_group,
        "--query",
        "[].name",
        "-o",
        "tsv",
        "--only-show-errors",
    ):
        for topic in _servicebus_az_names(
            "servicebus",
            "topic",
            "list",
            "--resource-group",
            SETTINGS.resource_group,
            "--namespace-name",
            namespace,
            "--query",
            "[].name",
            "-o",
            "tsv",
            "--only-show-errors",
        ):
            if topic not in expected:
                continue  # not a topic this deployment declares
            reconciled_topics += 1
            topic_inspected, topic_removed = _reconcile_servicebus_topic(
                namespace, topic, expected[topic]
            )
            inspected += topic_inspected
            removed += topic_removed
    # The census, not the verdict: "no orphans" over 0 inspected subscriptions
    # and "no orphans" over 34 are entirely different results, and a log line
    # that cannot tell them apart is what lets a broken sweep read as a clean one.
    if reconciled_topics != len(expected):
        sub(
            f"{len(expected) - reconciled_topics} declared topic(s) were not "
            f"found in this resource group and were not reconciled"
        )
    ok(
        f"Service Bus reconcile: {inspected} subscription(s) inspected across "
        f"{reconciled_topics}/{len(expected)} declared topic(s), "
        f"{removed} orphan(s) removed"
    )


def preflight(
    param_file: str,
    *,
    run_what_if: bool = True,
    skip_reason: str = "",
) -> None:
    """Run the cheap checks that catch the biggest blockers before provisioning.

    Covers unregistered providers, soft-deleted name collisions, stranded
    diagnostic settings, and (when ``run_what_if`` is True) template errors via
    what-if. It does NOT catch offer/quota restrictions -- the foundation stage
    exists for that class.

    Args:
        param_file: The ``.bicepparam`` this run will deploy; what-if previews it.
        run_what_if: False when the infra-hash stamp already proves this exact
            template converged in this resource group -- provider registration,
            soft-delete purge, and diagnostic-settings reconcile still run (they
            guard operator-side state, not template state); only the advisory
            what-if is skipped.
        skip_reason: Operator-facing note explaining why what-if was skipped.
            Required (non-empty) whenever run_what_if is False.
    """
    step("Preflight checks (before any provisioning)")
    register_required_providers()
    clear_soft_deleted_blockers()
    # Clear settings stranded by a rename BEFORE the deploy tries to (re)create
    # them: a stranded setting reserves the workspace sink and makes the create
    # fail with a "Data sink ... is already used" conflict.
    reconcile_diagnostic_settings()

    if not run_what_if:
        note(skip_reason)
        return

    # what-if is ADVISORY only. Template correctness is already gated by
    # 'az bicep build' (fatal) before this runs. what-if's incremental
    # prediction can fail with DeploymentWhatIfResourceError against
    # existing/partial state -- a known engine limitation, not a template error
    # -- so it must never block the deploy. The real deployment reports real
    # errors, and offer/quota limits surface in the foundation stage, not here.
    item1("what-if validation (advisory)")
    result = az(
        "deployment",
        "group",
        "what-if",
        "--resource-group",
        SETTINGS.resource_group,
        "--parameters",
        param_file,
        "--no-pretty-print",
        "-o",
        "none",
        "--only-show-errors",
    )
    if result.succeeded:
        ok("template validated (what-if).")
    else:
        note(
            f"what-if could not predict all changes (likely a known what-if "
            f"limitation against existing/partial state, not a template error). "
            f"Template correctness was already validated by 'az bicep build'. "
            f"Proceeding -- the actual deployment reports real errors. Detail: "
            f"{result.output}"
        )


# ---------------------------------------------------------------------------
# Wave dispatch
# ---------------------------------------------------------------------------


def run_deploy_wave(
    wave_size: int,
    action: Callable[[int, Service], None],
    services: Sequence[Service],
) -> None:
    """Run ``action`` once per service, at most ``wave_size`` at a time.

    Each item's console output is buffered and replayed in list order once its
    wave completes, so concurrent pushes do not interleave their progress lines
    into an unreadable stream.

    Fails loud: if ANY item raises, the whole wave -- and therefore the leg --
    stops with that item's own message, and no later wave is dispatched.

    Args:
        wave_size: Maximum number of items running concurrently. 1 means
            strictly one at a time.
        action: Callable invoked as ``action(one_based_index, service)``.
        services: The services to process, in report order.

    Raises:
        DeployError: If ``wave_size`` is not positive, or any item failed.
    """
    if wave_size < 1:
        raise DeployError(
            f"Wave size must be at least 1, got {wave_size}. It bounds how many "
            f"pushes run concurrently."
        )
    for offset in range(0, len(services), wave_size):
        batch = list(enumerate(services[offset : offset + wave_size], offset + 1))
        with concurrent.futures.ThreadPoolExecutor(max_workers=len(batch)) as pool:
            futures = [
                (service, pool.submit(_run_wave_item, action, index, service))
                for index, service in batch
            ]
        for service, future in futures:
            lines, failure = future.result()
            for line in lines:
                emit(line)
            if failure is not None:
                raise DeployError(
                    f"Wave dispatch failed for '{service.display_name}': {failure}"
                )


def _run_wave_item(
    action: Callable[[int, Service], None], index: int, service: Service
) -> tuple[list[str], str | None]:
    """Run one wave item with its console output captured.

    Returns:
        The item's buffered output lines, and its failure message (``None`` when
        the item succeeded).
    """
    buffer: list[str] = []
    OUTPUT.local.buffer = buffer
    try:
        action(index, service)
        return buffer, None
    except DeployError as error:
        return buffer, str(error)
    except OSError as error:
        return buffer, f"{type(error).__name__}: {error}"
    finally:
        OUTPUT.local.buffer = None


# ---------------------------------------------------------------------------
# Post-deploy verification
# ---------------------------------------------------------------------------


def poll_health_endpoint(
    url: str,
    timeout_seconds: int,
    poll_interval_seconds: int = VERIFY_POLL_INTERVAL_SECONDS,
) -> tuple[bool, str]:
    """Poll ``url`` with ``urllib`` until it answers HTTP 200 or the budget expires.

    Takes a fully-formed URL and carries no Azure-specific knowledge, which is
    what makes it directly testable against a real local HTTP server.

    Args:
        url: The full URL to GET, including scheme.
        timeout_seconds: Total budget to keep retrying.
        poll_interval_seconds: Delay between retries.

    Returns:
        ``(True, "ready (<url>)")`` on a 200 within budget; otherwise
        ``(False, "<last observed status or error> (<url>)")``.
    """
    deadline = time.monotonic() + timeout_seconds
    last_detail = "never answered"
    while True:
        try:
            with urllib.request.urlopen(
                url, timeout=VERIFY_REQUEST_TIMEOUT_SECONDS
            ) as response:
                if response.status == 200:
                    return True, f"ready ({url})"
                last_detail = f"HTTP {response.status}"
        except urllib.error.HTTPError as error:
            last_detail = f"HTTP {error.code}"
        except (urllib.error.URLError, OSError) as error:
            last_detail = str(error)
        if time.monotonic() >= deadline:
            return False, f"{last_detail} ({url})"
        time.sleep(poll_interval_seconds)


#: ARM metric carrying App Service's own health-check verdict. The platform
#: probes each instance's health-check route from INSIDE App Service and
#: aggregates the result as a percentage of healthy instances, so 100 means
#: every connected instance answered 2xx. Read on the ARM plane, this needs no
#: network path to the app at all -- which is the point: under a restricted
#: posture there is no route from anywhere the deploy runs.
WEB_APP_HEALTH_METRIC = "HealthCheckStatus"

#: The metric value meaning "every instance healthy". It is a percentage, even
#: though the metric definition declares its unit as ``Count``.
WEB_APP_HEALTHY_METRIC_VALUE = 100.0

#: Time grain to request. Azure publishes this metric at a 5-minute grain at the
#: finest and REJECTS anything finer outright rather than returning coarser
#: data: ``--interval PT1M`` answers ``BadRequest: Commonly allowed time grains:
#: 00:05:00,01:00:00,1.00:00:00``, which fails the query itself. Only a grain
#: this metric actually publishes may go here.
WEB_APP_HEALTH_METRIC_GRAIN = "PT5M"

#: How recent the newest reported bucket must be to count as a verdict on the
#: container THIS deploy placed. The query's lookback window spans an hour, so
#: without this bound a bucket recorded by the PREVIOUS container can vouch for
#: a replacement that never started -- the check would pass in precisely the
#: case it exists to catch. Three grains, so ordinary aggregation and ingestion
#: lag never reads as staleness.
WEB_APP_HEALTH_METRIC_MAX_AGE_SECONDS = 900


class HealthMetricReading(NamedTuple):
    """One reading of the platform's health verdict for a site.

    The outcomes are kept distinct deliberately. Collapsing "the query failed"
    into "the metric reported nothing" is what once let a malformed ``--interval``
    argument be reported to the operator as *"the site never came up"*: every
    query failed, and the script rendered its own broken argument as a
    confident claim about the application that it had never actually learned.
    A failed query attests nothing, and must never be phrased as if it did.
    """

    #: Newest health percentage, or None when the platform published none.
    percent: float | None
    #: Age of that reading in seconds; None when there is no reading.
    age_seconds: float | None
    #: Non-empty when the QUERY failed -- ``percent`` carries no meaning then.
    query_error: str


def _parse_metric_timestamp(raw: object) -> dt.datetime | None:
    """Parse an ARM metric ``timeStamp`` (ISO 8601, ``Z``-suffixed) if valid."""
    if not isinstance(raw, str):
        return None
    try:
        return dt.datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return None


def _read_health_metric(web_app: str) -> HealthMetricReading:
    """Read the newest health-check verdict Azure has published for one site.

    Returns:
        A reading whose ``query_error`` is non-empty when the query itself
        failed, whose ``percent`` is None when the query succeeded but the
        platform has published no verdict, and which otherwise carries the
        newest value together with its age.
    """
    result = az(
        "monitor",
        "metrics",
        "list",
        "--resource",
        web_app,
        "--resource-group",
        SETTINGS.resource_group,
        "--resource-type",
        "Microsoft.Web/sites",
        "--metric",
        WEB_APP_HEALTH_METRIC,
        "--aggregation",
        "Average",
        "--interval",
        WEB_APP_HEALTH_METRIC_GRAIN,
        "-o",
        "json",
        "--only-show-errors",
    )
    if not result.succeeded:
        return HealthMetricReading(
            None, None, result.stderr or f"az exited {result.returncode}"
        )
    try:
        payload = json.loads(result.stdout or "{}")
    except json.JSONDecodeError:
        return HealthMetricReading(None, None, "az returned output that is not JSON")
    points: list[tuple[dt.datetime, float]] = [
        (stamp, float(point["average"]))
        for series in payload.get("value", [])
        for block in series.get("timeseries", [])
        for point in block.get("data", [])
        if point.get("average") is not None
        and (stamp := _parse_metric_timestamp(point.get("timeStamp"))) is not None
    ]
    if not points:
        return HealthMetricReading(None, None, "")
    newest_at, newest_value = max(points)
    age = (dt.datetime.now(dt.timezone.utc) - newest_at).total_seconds()
    return HealthMetricReading(newest_value, age, "")


def _unhealthy_web_app_detail(web_app: str, reading: HealthMetricReading) -> str:
    """Explain a failed verification strictly in terms of what was observed.

    Each branch states only what the reading actually establishes. In
    particular a failed query is reported as a failure to verify -- never as a
    finding about the application.
    """
    if reading.query_error:
        return (
            f"could not read {WEB_APP_HEALTH_METRIC} for '{web_app}' -- "
            f"verification did not run, and this says NOTHING about whether the "
            f"app is healthy. az reported: {reading.query_error}"
        )
    if reading.percent is None:
        return (
            f"{WEB_APP_HEALTH_METRIC} reported no data for '{web_app}' within "
            f"the budget -- the site never came up far enough for App Service "
            f"to record a health verdict"
        )
    if (
        reading.age_seconds is not None
        and reading.age_seconds > WEB_APP_HEALTH_METRIC_MAX_AGE_SECONDS
    ):
        return (
            f"the newest {WEB_APP_HEALTH_METRIC} verdict for '{web_app}' is "
            f"{reading.age_seconds / 60:.0f}m old -- it predates this deployment, "
            f"so it cannot vouch for the container now configured"
        )
    return (
        f"{WEB_APP_HEALTH_METRIC} {reading.percent:.0f}% for '{web_app}' "
        f"(expected {WEB_APP_HEALTHY_METRIC_VALUE:.0f}%) -- instances are "
        f"failing their health-check route"
    )


def verify_site_via_arm(web_app: str) -> tuple[bool, str]:
    """Confirm one deployed site is serving, using App Service's own health verdict.

    Used for a web app under any restricted ingress posture -- which is every
    posture except a fully public one. There, no HTTP probe can work from where
    the deploy runs: the app admits only the callers the system creates (the
    managed gateway and the peer services' subnet), and under private-by-default
    it has no public path at all. Rather than manufacture a network route for the
    deployer, this reads the verdict the platform already produces from inside
    App Service. A worker site, whose public access is always disabled, is
    verified this way under every posture.

    That is a real check, not a formality: the platform probes the site's
    health-check route on every instance and reports the percentage answering
    2xx, so a container that never started, crash-loops, or serves errors cannot
    report 100.

    It attests the LIVENESS route App Service is configured to probe, not the
    dependency-gated readiness route -- a deliberate trade, since the readiness
    route is unreachable from here by construction.

    A verdict counts only when it is recent enough to describe the container
    this deploy configured -- see ``WEB_APP_HEALTH_METRIC_MAX_AGE_SECONDS``.

    Returns:
        ``(True, detail)`` once the site reports every instance healthy;
        ``(False, detail)`` when it never does within the budget, phrased
        strictly in terms of what was observed.
    """
    deadline = time.monotonic() + SETTINGS.verify_timeout_seconds
    while True:
        reading = _read_health_metric(web_app)
        if (
            not reading.query_error
            and reading.percent is not None
            and reading.age_seconds is not None
            and reading.percent >= WEB_APP_HEALTHY_METRIC_VALUE
            and reading.age_seconds <= WEB_APP_HEALTH_METRIC_MAX_AGE_SECONDS
        ):
            return True, f"healthy ({WEB_APP_HEALTH_METRIC} {reading.percent:.0f}%)"
        if time.monotonic() >= deadline:
            return False, _unhealthy_web_app_detail(web_app, reading)
        time.sleep(VERIFY_POLL_INTERVAL_SECONDS)


def verify_one_web_app(service: Service) -> tuple[bool, str]:
    """Resolve one web app's hostname and poll its readiness route.

    Used only when the deploy host is an admitted caller -- an unrestricted
    (``public``) ingress posture. Every other posture verifies through
    :func:`verify_site_via_arm`.

    The readiness route is identical whether the site runs pushed code or a
    container image, so this deliberately does not special-case
    ``CONTAINER_MODE`` -- 'verify' only cares about the running site's own
    HTTP behavior.

    Returns:
        ``(True, detail)`` when the app answered 200 within budget;
        ``(False, detail)`` otherwise, or when the hostname could not be
        resolved at all.
    """
    web_app = f"{service.web_app_name}-{SETTINGS.environment}"
    host = az_text(
        "webapp",
        "show",
        "--resource-group",
        SETTINGS.resource_group,
        "--name",
        web_app,
        "--query",
        "defaultHostName",
        "-o",
        "tsv",
        "--only-show-errors",
    )
    if not host:
        return False, f"could not resolve the hostname of '{web_app}'"
    url = f"{WEB_APP_PROBE_SCHEME}://{host}{service.health_check_path}"
    return poll_health_endpoint(url, SETTINGS.verify_timeout_seconds)


def _deployed_function_names(function_app: str) -> set[str]:
    """The function names Azure lists for a deployed Function App.

    ``az functionapp function list`` names each function ``<app>/<function>``;
    the part after the ``/`` is the name the adapter registered.

    Raises:
        DeployError: A listed function carries no string ``name``.
    """
    listing = az_json_list(
        "functionapp",
        "function",
        "list",
        "-n",
        function_app,
        "-g",
        SETTINGS.resource_group,
        "-o",
        "json",
        "--only-show-errors",
    )
    names: set[str] = set()
    for entry in listing:
        name = entry.get("name")
        if not isinstance(name, str):
            raise DeployError(
                f"'az functionapp function list' for '{function_app}' returned a "
                f"function with no string 'name' ({entry!r}); expected "
                "'<app>/<function>'. Update the Azure CLI and retry."
            )
        names.add(name.rsplit("/", 1)[-1])
    return names


def verify_one_function_app(service: Service) -> tuple[bool, str]:
    """Poll until Azure lists EXACTLY the function names the service's package registers.

    Set equality is required, not a count: a partial index load (some functions
    present, some not) and a stray function (a name nothing generated) are
    exactly the failures this check exists to catch, and a count cannot tell a
    renamed function from the right one.

    Returns:
        ``(True, detail)`` when the listed set equals ``service.function_names``
        within budget; ``(False, detail)`` naming the missing and the unexpected
        names otherwise.
    """
    function_app = f"{service.function_app_name}-{SETTINGS.environment}"
    expected = set(service.function_names)
    deadline = time.monotonic() + SETTINGS.verify_timeout_seconds
    while True:
        observed = _deployed_function_names(function_app)
        if observed == expected:
            return True, f"{len(observed)}/{len(expected)} functions indexed"
        if time.monotonic() >= deadline:
            missing = sorted(expected - observed)
            unexpected = sorted(observed - expected)
            return False, (
                f"deployed function set differs from the generated package: "
                f"missing {missing}, unexpected {unexpected}"
            )
        time.sleep(VERIFY_POLL_INTERVAL_SECONDS)


# ---------------------------------------------------------------------------
# Local pre-deploy validation
# ---------------------------------------------------------------------------


def invoke_code_validation() -> None:
    """Build every service package and resolve every requirement set, locally.

    Runs BEFORE any cloud resource is touched, so a broken package or an
    unresolvable/conflicting dependency fails in seconds -- with the FULL list
    of offenders -- instead of surfacing one at a time after a long
    infrastructure deploy and a per-service cloud build. Dependency resolution
    runs on the deploy host: it catches missing packages, nonexistent versions,
    and conflicts. It is not a full Linux build (only the server-side build
    performs that), so it is a fast pre-check, not a guarantee.

    Raises:
        DeployError: Listing every problem found. No cloud resource is touched.
    """
    step("Pre-deploy validation (local: service builds + dependency resolution)")
    failures: list[str] = []
    wheel_dir = SETTINGS.build_dir / "validation-wheels"
    shutil.rmtree(wheel_dir, ignore_errors=True)
    wheel_dir.mkdir(parents=True, exist_ok=True)
    try:
        # Only a manifest-resolved payload is built into a package and resolved
        # here; a PREBUILT payload is validated by its own build steps, which
        # run before anything is pushed.
        for service in manifest_resolved_services():
            failures.extend(_validate_service_build(service, wheel_dir))
        for service in SERVICES:
            # Only a remote-build package ships a dependency manifest the host
            # resolves; a PREBUILT package is resolved by its own build steps.
            if service.function_package_mode != FUNCTION_PACKAGE_REMOTE_BUILD:
                continue
            requirements = (
                Path(service.function_source_dir) / service.function_manifest_file
            )
            if (PROJECT_ROOT / requirements).is_file():
                failure = _validate_requirements(requirements)
                if failure is not None:
                    failures.append(
                        f"[{requirements.as_posix()}] function dependency "
                        f"resolution failed: {failure}"
                    )
    finally:
        shutil.rmtree(wheel_dir, ignore_errors=True)
    if failures:
        rendered = "\n  ".join(failures)
        raise DeployError(
            f"Pre-deploy validation found {len(failures)} problem(s) -- fix them "
            f"before deploying (NO cloud resources were touched):\n  {rendered}"
        )
    ok("Service builds and dependency manifests validated.")


def manifest_resolved_services() -> tuple[Service, ...]:
    """Return the services whose web-app payload resolves a dependency manifest."""
    return tuple(
        service
        for service in SERVICES
        if service.web_package_mode == WEB_PACKAGE_MANIFEST_RESOLVED
    )


def _validate_service_build(service: Service, wheel_dir: Path) -> list[str]:
    """Build one service's wheel and resolve its requirements; return failures."""
    build = pip("wheel", f"./{service.service_dir}", "--no-deps", "-w", str(wheel_dir))
    if not build.succeeded:
        return [f"[{service.service_dir}] wheel build failed: {_tail(build.output)}"]
    requirements = Path(service.service_dir) / service.web_dependency_manifest
    if not (PROJECT_ROOT / requirements).is_file():
        return []
    failure = _validate_requirements(requirements)
    if failure is None:
        return []
    return [f"[{requirements.as_posix()}] dependency resolution failed: {failure}"]


def _validate_requirements(requirements: Path) -> str | None:
    """Dry-run resolve a requirements file; return the error text, or None."""
    result = pip(
        "install",
        "--dry-run",
        "--ignore-installed",
        "--quiet",
        "-r",
        requirements.as_posix(),
    )
    if result.succeeded:
        return None
    return _tail(result.output)


def _tail(text: str, lines: int = 3) -> str:
    """Return the last few lines of command output, joined for one message line."""
    return " ".join(text.splitlines()[-lines:])


# ---------------------------------------------------------------------------
# Shared dependency assembly
# ---------------------------------------------------------------------------


def service_requirements_files() -> list[Path]:
    """Return each distinct manifest-resolved service's dependency manifest, in
    service order -- the manifests the shared dependency layer is built from."""
    seen: set[str] = set()
    files: list[Path] = []
    for service in manifest_resolved_services():
        if service.service_dir in seen:
            continue
        seen.add(service.service_dir)
        files.append(Path(service.service_dir) / service.web_dependency_manifest)
    return files


def _write_union_requirements(
    requirements_files: Sequence[Path], union_file: Path, *, add_greenlet: bool
) -> None:
    """Write the sorted, de-duplicated union of several requirements files.

    Args:
        requirements_files: Files to union.
        union_file: Destination path.
        add_greenlet: When True and the union pulls SQLAlchemy, add an explicit
            ``greenlet`` requirement. pip's cross-platform ``--platform`` install
            does NOT evaluate ``platform_machine`` environment markers for the
            cross target, so a dependency gated purely on that marker is
            silently dropped. SQLAlchemy declares greenlet exactly that way and
            its async engine hard-requires it at runtime -- omitted, the first
            async database connect dies with ``No module named 'greenlet'``.
    """
    lines: set[str] = set()
    for requirements in requirements_files:
        path = PROJECT_ROOT / requirements
        if not path.is_file():
            continue
        for line in path.read_text(encoding="utf-8").splitlines():
            if line.strip():
                lines.add(line)
    if add_greenlet and any(
        re.match(r"^\s*sqlalchemy\b", line, re.IGNORECASE) for line in lines
    ):
        lines.add("greenlet>=1")
    union_file.parent.mkdir(parents=True, exist_ok=True)
    union_file.write_text(
        "".join(f"{line}\n" for line in sorted(lines)), encoding="utf-8"
    )


def build_deploy_wheelhouse(
    wheelhouse_dir: Path, requirements_files: Sequence[Path]
) -> bool:
    """Union-download every service's dependencies once, up front.

    A pure speed accelerator: PyPI always remains the fallback resolver, so a
    failed or partial download costs build time and never correctness. It
    therefore reports what fell back and returns False rather than failing the
    deploy.

    Returns:
        True when the whole union resolved, False when anything fell back.
    """
    wheelhouse_dir.mkdir(parents=True, exist_ok=True)
    union_file = wheelhouse_dir.parent / "union-requirements.txt"
    _write_union_requirements(requirements_files, union_file, add_greenlet=False)
    sub(
        f"building shared dependency wheelhouse (one network pass for "
        f"{len(requirements_files)} requirements file(s))"
    )
    result = pip(
        "download",
        "-r",
        str(union_file),
        "-d",
        str(wheelhouse_dir),
        *pip_cloud_wheel_flags(),
    )
    if result.succeeded:
        ok(f"Shared wheelhouse populated at {wheelhouse_dir}.")
        return True
    unresolved = sorted(
        set(
            re.findall(
                r"(?:No matching distribution found for|Could not find a version that "
                r"satisfies the requirement) (\S+)",
                result.output,
            )
        )
    )
    named = ", ".join(unresolved) if unresolved else "(see the pip output above)"
    note(
        f"Shared wheelhouse build did not resolve every package ({named}) -- "
        f"those packages fall back to PyPI at build time (slower, still "
        f"correct). Continuing."
    )
    return False


def add_service_wheel_subset(
    service_requirements: Path, wheelhouse_dir: Path, stage_dir: Path
) -> None:
    """Resolve one service's dependency subset offline into its staging area.

    Never blocks the deploy: a partial or failed offline resolution logs a note
    and proceeds. ``--no-index`` is NEVER written into the staged
    requirements.txt, so the server-side install still resolves any miss from
    PyPI -- only ``--find-links wheels/`` is prepended.
    """
    wheels_dir = stage_dir / "wheels"
    wheels_dir.mkdir(parents=True, exist_ok=True)
    if wheelhouse_dir.is_dir():
        result = pip(
            "download",
            "-r",
            str(PROJECT_ROOT / service_requirements),
            "-d",
            str(wheels_dir),
            "--no-index",
            "--find-links",
            str(wheelhouse_dir),
            *pip_cloud_wheel_flags(),
        )
        if not result.succeeded:
            note(
                f"Offline wheel subset for '{service_requirements.as_posix()}' is "
                f"incomplete -- the missing packages fall back to PyPI at build "
                f"time (slower, still correct)."
            )
    else:
        note(
            f"No shared wheelhouse available for "
            f"'{service_requirements.as_posix()}' -- every dependency falls back "
            f"to PyPI at build time."
        )
    staged_requirements = stage_dir / "requirements.txt"
    existing = staged_requirements.read_text(encoding="utf-8")
    staged_requirements.write_text(
        f"--find-links wheels/\n{existing}", encoding="utf-8"
    )


def build_deploy_dependency_layer(
    build_dir: Path, requirements_files: Sequence[Path]
) -> Path:
    """Assemble the ONE shared dependency tree every web app mounts.

    Unlike the wheelhouse (a download accelerator PyPI still falls back through
    at build time), this unpacks the actual wheel-only importable tree with
    ``pip install --target``. The tree is LOAD-BEARING: it is uploaded to the
    shared Azure Files share every web app mounts, and the server-side build is
    disabled, so a failed assembly would leave every web app with no importable
    dependencies.

    Returns:
        The assembled tree's directory.

    Raises:
        DeployError: If the assembly fails -- the deploy cannot proceed.
    """
    layer_dir = build_dir / DEPLOYMENT_LAYER_SHARE
    layer_dir.mkdir(parents=True, exist_ok=True)
    union_file = build_dir / "union-dependency-requirements.txt"
    _write_union_requirements(requirements_files, union_file, add_greenlet=True)
    sub(
        f"assembling shared dependency tree (one wheel-only install for "
        f"{len(requirements_files)} requirements file(s))"
    )
    result = pip(
        "install",
        "--target",
        str(layer_dir),
        "-r",
        str(union_file),
        *pip_cloud_wheel_flags(),
    )
    if not result.succeeded:
        raise DeployError(
            f"The shared dependency tree assembly failed -- the web-app deploy "
            f"cannot proceed. This prebuilt tree is uploaded to the shared "
            f"'{DEPLOYMENT_LAYER_SHARE}' Azure Files share, mounted on every web "
            f"app with the server-side build disabled, so every app would start "
            f"with no importable dependencies. Ensure every requirements.txt "
            f"resolves to wheels for Python {DEPENDENCY_RUNTIME_VERSION} on "
            f"Linux. pip reported: {result.output}"
        )
    ok(f"Shared dependency tree assembled at {layer_dir}.")
    return layer_dir


def upload_dependency_layer(layer_dir: Path) -> None:
    """Upload the assembled dependency tree to its Azure Files share, once.

    Every Python web app mounts this share read-shared and imports from it, so
    the tree is NOT copied into any per-app zip: an earlier tree-in-each-zip
    approach could not survive the deployment service's parallel sync of the
    union tree onto the App Service file mount at real scale. The share
    delivers the tree exactly once instead.

    The storage account NAME is resolved from the infrastructure deployment's
    own output rather than a generator-baked literal, so the deploy host never
    carries a second, independently-derived copy that can drift from what the
    Bicep actually created.

    Raises:
        DeployError: If the account name or key cannot be resolved, or the
            upload fails -- every web app mounts this share, so the deploy
            cannot proceed without it.
    """
    account_result = az(
        "deployment",
        "group",
        "show",
        "--resource-group",
        SETTINGS.resource_group,
        "--name",
        LAST_STAGE_DEPLOYMENT_NAME,
        "--query",
        "properties.outputs.deploymentLayerStorageAccountName.value",
        "-o",
        "tsv",
        "--only-show-errors",
    )
    if not account_result.succeeded or not account_result.stdout:
        raise DeployError(
            f"Could not resolve the deployment-layer storage account name from "
            f"the '{LAST_STAGE_DEPLOYMENT_NAME}' deployment outputs. Ensure the "
            f"infrastructure stage succeeded. az reported: "
            f"{account_result.output}"
        )
    account = account_result.stdout
    step(
        f"Uploading shared dependency tree to Azure Files share "
        f"'{DEPLOYMENT_LAYER_SHARE}' (once)"
    )
    key_result = az(
        "storage",
        "account",
        "keys",
        "list",
        "--account-name",
        account,
        "--resource-group",
        SETTINGS.resource_group,
        "--query",
        "[0].value",
        "-o",
        "tsv",
        "--only-show-errors",
    )
    if not key_result.succeeded or not key_result.stdout:
        raise DeployError(
            f"Could not read the access key for the deployment-layer storage "
            f"account '{account}' (resource group '{SETTINGS.resource_group}'). "
            f"az reported: {key_result.output}"
        )
    upload = az(
        "storage",
        "file",
        "upload-batch",
        "--account-name",
        account,
        "--account-key",
        key_result.stdout,
        "--destination",
        DEPLOYMENT_LAYER_SHARE,
        "--source",
        str(layer_dir),
        "--only-show-errors",
    )
    if not upload.succeeded:
        raise DeployError(
            f"Failed to upload the shared dependency tree to the "
            f"'{DEPLOYMENT_LAYER_SHARE}' Azure Files share on '{account}'. Every "
            f"web app mounts this share, so the deploy cannot proceed. Check "
            f"network access to the storage account's file endpoint and re-run. "
            f"az reported: {upload.output}"
        )
    ok(f"Shared dependency tree uploaded to the '{DEPLOYMENT_LAYER_SHARE}' share.")


# ---------------------------------------------------------------------------
# Server-side build outcome (Kudu)
# ---------------------------------------------------------------------------


def kudu_state_from_log(log_json: str, since_epoch: float) -> str:
    """Classify a Kudu deployment log against a push watermark.

    The CLI's own exit code is not a reliable signal: it can report failure on a
    client-side polling timeout or a transient SCM error while the server-side
    build SUCCEEDS. The log is therefore the source of truth, scoped to entries
    stamped at or after the push (with a clock-skew allowance) so an entry from
    a PRIOR push is never mistaken for this one's outcome.

    Args:
        log_json: Raw ``az webapp log deployment show -o json`` output.
        since_epoch: Epoch seconds captured just before the push.

    Returns:
        ``"succeeded"`` -- the build's success was logged.
        ``"failed"`` -- the build's failure was logged.
        ``"pending"`` -- at least one entry belongs to this push (so it WAS
        accepted and is being tracked), but none of them is terminal yet.
        ``"none"`` -- no entry belongs to this push: the log is empty,
        unreadable, or every entry predates the watermark. Distinct from
        ``"pending"``: it means there is NO evidence the push was ever accepted,
        which is what lets a nonzero submission be told apart from a
        false-negative one.
    """
    if not log_json.strip():
        return "none"
    try:
        entries = json.loads(log_json)
    except json.JSONDecodeError:
        return "none"
    if not isinstance(entries, list):
        return "none"
    cutoff = since_epoch - KUDU_CLOCK_SKEW_SECONDS
    saw_entry = False
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        stamp = _parse_log_time(entry.get("log_time"))
        if stamp is None or stamp < cutoff:
            continue
        saw_entry = True
        # Kudu's own generic terminal log lines, emitted regardless of which
        # build step actually threw.
        message = str(entry.get("message") or "").lower()
        if "deployment successful" in message:
            return "succeeded"
        if "deployment failed" in message:
            return "failed"
    return "pending" if saw_entry else "none"


def _parse_log_time(raw: object) -> float | None:
    """Parse a Kudu log timestamp into epoch seconds, or None if unusable."""
    if not isinstance(raw, str) or not raw:
        return None
    try:
        parsed = dt.datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=dt.timezone.utc)
    return parsed.timestamp()


def get_kudu_deployment_state(app_name: str, since_epoch: float) -> str:
    """Read an app's Kudu deployment log and classify it against a watermark."""
    result = az(
        "webapp",
        "log",
        "deployment",
        "show",
        "--name",
        app_name,
        "--resource-group",
        SETTINGS.resource_group,
        "-o",
        "json",
        "--only-show-errors",
    )
    if not result.succeeded:
        return "none"
    return kudu_state_from_log(result.stdout, since_epoch)


def wait_kudu_deployment_terminal(app_name: str, since_epoch: float, label: str) -> str:
    """Poll the Kudu log until the server-side build is terminal, or time out.

    Polling the log directly resolves the push the instant the real build ends,
    instead of waiting out the CLI's own synchronous polling -- which routinely
    runs to its client-side timeout long after the build finished.

    Returns:
        ``"succeeded"``, ``"failed"``, or ``"timeout"`` (still non-terminal at
        the deadline). The caller treats a timeout exactly like a failure; it is
        reported separately only so the retry note names the real cause.
    """
    deadline = since_epoch + KUDU_TERMINAL_DEADLINE_SECONDS
    last_beat = since_epoch
    while True:
        state = get_kudu_deployment_state(app_name, since_epoch)
        if state in ("succeeded", "failed"):
            return state
        now = time.time()
        if now >= deadline:
            return "timeout"
        if now - last_beat >= KUDU_HEARTBEAT_SECONDS:
            sub(
                f"{label} -- waiting on the server-side build, "
                f"{int(now - since_epoch)}s elapsed"
            )
            last_beat = now
        time.sleep(KUDU_POLL_SECONDS)


# ---------------------------------------------------------------------------
# Packaging
# ---------------------------------------------------------------------------


def create_deploy_zip(source_dir: Path, zip_path: Path) -> None:
    """Zip a staging directory's CONTENTS with POSIX entry paths.

    Entry names always use forward slashes: the App Service side extracts the
    archive on Linux, and a backslash-separated entry name becomes a literal
    filename there, which breaks the wwwroot sync before any application boots.
    Byte-compiled output is excluded, matching the content hash.
    """
    zip_path.parent.mkdir(parents=True, exist_ok=True)
    if zip_path.exists():
        zip_path.unlink()
    with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as archive:
        for relative, path in _hashable_files(source_dir):
            archive.write(path, arcname=relative)


# ---------------------------------------------------------------------------
# Web app code push
# ---------------------------------------------------------------------------


def _service_matches(service: Service, patterns: Sequence[str]) -> list[Path]:
    """Expand the language-declared patterns under the service directory.

    Each pattern contributes its matches in sorted order, patterns in declared
    order; a pattern matching nothing contributes nothing.
    """
    service_dir = PROJECT_ROOT / service.service_dir
    matches: list[Path] = []
    for pattern in patterns:
        matches.extend(sorted(service_dir.glob(pattern)))
    return matches


def web_app_hash_inputs(service: Service) -> list[Path]:
    """Return the deploy-determining inputs of one service's web app.

    The service's language declares them (``web_hash_inputs``): everything the
    payload is built from, so a change to any of them invalidates the hash and
    forces a redeploy.
    """
    return _service_matches(service, service.web_hash_inputs)


def stage_web_app_payload(service: Service, stage_dir: Path) -> None:
    """Stage one service's web-app payload, as its language declares it.

    A PREBUILT payload first runs its declared build steps in the service
    directory. Each match of the declared payload paths is copied to the stage
    ROOT under its own name -- for a manifest-resolved payload, the service's
    source. A manifest-resolved payload's dependencies live on the mounted
    shared dependency layer, uploaded once, and are deliberately NOT copied in
    here.

    Raises:
        DeployError: A build step failed or its executable is not on PATH.
    """
    if service.web_package_mode == WEB_PACKAGE_PREBUILT:
        run_build_steps(
            f"Web app '{service.web_app_name}'",
            service.service_dir,
            service.web_build_steps,
        )
    sub("staging the service's web-app payload")
    shutil.rmtree(stage_dir, ignore_errors=True)
    stage_dir.mkdir(parents=True, exist_ok=True)
    for path in _service_matches(service, service.web_payload_paths):
        if path.is_dir():
            shutil.copytree(path, stage_dir / path.name)
        elif path.is_file():
            shutil.copy2(path, stage_dir / path.name)


def code_push_sites(service: Service) -> tuple[str, ...]:
    """Return the deployed names of the App Service sites that run one service's code.

    Its web site when it serves HTTP, and each of its worker sites: a worker runs
    the same payload under its own startup command, so it receives the same zip.
    """
    web = (
        (f"{service.web_app_name}-{SETTINGS.environment}",)
        if service.has_web_site
        else ()
    )
    return web + worker_sites(service)


def deploy_one_web_app(index: int, service: Service) -> None:
    """Push one service's code to its App Service web app and worker sites.

    Sequence: skip check against each site's stamped content hash, stage the
    service's own source once, zip it, then for each stale site submit
    asynchronously, poll the server-side build to a terminal state, and stamp
    the new hash on that site.

    The submission is asynchronous and the build is polled here rather than by
    the CLI, because the CLI's synchronous mode routinely runs to its own
    client-side timeout and then reports failure even though the server-side
    build had already succeeded.

    Raises:
        DeployError: If every push attempt to a site failed.
    """
    started = time.monotonic()
    item(index, len(SERVICES), service.web_app_name)
    sites = code_push_sites(service)
    if not sites:
        ok(f"{service.web_app_name} runs no App Service site -- nothing to push")
        return

    content_hash = deploy_content_hash(web_app_hash_inputs(service))
    stale = [
        site
        for site in sites
        if service_deploy_needed(
            content_hash,
            "" if SETTINGS.force else read_stored_deploy_hash(site),
            SETTINGS.force,
        )
    ]
    if not stale:
        ok(f"{service.web_app_name} unchanged (hash {content_hash[:8]}) -- skipping")
        return

    stage_dir = SETTINGS.build_dir / f"src-{service.web_app_name}"
    zip_path = SETTINGS.build_dir / f"{service.web_app_name}.zip"
    stage_web_app_payload(service, stage_dir)
    sub("packaging deploy zip")
    create_deploy_zip(stage_dir, zip_path)

    for site in stale:
        sub(f"deploying to {site} (async submit; polling the server-side build)")
        _push_web_app_zip(site, zip_path)
        set_deploy_hash_stamp(site, content_hash)
    shutil.rmtree(stage_dir, ignore_errors=True)
    zip_path.unlink(missing_ok=True)
    ok(f"{service.web_app_name} deployed ({int(time.monotonic() - started)}s)")


def _push_web_app_zip(web_app: str, zip_path: Path) -> None:
    """Submit a web app zip and wait for the server-side build, with retries.

    Raises:
        DeployError: If every attempt failed.
    """
    last_submit_error = ""
    for attempt in range(1, CODE_PUSH_MAX_ATTEMPTS + 1):
        # Recomputed per attempt: each retry is a fresh push, and the state
        # check below must not see an entry left behind by a PRIOR attempt.
        since = time.time()
        submission = az(
            "webapp",
            "deploy",
            "--resource-group",
            SETTINGS.resource_group,
            "--name",
            web_app,
            "--src-path",
            str(zip_path),
            "--type",
            "zip",
            "--async",
            "true",
            "--only-show-errors",
        )
        if not submission.succeeded:
            # A nonzero exit from the submission does not always mean the zip
            # was rejected -- the CLI's submission path can false-negative too
            # (a push that had already landed and was building). So consult the
            # deployment log directly: if ANY entry belongs to this push --
            # succeeded, failed, or still building -- the push WAS accepted and
            # this falls through to the same wait a clean submission takes.
            # Only "none" means the submission genuinely did not land.
            if get_kudu_deployment_state(web_app, since) == "none":
                last_submit_error = _tail(submission.output, lines=5)
                if attempt < CODE_PUSH_MAX_ATTEMPTS:
                    note(
                        f"{web_app}: async push submission failed "
                        f"(attempt {attempt}): {last_submit_error} -- retrying in "
                        f"{CODE_PUSH_RETRY_SECONDS}s."
                    )
                    time.sleep(CODE_PUSH_RETRY_SECONDS)
                continue
            note(
                f"{web_app}: submission returned nonzero but the "
                f"deployment log shows it was accepted (CLI false-negative) -- "
                f"polling the server-side build."
            )
        state = wait_kudu_deployment_terminal(web_app, since, web_app)
        if state == "succeeded":
            return
        if attempt < CODE_PUSH_MAX_ATTEMPTS:
            if state == "timeout":
                note(
                    f"{web_app}: the server-side build did not reach "
                    f"a terminal state within "
                    f"{KUDU_TERMINAL_DEADLINE_SECONDS // 60} minutes (attempt "
                    f"{attempt}) -- retrying in {CODE_PUSH_RETRY_SECONDS}s."
                )
            else:
                note(
                    f"{web_app}: the server-side build failed "
                    f"(attempt {attempt}) -- retrying in "
                    f"{CODE_PUSH_RETRY_SECONDS}s."
                )
            time.sleep(CODE_PUSH_RETRY_SECONDS)
    hint = f" Last submission error: {last_submit_error}." if last_submit_error else ""
    raise DeployError(
        f"Failed to deploy '{web_app}' after "
        f"{CODE_PUSH_MAX_ATTEMPTS} attempts.{hint} The zip deployment runs "
        f"server-side; inspect the deployment log for the build error."
    )


# ---------------------------------------------------------------------------
# Function app code push
# ---------------------------------------------------------------------------


def function_app_services() -> tuple[Service, ...]:
    """Return every service that provisions a Function App."""
    return tuple(service for service in SERVICES if service.has_function_app)


def function_app_hash_inputs(service: Service) -> list[Path]:
    """Return the deploy-determining inputs of one service's Function App.

    Always the package source root and its dependency manifest. A remote-build
    package also ships the owning service's built artifact, so the service
    directory it is built from is an input too.
    """
    source_root = PROJECT_ROOT / service.function_source_dir
    inputs = [source_root, source_root / service.function_manifest_file]
    if service.function_package_mode == FUNCTION_PACKAGE_REMOTE_BUILD:
        inputs.append(PROJECT_ROOT / service.service_dir)
    return inputs


BUILD_TOOL_INSTALL_HINT = (
    "A PREBUILT package is built with the target language's own toolchain "
    "before it is deployed -- install the tool named above and retry."
)


def run_build_steps(
    label: str, source_dir: str, steps: Sequence[tuple[str, ...]]
) -> None:
    """Run a PREBUILT package's declared build steps in its source directory.

    Each step is an argument vector passed straight to ``subprocess.run`` --
    never a shell string -- with its executable resolved to an absolute path.

    Args:
        label: The package named in a failure (e.g. "Function App 'orders-func'").
        source_dir: The directory the steps run in, relative to the project root.
        steps: The declared argument vectors, run in order.

    Raises:
        DeployError: A step exited nonzero (with its output tail), or its
            executable is not on PATH.
    """
    cwd = PROJECT_ROOT / source_dir
    for step in steps:
        argv = (resolve_executable(step[0], BUILD_TOOL_INSTALL_HINT), *step[1:])
        sub(f"build step: {' '.join(step)}")
        completed = subprocess.run(
            list(argv),
            cwd=cwd,
            capture_output=True,
            text=True,
            check=False,
        )
        if completed.returncode != 0:
            output = "\n".join(
                part for part in (completed.stdout, completed.stderr) if part
            ).strip()
            raise DeployError(
                f"{label} build step {list(step)} failed in '{source_dir}' (exit "
                f"{completed.returncode}): {_tail(output, lines=10)}. Fix the build "
                f"error and redeploy."
            )


def _stage_remote_build_package(service: Service, stage_dir: Path) -> None:
    """Stage a remote-build package: the source root plus the service's wheel.

    The Flex Consumption plan performs a server-side remote build driven by the
    package's dependency manifest, so the package ships the generated function
    source PLUS the owning service's wheel, with the wheel filename appended to
    the manifest -- the remote build then installs both the worker library and
    the service package (which carries the handlers the adapters import).
    """
    shutil.copytree(PROJECT_ROOT / service.function_source_dir, stage_dir)
    sub("building application wheel")
    wheel_name = _build_service_wheel(service, stage_dir)
    # Append the wheel to the staged manifest (which already carries the
    # worker library), preserving its existing content.
    staged_manifest = stage_dir / service.function_manifest_file
    with staged_manifest.open("a", encoding="utf-8") as handle:
        handle.write(f"{wheel_name}\n")
    add_service_wheel_subset(
        Path(service.service_dir) / "requirements.txt",
        SETTINGS.build_dir / "wheelhouse",
        stage_dir,
    )


def _stage_prebuilt_package(service: Service, stage_dir: Path) -> None:
    """Stage a PREBUILT package: run its build steps, then copy the built directory."""
    run_build_steps(
        f"Function App '{service.function_app_name}'",
        service.function_source_dir,
        service.function_build_steps,
    )
    shutil.copytree(
        PROJECT_ROOT / service.function_source_dir / service.function_package_dir,
        stage_dir,
    )


def deploy_one_function_app(index: int, service: Service) -> None:
    """Push one service's Function App package, built the way its language declares.

    ``FUNCTION_PACKAGE_REMOTE_BUILD``: the source root plus the service's wheel,
    pushed with the host's remote build on. ``FUNCTION_PACKAGE_PREBUILT``: the
    declared build steps run locally, the built directory is zipped whole and
    pushed with the remote build off.

    Raises:
        DeployError: An unknown package mode, a failed build step, a wheel that
            cannot be built, or every push attempt failed.
    """
    started = time.monotonic()
    functions = function_app_services()
    function_app = f"{service.function_app_name}-{SETTINGS.environment}"
    item(index, len(functions), service.function_app_name)

    content_hash = deploy_content_hash(function_app_hash_inputs(service))
    stored_hash = "" if SETTINGS.force else read_stored_deploy_hash(function_app)
    if not service_deploy_needed(content_hash, stored_hash, SETTINGS.force):
        ok(
            f"{service.function_app_name} unchanged (hash {content_hash[:8]}) "
            f"-- skipping"
        )
        return

    stage_dir = SETTINGS.build_dir / f"func-{service.function_app_name}"
    zip_path = SETTINGS.build_dir / f"{service.function_app_name}.zip"
    shutil.rmtree(stage_dir, ignore_errors=True)
    if service.function_package_mode == FUNCTION_PACKAGE_REMOTE_BUILD:
        _stage_remote_build_package(service, stage_dir)
        remote_build = True
    elif service.function_package_mode == FUNCTION_PACKAGE_PREBUILT:
        _stage_prebuilt_package(service, stage_dir)
        remote_build = False
    else:
        raise DeployError(
            f"Function App '{service.function_app_name}' has package mode "
            f"'{service.function_package_mode}', which this deploy script cannot "
            f"build. Expected '{FUNCTION_PACKAGE_REMOTE_BUILD}' or "
            f"'{FUNCTION_PACKAGE_PREBUILT}'. Regenerate the project."
        )

    sub("packaging function zip")
    create_deploy_zip(stage_dir, zip_path)
    sub("deploying" + (" (remote build installs dependencies)" if remote_build else ""))
    _push_function_app_zip(service, function_app, zip_path, remote_build=remote_build)

    set_deploy_hash_stamp(function_app, content_hash)
    shutil.rmtree(stage_dir, ignore_errors=True)
    zip_path.unlink(missing_ok=True)
    ok(f"{service.function_app_name} deployed ({int(time.monotonic() - started)}s)")


def _build_service_wheel(service: Service, stage_dir: Path) -> str:
    """Build the owning service's wheel into the staging directory.

    Returns:
        The built wheel's file name.

    Raises:
        DeployError: If the build failed or produced no wheel.
    """
    # Path-qualified ('./'): pip reads a bare token as a PyPI package name.
    build = pip("wheel", f"./{service.service_dir}", "--no-deps", "-w", str(stage_dir))
    if not build.succeeded:
        raise DeployError(
            f"Failed to build the application wheel for Function App "
            f"'{service.function_app_name}'. pip reported: {build.output}"
        )
    wheels = sorted(stage_dir.glob("*.whl"))
    if not wheels:
        raise DeployError(
            f"No wheel was produced for Function App '{service.function_app_name}'."
        )
    return wheels[0].name


def _push_function_app_zip(
    service: Service, function_app: str, zip_path: Path, *, remote_build: bool
) -> None:
    """Push a Function App zip with the same false-negative guard as web apps.

    The zip deploy has no asynchronous submission mode, so this leg stays on a
    synchronous push plus a log-confirmed false-negative check. *remote_build*
    selects whether the host builds the package (a remote-build package) or
    runs it as shipped (a prebuilt package).

    Raises:
        DeployError: If every attempt failed.
    """
    since = time.time()
    last_error = ""
    for attempt in range(1, CODE_PUSH_MAX_ATTEMPTS + 1):
        push = az(
            "functionapp",
            "deployment",
            "source",
            "config-zip",
            "--resource-group",
            SETTINGS.resource_group,
            "--name",
            function_app,
            "--src",
            str(zip_path),
            "--build-remote",
            "true" if remote_build else "false",
            "--only-show-errors",
        )
        if push.succeeded:
            return
        last_error = _tail(push.output, lines=5)
        if get_kudu_deployment_state(function_app, since) == "succeeded":
            note(
                f"{service.function_app_name}: the push returned nonzero but the "
                f"server-side build succeeded (CLI false-negative) -- continuing."
            )
            return
        if attempt < CODE_PUSH_MAX_ATTEMPTS:
            note(
                f"{service.function_app_name}: deploy attempt {attempt} did not "
                f"confirm success -- retrying in {CODE_PUSH_RETRY_SECONDS}s."
            )
            time.sleep(CODE_PUSH_RETRY_SECONDS)
    raise DeployError(
        f"Failed to deploy Function App '{service.function_app_name}' after "
        f"{CODE_PUSH_MAX_ATTEMPTS} attempts. Inspect the Function App's deployment "
        f"log for the error. Last error: {last_error}"
    )


# ---------------------------------------------------------------------------
# The code-push phase
# ---------------------------------------------------------------------------


def push_phase() -> None:
    """Assemble shared dependencies, then push every web app and Function App.

    The shared dependency layer exists only for the manifest-resolved web apps
    (the infrastructure provisions its share only when one mounts it); a system
    whose web apps are all PREBUILT assembles and uploads none.
    """
    requirements_files = service_requirements_files()
    if requirements_files:
        wheelhouse_dir = SETTINGS.build_dir / "wheelhouse"
        # A pure accelerator: PyPI always remains the fallback resolver.
        build_deploy_wheelhouse(wheelhouse_dir, requirements_files)
        layer_dir = build_deploy_dependency_layer(
            SETTINGS.build_dir, requirements_files
        )
        upload_dependency_layer(layer_dir)

    step(f"Deploying application code ({len(SERVICES)} services)")
    run_deploy_wave(SETTINGS.web_wave_size, deploy_one_web_app, SERVICES)

    push_function_apps()


def push_function_apps() -> None:
    """Push every Function App's zip package, built the way its language declares.

    A Flex Consumption Function App is NOT a container: each is pushed as a zip,
    so this leg runs whether the web tier is delivered as pushed code
    (``push_phase``) or as a container image (container mode's
    ``command_deploy`` branch). The shared wheelhouse only accelerates a
    remote-build package's server-side build -- the leg falls back to PyPI when
    it is absent -- so it is built here only when such a package is pushed and
    the web-app leg, which shares this build directory, has not already
    assembled it.
    """
    functions = function_app_services()
    if not functions:
        return
    wheelhouse_dir = SETTINGS.build_dir / "wheelhouse"
    remote_build = any(
        service.function_package_mode == FUNCTION_PACKAGE_REMOTE_BUILD
        for service in functions
    )
    if remote_build and not wheelhouse_dir.is_dir():
        build_deploy_wheelhouse(wheelhouse_dir, service_requirements_files())
    step(f"Deploying Function App code ({len(functions)} function app(s))")
    run_deploy_wave(SETTINGS.function_wave_size, deploy_one_function_app, functions)


# ---------------------------------------------------------------------------
# Static Web App build + upload
# ---------------------------------------------------------------------------


def _resolve_static_web_app_deployment_token(swa: StaticWebApp) -> str:
    """Resolve one Static Web App's deployment token from its logical secret handle.

    Azure Static Web Apps' own 'listSecrets()' action -- exposed by the CLI as
    'az staticwebapp secrets list' -- IS this resource type's native secret
    mechanism: there is no Key Vault round trip, mirroring
    the Bicep module's own comment. Returns the value only -- never printed,
    never written to disk.

    Raises:
        DeployError: If the token cannot be read. Names the logical handle and
            the backend class, never any partial secret material.
    """
    result = az(
        "staticwebapp",
        "secrets",
        "list",
        "--name",
        swa.static_site_name,
        "--resource-group",
        SETTINGS.resource_group,
        "--query",
        "properties.apiKey",
        "-o",
        "tsv",
    )
    token = result.stdout.strip() if result.succeeded else ""
    if not token:
        raise DeployError(
            f"Could not resolve the deployment token for logical secret handle "
            f"'{swa.deployment_token_handle}' (backend: Azure Static Web Apps "
            f"listSecrets()). Ensure '{swa.static_site_name}' was created by the "
            f"infrastructure stage above and the signed-in principal has "
            f"'Microsoft.Web/staticSites/listSecrets/action' on it."
        )
    return token


def deploy_one_static_web_app(
    swa: StaticWebApp, build_inputs: Mapping[str, str]
) -> None:
    """Build one Static Web App's bundle and upload it with 'swa deploy'.

    *build_inputs* are the inputs only the deploy can supply that the build takes (the
    clients step derives them); they join the site's own ``build_env``.

    Sequence: install dependencies, run the client target's own production
    build, copy the deploy-time runtime-config file into the bundle as
    'runtime-config.json', resolve the deployment token from its logical
    secret handle, then upload with the pinned '@azure/static-web-apps-cli'
    'swa deploy'. The token is held only in this process's memory and the
    upload child process's own environment -- never written to disk, never
    logged.

    Raises:
        DeployError: If the build fails, the runtime-config file is missing,
            the deployment token cannot be resolved, or the upload fails.
    """
    client_dir = PROJECT_ROOT / swa.client_dir

    sub(f"installing dependencies ({' '.join(swa.install_argv)})")
    install_result = run_command(_resolve_build_argv(swa.install_argv), cwd=client_dir)
    if not install_result.succeeded:
        raise DeployError(
            f"'{' '.join(swa.install_argv)}' failed for '{swa.static_site_name}' "
            f"in {client_dir}: {install_result.output}"
        )

    sub(f"building ({' '.join(swa.build_argv)})")
    build_environment = {**dict(swa.build_env), **build_inputs}
    build_result = run_command(
        _resolve_build_argv(swa.build_argv),
        cwd=client_dir,
        env={**os.environ, **build_environment} if build_environment else None,
    )
    if not build_result.succeeded:
        raise DeployError(
            f"'{' '.join(swa.build_argv)}' failed for '{swa.static_site_name}' "
            f"in {client_dir}: {build_result.output}"
        )

    bundle_dir = client_dir / swa.bundle_dir
    if not bundle_dir.is_dir():
        raise DeployError(
            f"Build for '{swa.static_site_name}' did not produce the expected "
            f"bundle directory '{bundle_dir}'. Check the build output above."
        )

    if swa.runtime_config_path:
        runtime_config_source = PROJECT_ROOT / swa.runtime_config_path
        if not runtime_config_source.is_file():
            raise DeployError(
                f"Deployed runtime-config file '{runtime_config_source}' is missing "
                f"for '{swa.static_site_name}'. The clients step composes it from "
                f"the client contract before any site publishes, so run the full "
                f"'deploy' command rather than a stage of it."
            )
        shutil.copyfile(runtime_config_source, bundle_dir / "runtime-config.json")

    swa_config_source = PROJECT_ROOT / swa.swa_config_path
    if not swa_config_source.is_file():
        raise DeployError(
            f"'{swa_config_source}' is missing for '{swa.static_site_name}'. "
            f"It carries the site's security headers, cache policy and SPA "
            f"routes, and is generated with the infrastructure -- regenerate "
            f"the project; never deploy the bundle without it."
        )
    shutil.copyfile(swa_config_source, bundle_dir / swa_config_source.name)

    sub("resolving deployment token")
    token = _resolve_static_web_app_deployment_token(swa)
    upload_env = dict(os.environ)
    upload_env["SWA_CLI_DEPLOYMENT_TOKEN"] = token
    try:
        sub(f"uploading with swa deploy (@azure/static-web-apps-cli {SWA_CLI_VERSION})")
        upload_result = run_command(
            _resolve_build_argv(
                (
                    "npx",
                    "--yes",
                    f"@azure/static-web-apps-cli@{SWA_CLI_VERSION}",
                    "deploy",
                    str(bundle_dir),
                    "--env",
                    "production",
                )
            ),
            cwd=client_dir,
            env=upload_env,
        )
    finally:
        del upload_env, token
    if not upload_result.succeeded:
        raise DeployError(
            f"'swa deploy' failed for '{swa.static_site_name}': {upload_result.output}"
        )


# ---------------------------------------------------------------------------
# Client runtime configs: the client contract and each deployed copy
# ---------------------------------------------------------------------------
# A generated runtime config carries the app's own facts; the environment's come
# from the client contract the backend's deploy publishes. Each config's deployed
# copy is composed from the two -- the only copy any client is given. Anything the
# contract lacks fails the deploy: there is no fallback id.


def client_resource_group() -> str:
    """The resource group holding this deployment's Static Web Apps."""
    return SETTINGS.resource_group


#: The runtime config's identity block and its client-id member -- the same
#: names `client_runtime_config` declares.
RUNTIME_CONFIG_IDENTITY_KEY = "identity"
RUNTIME_CONFIG_CLIENT_ID_KEY = "clientId"
#: The other environment facts a deployed runtime config carries -- the same
#: names `client_runtime_config` declares.
RUNTIME_CONFIG_API_BASE_URL_KEY = "apiBaseUrl"
RUNTIME_CONFIG_WEB_ORIGIN_KEY = "webOrigin"
#: The members of a deployed config's identity block -- the same names as
#: `client_runtime_config.IDENTITY_CLIENT_KEYS`.
CLIENT_RECORD_KEYS = (
    "authority",
    RUNTIME_CONFIG_CLIENT_ID_KEY,
    "scopes",
    "redirectUris",
    "logoutUris",
    "flows",
    "rolesClaim",
    "roleMappings",
)
#: The identity provider's `iss`, which its OpenID configuration must state: a
#: release checks the provider against it. A contract's client record carries it;
#: a deployed identity block does not, since no client reads it.
CLIENT_CONTRACT_ISSUER_KEY = "issuer"
#: The members of a client record in the client contract.
CLIENT_CONTRACT_RECORD_KEYS = (*CLIENT_RECORD_KEYS, CLIENT_CONTRACT_ISSUER_KEY)

#: The client contract's own members.
CLIENT_CONTRACT_SYSTEM_KEY = "system"
CLIENT_CONTRACT_SYSTEM_NAME_KEY = "name"
CLIENT_CONTRACT_SYSTEM_VERSION_KEY = "version"
CLIENT_CONTRACT_BACKEND_KEY = "backend"
CLIENT_CONTRACT_REGISTRATIONS_KEY = "registrations"
CLIENT_CONTRACT_APP_ID_KEY = "appId"
CLIENT_CONTRACT_KINDS_KEY = "kinds"
CLIENT_CONTRACT_SERVICES_KEY = "services"
CLIENT_CONTRACT_CLIENTS_KEY = "clients"
#: In a contract plan only: a client record whose id the platform provisions
#: names the output it is published under here. The published contract never
#: carries it.
CLIENT_PLAN_ID_REF_KEY = "clientIdRef"
#: The backend's member holding the API it serves its clients: the consumed API
#: document (`client_api_document`) of the backend's own client contract, which a
#: release compares each app's consumed document against.
CLIENT_CONTRACT_BACKEND_API_KEY = "api"
#: An API document's list of services, each with the routes a client may call.
CLIENT_API_DOCUMENT_SERVICES_KEY = "services"

#: What a provisioned OAuth2 client id may look like before it is written into
#: a file a browser loads: a GUID, a Cognito app-client id, a Zitadel
#: `<digits>@<project>` id. Anything else -- whitespace, a quote, markup, an
#: empty value -- is refused rather than served.
_PROVISIONED_CLIENT_ID_SHAPE = re.compile(r"[A-Za-z0-9][A-Za-z0-9@._:-]{0,255}")

#: What an origin in a contract may look like: `https://<host>[:port]`, or a
#: loopback host over either scheme. The whole value is matched, so no userinfo,
#: path, query or fragment reaches a client. A pattern rather than `urllib`
#: because every host imports `re` and not every host imports `urllib.parse`.
CLIENT_ORIGIN_SHAPE = re.compile(
    r"(?:https://[A-Za-z0-9][A-Za-z0-9.-]*|https?://(?:localhost|127\.0\.0\.1|\[::1\]))"
    r"(?::[0-9]{1,5})?"
)

#: How to clear any defect in a contract a deploy reads.
_CONTRACT_FIX = (
    "Use the file the backend's deploy published, unchanged; if it is out of date, "
    "redeploy the backend."
)

#: A client contract, as the JSON object it is published as. Plain data, so a
#: host needs no import beyond this module's own.
ClientContractDocument = dict[str, object]


class ClientRuntimeResolutionError(RuntimeError):
    """A client contract or a runtime config could not be written, read or composed."""


def _read_generated_config(generated_path: Path) -> dict[str, object]:
    """The generated runtime config at *generated_path*, or fail naming it."""
    if not generated_path.is_file():
        raise ClientRuntimeResolutionError(
            f"Runtime config '{generated_path}' does not exist. It is produced by "
            "generation; regenerate the project before deploying."
        )
    try:
        config = json.loads(generated_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ClientRuntimeResolutionError(
            f"Runtime config '{generated_path}' is not valid JSON ({exc}). "
            "Regenerate the project; never edit the generated file by hand."
        ) from exc
    if not isinstance(config, dict):
        raise ClientRuntimeResolutionError(
            f"Runtime config '{generated_path}' is not a JSON object. Regenerate "
            "the project; never edit the generated file by hand."
        )
    return config


def _write_sorted_json(path: Path, document: dict[str, object]) -> None:
    """Write *document* to *path* as sorted JSON, parents created."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(document, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )


def _provisioned_client_id(
    reference: str,
    consumer: str,
    lookup_client_id: Callable[[str], str | None],
) -> str:
    """The well-formed id the platform published under *reference*, or fail naming it."""
    client_id = lookup_client_id(reference)
    if client_id is None or not _PROVISIONED_CLIENT_ID_SHAPE.fullmatch(client_id):
        found = "nothing" if client_id is None else "a malformed value"
        raise ClientRuntimeResolutionError(
            f"The platform published {found} under '{reference}', the client id "
            f"{consumer} signs users in with. The "
            "registration is provisioned by this deployment's infrastructure; "
            "deploy the infrastructure first, and check that it created the "
            "registration. No client is deployed without its provisioned id."
        )
    return client_id


def client_contract_from_plan(
    plan: dict[str, object],
    lookup_client_id: Callable[[str], str | None],
) -> ClientContractDocument:
    """The client contract of *plan*, every late-bound client id looked up.

    Args:
        plan: The generation-time contract: the published document, except that a
            client record the platform provisions holds
            ``CLIENT_PLAN_ID_REF_KEY`` in place of its client id.
        lookup_client_id: Returns the id the platform provisioned under the given
            reference, or ``None`` when it publishes none.

    Returns:
        The contract, ready for :func:`write_client_contract`.

    Raises:
        ClientRuntimeResolutionError: A client record carries both or neither of
            the client id and its reference, or the platform publishes no
            well-formed id under a reference.
    """
    registrations = _contract_object(plan, CLIENT_CONTRACT_REGISTRATIONS_KEY, "plan")
    return {
        **plan,
        CLIENT_CONTRACT_REGISTRATIONS_KEY: {
            name: _registration_with_client_ids(
                name, _contract_object(registrations, name, "plan"), lookup_client_id
            )
            for name in registrations
        },
    }


def _registration_with_client_ids(
    name: str,
    registration: dict[str, object],
    lookup_client_id: Callable[[str], str | None],
) -> dict[str, object]:
    """*registration* with each client record's id in place."""
    source = f"plan, registration '{name}'"
    clients = _contract_object(registration, CLIENT_CONTRACT_CLIENTS_KEY, source)
    return {
        **registration,
        CLIENT_CONTRACT_CLIENTS_KEY: {
            kind: _client_with_id(
                f"registration '{name}' ({kind})",
                _contract_object(clients, kind, source),
                lookup_client_id,
            )
            for kind in clients
        },
    }


def _client_with_id(
    consumer: str,
    record: dict[str, object],
    lookup_client_id: Callable[[str], str | None],
) -> dict[str, object]:
    """*record* holding its client id: its own, or the one published under its reference."""
    has_id = RUNTIME_CONFIG_CLIENT_ID_KEY in record
    has_ref = CLIENT_PLAN_ID_REF_KEY in record
    if has_id == has_ref:
        raise ClientRuntimeResolutionError(
            f"Client contract plan: {consumer} carries "
            f"{'both' if has_id else 'neither'} of '{RUNTIME_CONFIG_CLIENT_ID_KEY}' "
            f"and '{CLIENT_PLAN_ID_REF_KEY}'; exactly one is required. "
            "Regenerate the project."
        )
    if has_id:
        return record
    reference = _contract_text(record, CLIENT_PLAN_ID_REF_KEY, consumer)
    resolved = {
        key: value for key, value in record.items() if key != CLIENT_PLAN_ID_REF_KEY
    }
    resolved[RUNTIME_CONFIG_CLIENT_ID_KEY] = _provisioned_client_id(
        reference, consumer, lookup_client_id
    )
    return resolved


def write_client_contract(contract: ClientContractDocument, path: Path) -> None:
    """Publish *contract* at *path* as sorted JSON (parents created).

    Args:
        contract: The contract (:func:`client_contract_from_plan`).
        path: Where it is published (``client_runtime_paths.client_contract_path``).

    Raises:
        ClientRuntimeResolutionError: The contract is not well formed; nothing is
            written.
    """
    _require_valid_contract(contract, f"'{path}'")
    _write_sorted_json(path, contract)


def read_client_contract(path: Path) -> ClientContractDocument:
    """The published client contract at *path*, checked as the writer checks it.

    Args:
        path: The contract file. In a frontend run an operator places it, so
            nothing about its content is taken on trust.

    Returns:
        The contract.

    Raises:
        ClientRuntimeResolutionError: The file is absent, is not a JSON object, or
            is not a well-formed contract.
    """
    if not path.is_file():
        raise ClientRuntimeResolutionError(
            f"Client contract '{path}' does not exist or is not a file. The backend's "
            "deploy publishes it: deploy the backend, or place its published contract "
            "at this path."
        )
    try:
        contract = json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise ClientRuntimeResolutionError(
            f"Client contract '{path}' is not valid JSON ({exc}). {_CONTRACT_FIX}"
        ) from exc
    if not isinstance(contract, dict):
        raise ClientRuntimeResolutionError(
            f"Client contract '{path}' is not a JSON object. {_CONTRACT_FIX}"
        )
    _require_valid_contract(contract, f"'{path}'")
    return contract


def compose_client_runtime_config(
    generated_path: Path,
    contract: ClientContractDocument,
    registration_name: str,
    kind: str,
    resolved_path: Path,
    *,
    identity: bool,
    web_origin: bool,
) -> None:
    """Write *resolved_path*: the app facts of *generated_path* plus the contract's facts.

    The deployed copy always carries the API base URL. The contract is checked
    again here, because a frontend run's copy is one an operator placed.

    Args:
        generated_path: The generated runtime config.
        contract: The published client contract.
        registration_name: The registration the app composes from.
        kind: The client kind the target runs as.
        resolved_path: Where the deployed copy is written (parents created).
        identity: Whether the deployed copy carries the kind's client record,
            projected onto `CLIENT_RECORD_KEYS` (the record's `issuer` stays in
            the contract).
        web_origin: Whether the deployed copy carries the registration's web origin.

    Raises:
        ClientRuntimeResolutionError: The generated config or the contract is not
            well formed, the registration or kind is absent from the contract, or
            a wanted client record or web origin is; nothing is written.
    """
    source = f"read for '{generated_path}'"
    _require_valid_contract(contract, source)
    config = _read_generated_config(generated_path)
    registration = _contract_registration(
        contract, registration_name, kind, generated_path
    )
    backend = _contract_object(contract, CLIENT_CONTRACT_BACKEND_KEY, source)
    config[RUNTIME_CONFIG_API_BASE_URL_KEY] = backend[RUNTIME_CONFIG_API_BASE_URL_KEY]
    if identity:
        clients = _contract_object(registration, CLIENT_CONTRACT_CLIENTS_KEY, source)
        if kind not in clients:
            raise ClientRuntimeResolutionError(
                f"Runtime config '{generated_path}' signs users in, but registration "
                f"'{registration_name}' has no '{kind}' client in the client contract. "
                "Check that the backend declares a login provider for it, then "
                "redeploy the backend."
            )
        record = _contract_object(clients, kind, source)
        config[RUNTIME_CONFIG_IDENTITY_KEY] = {
            key: record[key] for key in CLIENT_RECORD_KEYS
        }
    if web_origin:
        if RUNTIME_CONFIG_WEB_ORIGIN_KEY not in registration:
            raise ClientRuntimeResolutionError(
                f"Runtime config '{generated_path}' needs a web origin, but registration "
                f"'{registration_name}' states none in the client contract. Declare the "
                "registration's web origin on the backend, then redeploy it."
            )
        config[RUNTIME_CONFIG_WEB_ORIGIN_KEY] = registration[
            RUNTIME_CONFIG_WEB_ORIGIN_KEY
        ]
    _write_sorted_json(resolved_path, config)


def _contract_registration(
    contract: ClientContractDocument,
    registration_name: str,
    kind: str,
    generated_path: Path,
) -> dict[str, object]:
    """The contract's *registration_name* entry running as *kind*, or fail naming both."""
    source = f"read for '{generated_path}'"
    registrations = _contract_object(
        contract, CLIENT_CONTRACT_REGISTRATIONS_KEY, source
    )
    if registration_name not in registrations:
        raise ClientRuntimeResolutionError(
            f"Runtime config '{generated_path}' composes from registration "
            f"'{registration_name}', which the client contract does not hold. It holds "
            f"{sorted(registrations)}. Check the app's `appId` against the backend's "
            "registrations, then redeploy the backend."
        )
    registration = _contract_object(registrations, registration_name, source)
    kinds = _contract_text_list(registration, CLIENT_CONTRACT_KINDS_KEY, source)
    if kind not in kinds:
        raise ClientRuntimeResolutionError(
            f"Runtime config '{generated_path}' runs as client kind '{kind}', which "
            f"registration '{registration_name}' does not list in the client contract. "
            f"It lists {sorted(kinds)}. Add the kind to the registration on the "
            "backend, then redeploy it."
        )
    return registration


def _require_valid_contract(contract: ClientContractDocument, source: str) -> None:
    """Fail unless *contract* is one a client may be given; *source* names it in the message."""
    system = _contract_object(contract, CLIENT_CONTRACT_SYSTEM_KEY, source)
    _contract_text(system, CLIENT_CONTRACT_SYSTEM_NAME_KEY, source)
    _contract_text(system, CLIENT_CONTRACT_SYSTEM_VERSION_KEY, source)
    backend = _contract_object(contract, CLIENT_CONTRACT_BACKEND_KEY, source)
    _require_origin(backend, RUNTIME_CONFIG_API_BASE_URL_KEY, source)
    _require_served_api(backend, f"{source}, '{CLIENT_CONTRACT_BACKEND_KEY}'")
    registrations = _contract_object(
        contract, CLIENT_CONTRACT_REGISTRATIONS_KEY, source
    )
    for name in registrations:
        _require_valid_registration(
            _contract_object(registrations, name, source),
            f"{source}, registration '{name}'",
        )


def _require_served_api(backend: dict[str, object], source: str) -> None:
    """Fail unless *backend* states the API it serves: an object listing its services.

    Only the shape is checked here; the release verifier reads each service's routes
    and names any member it cannot read.
    """
    api = _contract_object(backend, CLIENT_CONTRACT_BACKEND_API_KEY, source)
    services = api.get(CLIENT_API_DOCUMENT_SERVICES_KEY)
    if not isinstance(services, list) or not all(
        isinstance(item, dict) for item in services
    ):
        raise ClientRuntimeResolutionError(
            f"Client contract {source}, '{CLIENT_CONTRACT_BACKEND_API_KEY}': "
            f"'{CLIENT_API_DOCUMENT_SERVICES_KEY}' is not a list of JSON objects. {_CONTRACT_FIX}"
        )


def _require_valid_registration(registration: dict[str, object], source: str) -> None:
    """Fail unless *registration* holds what a contract entry must."""
    if CLIENT_CONTRACT_APP_ID_KEY not in registration:
        raise ClientRuntimeResolutionError(
            f"Client contract {source}: '{CLIENT_CONTRACT_APP_ID_KEY}' is missing; "
            f"expected a string, or null for a client that states none. {_CONTRACT_FIX}"
        )
    _contract_text_list(registration, CLIENT_CONTRACT_SERVICES_KEY, source)
    kinds = _contract_text_list(registration, CLIENT_CONTRACT_KINDS_KEY, source)
    if RUNTIME_CONFIG_WEB_ORIGIN_KEY in registration:
        _require_origin(registration, RUNTIME_CONFIG_WEB_ORIGIN_KEY, source)
    clients = _contract_object(registration, CLIENT_CONTRACT_CLIENTS_KEY, source)
    if not clients:
        return
    if set(clients) != set(kinds):
        raise ClientRuntimeResolutionError(
            f"Client contract {source}: its clients {sorted(clients)} are not its kinds "
            f"{sorted(kinds)}. A registration with a login provider has one client per "
            f"kind, and one without has none. {_CONTRACT_FIX}"
        )
    for kind in clients:
        _require_valid_client(
            _contract_object(clients, kind, source), f"{source} ({kind})"
        )


def _require_valid_client(record: dict[str, object], source: str) -> None:
    """Fail unless client *record* is complete, its issuer stated and its client id well formed."""
    missing = [key for key in CLIENT_CONTRACT_RECORD_KEYS if key not in record]
    if missing:
        raise ClientRuntimeResolutionError(
            f"Client contract {source}: the client record lacks {missing}. {_CONTRACT_FIX}"
        )
    _contract_text(record, CLIENT_CONTRACT_ISSUER_KEY, source)
    client_id = record[RUNTIME_CONFIG_CLIENT_ID_KEY]
    if not isinstance(client_id, str) or not _PROVISIONED_CLIENT_ID_SHAPE.fullmatch(
        client_id
    ):
        raise ClientRuntimeResolutionError(
            f"Client contract {source}: '{RUNTIME_CONFIG_CLIENT_ID_KEY}' is malformed. "
            f"Expected a provisioned OAuth2 client id. {_CONTRACT_FIX}"
        )


def _require_origin(parent: dict[str, object], key: str, source: str) -> None:
    """Fail unless *parent*'s *key* is an https origin, or a loopback one."""
    origin = _contract_text(parent, key, source)
    if not CLIENT_ORIGIN_SHAPE.fullmatch(origin):
        raise ClientRuntimeResolutionError(
            f"Client contract {source}: '{key}' {origin!r} is not an origin a client may "
            "call. Expected 'https://<host>[:port]', or a loopback host on a local "
            f"profile, with no path. {_CONTRACT_FIX}"
        )


def _contract_object(
    parent: dict[str, object], key: str, source: str
) -> dict[str, object]:
    """*parent*'s *key* as a JSON object, or fail naming it."""
    value = parent.get(key)
    if not isinstance(value, dict):
        raise ClientRuntimeResolutionError(
            f"Client contract {source}: '{key}' is not a JSON object. {_CONTRACT_FIX}"
        )
    return value


def _contract_text(parent: dict[str, object], key: str, source: str) -> str:
    """*parent*'s *key* as a non-empty string, or fail naming it."""
    value = parent.get(key)
    if not isinstance(value, str) or not value:
        raise ClientRuntimeResolutionError(
            f"Client contract {source}: '{key}' is not a non-empty string. {_CONTRACT_FIX}"
        )
    return value


def _contract_text_list(parent: dict[str, object], key: str, source: str) -> list[str]:
    """*parent*'s *key* as a list of strings, or fail naming it."""
    value = parent.get(key)
    if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
        raise ClientRuntimeResolutionError(
            f"Client contract {source}: '{key}' is not a list of strings. {_CONTRACT_FIX}"
        )
    return value


