#: Each Static Web App by the release plan row that publishes it. Generation proves
#: every site has its row and every web row its site.
STATIC_WEB_APPS_BY_ROW: dict[tuple[str, str], StaticWebApp] = {
    (swa.app_key, swa.target): swa for swa in STATIC_WEB_APPS
}


def publish_static_web_app(
    app_key: str, target: str, build_inputs: Mapping[str, str]
) -> None:
    """Build the site of *app_key*'s *target*, given the deploy-supplied *build_inputs* its
    build takes, and upload it to its Static Web App.

    Raises:
        DeployError: The build or the upload failed.
    """
    deploy_one_static_web_app(STATIC_WEB_APPS_BY_ROW[(app_key, target)], build_inputs)


def host_static_web_app(app_key: str, target: str) -> None:
    """Serve the site of *app_key*'s *target* at its web domain.

    The site's Bicep module binds the domain to the Static Web App. A clients-only
    deploy runs no infrastructure stage, so the public access a ``down`` turned off is
    turned back on here, on every deploy that releases the site.

    Raises:
        DeployError: The site could not be served again.
    """
    swa = STATIC_WEB_APPS_BY_ROW[(app_key, target)]
    serve_static_web_app(swa)
    ok(f"{swa.static_site_name} deployed.")
    report_static_web_app_domain_records(swa)


# Custom domains: the DNS records each site's web domain needs. The site binds its domain
# with 'dns-txt-token' validation, which completes only once the operator's zone holds a TXT
# record with the token Azure issued, and the domain reaches the site only once a CNAME points
# it at the site's default hostname. The zone is the operator's, so the deploy names both
# records and says whether each is in place. Inlined from
# cruftfree_codegen_azure/custom_hostname_runtime.py.
#: The status Azure reports for a Static Web App custom domain once it is validated and bound.
STATIC_WEB_APP_DOMAIN_READY: str = "Ready"

#: The name prefix of the TXT record a Static Web App's ``dns-txt-token`` validation reads.
STATIC_WEB_APP_VALIDATION_PREFIX: str = "_dnsauth."


class CustomHostnameRecord(NamedTuple):
    """The ``CNAME`` one custom hostname needs, and whether DNS already answers it."""

    #: The custom hostname the edge binds.
    host: str
    #: The edge's managed host the ``CNAME`` points at.
    target: str
    #: Whether *host* resolves to an address *target* resolves to.
    published: bool


class DomainValidation(NamedTuple):
    """Where a Static Web App stands in validating one custom domain."""

    #: The custom domain.
    host: str
    #: The status Azure reports for it, e.g. ``Validating`` or ``Ready``.
    status: str
    #: The validation token the TXT record must hold; empty while Azure has issued none.
    token: str

    @property
    def validated(self) -> bool:
        """Whether Azure reports the domain validated and bound."""
        return self.status == STATIC_WEB_APP_DOMAIN_READY


def managed_gateway_host(gateway_url: str) -> str:
    """The host of API Management's gateway URL, the target of every custom hostname's record.

    Args:
        gateway_url: The ``gatewayUrl`` the deployed instance reports, e.g.
            ``https://shop-apim-dev.azure-api.net``.

    Returns:
        The host, e.g. ``shop-apim-dev.azure-api.net``.

    Raises:
        ValueError: The URL names no host.
    """
    host = urlsplit(gateway_url).hostname
    if not host:
        raise ValueError(
            f"API Management's gateway URL '{gateway_url}' names no host, so no custom "
            "hostname's DNS record can be named."
        )
    return host


def resolved_addresses(host: str) -> frozenset[str]:
    """The addresses DNS gives *host* now; empty when the name does not resolve.

    A name that does not resolve is the state this check exists to report (its record is not
    published yet), so it is an answer here, not a failure.
    """
    try:
        answers = socket.getaddrinfo(host, None)
    except (socket.gaierror, UnicodeError):
        return frozenset()
    return frozenset(str(answer[4][0]) for answer in answers)


def custom_hostname_records(
    hostnames: Sequence[str],
    target: str,
    resolve: Callable[[str], frozenset[str]] = resolved_addresses,
) -> list[CustomHostnameRecord]:
    """The record each of *hostnames* needs, in order, with whether it is published.

    A hostname counts as published when it resolves to an address *target* resolves to --
    what a ``CNAME`` to that host gives, however many hops the zone takes.

    Args:
        hostnames: The custom hostnames the edge binds.
        target: The edge's managed host.
        resolve: The host-to-addresses lookup.

    Returns:
        One record per hostname.
    """
    target_addresses = resolve(target)
    return [
        CustomHostnameRecord(
            host=host, target=target, published=bool(target_addresses & resolve(host))
        )
        for host in hostnames
    ]


def custom_hostname_line(record: CustomHostnameRecord, edge: str) -> str:
    """The one line a deploy prints for *record* on *edge*: the record, and whether DNS answers it."""
    if record.published:
        return f"{record.host} resolves to {edge} ({record.target})."
    return (
        f"{record.host} does not resolve to {edge} yet. Publish in its DNS zone: "
        f"CNAME {record.host} -> {record.target}"
    )


def static_web_app_domain_validation(host: str, shown: str) -> DomainValidation:
    """*host*'s validation state, from ``az staticwebapp hostname show -o json``'s output *shown*.

    Raises:
        ValueError: *shown* is not a JSON object.
    """
    data = json.loads(shown)
    if not isinstance(data, dict):
        raise ValueError(
            f"The state Azure reported for custom domain '{host}' is not a JSON object: {shown!r}"
        )
    return DomainValidation(
        host=host,
        status=str(data.get("status") or "unknown"),
        token=str(data.get("validationToken") or ""),
    )


def domain_validation_line(validation: DomainValidation, edge: str) -> str:
    """The one line a deploy prints for *validation* on *edge*: the TXT record it still needs."""
    if validation.validated:
        return f"{validation.host} is validated by {edge}."
    if validation.token:
        return (
            f"{validation.host} is not validated by {edge} yet ({validation.status}). "
            f"Publish in its DNS zone: TXT {STATIC_WEB_APP_VALIDATION_PREFIX}{validation.host} "
            f"{validation.token}"
        )
    return (
        f"{validation.host} is not validated by {edge} yet ({validation.status}), and Azure has "
        f"issued no validation token for it yet: the next deploy names its TXT record "
        f"{STATIC_WEB_APP_VALIDATION_PREFIX}{validation.host}."
    )


def report_static_web_app_domain_records(swa: StaticWebApp) -> None:
    """Name the TXT and CNAME records *swa*'s web domain needs, read against the deployed site.

    Reports, never fails: the site serves at its default hostname; its domain is reachable
    once the operator publishes the records, and the next deploy says so.

    Raises:
        DeployError: The site's default hostname could not be read.
    """
    edge = f"Static Web App {swa.static_site_name}"
    shown = az(
        "staticwebapp",
        "hostname",
        "show",
        "--name",
        swa.static_site_name,
        "--resource-group",
        client_resource_group(),
        "--hostname",
        swa.domain_name,
        "-o",
        "json",
        "--only-show-errors",
    )
    try:
        validation = (
            static_web_app_domain_validation(swa.domain_name, shown.stdout)
            if shown.succeeded
            else None
        )
    except ValueError as exc:
        note(f"Could not read the state of {swa.domain_name} on {edge}: {exc}")
    else:
        if validation is None:
            note(
                f"Could not read the state of {swa.domain_name} on {edge}: {shown.output}"
            )
        elif validation.validated:
            ok(domain_validation_line(validation, edge))
        else:
            note(domain_validation_line(validation, edge))
    (record,) = custom_hostname_records(
        (swa.domain_name,), read_static_site_property(swa, DEFAULT_HOSTNAME_PROPERTY)
    )
    if record.published:
        ok(custom_hostname_line(record, edge))
    else:
        note(custom_hostname_line(record, edge))


def run_clients_step(contract: Path, build_number: str | None) -> None:
    """Release every client of CLIENT_STEP_PLAN from the contract at *contract*.

    Args:
        contract: The client contract.
        build_number: The build number of a native target, or ``None`` when not given.

    Raises:
        DeployError: A check failed, the contract lacks what a deployed copy needs, or a
            publish or a build failed.
    """
    step("Releasing the clients")
    try:
        run_client_step(
            CLIENT_STEP_PLAN,
            PROJECT_ROOT,
            contract,
            ClientStepRuntime(
                read_contract=read_client_contract,
                compose=compose_client_runtime_config,
                verify_release=verify_client_release,
                log=ok,
            ),
            publish=publish_static_web_app,
            host=host_static_web_app,
            build_number=build_number,
        )
    except (ClientDeployStepError, ClientRuntimeResolutionError) as exc:
        raise DeployError(str(exc)) from exc


class ClientRequest(NamedTuple):
    """What the command line asked of ``deploy``'s clients."""

    #: The value of the scope flag, or ``None`` to run both scopes.
    scope: str | None
    #: The value of the contract flag, or ``None`` when absent.
    contract: str | None
    #: The build number of a native target, or ``None`` when absent.
    build_number: str | None


def client_request(parsed: argparse.Namespace) -> ClientRequest:
    """What *parsed* asks of ``deploy``'s clients."""
    return ClientRequest(
        parsed.scope,
        parsed.client_contract,
        None,
    )


def client_contract_file(clients: ClientRequest) -> Path:
    """The contract this deploy reads, refusing a bad command before anything runs.

    Raises:
        DeployError: The command names a contract this deploy does not read.
    """
    try:
        return client_contract_source(
            PROJECT_ROOT / CLIENT_CONTRACT_PATH,
            clients.contract,
            clients.scope,
            has_backend_scope=True,
        )
    except ClientDeployStepError as exc:
        raise DeployError(str(exc)) from exc


# ---------------------------------------------------------------------------
# Stopping and serving the sites: 'down' and the clients step
# ---------------------------------------------------------------------------
# The host defines client_resource_group(): the resource group holding STATIC_WEB_APPS.

#: The resource type of a Static Web App, as ``az resource`` names it.
STATIC_SITE_RESOURCE_TYPE: str = "Microsoft.Web/staticSites"

#: The site property that says whether public traffic reaches it, the value 'down' sets,
#: and the value the clients step restores. The site's Bicep module declares it public too.
PUBLIC_ACCESS_PROPERTY: str = "publicNetworkAccess"
PUBLIC_ACCESS_DISABLED: str = "Disabled"
PUBLIC_ACCESS_ENABLED: str = "Enabled"

#: The site property holding the host Azure assigned it.
DEFAULT_HOSTNAME_PROPERTY: str = "defaultHostname"

#: The lowest HTTP status that counts as a site refusing traffic: a 2xx serves it, and
#: a 3xx still sends a visitor on to it.
SITE_REFUSED_STATUS_FLOOR: int = 400

#: How long 'down' waits for a stopped site to refuse traffic, how often it asks, and
#: how long one request may take: the edge follows the resource after a delay.
SITE_STOP_TIMEOUT_SECONDS: int = 300
SITE_STOP_POLL_SECONDS: int = 10
SITE_STOP_REQUEST_TIMEOUT_SECONDS: int = 10


def standing_static_web_apps() -> list[StaticWebApp]:
    """The sites of STATIC_WEB_APPS deployed in the resource group, in declared order.

    Raises:
        DeployError: The resource group's sites could not be listed.
    """
    listed = az(
        "resource",
        "list",
        "--resource-group",
        client_resource_group(),
        "--resource-type",
        STATIC_SITE_RESOURCE_TYPE,
        "--query",
        "[].name",
        "-o",
        "tsv",
    )
    if not listed.succeeded:
        raise DeployError(
            f"Could not list the sites of resource group "
            f"'{client_resource_group()}': {listed.output}"
        )
    deployed = set(listed.stdout.splitlines())
    return [swa for swa in STATIC_WEB_APPS if swa.static_site_name in deployed]


def _static_site_arguments(swa: StaticWebApp) -> tuple[str, ...]:
    """The ``az resource`` arguments naming *swa*."""
    return (
        "--resource-group",
        client_resource_group(),
        "--name",
        swa.static_site_name,
        "--resource-type",
        STATIC_SITE_RESOURCE_TYPE,
    )


def read_static_site_property(swa: StaticWebApp, name: str) -> str:
    """The value of property *name* of *swa*, as Azure holds it now.

    Raises:
        DeployError: The site could not be read, or holds no such value.
    """
    shown = az(
        "resource",
        "show",
        *_static_site_arguments(swa),
        "--query",
        f"properties.{name}",
        "-o",
        "tsv",
    )
    if not shown.succeeded or not shown.stdout:
        raise DeployError(
            f"Could not read {name} of site '{swa.static_site_name}': "
            f"{shown.output or 'it holds no value'}"
        )
    return shown.stdout


def set_static_site_access(swa: StaticWebApp, access: str) -> None:
    """Set whether public traffic reaches *swa* to *access*, and read the setting back.

    Raises:
        DeployError: The update failed, or the site reads anything but *access*.
    """
    updated = az(
        "resource",
        "update",
        *_static_site_arguments(swa),
        "--set",
        f"properties.{PUBLIC_ACCESS_PROPERTY}={access}",
        "-o",
        "none",
    )
    if not updated.succeeded:
        raise DeployError(
            f"Could not set {PUBLIC_ACCESS_PROPERTY}={access} on site "
            f"'{swa.static_site_name}': {updated.output}"
        )
    read_back = read_static_site_property(swa, PUBLIC_ACCESS_PROPERTY)
    if read_back != access:
        raise DeployError(
            f"Site '{swa.static_site_name}' reads {PUBLIC_ACCESS_PROPERTY}={read_back} "
            f"after the update to {access}."
        )


def serve_static_web_app(swa: StaticWebApp) -> None:
    """Admit public traffic to *swa* again, unless it already does.

    Raises:
        DeployError: The site could not be read or updated.
    """
    if read_static_site_property(swa, PUBLIC_ACCESS_PROPERTY) != PUBLIC_ACCESS_ENABLED:
        set_static_site_access(swa, PUBLIC_ACCESS_ENABLED)
        ok(f"{swa.static_site_name} serves public traffic again.")


def site_refuses_traffic(hostname: str) -> tuple[bool, str]:
    """Whether *hostname* refuses a request, and what it answered.

    One request over verified TLS, following no redirect. Only a refusal the site gave
    counts: no answer proves nothing, since it may be this machine's network.

    Returns:
        ``(True, "HTTP <status>")`` on a refusal; otherwise ``(False, <what happened>)``.
    """
    connection = http.client.HTTPSConnection(
        hostname, timeout=SITE_STOP_REQUEST_TIMEOUT_SECONDS
    )
    try:
        connection.request("GET", "/")
        status = connection.getresponse().status
    except (OSError, http.client.HTTPException) as error:
        return False, f"no answer ({error})"
    finally:
        connection.close()
    return status >= SITE_REFUSED_STATUS_FLOOR, f"HTTP {status}"


def require_static_web_app_stopped(swa: StaticWebApp) -> None:
    """Wait, within SITE_STOP_TIMEOUT_SECONDS, for *swa*'s default hostname to refuse traffic.

    Raises:
        DeployError: The site still serves, or gave no refusal, when the wait ends.
    """
    hostname = read_static_site_property(swa, DEFAULT_HOSTNAME_PROPERTY)
    deadline = time.monotonic() + SITE_STOP_TIMEOUT_SECONDS
    while True:
        refused, answer = site_refuses_traffic(hostname)
        if refused:
            ok(f"{swa.static_site_name} stopped: {hostname} answers {answer}.")
            return
        if time.monotonic() >= deadline:
            break
        time.sleep(SITE_STOP_POLL_SECONDS)
    raise DeployError(
        f"Site '{swa.static_site_name}' reads {PUBLIC_ACCESS_PROPERTY}="
        f"{PUBLIC_ACCESS_DISABLED}, but {hostname} last gave {answer} after "
        f"{SITE_STOP_TIMEOUT_SECONDS}s of waiting for a refusal. Its files are intact: "
        f"run '{VERB_DOWN}' again once the cause is clear."
    )


def stop_static_web_apps() -> None:
    """Stop serving every deployed site, losing nothing.

    Each site refuses public traffic, which is read back and then proved at its default
    hostname. Its files stay, and the next ``deploy`` that releases it serves it again.
    A site never deployed is skipped.

    Raises:
        DeployError: Azure could not answer, or a site did not stop.
    """
    standing = standing_static_web_apps()
    if not standing:
        note(f"No site of {APP_NAME} is deployed -- no site to stop.")
        return

    step("Stopping the Static Web Apps")
    for swa in standing:
        ok(f"stopping {swa.static_site_name}")
        set_static_site_access(swa, PUBLIC_ACCESS_DISABLED)

    step("Waiting for each site to refuse traffic")
    for swa in standing:
        require_static_web_app_stopped(swa)


# ---------------------------------------------------------------------------
# API Management custom domain: TLS certificate store + certificate gate
# ---------------------------------------------------------------------------


def apim_tls_vault_name() -> str:
    """The TLS certificate Key Vault's name for this environment ('' when no
    gateway custom domain is declared)."""
    if APIM_TLS_CERTIFICATE is None:
        return ""
    return APIM_TLS_CERTIFICATE.vault_name


def _recover_soft_deleted_tls_vault(vault_name: str) -> None:
    """Recover the TLS certificate vault when a teardown left it soft-deleted.

    The vault is purge-protected, so a same-name redeploy can neither purge
    nor recreate it -- recovering is the only way forward, and it brings the
    imported certificate back with it.
    """
    deleted = az_text(
        "keyvault",
        "list-deleted",
        "--query",
        f"[?name=='{vault_name}'].name",
        "-o",
        "tsv",
        "--only-show-errors",
    )
    if not deleted:
        return
    note(
        f"recovering soft-deleted TLS certificate vault '{vault_name}' (purge-protected)"
    )
    recovered = az(
        "keyvault", "recover", "--name", vault_name, "-o", "none", "--only-show-errors"
    )
    if not recovered.succeeded:
        raise DeployError(
            f"Could not recover the soft-deleted TLS certificate vault "
            f"'{vault_name}'. It is purge-protected, so the name cannot be "
            f"reused until it is recovered. az reported: {recovered.output} "
            f"Fix: run 'az keyvault recover --name {vault_name}' with an "
            f"identity allowed to recover vaults in this subscription, then "
            f"re-run this command."
        )


def _require_tls_certificate(vault_name: str, certificate: ApimTlsCertificate) -> None:
    """Refuse to continue until the gateway custom domain's certificate exists.

    API Management fetches the certificate while it applies the custom
    hostname, so deploying without it fails deep inside the infrastructure
    stage with a Key Vault error that names neither the vault nor the fix.
    Checked through the control plane, which needs no data-plane role and no
    network line of sight to the vault.
    """
    found = az_text(
        "resource",
        "show",
        "--resource-group",
        SETTINGS.resource_group,
        "--namespace",
        "Microsoft.KeyVault",
        "--parent",
        f"vaults/{vault_name}",
        "--resource-type",
        "secrets",
        "--name",
        certificate.certificate_name,
        "--query",
        "id",
        "-o",
        "tsv",
        "--only-show-errors",
    )
    if found:
        ok(f"certificate '{certificate.certificate_name}' is in '{vault_name}'")
        return
    raise DeployError(
        f"The TLS certificate for the API gateway custom domain "
        f"'{certificate.domain_name}' is not in Key Vault '{vault_name}'. "
        f"Import it as a Key Vault CERTIFICATE (not a secret) named "
        f"'{certificate.certificate_name}' -- a PFX whose subject or subject "
        f"alternative name covers '{certificate.domain_name}':\n"
        f"  az keyvault certificate import --vault-name {vault_name} "
        f"--name {certificate.certificate_name} --file <certificate.pfx>\n"
        f"The importing identity needs the 'Key Vault Certificates Officer' "
        f"role on that vault, and a network the vault admits. Then re-run "
        f"this command."
    )


def provision_apim_tls_certificate_store() -> None:
    """Provision the gateway custom domain's certificate store, then gate on
    the certificate.

    Runs before the infrastructure stage that creates API Management: the
    reader identity's role must already be granted, and the certificate
    already imported, when API Management applies the hostname. A no-op when
    no gateway custom domain is declared.
    """
    certificate = APIM_TLS_CERTIFICATE
    if certificate is None:
        return
    vault_name = apim_tls_vault_name()
    step(f"API gateway custom domain: TLS certificate store ('{vault_name}')")
    _recover_soft_deleted_tls_vault(vault_name)
    deployed = az(
        "deployment",
        "group",
        "create",
        "--name",
        f"cruftfree-apim-tls-certificate-{SETTINGS.environment}",
        "--resource-group",
        SETTINGS.resource_group,
        "--template-file",
        str(PROJECT_ROOT / certificate.module_path),
        "--parameters",
        f"location={SETTINGS.location}",
        "-o",
        "none",
        "--only-show-errors",
    )
    if not deployed.succeeded:
        raise DeployError(
            f"The TLS certificate store deployment for '{vault_name}' failed. "
            f"az reported: {deployed.output}"
        )
    ok(
        "vault and certificate-reader identity in place (identity: "
        f"{certificate.identity_name})"
    )
    _require_tls_certificate(vault_name, certificate)


def run_push_phase_with_turbo_scale(
    push: Callable[[], None] = push_phase,
) -> None:
    """Run the code-push phase, optionally inside a temporary plan scale-up.

    OFF by default: without the flag this makes ZERO ``az appservice plan``
    calls and simply runs the push phase. Turned on, it records the shared
    plan's current SKU, scales it up for the push phase only, and restores the
    original SKU afterward -- on success, on failure, and on interrupt. The
    behavior stays explicit-flag-only because scaling changes what the plan
    bills and restarts every site on it.

    Args:
        push: The phase to run inside the scale-up. Defaults to the real
            code-push phase; taking it as an argument is what makes the
            scale-up/restore contract exercisable on its own.

    Raises:
        DeployError: If the push phase failed, or if the restore itself failed
            (which names the exact manual restore command).
    """
    if not SETTINGS.turbo_scale:
        push()
        return

    plan = SETTINGS.plan_name
    step(f"TurboScale: recording current SKU for plan '{plan}' before the code push")
    original_sku = az_text(
        "appservice",
        "plan",
        "show",
        "--name",
        plan,
        "--resource-group",
        SETTINGS.resource_group,
        "--query",
        "sku.name",
        "-o",
        "tsv",
        "--only-show-errors",
    )
    if not original_sku:
        note(
            f"TurboScale: could not read the current SKU for plan '{plan}' in "
            f"resource group '{SETTINGS.resource_group}' -- running the push "
            f"phase WITHOUT scaling."
        )
        push()
        return

    note(
        f"TurboScale: scaling '{plan}' from '{original_sku}' to "
        f"'{TURBO_SCALE_SKU}' for the code-push phase. Sites on this plan will "
        f"restart; the original SKU is restored afterward."
    )
    scale_up = az(
        "appservice",
        "plan",
        "update",
        "--name",
        plan,
        "--resource-group",
        SETTINGS.resource_group,
        "--sku",
        TURBO_SCALE_SKU,
        "-o",
        "none",
    )
    if not scale_up.succeeded:
        note(
            f"TurboScale: scale-up to '{TURBO_SCALE_SKU}' failed -- running the "
            f"push phase at the ORIGINAL SKU '{original_sku}' (nothing to "
            f"restore). az reported: {scale_up.output}"
        )
        push()
        return

    try:
        push()
    finally:
        _restore_plan_sku(plan, original_sku)


def _restore_plan_sku(plan: str, original_sku: str) -> None:
    """Restore the shared plan's original SKU after a scaled code-push phase.

    Raises:
        DeployError: If the restore failed, naming the manual restore command.
            Raised from a ``finally`` block, so it never masks a push-phase
            failure that is already propagating.
    """
    step(f"TurboScale: restoring plan '{plan}' to its original SKU '{original_sku}'")
    restore = az(
        "appservice",
        "plan",
        "update",
        "--name",
        plan,
        "--resource-group",
        SETTINGS.resource_group,
        "--sku",
        original_sku,
        "-o",
        "none",
    )
    if restore.succeeded:
        ok(f"TurboScale: plan '{plan}' restored to '{original_sku}'.")
        return
    raise DeployError(
        f"TurboScale FAILED to restore plan '{plan}' to its original SKU "
        f"'{original_sku}'. Restore it manually: az appservice plan update "
        f"--name {plan} --resource-group {SETTINGS.resource_group} --sku "
        f"{original_sku}"
    )


# ---------------------------------------------------------------------------
# Container image supply
# ---------------------------------------------------------------------------


def docker_with_retry(what: str, argv: Sequence[str]) -> None:
    """Run a registry-facing docker/az command, retrying transient faults.

    Args:
        what: Operator-facing description used in progress and error messages.
        argv: Arguments to ``docker``, or to ``az`` when the first element is
            ``"az"`` -- the ACR login is part of the same retry contract as the
            pushes that depend on it.

    Raises:
        DeployError: When the attempt budget is exhausted.
    """
    last_result: CommandResult | None = None
    for attempt in range(1, DOCKER_MAX_ATTEMPTS + 1):
        # Streamed, not captured: these are the longest-running commands of a
        # container deploy, and an operator must be able to watch them.
        if argv[0] == "az":
            last_result = az(*argv[1:], stream=True)
        else:
            last_result = docker(*argv, stream=True)
        if last_result.succeeded:
            if attempt > 1:
                ok(f"{what} succeeded on attempt {attempt} (after backoff).")
            return
        if attempt == DOCKER_MAX_ATTEMPTS:
            break
        wait = DOCKER_BACKOFFS[min(attempt, len(DOCKER_BACKOFFS)) - 1]
        note(
            f"{what} failed (attempt {attempt}/{DOCKER_MAX_ATTEMPTS}, exit "
            f"{last_result.returncode}) -- likely a transient registry/network "
            f"fault; backing off {wait}s and retrying idempotently (cached "
            f"layers and already-pushed content are reused)."
        )
        time.sleep(wait)
    exit_code = last_result.returncode if last_result is not None else -1
    captured = (
        f"\n  Captured output (this ran inside a wave, so it was captured "
        f"rather than streamed):\n  {last_result.output}"
        if last_result is not None and last_result.output
        else ""
    )
    raise DeployError(
        f"{what} failed after {DOCKER_MAX_ATTEMPTS} attempts (last exit "
        f"{exit_code}). A deterministic failure (broken Dockerfile, bad "
        f"credentials, real registry outage) fails every attempt in seconds; a "
        f"persistent transient fault exhausts the retry budget. Review the "
        f"output above.{captured}"
    )


def acr_login() -> None:
    """Authenticate the local docker daemon against the shared registry."""
    docker_with_retry(
        f"az acr login for registry '{SETTINGS.acr_name}'",
        ("az", "acr", "login", "--name", SETTINGS.acr_name, "--only-show-errors"),
    )


def acr_tag_exists(repository: str, tag: str) -> bool:
    """Return True when the registry already holds ``repository:tag``.

    Distinguishes "repository or tag not found" (a build is needed) from any
    other failure such as an authentication error, which fails loud rather than
    being silently treated as a skip.

    Raises:
        DeployError: If the registry could not be queried at all.
    """
    result = az(
        "acr",
        "repository",
        "show-tags",
        "--name",
        SETTINGS.acr_name,
        "--repository",
        repository,
        "--query",
        f"[?@=='{tag}']",
        "-o",
        "tsv",
        "--only-show-errors",
    )
    if result.succeeded:
        return bool(result.stdout)
    lowered = result.output.lower()
    if any(
        fragment in lowered
        for fragment in ("not found", "name_unknown", "could not be found")
    ):
        return False
    raise DeployError(
        f"Could not query the container registry for repository '{repository}' "
        f"tag '{tag}': {result.output}"
    )


def build_and_push_base_images() -> None:
    """Build (or reuse) each shared base image (:func:`build_and_push_base_image`)."""
    for base in BASE_IMAGES:
        build_and_push_base_image(base)


def build_and_push_base_image(base: BaseImage) -> None:
    """Build (or reuse) one shared base image and leave it resolvable locally.

    The base image tag is a content hash of the union of the runtime
    requirements of the services of its language, computed at GENERATION time
    by the same shared algorithm that baked this exact tag into the ``FROM``
    line of every Dockerfile of that language -- never re-derived here.

    Local availability is part of this function's contract, not an
    afterthought: each per-service Dockerfile's ``FROM`` is the BARE
    ``<repo>:<tag>`` reference (that template is shared with the local compose
    target, so it carries no registry prefix), which docker resolves against the
    local daemon and then the public hub -- never against this registry. A plain
    ``buildx --push`` publishes without loading locally, and the
    already-in-registry path builds nothing at all, so on a fresh deploy host
    every service build would fail resolving its ``FROM``. Both paths below
    therefore end with the base present locally under exactly that reference.
    """
    remote = f"{SETTINGS.acr_login_server}/{base.repo}:{base.tag}"
    bare = f"{base.repo}:{base.tag}"
    if acr_tag_exists(base.repo, base.tag):
        ok(
            f"Base image {bare} is already in the registry -- skipping the "
            f"build, pulling it for the service builds."
        )
        # The explicit platform is mandatory, not host-default: the base image
        # exists only for linux/amd64, so a bare pull on an arm64 host fails
        # resolving the manifest.
        docker_with_retry(
            "Pulling the shared base image",
            ("pull", "--platform", CONTAINER_PLATFORM, remote),
        )
    else:
        step(f"Building shared base image {bare} (union requirements)")
        # --load (then an explicit push) rather than a bare --push: --push alone
        # never populates the local daemon, which the service builds need.
        docker_with_retry(
            "Building the shared base image",
            (
                "buildx",
                "build",
                "--platform",
                CONTAINER_PLATFORM,
                "-t",
                remote,
                "-f",
                base.dockerfile_path,
                base.build_context,
                "--load",
            ),
        )
        docker_with_retry("Pushing the shared base image", ("push", remote))
    tag_result = docker("tag", remote, bare)
    if not tag_result.succeeded:
        raise DeployError(
            f"Tagging the shared base image as '{bare}' failed -- every service "
            f"Dockerfile's FROM line resolves exactly that reference. docker "
            f"reported: {tag_result.output}"
        )


def service_image_tag(service: Service) -> str:
    """Return one service's image tag: a content hash of its build inputs."""
    return deploy_content_hash([PROJECT_ROOT / service.service_dir])


def base_image_contexts() -> list[str]:
    """The ``--build-context`` arguments that resolve each service ``FROM`` from the registry.

    A service Dockerfile's ``FROM`` names the bare base tag. A builder that runs
    in a container never reads the engine's image store, so it would resolve that
    name against a public registry and fail on a pull of an image that was never
    published. Each bare tag is therefore bound to the pushed, registry-qualified
    image, which every builder driver resolves the same way. A base the
    Dockerfile does not name is ignored by the build.
    """
    contexts: list[str] = []
    for base in BASE_IMAGES:
        bare = f"{base.repo}:{base.tag}"
        contexts.extend(
            [
                "--build-context",
                f"{bare}=docker-image://{SETTINGS.acr_login_server}/{bare}",
            ]
        )
    return contexts


def build_and_push_service_image(service: Service) -> str:
    """Build and push one service's image, skipping when the tag already exists.

    A base-image build argument is deliberately NOT passed: the service
    Dockerfile's ``FROM`` is a bare, non-parameterized literal, so such an
    argument would be silently ignored. The base image is instead guaranteed to
    resolve locally under exactly that reference.

    Returns:
        The resolved content-hash tag.
    """
    tag = service_image_tag(service)
    if acr_tag_exists(service.image_name, tag):
        ok(
            f"Image {service.image_name}:{tag} is already in the registry -- "
            f"skipping build and push."
        )
        return tag
    docker_with_retry(
        f"Building and pushing the image for '{service.image_name}'",
        (
            "buildx",
            "build",
            "--platform",
            CONTAINER_PLATFORM,
            *base_image_contexts(),
            "-t",
            f"{SETTINGS.acr_login_server}/{service.image_name}:{tag}",
            "-f",
            f"{service.service_dir}/Dockerfile",
            "--push",
            service.service_dir,
        ),
    )
    return tag


def build_and_push_worker_image(service: Service, worker: Worker, tag: str) -> None:
    """Build and push one worker image FROM its service's image, with that image's tag.

    The worker Dockerfile's ``FROM`` is its ``SERVICE_IMAGE`` build argument, so
    the worker runs exactly the service image it was built on; the service image
    is in the registry by now (:func:`build_and_push_service_image` returned its
    tag), and the build pulls it from there. The worker image shares the service
    image's tag: both are a content hash of the service directory, which holds the
    worker Dockerfile too, so a changed worker Dockerfile changes the tag.
    """
    if acr_tag_exists(worker.image_name, tag):
        ok(
            f"Image {worker.image_name}:{tag} is already in the registry -- "
            f"skipping build and push."
        )
        return
    docker_with_retry(
        f"Building and pushing the worker image '{worker.image_name}'",
        (
            "buildx",
            "build",
            "--platform",
            CONTAINER_PLATFORM,
            "--build-arg",
            f"SERVICE_IMAGE={SETTINGS.acr_login_server}/{service.image_name}:{tag}",
            "-t",
            f"{SETTINGS.acr_login_server}/{worker.image_name}:{tag}",
            "-f",
            worker.dockerfile_path,
            "--push",
            service.service_dir,
        ),
    )


def container_sites(service: Service) -> tuple[tuple[str, str], ...]:
    """Return each deployed App Service site of one service with the image it runs.

    Its web site runs the service image when it serves HTTP; each worker site
    runs its own worker image (container mode).
    """
    sites = (
        ((service.web_app_name, service.image_name),) if service.has_web_site else ()
    )
    sites += tuple((worker.site_name, worker.image_name) for worker in service.workers)
    return tuple((f"{site}-{SETTINGS.environment}", image) for site, image in sites)


def image_tag_param_keys(service: Service) -> tuple[str, ...]:
    """Return the keys of the image-tag parameters one service's sites take.

    Its own image's when it runs a web site, and each worker image's. A service
    without a web site still builds its image (its workers are built FROM it) but
    takes no parameter for it.
    """
    keys = (service.image_tag_param_key,) if service.has_web_site else ()
    return keys + tuple(worker.image_tag_param_key for worker in service.workers)


def deploy_param_file(source_param_file: str) -> str:
    """Return the deploy-time copy's path for a generated ``.bicepparam``.

    Kept in the SAME directory as the source so the parameter file's relative
    ``using`` path still resolves. The derived file is gitignored.
    """
    return re.sub(r"\.bicepparam$", ".deploy.bicepparam", source_param_file)


def set_container_image_tag_placeholder(
    param_file: Path, service_key: str, tag: str
) -> None:
    """Replace one service's image-tag placeholder with its resolved tag.

    The full quoted placeholder is matched, including its surrounding quotes, so
    one service's key can never match as a substring of another's.

    Raises:
        DeployError: If the tag is not a valid Docker tag, or the placeholder is
            missing. Both would otherwise surface much later as an opaque
            submission failure, after every image has been built and pushed.
    """
    if not DOCKER_TAG_PATTERN.match(tag):
        preview = tag[:100] + (" ...(truncated)" if len(tag) > 100 else "")
        raise DeployError(
            f"Resolved image tag for '{service_key}' is not a valid Docker tag "
            f"({len(tag)} chars): '{preview}'\n"
            f"  Expected: a leading alphanumeric or underscore, then "
            f"alphanumerics, dots, underscores or hyphens, 128 characters max.\n"
            f"  Refusing to continue: the deployment would ship a corrupted "
            f"image reference."
        )
    placeholder = f"'{IMAGE_TAG_PLACEHOLDER_PREFIX}{service_key}'"
    content = param_file.read_text(encoding="utf-8")
    if placeholder not in content:
        raise DeployError(
            f"Image-tag placeholder {placeholder} not found in "
            f"'{param_file}'.\n"
            f"  This is a deploy-time copy of the generated "
            f"infra/main*.bicepparam; a missing placeholder means the generated "
            f"file did not contain it. Re-generate the project so the "
            f"placeholders are emitted, then deploy again.\n"
            f"  Refusing to continue: the deployment would silently use a stale "
            f"or missing image tag."
        )
    param_file.write_text(content.replace(placeholder, f"'{tag}'"), encoding="utf-8")


def supply_service_images() -> dict[str, str]:
    """Build and push every service's container image, bounded-parallel.

    The base image is resolved SERIALLY first and is a real prerequisite:
    every per-service Dockerfile's ``FROM`` is a bare reference to it, so a
    service build that started before the base image is locally resolvable
    would fail resolving its own base layer. Per-service builds then run
    through the generic wave driver, bounded by ``SETTINGS.image_wave_size``.

    Each wave item's action returns ``None`` by the wave driver's contract
    (``run_deploy_wave``'s action type is ``Callable[[int, Service], None]``
    and is not changed here), so results are collected into a dict guarded by
    a lock held only around the dict write -- never around the build/push
    itself, so the lock never serializes the actual concurrent work.

    A service's worker images are built in its own wave item, after its service
    image, because each is built FROM it; they take the service image's tag.

    Returns:
        Mapping of each service's ``image_tag_param_key`` to its resolved
        (built-and-pushed, or already-registry-resident) image tag. A worker
        image's tag is its service's tag (:func:`image_tag_param_keys`).
    """
    resolve_executable("docker", DOCKER_INSTALL_HINT)
    step("Resolving container image tags")
    acr_login()
    build_and_push_base_images()

    resolved: dict[str, str] = {}
    lock = threading.Lock()

    def _build_one_service_image(index: int, service: Service) -> None:
        item(index, len(SERVICES), service.display_name)
        tag = build_and_push_service_image(service)
        for worker in service.workers:
            build_and_push_worker_image(service, worker, tag)
        with lock:
            resolved[service.image_tag_param_key] = tag

    run_deploy_wave(SETTINGS.image_wave_size, _build_one_service_image, SERVICES)
    return resolved


def resolve_container_image_tags(source_param_file: str) -> str:
    """Build and push every image, resolving the tags into a deploy-time param.

    Runs BEFORE any Bicep deploy stage, so every image the infrastructure
    references already exists. The generated ``.bicepparam`` is read-only here:
    mutating it in place would make the deploy single-use (a second run would
    find no placeholders) and leave the generated tree drifting from the
    generator's output. The source is copied to a sibling deploy-time file and
    the substitutions happen there.

    The substitution loop below runs strictly AFTER ``supply_service_images``
    returns -- i.e. after every wave has fully completed and exactly one
    thread is running -- because ``set_container_image_tag_placeholder`` is a
    read-modify-write on this shared file and is not safe to call
    concurrently: two threads racing to read-then-write it could silently
    lose one substitution.

    Returns:
        The deploy-time parameter file to hand to the infrastructure stage.
    """
    resolved_param_file = deploy_param_file(source_param_file)
    shutil.copyfile(
        PROJECT_ROOT / source_param_file, PROJECT_ROOT / resolved_param_file
    )
    resolved_tags = supply_service_images()
    for service in SERVICES:
        for key in image_tag_param_keys(service):
            set_container_image_tag_placeholder(
                PROJECT_ROOT / resolved_param_file,
                key,
                resolved_tags[service.image_tag_param_key],
            )
    return resolved_param_file


# ---------------------------------------------------------------------------
# Shared deploy steps
# ---------------------------------------------------------------------------


def validate_bicep_templates(template: str) -> None:
    """Compile a Bicep template, failing loud with the compiler's own errors."""
    step("Validating Bicep templates")
    result = az("bicep", "build", "--file", template)
    if not result.succeeded:
        raise DeployError(
            f"Bicep template validation failed. Fix {template} before deploying. "
            f"az reported: {result.output}"
        )
    ok("Bicep templates valid")


def same_region(left: str, right: str) -> bool:
    """Compare two Azure region designations that may be written differently.

    Azure names one region two ways and hands back whichever the API in
    question prefers: the slug an ARM path is addressed by ("westcentralus")
    and the display name ("West Central US"). ``az`` takes either as an
    argument -- including the ``LOCATION`` an operator sets by hand -- so the
    difference stays invisible until something compares them, and then a raw
    ``==`` is silently False for two spellings of the same place.
    """
    return left.replace(" ", "").lower() == right.replace(" ", "").lower()


def ensure_resource_group() -> None:
    """Create the resource group, guarding against a wrong-region collision.

    A resource group's location is immutable, so an existing group in another
    region is reported with both ways out rather than silently deployed into.
    """
    step(
        f"Ensuring resource group '{SETTINGS.resource_group}' in '{SETTINGS.location}'"
    )
    existing_location = ""
    if az_text("group", "exists", "--name", SETTINGS.resource_group) == "true":
        existing_location = az_text(
            "group",
            "show",
            "--name",
            SETTINGS.resource_group,
            "--query",
            "location",
            "-o",
            "tsv",
        )
    if existing_location and not same_region(existing_location, SETTINGS.location):
        raise DeployError(
            f"Resource group '{SETTINGS.resource_group}' already exists in "
            f"'{existing_location}', but this deploy targets "
            f"'{SETTINGS.location}'. A resource group's location cannot be "
            f"changed.\n"
            f"  - To deploy to the existing region: set LOCATION="
            f"'{existing_location}' and re-run (it must not be offer-restricted "
            f"for your resources).\n"
            f"  - To move to '{SETTINGS.location}' (DELETES all resources in "
            f"'{SETTINGS.resource_group}'): run the destroy command, then deploy "
            f"again."
        )
    result = az(
        "group",
        "create",
        "--name",
        SETTINGS.resource_group,
        "--location",
        SETTINGS.location,
        "-o",
        "none",
    )
    if not result.succeeded:
        raise DeployError(
            f"Failed to create or update resource group "
            f"'{SETTINGS.resource_group}'. az reported: {result.output}"
        )
    ok("Resource group ready")


def apply_staged_connection_capacity() -> None:
    """Restart any Postgres server still staging a connection-capacity change.

    The pool Bicep sets max_connections to the compute SKU's default, but that
    is a STATIC PostgreSQL parameter: on a server whose tier changed after
    creation, Azure stages the new value as pending-restart and the engine keeps
    enforcing the smaller ceiling until the server restarts. This clears that
    after the infrastructure deploy and before services open their pools, so the
    fleet does not crash-loop on "remaining connection slots are reserved". A
    freshly provisioned server already runs at the value, so this is a no-op on
    a from-scratch deploy.

    Raises:
        DeployError: If a restart that is needed fails.
    """
    if not POSTGRES_FLEXIBLE_SERVERS:
        return
    step("Applying staged database connection-capacity changes")
    for server in POSTGRES_FLEXIBLE_SERVERS:
        pending = az_text(
            "postgres",
            "flexible-server",
            "parameter",
            "show",
            "--resource-group",
            SETTINGS.resource_group,
            "--server-name",
            server,
            "--name",
            "max_connections",
            "--query",
            "isConfigPendingRestart",
            "-o",
            "tsv",
            "--only-show-errors",
        )
        if pending.strip().lower() != "true":
            ok(f"'{server}' connection capacity already in effect (no restart needed).")
            continue
        note(
            f"max_connections is staged on '{server}' (pending restart) -- "
            f"restarting to apply the validated connection capacity."
        )
        result = az(
            "postgres",
            "flexible-server",
            "restart",
            "--resource-group",
            SETTINGS.resource_group,
            "--name",
            server,
            "-o",
            "none",
            "--only-show-errors",
        )
        if not result.succeeded:
            raise DeployError(
                f"Failed to restart Postgres flexible server '{server}' to apply "
                f"the staged max_connections change. The server is still "
                f"enforcing its previous connection ceiling; pooled services may "
                f"crash-loop on 'remaining connection slots are reserved'. "
                f"Restart it manually: az postgres flexible-server restart "
                f"--resource-group {SETTINGS.resource_group} --name {server}. "
                f"az reported: {result.output}"
            )
        ok(f"Restarted '{server}' -- max_connections now in effect.")


def deploy_foundation_stage() -> None:
    """Deploy the foundation stage: Key Vault, databases, their schema workload, and the registry.

    These carry the offer/quota restrictions and the slowest provisioning, so
    deploying them first surfaces a region/SKU block in a couple of minutes
    instead of after the bulk. The schema workload (the run store, each block's
    schema identity and owner), when the application has a database, is here so
    every block's schema can be read and changed before the release starts. The
    full stage re-declares them idempotently, so nothing is wasted.
    """
    registry = " + registry" if CONTAINER_MODE else ""
    step(f"Stage 1/2: foundation (Key Vault + databases + schema workload{registry})")
    note("Provisioning the offer-restricted / slowest resources first to fail fast.")
    invoke_bicep_stage(SETTINGS.foundation_param_file, "foundation")
    ok(f"Foundation provisioned ({elapsed()} elapsed).")


def _account_name() -> str:
    """Return the signed-in subscription's display name."""
    return az_text("account", "show", "--query", "name", "-o", "tsv")


# ---------------------------------------------------------------------------
# Commands
# ---------------------------------------------------------------------------


def _resolve_infra_trim() -> tuple[bool, str]:
    """Decide whether this deploy may skip what-if and the foundation stage.

    Reads the resource-group stamp and this run's `infra_content_hash()` ONCE,
    so the identical current hash is reused both for the trim decision here and
    for the stamp write at the end of a successful run -- computing it twice
    could theoretically observe a filesystem change between the two reads.

    Returns:
        (trim, current_hash) -- current_hash is returned so the caller can pass
        it straight to `write_infra_hash_stamp` later without recomputing it.
    """
    current_hash = infra_content_hash()
    stored_hash = read_infra_hash_stamp()
    trim = preflight_trim_allowed(stored_hash, current_hash, SETTINGS.force)
    return trim, current_hash


def command_deploy(approved: bool, clients: ClientRequest) -> None:
    """Provision the infrastructure and deliver the application code, converging every block around the release.

    The ``converge`` step: the foundation stage brings up the databases and their
    schema workload, every block is read, planned and expanded, the release (the
    full infrastructure stage and the code) starts and is verified healthy
    (``command_verify``), and only then is each block's contract applied and its
    schema verified. The client contract is then written, and the clients step
    releases every client from it.

    Args:
        approved: Whether the command line gave ``--approved``: the one source
            of approval for a change that needs it.
        clients: What the command line asked of the clients.
    """
    contract = client_contract_file(clients)
    banner(
        [
            f" Deploy {APP_NAME} -> Azure App Service",
            f"   resource group : {SETTINGS.resource_group}",
            f"   location       : {SETTINGS.location}",
            f"   environment    : {SETTINGS.environment}",
            f"   services       : {len(SERVICES)}",
        ]
    )

    step("Checking prerequisites")
    ok(f"az CLI present, signed in to '{_account_name()}'")
    if clients.scope == SCOPE_CLIENTS:
        # Read the contract off the deployed infrastructure again, so the clients are released
        # against the backend as it is deployed, also from a clean checkout (a scheduled site
        # refresh).
        resume_last_infrastructure_deployment()
        client_contract()
        run_clients_step(contract, clients.build_number)
        step("Done")
        ok(f"Clients of {APP_NAME} released in {elapsed()}.")
        return
    # Before preflight: what-if and every stage read the operator from the
    # parameter file, which reads it from the environment.
    resolve_operator_identity()

    validate_bicep_templates("infra/main.bicep")
    if not CONTAINER_MODE:
        # Validate every service's build and dependencies LOCALLY before
        # touching Azure, so a broken package fails in seconds.
        invoke_code_validation()

    ensure_resource_group()

    trim, current_infra_hash = _resolve_infra_trim()
    stamp_prefix = current_infra_hash[:8]
    if trim:
        preflight(
            SETTINGS.param_file,
            run_what_if=False,
            skip_reason=(
                f"what-if skipped: infrastructure inputs unchanged since the "
                f"last successful deploy (stamp {stamp_prefix}). Pass --force "
                f"to run it."
            ),
        )
    else:
        preflight(SETTINGS.param_file)

    # Each block's schema workload is a container group in the database's
    # virtual network, signed in as the block's schema identity, so the deploy
    # host reaches the private database through it alone. A change that needs
    # approval stops the deploy before anything applies unless --approved was
    # given; a failed expand or re-plan stops it before the release starts, and
    # an unhealthy release before any contract.
    converge_schema_blocks(
        PLAN_BLOCKS,
        approved,
        bring_up_data=functools.partial(deploy_data_stage, trim, stamp_prefix),
        start_release=functools.partial(deploy_release, current_infra_hash),
        verify_release=command_verify,
        concurrent_runs=run_group_concurrent_runs,
        schema_tool=run_project_schema_tool,
        channel=container_group_schema_channel(STEP_CONVERGE),
        failure=DeployError,
    )

    # The late-bound client ids are outputs of the infrastructure deployment above.
    client_contract()

    if clients.scope == SCOPE_BACKEND:
        step("Done")
        ok(
            f"Backend of {APP_NAME} deployed in {elapsed()}. Run "
            f"'{VERB_DEPLOY} {FLAG_SCOPE} {SCOPE_CLIENTS}' to release its clients."
        )
        return
    # Independent of CONTAINER_MODE: a Static Web App's bundle is built and uploaded
    # from the deploy host however the backend is delivered.
    run_clients_step(contract, clients.build_number)

    step("Done")
    ok(f"Deployment of {APP_NAME} complete in {elapsed()}.")
    emit("")
    emit("Other commands:")
    emit(f"  scripts/deploy.sh {VERB_DOWN}       stop compute, keep data")
    emit(f"  scripts/deploy.sh {VERB_DESTROY}    delete the resource group")
    emit("")
    emit("Cost guard available: run scripts/cost-guard.ps1 to cap monthly spend")
    emit("(stops apps + Postgres on breach; add -AllowDelete for RG deletion).")


def deploy_data_stage(trim: bool, stamp_prefix: str) -> None:
    """Bring up what the release runs against: the foundation's databases and their schema workload.

    Skipped, with a note, under the infrastructure trim: the stamp proves this exact
    foundation template already converged in this resource group, so its databases
    and schema workload exist.

    Args:
        trim: Whether the infrastructure inputs are unchanged since the last
            successful deploy (``_resolve_infra_trim``).
        stamp_prefix: The stamp's first characters, for the note.
    """
    if trim:
        note(
            f"foundation stage skipped: infrastructure inputs unchanged since "
            f"the last successful deploy (stamp {stamp_prefix}). Pass --force "
            f"to run it."
        )
        return
    deploy_foundation_stage()


def deploy_release(current_infra_hash: str) -> None:
    """Start the new release: the full infrastructure stage, then the application code.

    The web apps' code (their images in container mode) and the Function Apps. The
    infrastructure stamp is written last, once the release is in place: a failed
    release never stamps, and the health verification after it does not gate the
    stamp.

    Args:
        current_infra_hash: This run's ``infra_content_hash()``, stamped on success.
    """
    deploy_param = SETTINGS.param_file
    if CONTAINER_MODE:
        # Image supply runs AFTER the foundation stage because that stage
        # creates the registry it pushes to: the registry login cannot
        # authenticate against a registry that does not exist yet. Preflight
        # still runs first -- it registers the registry's resource provider and
        # clears soft-deleted name collisions, both prerequisites of the
        # foundation stage itself.
        deploy_param = resolve_container_image_tags(SETTINGS.param_file)

    # Before the stage that creates API Management -- never skipped by the
    # infrastructure trim: the certificate may have been removed since.
    provision_apim_tls_certificate_store()

    step(f"Stage 2/2: full infrastructure ({deploy_param})")
    note("Provisioning the remaining resources -- each is reported as it completes.")
    invoke_bicep_stage(deploy_param, INFRASTRUCTURE_STAGE)
    ok(f"Infrastructure deployed ({elapsed()} elapsed).")

    # Runs AFTER the deployment, unlike the diagnostic-setting reconcile in
    # preflight: an orphaned subscription does not block the deploy, and
    # deleting on the strength of a template that then failed to apply would be
    # acting on a state that never existed.
    reconcile_servicebus_subscriptions()

    # The in-VNet bootstrap (private App Configuration seeding, datasource
    # identity creation, residual secret seeding) runs as a
    # deploymentScript module INSIDE the deployment above, on a delegated
    # subnet, authenticated as its own managed identity. There is deliberately
    # no separate bootstrap stage: re-running the main parameter file would
    # only re-converge the whole template, not target the bootstrap.
    apply_staged_connection_capacity()

    # All secret provisioning and the operator-owned secret gate run INSIDE the
    # deployment via the secret-seeding deploymentScript, so this script needs
    # no Key Vault data-plane access of its own. Reaching this line means that
    # script exited zero: every required config key resolved and every
    # operator-owned secret carries a real value. A gap fails the deployment
    # above instead, and the seeder's own log names every unset handle with the
    # command that sets it.
    ok("Secret seeding satisfied -- all operator-owned secrets carry a real value.")

    if CONTAINER_MODE:
        # Web-app code is delivered by the container image the just-completed
        # infrastructure stage's resolved image reference pulls -- there is no
        # web-app code-push phase in container mode. Function Apps are NOT
        # containers, though: each Flex Consumption app performs a server-side
        # remote build from a pushed zip, so the Function App wave still runs.
        # Turbo scale is deliberately not applied here -- it scales the shared
        # App Service plan, which the Flex Consumption plan does not build on.
        if function_app_services():
            shutil.rmtree(SETTINGS.build_dir, ignore_errors=True)
            SETTINGS.build_dir.mkdir(parents=True, exist_ok=True)
            try:
                push_function_apps()
            finally:
                shutil.rmtree(SETTINGS.build_dir, ignore_errors=True)
    else:
        step(f"Deploying application code ({len(SERVICES)} services)")
        shutil.rmtree(SETTINGS.build_dir, ignore_errors=True)
        SETTINGS.build_dir.mkdir(parents=True, exist_ok=True)
        try:
            run_push_phase_with_turbo_scale()
        finally:
            shutil.rmtree(SETTINGS.build_dir, ignore_errors=True)

    write_infra_hash_stamp(current_infra_hash)


def command_canary() -> None:
    """Provision the full infrastructure MINUS API Management.

    Proves the whole project is deployable in a fraction of the time before
    committing to API Management, which is the long pole. Every resource is the
    real one; a subsequent deploy re-declares them idempotently and adds the
    gateway.

    In container mode the canary stage starts the release's images, so every
    block is expanded around it (``expand_schema_blocks``): the foundation stage
    brings up the databases, every block is planned without approval and its
    expand applied and re-planned, and only then does the canary stage run. No
    contract is applied -- the expanded schema still holds what the release
    before it reads -- and the next deploy applies it once its release is
    healthy.
    """
    banner(
        [
            f" Canary {APP_NAME} -> Azure App Service (full infra minus APIM)",
            f"   resource group : {SETTINGS.resource_group}",
            f"   location       : {SETTINGS.location}",
            f"   environment    : {SETTINGS.environment}",
            f"   services       : {len(SERVICES)}",
        ]
    )
    note(
        "Canary proves deployability WITHOUT API Management; run the deploy "
        "command afterward to add it."
    )

    step("Checking prerequisites")
    ok(f"az CLI present, signed in to '{_account_name()}'")
    # Before preflight: what-if and every stage read the operator from the
    # parameter file, which reads it from the environment.
    resolve_operator_identity()

    validate_bicep_templates("infra/canary.bicep")
    ensure_resource_group()
    preflight(SETTINGS.canary_param_file)
    # The canary has no --approved: a change that needs approval stops it before
    # anything applies, and only a deploy given --approved runs that change.
    expand_schema_blocks(
        PLAN_BLOCKS,
        False,
        bring_up_data=deploy_foundation_stage,
        start_release=canary_release,
        concurrent_runs=run_group_concurrent_runs,
        schema_tool=run_project_schema_tool,
        channel=container_group_schema_channel(STEP_CONVERGE),
        failure=DeployError,
    )

    banner(
        [
            " CANARY GREEN -- the full project is deployable (APIM excluded).",
            " Every block is expanded; the deploy command applies its contract.",
            " Run the deploy command to add API Management and finish.",
        ],
        color="ok",
    )


def canary_release() -> None:
    """Start the canary: every resource but API Management, with the release's image tags in container mode."""
    canary_param = SETTINGS.canary_param_file
    if CONTAINER_MODE:
        canary_param = resolve_container_image_tags(SETTINGS.canary_param_file)

    step("Stage 2/2: canary infrastructure (full infra minus APIM)")
    note(
        "Provisioning every resource except API Management -- each is reported "
        "as it completes."
    )
    invoke_bicep_stage(canary_param, "canary")
    ok(f"Canary infrastructure deployed ({elapsed()} elapsed).")


def command_code() -> None:
    """Deliver changed application code with zero Bicep stage.

    Refuses outright when the resource group has never been fully deployed,
    or when its infrastructure inputs changed since the last successful
    'deploy' -- the silent-drift failure mode this command exists to make
    impossible. There is deliberately no --force bypass for that refusal;
    --force here means something else entirely (see below).

    The code reads the schema it declares, and 'code' converges no database:
    every block is read and verified against its declared schema
    (``start_on_converged_schema``) before any code is delivered, and a block
    that differs -- a schema change since the last deploy, a contract a canary
    left to the deploy -- refuses the push, naming the block. 'deploy'
    converges it.

    Raises:
        DeployError: If the infra-hash guard refuses, a block does not hold
            its declared schema, or any site update / function-app push fails.
    """
    banner(
        [
            f" Code push {APP_NAME} -> Azure App Service",
            f"   resource group : {SETTINGS.resource_group}",
            f"   environment    : {SETTINGS.environment}",
            f"   services       : {len(SERVICES)}",
        ]
    )

    stored_hash = read_infra_hash_stamp()
    current_hash = infra_content_hash()
    if not code_deploy_allowed(stored_hash, current_hash):
        if stored_hash is None:
            raise DeployError(
                f"Resource group '{SETTINGS.resource_group}' has never been "
                f"fully deployed -- no infrastructure stamp is present.\n"
                f"  Expected: a 'cruftfree-infra-hash' tag written by a "
                f"successful 'deploy' run.\n"
                f"  Fix: run 'deploy' first. 'code' only ever updates an "
                f"environment 'deploy' has already converged."
            )
        raise DeployError(
            f"Infrastructure inputs for '{SETTINGS.resource_group}' changed "
            f"since the last successful deploy.\n"
            f"  Stamped hash : {stored_hash}\n"
            f"  Current hash : {current_hash}\n"
            f"  Fix: run 'deploy' to re-converge the infrastructure, then "
            f"'code' again. There is deliberately no --force bypass for this "
            f"check: a stale-infra code push is exactly the silent-drift "
            f"failure this command exists to prevent."
        )

    start_on_converged_schema(
        PLAN_BLOCKS,
        start_release=push_release_code,
        concurrent_runs=run_group_concurrent_runs,
        schema_tool=run_project_schema_tool,
        channel=container_group_schema_channel(VERB_SCHEMA_READ),
        failure=DeployError,
    )

    step("Done")
    ok(f"Code push to {APP_NAME} complete in {elapsed()}.")

    command_verify()


def push_release_code() -> None:
    """Deliver the changed application code: every site's image or zip, and every Function App."""
    if CONTAINER_MODE:
        update_site_images(supply_service_images())
        if function_app_services():
            shutil.rmtree(SETTINGS.build_dir, ignore_errors=True)
            SETTINGS.build_dir.mkdir(parents=True, exist_ok=True)
            try:
                push_function_apps()
            finally:
                shutil.rmtree(SETTINGS.build_dir, ignore_errors=True)
    else:
        step(f"Deploying application code ({len(SERVICES)} services)")
        shutil.rmtree(SETTINGS.build_dir, ignore_errors=True)
        SETTINGS.build_dir.mkdir(parents=True, exist_ok=True)
        try:
            run_push_phase_with_turbo_scale()
        finally:
            shutil.rmtree(SETTINGS.build_dir, ignore_errors=True)


def update_site_images(resolved_tags: dict[str, str]) -> None:
    """Point every site of every service at its image of *resolved_tags*, skipping a site already on it.

    Raises:
        DeployError: If a site cannot be updated to its tag.
    """

    def _update_one_site(index: int, service: Service) -> None:
        item(index, len(SERVICES), service.web_app_name)
        # Every site of the service runs an image of the service's one tag.
        tag = resolved_tags[service.image_tag_param_key]
        for site, image_name in container_sites(service):
            current = az_text(
                "webapp",
                "config",
                "show",
                "--name",
                site,
                "--resource-group",
                SETTINGS.resource_group,
                "--query",
                "linuxFxVersion",
                "-o",
                "tsv",
                "--only-show-errors",
            )
            if not SETTINGS.force and current.endswith(f":{tag}"):
                ok(f"{site} unchanged (tag {tag[:12]}) -- skipping")
                continue
            result = az(
                "webapp",
                "config",
                "container",
                "set",
                "--resource-group",
                SETTINGS.resource_group,
                "--name",
                site,
                "--container-image-name",
                f"{SETTINGS.acr_login_server}/{image_name}:{tag}",
                "-o",
                "none",
                "--only-show-errors",
            )
            if not result.succeeded:
                raise DeployError(
                    f"Failed to update '{site}' to image tag '{tag}'. az "
                    f"reported: {result.output}"
                )
            ok(f"{site} updated to tag {tag[:12]}")

    step(f"Updating web app container images ({len(SERVICES)} services)")
    run_deploy_wave(SETTINGS.web_wave_size, _update_one_site, SERVICES)


def command_verify() -> None:
    """Prove every deployed app is actually live.

    Waits on two independent signals per app: a web app is live when its
    readiness route answers HTTP 200; a Function App is live when Azure
    reports the same number of indexed functions the local generated package
    carries. Both wait up to ``SETTINGS.verify_timeout_seconds``, polling
    every ``VERIFY_POLL_INTERVAL_SECONDS`` -- a container cold pull after an
    image swap, and Function App trigger indexing after a push, both take
    minutes and carry no documented upper bound.

    Runs automatically at the tail of ``command_deploy`` -- as the converge
    step's health verification, before any block's contract applies, when the
    application has a database -- and of ``command_code``, so a routine deploy
    or code push cannot silently leave a broken app behind; it deliberately does
    NOT run after ``command_canary``, ``command_down`` or ``command_destroy``,
    though it works standalone against any converged environment.

    Deliberately excluded: Service Bus dead-letter depth and triggering
    ingestion runs. Those are runtime smoke tests needing data-plane access
    and domain knowledge; they belong to project-level tooling, not this
    generated lifecycle script.

    Raises:
        DeployError: If any app is not healthy within the budget, naming
            every failing app with its last observed status or counts.
    """
    step("Verifying deployment health")
    failures: list[str] = []
    failures_lock = threading.Lock()
    web_sites = web_site_services()

    def _verify_web(index: int, service: Service) -> None:
        # Restricted ingress: no HTTP route to this app exists from where the
        # deploy runs, so the platform's own health verdict is read on the ARM
        # plane instead. See verify_site_via_arm.
        healthy, detail = verify_site_via_arm(
            f"{service.web_app_name}-{SETTINGS.environment}"
        )
        item(index, len(web_sites), service.web_app_name)
        if healthy:
            ok(f"{service.web_app_name}: {detail}")
            return
        note(f"{service.web_app_name}: FAILED -- {detail}")
        with failures_lock:
            failures.append(f"{service.web_app_name}: {detail}")

    run_deploy_wave(SETTINGS.function_wave_size, _verify_web, web_sites)

    worker_services = tuple(service for service in SERVICES if service.workers)
    if worker_services:

        def _verify_workers(index: int, service: Service) -> None:
            item(index, len(worker_services), service.display_name)
            for site in worker_sites(service):
                # A worker answers only its liveness route and has no public
                # access, so App Service's own verdict on that route is read.
                healthy, detail = verify_site_via_arm(site)
                if healthy:
                    ok(f"{site}: {detail}")
                    continue
                note(f"{site}: FAILED -- {detail}")
                with failures_lock:
                    failures.append(f"{site}: {detail}")

        run_deploy_wave(SETTINGS.function_wave_size, _verify_workers, worker_services)

    functions = function_app_services()
    if functions:

        def _verify_function(index: int, service: Service) -> None:
            healthy, detail = verify_one_function_app(service)
            item(index, len(functions), service.function_app_name)
            if healthy:
                ok(f"{service.function_app_name}: {detail}")
                return
            note(f"{service.function_app_name}: FAILED -- {detail}")
            with failures_lock:
                failures.append(f"{service.function_app_name}: {detail}")

        run_deploy_wave(SETTINGS.function_wave_size, _verify_function, functions)

    if failures:
        raise DeployError(
            f"Post-deploy verification FAILED for {len(failures)} app(s):\n  "
            + "\n  ".join(failures)
        )
    step("Done")
    ok(f"Verification of {APP_NAME} complete in {elapsed()}.")


def command_down(scope: str | None) -> None:
    """Stop compute while keeping every byte of data, on the side *scope* names.

    The backend side is every App Service / Function App site and database server
    (``stop_backend_compute``); the clients side is every Static Web App
    (``stop_static_web_apps``). Both stop when no scope is given, the backend first.

    Args:
        scope: The value of the scope flag, or ``None`` when absent.

    Raises:
        DeployError: Azure could not answer, or a site did not stop.
    """
    if az_text("group", "exists", "--name", SETTINGS.resource_group) != "true":
        note(
            f"Resource group '{SETTINGS.resource_group}' does not exist -- "
            f"nothing to stop."
        )
        return

    banner(
        [
            f" Stopping {APP_NAME} -- stop compute, keep data",
            f"   resource group : {SETTINGS.resource_group}",
        ]
    )
    if scope != SCOPE_CLIENTS:
        stop_backend_compute()
    if scope != SCOPE_BACKEND:
        stop_static_web_apps()

    step("Done")
    ok(f"Down of {APP_NAME} complete in {elapsed()}.")


def stop_backend_compute() -> None:
    """Stop every App Service / Function App site and PostgreSQL Flexible Server, keeping their data."""
    step("Stopping App Service / Function App sites")
    sites = az_rows(
        "webapp",
        "list",
        "--resource-group",
        SETTINGS.resource_group,
        "--query",
        "[].{name:name,kind:kind}",
        "-o",
        "tsv",
    )
    stopped_sites = 0
    if not sites:
        note("No App Service sites found.")
    else:
        for row in sites:
            name = row[0]
            kind = row[1] if len(row) > 1 else ""
            item1(name)
            group = "functionapp" if "functionapp" in kind else "webapp"
            az(
                group,
                "stop",
                "--resource-group",
                SETTINGS.resource_group,
                "--name",
                name,
                "-o",
                "none",
            )
            stopped_sites += 1
        ok(f"Stopped {stopped_sites} site(s).")

    step("Stopping PostgreSQL Flexible Servers")
    servers = az_lines(
        "postgres",
        "flexible-server",
        "list",
        "--resource-group",
        SETTINGS.resource_group,
        "--query",
        "[].name",
        "-o",
        "tsv",
    )
    stopped_servers = 0
    if not servers:
        note("No PostgreSQL Flexible Servers found.")
    else:
        for server in servers:
            item1(server)
            az(
                "postgres",
                "flexible-server",
                "stop",
                "--resource-group",
                SETTINGS.resource_group,
                "--name",
                server,
                "-o",
                "none",
            )
            stopped_servers += 1
        ok(f"Stopped {stopped_servers} server(s).")
        note("Azure auto-restarts a stopped Flexible Server after 7 days.")

    ok(f"Shut down {stopped_sites} site(s) and {stopped_servers} database server(s).")
    note(
        "Storage, databases and Key Vault are retained. Run the deploy command "
        "to bring it back up."
    )
    note(
        "Note: the App Service Plan still bills while stopped; the destroy "
        "command removes it entirely."
    )


def remove_resource_type_in_parallel(resource_type: str, label: str) -> None:
    """Delete every resource of one type concurrently, then wait for the drain.

    Under a plain resource-group delete the Web resource provider tears sites
    and plans down largely serially -- and each site also unbinds its network
    integration and detaches private endpoints -- which dominates teardown time
    for a many-service application. Deleting them here without waiting runs them
    in parallel; the trailing group delete reclaims everything else, so the
    drain wait is bounded rather than blocking forever on a stuck resource.
    """
    resource_ids = az_lines(
        "resource",
        "list",
        "--resource-group",
        SETTINGS.resource_group,
        "--resource-type",
        resource_type,
        "--query",
        "[].id",
        "-o",
        "tsv",
    )
    if not resource_ids:
        return

    step(f"Deleting {len(resource_ids)} {label} in parallel")
    for resource_id in resource_ids:
        az("resource", "delete", "--ids", resource_id, "--no-wait", "-o", "none")

    deadline = time.monotonic() + DESTROY_DRAIN_DEADLINE_SECONDS
    remaining = len(resource_ids)
    while remaining > 0 and time.monotonic() < deadline:
        time.sleep(DESTROY_DRAIN_POLL_SECONDS)
        remaining = len(
            az_lines(
                "resource",
                "list",
                "--resource-group",
                SETTINGS.resource_group,
                "--resource-type",
                resource_type,
                "--query",
                "[].id",
                "-o",
                "tsv",
            )
        )
        sub(f"{label} remaining: {remaining}")
    if remaining > 0:
        note(
            f"{label} not fully drained after the timeout; the resource-group "
            f"delete will reclaim the rest."
        )
    else:
        ok(f"All {label} deleted.")


def purge_soft_deleted_remnants() -> None:
    """Purge the subscription-scoped remnants a resource-group delete leaves.

    Key Vault, App Configuration and API Management soft-delete to a
    SUBSCRIPTION scope, so the group delete never removes them -- they linger
    and block the next deploy's preflight. Purging here is what keeps
    teardown/redeploy cycles clean. Best-effort: a purge-protected vault
    (typically production) rejects the purge and keeps its soft-delete as a
    recovery net, which is expected and non-fatal.
    """
    step("Purging soft-deleted Key Vault / App Config / APIM (clean redeploy)")
    for blocker in find_soft_deleted_blockers():
        blocker.purge()
        if blocker.still_present():
            note(
                f"{blocker.kind} purge for '{blocker.name}' did not succeed "
                f"(purge protection keeps it recoverable): {blocker.purge_hint}"
            )
    ok("Soft-deleted resources purged where purge protection allows.")


def delete_log_analytics_workspaces() -> None:
    """Permanently delete Log Analytics workspaces before the group delete.

    A plain group delete only SOFT-deletes a workspace, and the next same-name
    deploy RECOVERS that exact instance rather than creating a fresh one --
    dragging every stale diagnostic-setting sink reservation back with it, so a
    reused sink then collides on redeploy. Force-deleting bypasses soft-delete,
    but only works while the workspace is still active and its group exists:
    after the group delete the workspace lingers with no group to recover it
    into. Enumerated so every workspace in the group is covered; best-effort per
    workspace.
    """
    workspaces = az_lines(
        "resource",
        "list",
        "--resource-group",
        SETTINGS.resource_group,
        "--resource-type",
        "Microsoft.OperationalInsights/workspaces",
        "--query",
        "[].name",
        "-o",
        "tsv",
    )
    if not workspaces:
        return
    step(
        "Permanently deleting Log Analytics workspace(s) (prevents soft-delete "
        "recovery on redeploy)"
    )
    for workspace in workspaces:
        result = az(
            "monitor",
            "log-analytics",
            "workspace",
            "delete",
            "--resource-group",
            SETTINGS.resource_group,
            "--workspace-name",
            workspace,
            "--force",
            "true",
            "--yes",
            "-o",
            "none",
            "--only-show-errors",
        )
        if not result.succeeded:
            note(
                f"Log Analytics workspace force-delete for '{workspace}' did not "
                f"succeed (it will soft-delete with the group; purge it before "
                f"the next deploy if a diagnostic-sink collision appears): "
                f"{result.output}"
            )
    ok("Log Analytics workspace(s) permanently deleted.")


def command_destroy() -> None:
    """Delete the entire resource group and everything in it."""
    OUTPUT.step_color = "danger"
    if az_text("group", "exists", "--name", SETTINGS.resource_group) != "true":
        note(
            f"Resource group '{SETTINGS.resource_group}' does not exist -- "
            f"nothing to destroy."
        )
        return

    resource_count = len(
        az_lines(
            "resource",
            "list",
            "--resource-group",
            SETTINGS.resource_group,
            "--query",
            "[].id",
            "-o",
            "tsv",
        )
    )
    banner(
        [
            f" DESTROY {APP_NAME} -- Azure installation",
            f"   subscription   : {_account_name()}",
            f"   resource group : {SETTINGS.resource_group}",
            f"   resources      : {resource_count} (ALL will be deleted)",
        ],
        color="danger",
    )
    lost = (
        f"Resource group '{SETTINGS.resource_group}' and all {resource_count} "
        f"resource(s) in it are deleted. Databases and storage will be "
        f"permanently lost."
    )
    if not confirm_destructive(
        VERB_DESTROY, lost, SETTINGS.resource_group, SETTINGS.force
    ):
        raise DeployError(f"'{VERB_DESTROY}' was not confirmed. Aborting.")

    # Drain the slow compute first, in parallel. Sites must go before plans -- a
    # plan cannot be deleted while sites are still attached to it.
    remove_resource_type_in_parallel(
        "Microsoft.Web/sites", "App Service / Function App site(s)"
    )
    remove_resource_type_in_parallel("Microsoft.Web/serverfarms", "App Service Plan(s)")
    delete_log_analytics_workspaces()

    step(f"Deleting resource group '{SETTINGS.resource_group}'")
    note("Azure is removing all remaining resources -- this can take several minutes.")
    result = az(
        "group", "delete", "--name", SETTINGS.resource_group, "--yes", "-o", "none"
    )
    if not result.succeeded:
        raise DeployError(
            f"Deleting resource group '{SETTINGS.resource_group}' FAILED -- the "
            f"resources still exist and are still billing. Common causes: a "
            f"resource lock, an API Management instance still draining, or "
            f"insufficient permissions. Clear the blocker and run destroy again. "
            f"az reported: {result.output}"
        )
    ok(f"Resource group '{SETTINGS.resource_group}' deleted.")

    purge_soft_deleted_remnants()

    step("Done")
    ok(f"Destroyed {APP_NAME} in {elapsed()}.")


# ---------------------------------------------------------------------------
# Schema verbs
# ---------------------------------------------------------------------------
# Inlined from cruftfree_codegen_kernel/deployment/schema_read_runtime.py, then
# cruftfree_codegen_azure/schema_run_runtime.py: the half of 'schema-read' every
# CruftFree front door shares -- the read's input from the schema tool, the run's
# private files and the tool's check of what the client returned -- and the
# container-group run App Service and azure-vm share as their channel.
#: Seconds the catalog client may run before ``timeout`` stops it. A read is a handful of catalog
#: queries in one transaction; a client still running after this is stuck, not slow.
SCHEMA_CLIENT_TIMEOUT_SECONDS: int = 600

#: Seconds ``timeout`` waits after its stop signal before it kills a client that did not exit.
SCHEMA_CLIENT_KILL_AFTER_SECONDS: int = 10

#: Seconds a workload's other steps may take beside the client: starting it (its images pulled),
#: copying the input in and the client's files out.
SCHEMA_RUN_STEPS_SECONDS: int = 300

#: The longest a deploy waits for one run's workload. Past it the deploy stops the workload itself;
#: the client inside it has already been stopped by ``timeout``.
SCHEMA_RUN_WAIT_SECONDS: int = (
    SCHEMA_CLIENT_TIMEOUT_SECONDS
    + SCHEMA_CLIENT_KILL_AFTER_SECONDS
    + SCHEMA_RUN_STEPS_SECONDS
)

#: The client's input, as the deploy writes it into a run.
SCHEMA_RUN_INPUT_FILE: str = "in"
#: The client's standard output, as the channel brings it back.
SCHEMA_RUN_OUTPUT_FILE: str = "out"
#: The client's standard error, as the channel brings it back.
SCHEMA_RUN_ERROR_FILE: str = "err"
#: The client's exit status, one decimal number and a line break, as the channel brings it back.
SCHEMA_RUN_EXIT_FILE: str = "exit"
#: The files a channel brings back from a run, in the order the workload writes them.
SCHEMA_RUN_RESULT_FILES: tuple[str, ...] = (
    SCHEMA_RUN_OUTPUT_FILE,
    SCHEMA_RUN_ERROR_FILE,
    SCHEMA_RUN_EXIT_FILE,
)

#: The characters a run-store name part holds, as a bracket-expression body that a regular
#: expression and a shell pattern both read the same way.
RUN_STORE_NAME_CHARACTERS: str = "A-Za-z0-9._-"
#: The one character of :data:`RUN_STORE_NAME_CHARACTERS` a name part may not start with.
RUN_STORE_NAME_REFUSED_START: str = "."

#: A name an object key, a blob name and a container group name carry verbatim, as one part of a
#: run-store key or as a run id: letters, digits, ``.``, ``_`` and ``-``, never starting with ``.``
#: (so no part reads as ``.`` or ``..``).
RUN_STORE_NAME_PART: re.Pattern[str] = re.compile(
    f"[{RUN_STORE_NAME_CHARACTERS.replace(RUN_STORE_NAME_REFUSED_START, '')}]"
    f"[{RUN_STORE_NAME_CHARACTERS}]*"
)

#: The schema tool's command printing a read's input, and its option printing the client arguments.
SCHEMA_READ_BATCH_COMMAND: str = "read-batch"
SCHEMA_READ_PLACES_OPTION: str = "--places"
#: The schema tool's command checking a run's files and printing the verified document.
SCHEMA_READ_VERIFY_COMMAND: str = "read-verify"
#: ``read-verify``'s and ``apply-verify``'s option naming each file a run brings back.
SCHEMA_RUN_FILE_OPTIONS: tuple[tuple[str, str], ...] = (
    ("--stdout", SCHEMA_RUN_OUTPUT_FILE),
    ("--stderr", SCHEMA_RUN_ERROR_FILE),
    ("--exit", SCHEMA_RUN_EXIT_FILE),
)

#: The schema tool's command printing the client's input applying one of a block's plan files,
#: and its option naming that file.
SCHEMA_APPLY_BATCH_COMMAND: str = "apply-batch"
SCHEMA_APPLY_SQL_OPTION: str = "--sql"
#: The schema tool's command checking an apply's run files (:data:`SCHEMA_RUN_FILE_OPTIONS`, and
#: the file under :data:`SCHEMA_APPLY_SQL_OPTION`) and printing the verified document of the
#: catalog the apply left, as :data:`SCHEMA_READ_VERIFY_COMMAND` prints a read's.
SCHEMA_APPLY_VERIFY_COMMAND: str = "apply-verify"

#: The command a provider's front door gives the container runtime's script on the machine hosting
#: the containers, to run one block's client there (:func:`host_client_operands`).
SCHEMA_HOST_CLIENT_COMMAND: str = "schema-client"
#: The command a provider's front door gives the container runtime's script on the machine hosting
#: the containers, to start the containers of the databases it hosts and return once they are
#: healthy, before any schema is converged or the release starts.
SCHEMA_HOST_DATABASES_COMMAND: str = "databases-up"

#: The schema tool's command printing a block's plan from the document a verified read printed,
#: and its options naming that document's file and the two files it writes the plan's SQL to:
#: the expand phase, applied before the new release starts, and the contract phase, applied once
#: it is healthy (each beside its statement map).
SCHEMA_PLAN_COMMAND: str = "plan"
SCHEMA_PLAN_CATALOG_OPTION: str = "--catalog"
SCHEMA_PLAN_EXPAND_OPTION: str = "--expand"
SCHEMA_PLAN_CONTRACT_OPTION: str = "--contract"
#: ``plan``'s switch planning the changes that need approval instead of refusing them. A deploy
#: passes it exactly when its own command line carries ``deploy --approved``.
SCHEMA_PLAN_APPROVED_OPTION: str = "--approved"
#: ``plan``'s exit status when its plan refuses a change: one needing approval, or one never
#: applied. Any other non-zero status is a failure to plan.
SCHEMA_PLAN_REFUSED_EXIT: int = 1
#: How every plan ``plan`` prints begins, naming its block: an exit status that comes with no
#: plan is a failure, never a refusal.
SCHEMA_PLAN_HEADER: str = "Plan of block '{block}'"
#: The schema tool's command checking a block's re-plan, made once its expand SQL is applied,
#: against the contract file of its first plan; and its option naming that contract file. The
#: re-plan's files go under :data:`SCHEMA_PLAN_EXPAND_OPTION` and :data:`SCHEMA_PLAN_CONTRACT_OPTION`.
SCHEMA_PLAN_COMPARE_COMMAND: str = "plan-compare"
SCHEMA_PLAN_COMPARE_PLANNED_OPTION: str = "--planned-contract"
#: The schema tool's command saying whether a block's catalog holds its declared schema, from the
#: document a verified read printed, given under :data:`SCHEMA_PLAN_CATALOG_OPTION`.
SCHEMA_VERIFY_COMMAND: str = "verify"

#: The program every client runs under, and its option naming the kill grace.
_TIMEOUT_PROGRAM: str = "timeout"
_TIMEOUT_KILL_OPTION: str = "-k"

_LINE_BREAK: str = "\n"
_TEXT_ENCODING: str = "utf-8"
_RUN_DIRECTORY_PREFIX: str = "schema-read-"
_APPLY_DIRECTORY_PREFIX: str = "schema-apply-"
_PLAN_DIRECTORY_PREFIX: str = "schema-plan-"
_PLAN_CATALOG_FILE: str = "catalog.json"
_PLAN_EXPAND_FILE: str = "expand.sql"
_PLAN_CONTRACT_FILE: str = "contract.sql"
_CONVERGE_DIRECTORY_PREFIX: str = "schema-converge-"
#: The subdirectories of a block's converge directory: its first plan; the catalog its expand
#: left and the re-plan made from it; and the catalog its contract left, which its verify checks.
_CONVERGE_PLAN_STEP: str = "plan"
_CONVERGE_REPLAN_STEP: str = "replan"
_CONVERGE_VERIFY_STEP: str = "verify"
_RUN_ID_TIME_FORMAT: str = "%Y%m%dT%H%M%SZ"
_RUN_ID_RANDOM_BYTES: int = 8


class SchemaToolRun(NamedTuple):
    """What one command of the schema tool left: its exit status and its two output streams."""

    exit_status: int
    stdout: bytes
    stderr: bytes


class SchemaRun(NamedTuple):
    """One run of a block's read, as the channel sees it.

    Attributes:
        block: The block key the read is of.
        run_id: The run's id (:func:`require_run_id`): names the run's run-store prefix, its
            workload and its tag.
        directory: The run's private directory, holding ``in`` and receiving ``out``, ``err``
            and ``exit``.
        client_arguments: The arguments the client takes after its own (the places binding),
            from ``read-batch --places``.
    """

    block: str
    run_id: str
    directory: Path
    client_arguments: tuple[str, ...]

    @property
    def input_file(self) -> Path:
        """The client's input, to be delivered on the client's standard input."""
        return self.directory / SCHEMA_RUN_INPUT_FILE

    @property
    def output_file(self) -> Path:
        """Where the channel leaves the client's standard output."""
        return self.directory / SCHEMA_RUN_OUTPUT_FILE

    @property
    def error_file(self) -> Path:
        """Where the channel leaves the client's standard error."""
        return self.directory / SCHEMA_RUN_ERROR_FILE

    @property
    def exit_file(self) -> Path:
        """Where the channel leaves the client's exit status."""
        return self.directory / SCHEMA_RUN_EXIT_FILE

    def record_exit_status(self, status: int) -> None:
        """Write *status*, the client's exit status, as the run's ``exit`` file.

        For a channel that runs the client from the deploy's own process; a workload writes
        the file itself.
        """
        _write_new_file(self.exit_file, f"{status}{_LINE_BREAK}".encode("ascii"))


#: Runs one schema-tool command with the given arguments and returns what it left.
SchemaTool = Callable[[Sequence[str]], SchemaToolRun]

#: A platform's channel: runs the client of :class:`SchemaRun` on the database's network and
#: leaves its ``out``, ``err`` and ``exit`` in the run's directory, raising the host's error when
#: the run could not be carried out.
SchemaChannel = Callable[[SchemaRun], None]

#: How many runs a platform's channel carries side by side: asked once, before the first run of a
#: plan or a converge with a block, and at least one. A channel that carries several runs at once
#: is called from that many threads.
ConcurrentRuns = Callable[[], int]

_Result = TypeVar("_Result")


def schema_client_command(
    client_argv: Sequence[str], arguments: Sequence[str] = ()
) -> tuple[str, ...]:
    """The command line a run's client runs as: *client_argv* and *arguments* under ``timeout``.

    ``timeout`` stops the client after :data:`SCHEMA_CLIENT_TIMEOUT_SECONDS` and kills it
    :data:`SCHEMA_CLIENT_KILL_AFTER_SECONDS` later, so every run ends by itself. Both GNU
    coreutils and BusyBox ``timeout`` take this spelling.

    Args:
        client_argv: The engine's client program and options (``CatalogClient.argv``).
        arguments: The arguments a run appends (:attr:`SchemaRun.client_arguments`); empty
            where the workload declares the command and a run appends them itself.

    Raises:
        ValueError: *client_argv* is empty.
    """
    if not client_argv:
        raise ValueError(
            "A schema read was given no client program. Pass the engine's catalog client "
            "argv (CatalogClient.argv), the program first."
        )
    return (
        _TIMEOUT_PROGRAM,
        _TIMEOUT_KILL_OPTION,
        str(SCHEMA_CLIENT_KILL_AFTER_SECONDS),
        str(SCHEMA_CLIENT_TIMEOUT_SECONDS),
        *client_argv,
        *arguments,
    )


def require_run_id(run_id: str) -> str:
    """Return *run_id* when it is a run id: a :data:`RUN_STORE_NAME_PART`.

    Raises:
        ValueError: *run_id* is empty, starts with ``.`` or holds a character outside
            ``[A-Za-z0-9._-]``.
    """
    if RUN_STORE_NAME_PART.fullmatch(run_id) is None:
        raise ValueError(
            f"{run_id!r} is not a run id. A run id names the run's run-store keys and its "
            "workload, so it holds only letters, digits, '.', '_' and '-', and does not start "
            "with '.'."
        )
    return run_id


def new_run_id() -> str:
    """A new run id: the UTC time and 16 random hex digits, ``20261027T081143Z-<hex>``."""
    stamp = time.strftime(_RUN_ID_TIME_FORMAT, time.gmtime())
    return require_run_id(f"{stamp}-{secrets.token_hex(_RUN_ID_RANDOM_BYTES)}")


def host_client_operands(
    block: str, run_id: str, client_arguments: Sequence[str]
) -> tuple[str, ...]:
    """The operands of :data:`SCHEMA_HOST_CLIENT_COMMAND` for one run of *block*'s client.

    The command is started inside the run's directory on the host, which holds ``in``, so no
    operand names a path: ``<block> <run id> [client argument ...]``.

    Raises:
        ValueError: *run_id* is not a run id.
    """
    return (block, require_run_id(run_id), *client_arguments)


def host_client_run(
    arguments: Sequence[str],
    directory: Path,
    blocks: Sequence[str],
    failure: Callable[[str], Exception],
) -> SchemaRun:
    """The run :data:`SCHEMA_HOST_CLIENT_COMMAND` was given: *arguments* as
    :func:`host_client_operands` built them, started in the run's *directory*.

    Args:
        arguments: The command's operands.
        directory: The directory the command was started in: the run's.
        blocks: The blocks whose client the host runs.
        failure: The host's error type, built from a message naming the cause.

    Raises:
        Exception: *failure*'s, when an operand is missing, the block has no client here, the run
            id breaks the run-store name rule, or *directory* holds no ``in``.
    """
    if len(arguments) < 2:
        raise failure(
            f"'{SCHEMA_HOST_CLIENT_COMMAND}' takes a block and a run id, then the client's "
            f"arguments; got {list(arguments)}."
        )
    block, run_id, *client_arguments = arguments
    if block not in blocks:
        raise failure(
            f"'{SCHEMA_HOST_CLIENT_COMMAND}' has no client for block '{block}'; the blocks this "
            f"host reaches are {sorted(blocks)}."
        )
    if RUN_STORE_NAME_PART.fullmatch(run_id) is None:
        raise failure(
            f"'{SCHEMA_HOST_CLIENT_COMMAND}' was given {run_id!r}, which is not a run id: letters, "
            "digits, '.', '_' and '-', not starting with '.'."
        )
    run = SchemaRun(block, run_id, directory.resolve(), tuple(client_arguments))
    if not run.input_file.is_file():
        raise failure(
            f"'{SCHEMA_HOST_CLIENT_COMMAND}' runs inside the run's directory, which holds the "
            f"client's input '{SCHEMA_RUN_INPUT_FILE}'; {run.directory} holds none."
        )
    return run


def run_schema_tool(script: Path, arguments: Sequence[str]) -> SchemaToolRun:
    """Run the schema tool *script* with *arguments* under this interpreter, its output as bytes.

    The tool needs only the standard library, so the deploy's own interpreter runs it. Its
    output is kept as the bytes it wrote, never decoded or translated here.
    """
    completed = subprocess.run(
        [sys.executable, str(script), *arguments],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        check=False,
    )
    return SchemaToolRun(completed.returncode, completed.stdout, completed.stderr)


def _write_new_file(path: Path, content: bytes) -> None:
    """Create *path* (it must not exist) holding exactly *content*."""
    with path.open("xb") as handle:
        handle.write(content)


def _say(message: str) -> None:
    """Write *message* and a line break on standard error as one write, so lines of runs carried
    out side by side never run into each other."""
    sys.stderr.write(f"{message}{_LINE_BREAK}")


def serial_schema_runs() -> int:
    """The :data:`ConcurrentRuns` of a channel that carries one run at a time: one."""
    return 1


def _concurrency(
    concurrent_runs: ConcurrentRuns, failure: Callable[[str], Exception]
) -> int:
    """How many runs the channel carries at once, as *concurrent_runs* says; the host's error unless at least one."""
    count = concurrent_runs()
    if count < 1:
        raise failure(
            f"The schema channel says it carries {count!r} run(s) at once, where a number of at "
            "least one is expected. This is a generator defect -- regenerate the project."
        )
    return count


class _NotStarted(Exception):
    """A block's step that never started, because the step of a block before it failed."""


def _each_block(
    blocks: Sequence[str], step: Callable[[str], _Result], concurrent: int
) -> Iterator[tuple[str, _Result]]:
    """*step* of each block of *blocks*, at most *concurrent* at once: each block and its result, in block order.

    The steps start in the blocks' order. Once a block's step raises, no step of a block after
    it starts; the steps already running finish, and the error is raised when the iteration
    reaches that block, every block before it having been yielded. A step that never started
    is never reached, since a block before it failed. Leaving the iteration early starts no
    further step and waits for the running ones. With *concurrent* one, every step runs on the
    calling thread, each once the block before it was yielded, so a channel carrying one run at
    a time is never called from another thread.
    """
    if concurrent == 1:
        for block in blocks:
            yield block, step(block)
        return
    failed: list[int] = []
    lock = threading.Lock()

    def guarded(index: int, block: str) -> _Result:
        with lock:
            if any(earlier < index for earlier in failed):
                raise _NotStarted(block)
        try:
            return step(block)
        except BaseException:
            with lock:
                failed.append(index)
            raise

    pool = ThreadPoolExecutor(max_workers=concurrent)
    try:
        futures = [
            pool.submit(guarded, index, block) for index, block in enumerate(blocks)
        ]
        for block, future in zip(blocks, futures, strict=True):
            yield block, future.result()
    finally:
        with lock:
            failed.append(-1)
        pool.shutdown(wait=True, cancel_futures=True)


def _exit_cause(result: SchemaToolRun) -> str:
    """What a schema-tool command that did not succeed printed on its standard error."""
    return (
        result.stderr.decode(_TEXT_ENCODING, errors="replace").strip()
        or "it printed no error"
    )


def _tool_output(
    schema_tool: SchemaTool,
    arguments: Sequence[str],
    failed: str,
    failure: Callable[[str], Exception],
) -> bytes:
    """The standard output of the schema-tool command *arguments*; the host's error opening with *failed* otherwise.

    *failed* is the sentence naming the block and what did not happen to it.
    """
    result = schema_tool(arguments)
    if result.exit_status != 0:
        raise failure(
            f"{failed}: 'schema.py {' '.join(arguments)}' exited {result.exit_status}: "
            f"{_exit_cause(result)}"
        )
    return result.stdout


def _decoded_lines(
    output: bytes, what: str, failed: str, failure: Callable[[str], Exception]
) -> list[str]:
    """*output*, UTF-8 text ended by a line break, as its lines; the host's error opening with *failed* otherwise."""
    try:
        text = output.decode(_TEXT_ENCODING)
    except UnicodeDecodeError as error:
        raise failure(
            f"{failed}: the schema tool's {what} is not UTF-8 ({error})."
        ) from error
    if not text.endswith(_LINE_BREAK):
        raise failure(
            f"{failed}: the schema tool's {what} does not end with a line break, so it may have "
            "been cut."
        )
    return text[: -len(_LINE_BREAK)].split(_LINE_BREAK)


def _client_arguments(
    schema_tool: SchemaTool,
    block: str,
    failed: str,
    failure: Callable[[str], Exception],
) -> tuple[str, ...]:
    """The client arguments ``read-batch <block> --places`` printed, one per line."""
    places = (SCHEMA_READ_BATCH_COMMAND, block, SCHEMA_READ_PLACES_OPTION)
    output = _tool_output(schema_tool, places, failed, failure)
    arguments = _decoded_lines(output, "client arguments", failed, failure)
    if not all(arguments):
        raise failure(
            f"{failed}: 'schema.py {' '.join(places)}' printed an empty line where each line is "
            "one client argument."
        )
    return tuple(arguments)


def _run_file_options(run: SchemaRun) -> list[str]:
    """The options naming the files *run* brought back, as ``read-verify`` and ``apply-verify`` take them."""
    return [
        part
        for option, name in SCHEMA_RUN_FILE_OPTIONS
        for part in (option, str(run.directory / name))
    ]


def _private_directory(
    prefix: str, failed: str, failure: Callable[[str], Exception]
) -> Path:
    """A new temporary directory private to one step, named from *prefix*; the host's error opening with *failed* otherwise."""
    try:
        return Path(tempfile.mkdtemp(prefix=prefix))
    except OSError as error:
        raise failure(
            f"{failed}: its private directory could not be created ({error})."
        ) from error


def _write_stdout(content: bytes) -> None:
    """Write *content* to standard output as these bytes, whatever the console's encoding or line ending."""
    sys.stdout.flush()
    sys.stdout.buffer.write(content)
    sys.stdout.buffer.flush()


def _remove_private_directory(
    directory: Path, block: str, holding: str, failure: Callable[[str], Exception]
) -> None:
    """Remove *directory*, private to one step on *block*, or raise the host's error naming it."""
    try:
        shutil.rmtree(directory)
    except OSError as error:
        raise failure(
            f"The files of block '{block}' could not be removed from {directory}: {error}. "
            f"They hold {holding}: remove the directory."
        ) from error


def read_live_catalog(
    block: str,
    *,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> str:
    """Read *block*'s live catalog through *channel* and return the verified document.

    Args:
        block: The block key (``schema_tool_block_key``).
        schema_tool: Runs a schema-tool command (:func:`run_schema_tool` bound to the project's
            ``schema.py``).
        channel: The platform's channel to the block's client.
        failure: The host's error type, built from a message naming the cause.

    Raises:
        Exception: *failure*'s, when the tool refuses the block, the channel's files are not a
            verified read, or the run's directory cannot be removed; and whatever *channel*
            raises.
    """
    failed = f"The live catalog of block '{block}' was not read"
    input_text = _tool_output(
        schema_tool, (SCHEMA_READ_BATCH_COMMAND, block), failed, failure
    )
    client_arguments = _client_arguments(schema_tool, block, failed, failure)
    run_id = new_run_id()
    directory = _private_directory(f"{_RUN_DIRECTORY_PREFIX}{run_id}-", failed, failure)
    try:
        run = SchemaRun(block, run_id, directory, client_arguments)
        _write_new_file(run.input_file, input_text)
        _say(f"Reading the live catalog of block '{block}' (run {run_id}).")
        channel(run)
        verified = _tool_output(
            schema_tool,
            [SCHEMA_READ_VERIFY_COMMAND, block, *_run_file_options(run)],
            failed,
            failure,
        )
    finally:
        _remove_private_directory(
            directory, block, "the read's input and the client's output", failure
        )
    return _LINE_BREAK.join(
        _decoded_lines(verified, "verified document", failed, failure)
    )


def schema_read(
    block: str,
    *,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> None:
    """``schema-read <block>``: print *block*'s verified live catalog on standard output, alone.

    The document is written as UTF-8 bytes ended by one line break, whatever the console's
    encoding or line ending, so what a consumer reads is what the server sent. Progress goes to
    standard error. Arguments and errors as :func:`read_live_catalog`.
    """
    document = read_live_catalog(
        block, schema_tool=schema_tool, channel=channel, failure=failure
    )
    _write_stdout(f"{document}{_LINE_BREAK}".encode(_TEXT_ENCODING))


def _plan_file_bytes(
    path: Path, failed: str, failure: Callable[[str], Exception]
) -> bytes:
    """The bytes of the SQL file *path*; the host's error opening with *failed* when it cannot be read."""
    try:
        return path.read_bytes()
    except OSError as error:
        raise failure(
            f"{failed}: the file could not be read ({error}). Give a SQL file "
            f"'schema.py {SCHEMA_PLAN_COMMAND}' wrote for the block."
        ) from error


def _apply_plan_file(
    block: str,
    path: Path,
    *,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> str | None:
    """Apply *path*, one of *block*'s plan files, through *channel*: the verified document of the
    catalog it left, or ``None``.

    ``None`` is an empty file, which applies nothing: that is said on standard error and no client
    runs. The steps and the errors are :func:`schema_apply`'s.
    """
    failed = f"The SQL file {path} was not applied to block '{block}'"
    if not _plan_file_bytes(path, failed, failure):
        _say(f"The SQL file {path} of block '{block}' is empty: nothing applies.")
        return None
    sql_option = (SCHEMA_APPLY_SQL_OPTION, str(path))
    input_text = _tool_output(
        schema_tool, (SCHEMA_APPLY_BATCH_COMMAND, block, *sql_option), failed, failure
    )
    if not input_text:
        raise failure(
            f"{failed}: 'schema.py {SCHEMA_APPLY_BATCH_COMMAND}' printed no input, so the file was "
            "emptied after it was read."
        )
    client_arguments = _client_arguments(schema_tool, block, failed, failure)
    run_id = new_run_id()
    directory = _private_directory(
        f"{_APPLY_DIRECTORY_PREFIX}{run_id}-", failed, failure
    )
    unverified = f"The apply of {path} to block '{block}' was not verified"
    try:
        run = SchemaRun(block, run_id, directory, client_arguments)
        _write_new_file(run.input_file, input_text)
        _say(f"Applying {path} to block '{block}' (run {run_id}).")
        channel(run)
        verified = _tool_output(
            schema_tool,
            [SCHEMA_APPLY_VERIFY_COMMAND, block, *sql_option, *_run_file_options(run)],
            unverified,
            failure,
        )
    finally:
        _remove_private_directory(
            directory, block, "the apply's input and the client's output", failure
        )
    document = _LINE_BREAK.join(
        _decoded_lines(verified, "verified document", unverified, failure)
    )
    if not document:
        raise failure(
            f"{unverified}: 'schema.py {SCHEMA_APPLY_VERIFY_COMMAND}' printed an empty line where "
            "it prints the document of the catalog the apply left."
        )
    return document


def schema_apply(
    block: str,
    sql_file: str,
    *,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> None:
    """``schema-apply <block> <sql-file>``: apply *sql_file*, one of *block*'s plan files, through *channel*.

    ``schema.py apply-batch`` prints the client's input, refusing a file that is not one of
    *block*'s plan files (so no DDL runs unguarded), and ``read-batch --places`` the client
    arguments, as for a read. The input is written to ``in`` in a directory private to this run,
    never passed as an argument; *channel* runs the client as the block's owner login, and
    ``schema.py apply-verify`` checks the files it left. The directory is removed whatever
    happened. The verified document of the catalog the apply left goes to standard output as
    UTF-8 bytes ended by one line break, nothing else, as :func:`schema_read` prints a read's;
    progress goes to standard error. An empty file applies nothing: that is said on standard
    error and no client runs.

    Args:
        block: The block key (``schema_tool_block_key``).
        sql_file: The SQL file, as ``schema.py plan`` wrote it beside its statement map.
        schema_tool: Runs a schema-tool command (:func:`run_schema_tool` bound to the project's
            ``schema.py``).
        channel: The platform's channel to the block's client: the one ``schema-read`` uses.
        failure: The host's error type, built from a message naming the cause.

    Raises:
        Exception: *failure*'s, naming *block* and the cause, when the file cannot be read, the
            tool refuses the file or the block, the run is not a verified apply (``apply-verify``'s
            message names the statement and change a failed apply stopped at and what it left of
            the schema), or the run's directory cannot be removed; and whatever *channel* raises.
    """
    document = _apply_plan_file(
        block,
        Path(sql_file).resolve(),
        schema_tool=schema_tool,
        channel=channel,
        failure=failure,
    )
    if document is not None:
        _write_stdout(f"{document}{_LINE_BREAK}".encode(_TEXT_ENCODING))


def schema_plan_arguments(
    block: str, catalog: Path, expand: Path, contract: Path, approved: bool
) -> list[str]:
    """``schema.py plan``'s arguments for *block*: :data:`SCHEMA_PLAN_APPROVED_OPTION` exactly when *approved*."""
    arguments = [
        SCHEMA_PLAN_COMMAND,
        block,
        SCHEMA_PLAN_CATALOG_OPTION,
        str(catalog),
        SCHEMA_PLAN_EXPAND_OPTION,
        str(expand),
        SCHEMA_PLAN_CONTRACT_OPTION,
        str(contract),
    ]
    if approved:
        arguments.append(SCHEMA_PLAN_APPROVED_OPTION)
    return arguments


def _printed_plan(result: SchemaToolRun, block: str) -> bool:
    """Whether *result*'s standard output is a plan of *block*: it opens with :data:`SCHEMA_PLAN_HEADER`."""
    return result.stdout.startswith(
        SCHEMA_PLAN_HEADER.format(block=block).encode(_TEXT_ENCODING)
    )


class _PlanFiles(NamedTuple):
    """The files one ``plan`` of a block reads and writes: the live catalog's document and each phase's SQL.

    ``plan`` writes each phase's statement map beside its SQL file.
    """

    catalog: Path
    expand: Path
    contract: Path


def _plan_files(directory: Path) -> _PlanFiles:
    """The files of one ``plan`` in *directory*, a directory private to it."""
    return _PlanFiles(
        directory / _PLAN_CATALOG_FILE,
        directory / _PLAN_EXPAND_FILE,
        directory / _PLAN_CONTRACT_FILE,
    )


def _write_catalog(
    catalog: Path, document: str, failed: str, failure: Callable[[str], Exception]
) -> None:
    """Write *document*, a verified catalog document, to *catalog* as a verified read prints it.

    A document that cannot be written raises the host's error opening with *failed*.
    """
    try:
        _write_new_file(catalog, f"{document}{_LINE_BREAK}".encode(_TEXT_ENCODING))
    except OSError as error:
        raise failure(
            f"{failed}: its catalog could not be written to {catalog} ({error})."
        ) from error


def _run_plan(
    block: str,
    approved: bool,
    files: _PlanFiles,
    failed: str,
    *,
    schema_tool: SchemaTool,
    failure: Callable[[str], Exception],
) -> SchemaToolRun:
    """Run ``schema.py plan`` over *files*' catalog document, writing its SQL there.

    ``plan`` gets :data:`SCHEMA_PLAN_APPROVED_OPTION` exactly when *approved*.

    Returns:
        ``plan``'s run, which printed a plan of *block*: exit 0 applies every change, exit
        :data:`SCHEMA_PLAN_REFUSED_EXIT` refuses one.

    Raises:
        Exception: *failure*'s, opening with *failed*, when ``plan`` exits with any other status
            or prints no plan of *block*.
    """
    result = schema_tool(
        schema_plan_arguments(
            block, files.catalog, files.expand, files.contract, approved
        )
    )
    planned = result.exit_status in (0, SCHEMA_PLAN_REFUSED_EXIT) and _printed_plan(
        result, block
    )
    if not planned:
        raise failure(
            f"{failed}: 'schema.py {SCHEMA_PLAN_COMMAND} {block}' exited {result.exit_status} "
            f"without printing a plan of the block: {_exit_cause(result)}"
        )
    return result


def _read_and_plan(
    block: str,
    approved: bool,
    files: _PlanFiles,
    *,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> SchemaToolRun:
    """Read *block*'s live catalog into *files* and run ``schema.py plan`` over it (:func:`_run_plan`).

    Raises:
        Exception: *failure*'s, naming *block* and the cause, when the read fails, the document
            cannot be written, or ``plan`` fails; and whatever *channel* raises.
    """
    failed = f"The plan of block '{block}' was not made"
    document = read_live_catalog(
        block, schema_tool=schema_tool, channel=channel, failure=failure
    )
    _write_catalog(files.catalog, document, failed, failure)
    return _run_plan(
        block, approved, files, failed, schema_tool=schema_tool, failure=failure
    )


def _refused_plans(refused: Sequence[str], outcome: str) -> str:
    """The message naming each refused block (*refused*: ``<block>: <cause>``) and *outcome*."""
    listed = "\n  - ".join(refused)
    return (
        f"The plan refuses changes in {len(refused)} block(s), and {outcome}:\n"
        f"  - {listed}\nA change that needs approval is planned only when the deploy runs "
        f"with {SCHEMA_PLAN_APPROVED_OPTION}; a change never applied needs the fix its plan "
        "names."
    )


def _plan_block(
    block: str,
    approved: bool,
    *,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> SchemaToolRun:
    """What a deploy would do to *block*, changing nothing: the run of ``schema.py plan`` that printed it.

    *block*'s live catalog is read (:func:`read_live_catalog`), its document written to a
    directory private to this plan, and ``schema.py plan`` run over it with ``--approved`` exactly
    when *approved*, writing its expand and contract SQL, each with its statement map, into that
    directory. The directory, holding the document and every file the plan wrote, is removed
    whatever happened.

    Raises:
        Exception: *failure*'s, naming *block* and the cause, when the read fails, when ``plan``
            exits with a status other than 0 and :data:`SCHEMA_PLAN_REFUSED_EXIT` or prints no
            plan of *block*, or when the directory cannot be removed; and whatever *channel*
            raises.
    """
    directory = _private_directory(
        _PLAN_DIRECTORY_PREFIX, f"The plan of block '{block}' was not made", failure
    )
    try:
        return _read_and_plan(
            block,
            approved,
            _plan_files(directory),
            schema_tool=schema_tool,
            channel=channel,
            failure=failure,
        )
    finally:
        _remove_private_directory(
            directory, block, "its live catalog and the plan's SQL files", failure
        )


def plan_schema_blocks(
    blocks: Sequence[str],
    approved: bool,
    *,
    concurrent_runs: ConcurrentRuns,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> None:
    """``deploy --plan``: print what a deploy would do to every block of *blocks*, changing nothing.

    The blocks are planned side by side (:func:`_plan_block`), as many at once as the channel
    carries, and each plan goes to standard output as its bytes, in the blocks' order. A plan that
    refuses a change is printed and the other blocks planned, so one run shows every refusal.

    Args:
        blocks: The block keys whose schema convergence is enabled, in the order to plan them.
        approved: Whether the operator gave ``deploy --approved``; the one source of approval.
        concurrent_runs: How many runs *channel* carries at once, asked once when there is a block.
        schema_tool: Runs a schema-tool command (:func:`run_schema_tool` bound to the project's
            ``schema.py``).
        channel: The platform's channel to a block's client.
        failure: The host's error type, built from a message naming the cause.

    Raises:
        Exception: *failure*'s, naming each block whose plan refuses a change once every block
            is planned; or, for the first block in order that cannot be read or planned, naming
            it and the cause, once the plans already running have finished (no block after it
            starts).
    """
    if not blocks:
        print(
            "No RDBMS block has schema convergence enabled: there is nothing to plan."
        )
        return

    def plan_block(block: str) -> SchemaToolRun:
        return _plan_block(
            block, approved, schema_tool=schema_tool, channel=channel, failure=failure
        )

    refused: list[str] = []
    for block, result in _each_block(
        blocks, plan_block, _concurrency(concurrent_runs, failure)
    ):
        _write_stdout(result.stdout)
        if result.exit_status != 0:
            refused.append(f"{block}: {_exit_cause(result)}")
    if refused:
        raise failure(_refused_plans(refused, "nothing was changed"))


def _step_files(
    directory: Path, step: str, block: str, failure: Callable[[str], Exception]
) -> _PlanFiles:
    """The files of one converge *step* on *block*, in its own new subdirectory of *directory*."""
    step_directory = directory / step
    try:
        step_directory.mkdir()
    except OSError as error:
        raise failure(
            f"Block '{block}' was not converged: the directory {step_directory} could not be "
            f"created ({error})."
        ) from error
    return _plan_files(step_directory)


class _Converging(NamedTuple):
    """Where one block's converge stands once its expand is applied.

    Attributes:
        expanded: Whether its expand applied a change.
        contract: The contract SQL it applies once the release is healthy: the re-plan's when
            its expand applied a change, the first plan's otherwise.
        catalog: The document of the catalog it was last seen with: the one its expand left, or
            the first read's.
    """

    expanded: bool
    contract: Path
    catalog: Path


def _plan_before_release(
    blocks: Sequence[str],
    approved: bool,
    directories: dict[str, Path],
    concurrent: int,
    *,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> dict[str, _PlanFiles]:
    """Read and plan every block of *blocks* in its converge directory, printing each plan; the files of each block's plan.

    The blocks are planned side by side, *concurrent* at once, and each plan printed in the
    blocks' order. A plan refusing a change is printed and the other blocks planned; once every
    block is planned, the host's error names each refused block, before anything is applied.
    """

    def plan_block(block: str) -> tuple[_PlanFiles, SchemaToolRun]:
        files = _step_files(directories[block], _CONVERGE_PLAN_STEP, block, failure)
        return files, _read_and_plan(
            block,
            approved,
            files,
            schema_tool=schema_tool,
            channel=channel,
            failure=failure,
        )

    planned: dict[str, _PlanFiles] = {}
    refused: list[str] = []
    for block, (files, result) in _each_block(blocks, plan_block, concurrent):
        _write_stdout(result.stdout)
        if result.exit_status != 0:
            refused.append(f"{block}: {_exit_cause(result)}")
        planned[block] = files
    if refused:
        raise failure(
            _refused_plans(
                refused, "nothing was applied and the new release was not started"
            )
        )
    return planned


def _apply_phase(
    block: str,
    phase: str,
    sql: Path,
    step: tuple[Path, str],
    *,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> _PlanFiles | None:
    """Apply *sql*, *block*'s *phase* SQL (:func:`_apply_plan_file`), keeping the catalog it left.

    *step* is the block's converge directory and the step whose new subdirectory receives the
    verified document of the catalog the apply left, as its catalog file.

    Returns:
        The step's files, or ``None`` when *sql* is empty: it applies nothing and no client runs.
    """
    document = _apply_plan_file(
        block, sql.resolve(), schema_tool=schema_tool, channel=channel, failure=failure
    )
    if document is None:
        return None
    directory, name = step
    files = _step_files(directory, name, block, failure)
    kept = f"The {phase} of block '{block}' is applied, but the catalog it left was not kept"
    _write_catalog(files.catalog, document, kept, failure)
    return files


def _replan_after_expand(
    block: str,
    approved: bool,
    replanned: _PlanFiles,
    planned: _PlanFiles,
    *,
    schema_tool: SchemaTool,
    failure: Callable[[str], Exception],
) -> None:
    """Plan *block* again from the catalog its expand left (*replanned*'s catalog), into *replanned*.

    The re-plan runs with the arguments of the first and must hold exactly *planned*'s contract
    changes (``schema.py plan-compare``): no expand change, no contract change more or less. The
    catalog is the one the apply itself read under the block's lock once its changes were
    committed, so what anything else changed beside the expand is in it.

    Raises:
        Exception: *failure*'s, naming *block*, when the re-plan fails, refuses a change or
            differs from *planned*'s contract (``plan-compare``'s message names each extra and
            each missing change).
    """
    failed = (
        f"The re-plan of block '{block}' after its expand is not exactly its planned contract, "
        "so the new release was not started"
    )
    result = _run_plan(
        block, approved, replanned, failed, schema_tool=schema_tool, failure=failure
    )
    if result.exit_status != 0:
        raise failure(f"{failed}: it refuses a change: {_exit_cause(result)}")
    comparison = (
        SCHEMA_PLAN_COMPARE_COMMAND,
        block,
        SCHEMA_PLAN_COMPARE_PLANNED_OPTION,
        str(planned.contract),
        SCHEMA_PLAN_EXPAND_OPTION,
        str(replanned.expand),
        SCHEMA_PLAN_CONTRACT_OPTION,
        str(replanned.contract),
    )
    _tool_output(schema_tool, comparison, failed, failure)


def _expand_and_replan(
    blocks: Sequence[str],
    approved: bool,
    directories: dict[str, Path],
    planned: dict[str, _PlanFiles],
    concurrent: int,
    *,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> dict[str, _Converging]:
    """Apply each block's expand and re-plan each block it changed (:func:`_replan_after_expand`); where each block stands.

    The blocks are carried side by side, *concurrent* at once. A block whose expand is empty
    applies nothing and keeps its first plan: no change ran, so its contract still carries the
    fingerprint of the catalog it applies to.
    """

    def expand(block: str) -> _Converging:
        files = planned[block]
        replanned = _apply_phase(
            block,
            "expand",
            files.expand,
            (directories[block], _CONVERGE_REPLAN_STEP),
            schema_tool=schema_tool,
            channel=channel,
            failure=failure,
        )
        if replanned is None:
            return _Converging(False, files.contract, files.catalog)
        _replan_after_expand(
            block, approved, replanned, files, schema_tool=schema_tool, failure=failure
        )
        return _Converging(True, replanned.contract, replanned.catalog)

    standing: dict[str, _Converging] = {}
    for block, converging in _each_block(blocks, expand, concurrent):
        if converging.expanded:
            print(
                f"Applied the expand of block '{block}'; its re-plan holds exactly its planned contract."
            )
        standing[block] = converging
    return standing


def _verdict(result: SchemaToolRun, block: str) -> str:
    """Why ``schema.py verify``'s run *result* says *block* differs from its declared schema."""
    verdict = result.stdout.decode(_TEXT_ENCODING, errors="replace").strip()
    return (
        f"'schema.py {SCHEMA_VERIFY_COMMAND} {block}' exited {result.exit_status}: "
        f"{verdict or 'it printed no verdict'} ({_exit_cause(result)})"
    )


def _contract_and_verify(
    blocks: Sequence[str],
    directories: dict[str, Path],
    standing: dict[str, _Converging],
    concurrent: int,
    *,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> None:
    """Apply each block's contract, then have ``schema.py verify`` check the catalog the block was left with.

    The blocks are carried side by side, *concurrent* at once, and each verdict printed in the
    blocks' order. The catalog verified is the one the contract's apply left, or, when the
    contract is empty, the one the block was last seen with (:class:`_Converging`).

    Raises:
        Exception: *failure*'s, naming each block whose catalog differs from its declared schema,
            once every block is verified; and as :func:`_apply_phase`.
    """

    def contract(block: str) -> tuple[bool, SchemaToolRun]:
        converging = standing[block]
        applied = _apply_phase(
            block,
            "contract",
            converging.contract,
            (directories[block], _CONVERGE_VERIFY_STEP),
            schema_tool=schema_tool,
            channel=channel,
            failure=failure,
        )
        catalog = converging.catalog if applied is None else applied.catalog
        return applied is not None, schema_tool(
            (SCHEMA_VERIFY_COMMAND, block, SCHEMA_PLAN_CATALOG_OPTION, str(catalog))
        )

    differing: list[str] = []
    for block, (contracted, result) in _each_block(blocks, contract, concurrent):
        if contracted:
            print(f"Applied the contract of block '{block}'.")
        _write_stdout(result.stdout)
        if result.exit_status != 0:
            differing.append(f"{block}: {_verdict(result, block)}")
    if differing:
        listed = "\n  - ".join(differing)
        raise failure(
            f"{len(differing)} block(s) do not hold their declared schema after the deploy:\n"
            f"  - {listed}\nThe new release runs against the schema the deploy left; read the "
            "block's catalog for what changed, then deploy again: it plans the remaining changes "
            "anew."
        )


def _remove_converge_directories(
    directories: dict[str, Path], failure: Callable[[str], Exception]
) -> None:
    """Remove every block's converge directory of *directories*, naming each that cannot be removed."""
    left: list[str] = []
    for block, directory in directories.items():
        try:
            shutil.rmtree(directory)
        except OSError as error:
            left.append(f"block '{block}': {directory} ({error})")
    if left:
        listed = "\n  - ".join(left)
        raise failure(
            f"The converge files of {len(left)} block(s) could not be removed:\n  - {listed}\n"
            "They hold the blocks' live catalogs and plan SQL: remove the directories."
        )


def _expand_and_start(
    blocks: Sequence[str],
    approved: bool,
    directories: dict[str, Path],
    concurrent: int,
    *,
    start_release: Callable[[], None],
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> dict[str, _Converging]:
    """Plan every block, apply each expand, re-plan each against its planned contract, then start the release.

    Each block gets a directory private to its converge, recorded in *directories* as soon as it
    exists so the caller removes it whatever happens. The blocks are carried side by side,
    *concurrent* at once.

    Returns:
        Where each block stands (:class:`_Converging`): the contract SQL it applies once the
        release is healthy and the catalog it was last seen with.
    """
    for block in blocks:
        directories[block] = _private_directory(
            _CONVERGE_DIRECTORY_PREFIX, f"Block '{block}' was not converged", failure
        )
    planned = _plan_before_release(
        blocks,
        approved,
        directories,
        concurrent,
        schema_tool=schema_tool,
        channel=channel,
        failure=failure,
    )
    standing = _expand_and_replan(
        blocks,
        approved,
        directories,
        planned,
        concurrent,
        schema_tool=schema_tool,
        channel=channel,
        failure=failure,
    )
    print(
        f"The expand of {len(blocks)} block(s) is applied and each re-plan holds exactly its "
        "planned contract: starting the new release."
    )
    start_release()
    return standing


def _converge(
    blocks: Sequence[str],
    approved: bool,
    directories: dict[str, Path],
    concurrent: int,
    *,
    start_release: Callable[[], None],
    verify_release: Callable[[], None],
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> None:
    """The steps of :func:`converge_schema_blocks` once the databases are up, in their order."""
    standing = _expand_and_start(
        blocks,
        approved,
        directories,
        concurrent,
        start_release=start_release,
        schema_tool=schema_tool,
        channel=channel,
        failure=failure,
    )
    print(
        "Verifying the new release: no block's contract is applied unless it is healthy."
    )
    verify_release()
    _contract_and_verify(
        blocks,
        directories,
        standing,
        concurrent,
        schema_tool=schema_tool,
        channel=channel,
        failure=failure,
    )


def converge_schema_blocks(
    blocks: Sequence[str],
    approved: bool,
    *,
    bring_up_data: Callable[[], None],
    start_release: Callable[[], None],
    verify_release: Callable[[], None],
    concurrent_runs: ConcurrentRuns,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> None:
    """``deploy``'s ``converge`` step: bring every block of *blocks* to its declared schema around the release.

    In this order, each step only once the one before succeeded for every block:

    1. *bring_up_data* starts the databases, and every block is read and planned
       (``schema.py plan``, ``--approved`` exactly when *approved*), its plan printed. A plan
       refusing a change stops the deploy, naming every refused block, before anything applies.
    2. Each block's expand SQL is applied (:func:`schema_apply`'s path; an empty file applies
       nothing and runs no client). A block whose expand applied a change is planned again with
       the same arguments from the verified catalog that apply left, and ``schema.py
       plan-compare`` requires the re-plan to hold exactly the first plan's contract changes; a
       block whose expand is empty keeps its first plan's contract.
    3. *start_release* starts the new release and *verify_release* proves it healthy.
    4. Each block's contract SQL is applied: it carries the fingerprint of the catalog the block
       was last seen with. ``schema.py verify`` then checks the catalog the block was left with
       -- the one its contract's apply left, else its expand's, else its first read -- and prints
       its verdict; a block that differs from its declared schema fails the deploy once every
       block is verified.

    A block's client runs once for its read and once for each phase file holding a change: an
    apply reads the catalog it left under the block's lock, so no step reads the catalog again.
    Each step is carried out for the blocks side by side, as many at once as *concurrent_runs*
    says, and what it prints comes out in the blocks' order; a block that fails stops every block
    after it from starting that step, the ones already running finish, and the failure is raised
    for the first failed block in order.

    Every plan's files stay in a directory private to the block's converge until the end, and
    every such directory is removed whatever happened. With no block (the profile's migrations
    disabled) the three callbacks run in their order, no block is converged and *concurrent_runs*
    is not asked.

    Args:
        blocks: The block keys whose schema convergence is enabled, each once (a shared block under its
            one key), in the order to converge them.
        approved: Whether the operator gave ``deploy --approved``; the one source of approval.
        bring_up_data: Starts the databases the blocks live in, returning once they accept
            connections.
        start_release: Starts the new release.
        verify_release: The deploy's health verification of the new release.
        concurrent_runs: How many runs *channel* carries at once, asked once *bring_up_data*
            returned, since a channel may read it from what that step deploys (Azure App
            Service's run store is part of its foundation stage).
        schema_tool: Runs a schema-tool command (:func:`run_schema_tool` bound to the project's
            ``schema.py``).
        channel: The platform's channel to a block's client: the one ``schema-read`` uses.
        failure: The host's error type, built from a message naming the cause.

    Raises:
        Exception: *failure*'s, naming the block and the cause, when a block is given twice, the
            channel's concurrency is not at least one, a plan refuses a change, an apply fails, a
            re-plan differs, a block differs from its declared schema at the end, or a directory
            cannot be removed; and whatever a callback or *channel* raises, which stops the steps
            after it.
    """
    _require_distinct_blocks(blocks, failure)
    if not blocks:
        print("No RDBMS block has schema convergence enabled: no block is converged.")
        bring_up_data()
        start_release()
        verify_release()
        return
    bring_up_data()
    # Asked once the data is up: a channel may read its count from what bring_up_data deploys.
    concurrent = _concurrency(concurrent_runs, failure)
    directories: dict[str, Path] = {}
    try:
        _converge(
            blocks,
            approved,
            directories,
            concurrent,
            start_release=start_release,
            verify_release=verify_release,
            schema_tool=schema_tool,
            channel=channel,
            failure=failure,
        )
    finally:
        _remove_converge_directories(directories, failure)


def _require_distinct_blocks(
    blocks: Sequence[str], failure: Callable[[str], Exception]
) -> None:
    """Raise the host's error naming every block *blocks* gives more than once."""
    repeated = sorted({block for block in blocks if blocks.count(block) > 1})
    if repeated:
        raise failure(
            f"The blocks to converge name {', '.join(repeated)} more than once; a block is "
            "planned once per run, under its one schema-tool key. Regenerate the project."
        )


def expand_schema_blocks(
    blocks: Sequence[str],
    approved: bool,
    *,
    bring_up_data: Callable[[], None],
    start_release: Callable[[], None],
    concurrent_runs: ConcurrentRuns,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> None:
    """The expand half of the ``converge`` step, around a release a later ``deploy`` completes.

    Steps 1 to 3 of :func:`converge_schema_blocks`, then *start_release*: the databases come up,
    every block is read and planned (a plan refusing a change stops the run, naming every refused
    block, before anything applies), each expand is applied, and each re-plan must hold exactly
    the first plan's contract changes before the release starts. No contract is applied and no
    block verified: the expanded schema still holds everything the release before it reads, and
    the next ``deploy``'s converge applies the contract once its own release is healthy.

    Args:
        blocks: The block keys whose schema convergence is enabled, each once, in the order to
            expand them.
        approved: Whether the plans run with ``--approved``; a command without that switch of its
            own passes ``False``.
        bring_up_data: Starts the databases the blocks live in, returning once they accept
            connections.
        start_release: Starts the release.
        concurrent_runs: As :func:`converge_schema_blocks` takes it, asked once the data is up.
        schema_tool: Runs a schema-tool command.
        channel: The platform's channel to a block's client.
        failure: The host's error type, built from a message naming the cause.

    Raises:
        Exception: *failure*'s, naming the block and the cause, when a block is given twice, the
            concurrency is below one, a plan refuses a change, an apply fails, a re-plan differs or
            a directory cannot be removed; and whatever a callback or *channel* raises.
    """
    _require_distinct_blocks(blocks, failure)
    if not blocks:
        print("No RDBMS block has schema convergence enabled: no block is expanded.")
        bring_up_data()
        start_release()
        return
    bring_up_data()
    concurrent = _concurrency(concurrent_runs, failure)
    directories: dict[str, Path] = {}
    try:
        _expand_and_start(
            blocks,
            approved,
            directories,
            concurrent,
            start_release=start_release,
            schema_tool=schema_tool,
            channel=channel,
            failure=failure,
        )
    finally:
        _remove_converge_directories(directories, failure)
    print(
        f"The contract of {len(blocks)} block(s) is not applied: the next deploy applies it once "
        "its release is healthy."
    )


def start_on_converged_schema(
    blocks: Sequence[str],
    *,
    start_release: Callable[[], None],
    concurrent_runs: ConcurrentRuns,
    schema_tool: SchemaTool,
    channel: SchemaChannel,
    failure: Callable[[str], Exception],
) -> None:
    """Start *start_release* only when every block of *blocks* already holds its declared schema.

    For a command that delivers a release without converging: each block is read and ``schema.py
    verify`` prints its verdict; once every block is verified, a block that differs from its
    declared schema stops the run, naming each differing block, before the release starts. A
    ``deploy`` converges them. The blocks are carried side by side as :func:`converge_schema_blocks`
    carries them, and each verdict is printed in the blocks' order.

    Args:
        blocks: The block keys whose schema convergence is enabled, each once.
        start_release: Starts the release.
        concurrent_runs: How many runs *channel* carries at once, asked once when there is a block.
        schema_tool: Runs a schema-tool command.
        channel: The platform's channel to a block's client.
        failure: The host's error type, built from a message naming the cause.

    Raises:
        Exception: *failure*'s, naming each block that differs from its declared schema, or the
            first block that cannot be read or verified, a directory that cannot be removed or a
            concurrency below one; and whatever *start_release* or *channel* raises.
    """
    _require_distinct_blocks(blocks, failure)
    if not blocks:
        print("No RDBMS block has schema convergence enabled: no block is verified.")
        start_release()
        return
    concurrent = _concurrency(concurrent_runs, failure)
    directories: dict[str, Path] = {}
    differing: list[str] = []

    def verify(block: str) -> SchemaToolRun:
        files = _step_files(directories[block], _CONVERGE_VERIFY_STEP, block, failure)
        document = read_live_catalog(
            block, schema_tool=schema_tool, channel=channel, failure=failure
        )
        _write_catalog(
            files.catalog, document, f"Block '{block}' was not verified", failure
        )
        return schema_tool(
            (
                SCHEMA_VERIFY_COMMAND,
                block,
                SCHEMA_PLAN_CATALOG_OPTION,
                str(files.catalog),
            )
        )

    try:
        for block in blocks:
            directories[block] = _private_directory(
                _CONVERGE_DIRECTORY_PREFIX, f"Block '{block}' was not verified", failure
            )
        for block, result in _each_block(blocks, verify, concurrent):
            _write_stdout(result.stdout)
            if result.exit_status != 0:
                differing.append(f"{block}: {_verdict(result, block)}")
    finally:
        _remove_converge_directories(directories, failure)
    if differing:
        listed = "\n  - ".join(differing)
        raise failure(
            f"{len(differing)} block(s) do not hold their declared schema, so the release was not "
            f"started:\n  - {listed}\nThe release reads the schema it declares; run deploy, which "
            "converges every block around its release."
        )
    print(
        f"Every one of {len(blocks)} block(s) holds its declared schema: starting the release."
    )
    start_release()


#: How many times one image's import is sent, the first included, while each failure is the
#: source registry refusing the pull for its rate limit (:data:`RUN_IMAGE_RATE_LIMIT_MARKERS`)
#: or one the host's classifier calls transient. A public registry's anonymous pull window is
#: counted in hours, and shared by every tenant of the registry's import egress.
RUN_IMAGE_IMPORT_ATTEMPTS: int = 4
#: How long an import waits before its first re-send; each later wait is twice the one before
#: (60 s, 120 s, 240 s), minutes in all, for a rate-limit window to recover.
RUN_IMAGE_IMPORT_RETRY_SECONDS: float = 60.0
#: What an import's output carries when the source registry refused the pull for its rate
#: limit: the registry's error code, its reason phrase, and the status ACR reports it with.
RUN_IMAGE_RATE_LIMIT_MARKERS: tuple[str, ...] = (
    "TOOMANYREQUESTS",
    "Too Many Requests",
    "StatusCode: 429",
)
#: What ACR answers an import without ``--force`` whose target tag the registry already holds.
#: The tag names the image's digest (``generators/schema_run_group.py``, ``run_group_image``),
#: so the registry holds exactly the bytes the run pulls.
RUN_IMAGE_PRESENT_MARKER: str = "already exists in target registry"


class ImportedAzRun(Protocol):
    """What one ``az`` invocation left, as an import reads it (``schema_run_runtime.AzRun``)."""

    @property
    def exit_status(self) -> int: ...

    @property
    def stdout(self) -> str: ...

    @property
    def stderr(self) -> str: ...


class ImportedImage(Protocol):
    """One image a run's group runs, as it is imported (``schema_run_runtime.RunGroupImage``)."""

    @property
    def source(self) -> str: ...

    @property
    def repository(self) -> str: ...

    @property
    def tag(self) -> str: ...


#: Runs ``az`` with the given arguments (after ``az``) and returns what it left.
ImportAz = Callable[[Sequence[str]], ImportedAzRun]


def is_source_rate_limited(output: str) -> bool:
    """Whether an import's *output* says the source registry refused the pull for its rate
    limit (:data:`RUN_IMAGE_RATE_LIMIT_MARKERS`): a refusal that settles with time."""
    return any(marker in output for marker in RUN_IMAGE_RATE_LIMIT_MARKERS)


def _import_attempts(attempt: int) -> str:
    """`` on attempt n of N`` once an import was sent again, else nothing."""
    return (
        f" on attempt {attempt} of {RUN_IMAGE_IMPORT_ATTEMPTS}" if attempt > 1 else ""
    )


class ImportRetry(Protocol):
    """When an import is sent again, and how it waits before it is (``schema_run_runtime.RunRetry``)."""

    @property
    def transient(self) -> Callable[[str], bool]: ...

    @property
    def sleep(self) -> Callable[[float], None]: ...


def import_run_image(
    image: ImportedImage,
    *,
    registry: tuple[str, str],
    az: ImportAz,
    failure: Callable[[str], Exception],
    retry: ImportRetry,
) -> None:
    """Import *image*, by its digest, into the *registry* (its name and resource group) under
    its digest's tag, unless the registry already holds that tag.

    The import is sent without ``--force``: one whose tag the registry holds is refused with
    :data:`RUN_IMAGE_PRESENT_MARKER`, and since the tag names the digest, that refusal says the
    bytes are there, so a re-sent import whose first answer was lost is answered as present
    too. An import the source registry refuses for its rate limit, or that fails in a way
    *retry* calls transient, is sent again, at most :data:`RUN_IMAGE_IMPORT_ATTEMPTS` times, after
    :data:`RUN_IMAGE_IMPORT_RETRY_SECONDS` and then twice the wait before.

    Raises:
        Exception: *failure*'s, when an import fails for another reason, or every attempt was
            refused; the refusal names the attempt.
    """
    registry_name, resource_group = registry
    arguments = (
        "acr",
        "import",
        "--name",
        registry_name,
        "--resource-group",
        resource_group,
        "--source",
        image.source,
        "--image",
        f"{image.repository}:{image.tag}",
        "--only-show-errors",
        "-o",
        "none",
    )
    what = f"Importing the image '{image.source}' into the registry '{registry_name}'"
    attempt = 1
    while True:
        result = az(arguments)
        output = f"{result.stderr}\n{result.stdout}"
        if result.exit_status == 0 or RUN_IMAGE_PRESENT_MARKER in output:
            return
        rate_limited = is_source_rate_limited(output)
        if attempt >= RUN_IMAGE_IMPORT_ATTEMPTS or not (
            rate_limited or retry.transient(output)
        ):
            advice = (
                " The source registry refuses pulls past its rate limit; wait for its window to "
                "recover and deploy again."
                if rate_limited
                else ""
            )
            raise failure(
                f"{what} failed{_import_attempts(attempt)} (az exited {result.exit_status}): "
                f"{result.stderr or 'no output'}{advice}"
            )
        settle = RUN_IMAGE_IMPORT_RETRY_SECONDS * 2 ** (attempt - 1)
        cause = (
            "the source registry's rate limit"
            if rate_limited
            else "a fault that settles with time"
        )
        # One write per line: several runs print side by side.
        sys.stderr.write(
            f"{what} failed on attempt {attempt} of {RUN_IMAGE_IMPORT_ATTEMPTS} with {cause}; "
            f"sending it again in {settle:g} seconds.\n"
        )
        retry.sleep(settle)
        attempt += 1


class _ImageImport:
    """One image's import in a command: its lock, and its outcome once it has one."""

    def __init__(self) -> None:
        self.lock = threading.Lock()
        self.imported = False
        self.refusal: str | None = None


class RunImageImports:
    """The images of one deploy command's runs, each imported into the registry once.

    The first run needing an image imports it (:func:`import_run_image`); a run needing it at
    the same time waits for that import, and every later run of the command sends nothing. An
    import that failed is not sent again by the command: every later run needing that image is
    refused with the same reason, so a public registry refusing pulls is not asked once per run.
    *registry* gives the registry's name and resource group, read on the first import (the run
    store session's place).
    """

    def __init__(
        self,
        *,
        registry: Callable[[], tuple[str, str]],
        az: ImportAz,
        failure: Callable[[str], Exception],
        retry: ImportRetry,
    ) -> None:
        self._registry = registry
        self._az = az
        self._failure = failure
        self._retry = retry
        self._lock = threading.Lock()
        self._imports: dict[tuple[str, str, str], _ImageImport] = {}

    def import_images(self, images: Sequence[ImportedImage]) -> None:
        """Make sure the registry holds each of *images* (:func:`import_run_image`).

        Raises:
            Exception: *failure*'s, when an image's import failed, now or earlier in the
                command.
        """
        for image in images:
            with self._lock:
                entry = self._imports.setdefault(
                    (image.source, image.repository, image.tag), _ImageImport()
                )
            with entry.lock:
                if entry.refusal is not None:
                    raise self._failure(entry.refusal)
                if entry.imported:
                    continue
                try:
                    import_run_image(
                        image,
                        registry=self._registry(),
                        az=self._az,
                        failure=self._failure,
                        retry=self._retry,
                    )
                except Exception as refused:
                    entry.refusal = str(refused)
                    raise
                entry.imported = True


#: The ARM API version every container group request names. It declares ``subnetIds``,
#: user-assigned identities and ``emptyDir`` volumes.
RUN_GROUP_API_VERSION: str = "2023-05-01"
#: The resource type of a container group, as ARM lists it.
RUN_GROUP_RESOURCE_TYPE: str = "Microsoft.ContainerInstance/containerGroups"

#: The tag naming the application whose runs a group belongs to: what the sweep selects by.
RUN_GROUP_TAG: str = "cruftfree-schema-run"
#: The tag naming the run a group carries out.
RUN_GROUP_RUN_TAG: str = "cruftfree-schema-run-id"

#: The group's containers, in the order they run.
RUN_GROUP_COPY_IN_CONTAINER: str = "copy-in"
RUN_GROUP_CLIENT_CONTAINER: str = "client"
RUN_GROUP_COPY_OUT_CONTAINER: str = "copy-out"
RUN_GROUP_CONTAINERS: tuple[str, ...] = (
    RUN_GROUP_COPY_IN_CONTAINER,
    RUN_GROUP_CLIENT_CONTAINER,
    RUN_GROUP_COPY_OUT_CONTAINER,
)
#: The group's one ephemeral volume, mounted in every container.
RUN_GROUP_VOLUME: str = "work"

#: The variables the copy containers read where the run's files are and who they are, and the
#: client container's run id: values, never secrets.
RUN_ID_VARIABLE: str = "RUN_ID"
RUN_STORE_ACCOUNT_VARIABLE: str = "RUN_STORE_ACCOUNT"
RUN_STORE_CONTAINER_VARIABLE: str = "RUN_STORE_CONTAINER"
RUN_STORE_PREFIX_VARIABLE: str = "RUN_STORE_PREFIX"
SCHEMA_IDENTITY_VARIABLE: str = "SCHEMA_IDENTITY_ID"
#: The client container's variable naming the URL of its block's owner secret in Key Vault, for
#: a block on an external server: a name, which only the block's schema identity may read.
SCHEMA_OWNER_SECRET_VARIABLE: str = "SCHEMA_OWNER_SECRET_URI"
#: The field of a schema identity's entry in the run store's deployment output naming that URL.
SCHEMA_IDENTITY_OWNER_SECRET_FIELD: str = "ownerSecretUri"
#: The client container's variable naming the URL of the CA certificate its block's external
#: server is verified against, in Key Vault: a name, which only the block's schema identity may
#: read.
SCHEMA_SERVER_CA_VARIABLE: str = "SCHEMA_SERVER_CA_URI"
#: The field of a schema identity's entry in the run store's deployment output naming that URL.
SCHEMA_IDENTITY_SERVER_CA_FIELD: str = "serverCaUri"

#: Each container's size. ACI requires a request of every main container, and the group is
#: their sum.
RUN_GROUP_CPU: float = 1.0
RUN_GROUP_MEMORY_GB: float = 1.5
#: The cores one run's group requests: every container's request.
RUN_GROUP_CORES: float = RUN_GROUP_CPU * len(RUN_GROUP_CONTAINERS)

#: The most runs a deploy carries in container groups at once, however much room the quota
#: leaves: each run is also a dozen ``az`` invocations on the operator's machine.
RUN_GROUP_MAX_CONCURRENT_RUNS: int = 8
#: The Container Instances usages of a region that bound how many groups can run at once, as ARM
#: names them (``name.value``): the groups, and the standard cores their containers request.
RUN_GROUP_GROUPS_USAGE: str = "ContainerGroups"
RUN_GROUP_CORES_USAGE: str = "StandardCores"

#: How often the deploy reads the group's state while it waits.
RUN_GROUP_POLL_SECONDS: float = 10.0
#: The group states after which no container of it runs again (``restartPolicy: Never``).
RUN_GROUP_TERMINAL_STATES: frozenset[str] = frozenset(
    {"Succeeded", "Failed", "Stopped"}
)
#: The provisioning state of a group Azure could not create: terminal as well.
RUN_GROUP_FAILED_PROVISIONING: str = "Failed"

#: How many times one request of a run's path (the group's create, read and delete, a run
#: file's upload and download) is sent, the first included, while each failure is one the
#: host's classifier calls transient (:class:`RunRetry`): a resource provider's own 5xx or az's
#: own connection failing. A full converge creates one group per block and run, so one fault
#: of Azure's must not throw the whole deploy away.
RUN_AZ_ATTEMPTS: int = 3
#: How long a run waits before its *n*-th re-send: *n* times this, so the waits grow.
RUN_AZ_RETRY_SECONDS: float = 30.0
#: ARM's code for a resource that does not exist: what a group's read answers when a create
#: whose answer was lost made nothing.
RUN_GROUP_ABSENT_CODE: str = "ResourceNotFound"
#: Azure Storage's code for an upload refused because the blob exists: after a re-send, the
#: earlier attempt's upload landed and only its answer was lost.
BLOB_ALREADY_EXISTS: str = "BlobAlreadyExists"
#: The exit status of a client container whose script gave up waiting for copy-in. Its script
#: ends with no other status of this value, so it proves the client never asked for a credential
#: and nothing reached the database.
RUN_GROUP_CLIENT_NOT_STARTED_STATUS: int = 75
#: How many groups one run may create, the first included. A group whose client never started
#: says nothing about the next one: a new group lands on a host of its own.
RUN_GROUP_ATTEMPTS: int = 2

#: The file in the run's directory holding the group's definition, passed to ``az rest`` by path.
RUN_GROUP_SPEC_FILE: str = "group.json"

#: How many of its last lines each container's log contributes to a failed run's refusal:
#: enough for the error a copy script's ``az`` or the client's shell printed, and bounded.
RUN_GROUP_LOG_TAIL_LINES: int = 100
#: The characters of a container's log a refusal does not print as they are: control
#: characters other than a tab, which a terminal could read as an escape sequence.
_LOG_CONTROL_CHARACTER: re.Pattern[str] = re.compile(r"[\x00-\x08\x0a-\x1f\x7f-\x9f]")

_GROUP_NAME: re.Pattern[str] = re.compile(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?")
#: A Key Vault secret's URL as the run store's deployment reads it back (``secretUri``): HTTPS,
#: a host name, and the secret's name, with nothing a shell or a query could read more into.
_SECRET_URL: re.Pattern[str] = re.compile(
    r"https://[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+/secrets/[A-Za-z0-9-]+"
)


class AzRun(NamedTuple):
    """What one ``az`` invocation left: its exit status and its two output streams."""

    exit_status: int
    stdout: str
    stderr: str


#: Runs ``az`` with the given arguments (after ``az``) and returns what it left.
Az = Callable[[Sequence[str]], AzRun]


class RunRetry(NamedTuple):
    """When a run sends one of its requests again, and how it waits before it does."""

    transient: Callable[[str], bool]
    """The host's classifier: whether az's combined output from one failed request names a
    fault that settles with time (a resource provider's own 5xx, az's connection dropping)."""

    sleep: Callable[[float], None]


def _az_output(result: AzRun) -> str:
    """*result*'s two streams, as one text a classifier reads."""
    return f"{result.stderr}\n{result.stdout}"


def _attempts(attempt: int) -> str:
    """`` on attempt n of N`` once a request was sent again, else nothing."""
    return f" on attempt {attempt} of {RUN_AZ_ATTEMPTS}" if attempt > 1 else ""


def _az_retried(az: Az, arguments: Sequence[str], retry: RunRetry) -> tuple[AzRun, int]:
    """Send *arguments* until az succeeds, fails in a way *retry* does not call transient, or
    :data:`RUN_AZ_ATTEMPTS` attempts were made; what the last attempt left, and its number.

    For a request that is safe to send again as it is: a read, a delete, a download.
    """
    attempt = 1
    result = az(arguments)
    while (
        result.exit_status != 0
        and attempt < RUN_AZ_ATTEMPTS
        and retry.transient(_az_output(result))
    ):
        retry.sleep(RUN_AZ_RETRY_SECONDS * attempt)
        attempt += 1
        result = az(arguments)
    return result, attempt


class RunFiles(Protocol):
    """The run as the kernel's ``SchemaRun`` gives it to a channel."""

    @property
    def block(self) -> str: ...

    @property
    def run_id(self) -> str: ...

    @property
    def directory(self) -> Path: ...

    @property
    def client_arguments(self) -> tuple[str, ...]: ...

    @property
    def input_file(self) -> Path: ...

    @property
    def output_file(self) -> Path: ...

    @property
    def error_file(self) -> Path: ...

    @property
    def exit_file(self) -> Path: ...


class RunGroupImage(NamedTuple):
    """One image a run's group runs, as the deploy imports it and the group pulls it.

    Attributes:
        source: The pinned image as its public registry serves it, by digest
            (``<registry>/<repository>@sha256:<64 hex>``): what is imported.
        repository: Its repository in the composition's registry.
        tag: The tag it is imported under there, which names its digest: a registry holding
            the tag holds these bytes.
        digest: Its ``sha256:<64 hex>`` digest: what the group pulls it by.
    """

    source: str
    repository: str
    tag: str
    digest: str


class RunGroupWorkload(NamedTuple):
    """What every run's group runs beside the block's client: generation facts.

    Attributes:
        copy_image: The Azure CLI image of both copy containers, pinned by tag and digest.
        shell: The shell every container runs its script with (``sh -c``).
        mount_path: Where the volume is mounted in every container.
        copy_in_script: Copy-in's script: the input and the CA bundle into the volume, then
            the marker the client waits for.
        copy_out_script: Copy-out's script: once the client's marker is on the volume,
            ``out``, ``err`` and ``exit`` into the run store.
        ca_bundle_file: The CA bundle's file name in the run and on the volume.
    """

    copy_image: RunGroupImage
    shell: str
    mount_path: str
    copy_in_script: str
    copy_out_script: str
    ca_bundle_file: str


class RunGroupClient(NamedTuple):
    """One block's client: generation facts.

    Attributes:
        run_store_prefix: The block's run-store prefix (``run_store_prefix``), ending in ``/``.
        image: The engine's catalog client image, pinned by tag and digest.
        command: What follows ``sh -c``: the client's script, which waits for copy-in's
            marker and writes its own last, and its ``$0``; a run appends the client
            arguments it binds.
    """

    run_store_prefix: str
    image: RunGroupImage
    command: tuple[str, ...]


class RunGroupPlace(NamedTuple):
    """Where one run's group is created and what it reaches, as the deploy resolved them.

    Attributes:
        subscription_id: The subscription holding the resource group.
        resource_group: The resource group the groups are created in.
        location: The groups' region.
        subnet_id: The schema-run subnet's resource id.
        storage_account: The run store's account name.
        storage_container: The run store's container name.
        registry_name: The name of the registry the group's images are imported into.
        registry_server: That registry's login server, which the group pulls from.
        app_tag: This application's value of :data:`RUN_GROUP_TAG`.
        identity_id: The block's schema identity's resource id.
        client_environment: The client's connection variables and their values: no secret.
    """

    subscription_id: str
    resource_group: str
    location: str
    subnet_id: str
    storage_account: str
    storage_container: str
    registry_name: str
    registry_server: str
    app_tag: str
    identity_id: str
    client_environment: tuple[tuple[str, str], ...]


def run_group_name(verb: str, run_id: str, failure: Callable[[str], Exception]) -> str:
    """The container group name of the run *run_id* of the schema verb *verb*: the verb, ``-``
    and the id in lower case, so the group says what it carries out.

    Raises:
        Exception: *failure*'s, when the name is not one Azure accepts for a container group
            (lower-case letters, digits and ``-``, at most 63, not ending in ``-``).
    """
    name = f"{verb}-{run_id.lower()}"
    if _GROUP_NAME.fullmatch(name) is None:
        raise failure(
            f"The verb {verb!r} and the run id {run_id!r} give the container group name {name!r}, "
            "which Azure does not accept: expected lower-case letters, digits and '-', at most 63 "
            "characters, starting and ending with a letter or digit. Pass a schema verb of the "
            "kernel's vocabulary and start the run with the kernel's new_run_id."
        )
    return name


def run_group_id(place: RunGroupPlace, name: str) -> str:
    """The resource id of the container group *name* in *place*'s resource group."""
    return (
        f"/subscriptions/{place.subscription_id}/resourceGroups/{place.resource_group}"
        f"/providers/{RUN_GROUP_RESOURCE_TYPE}/{name}"
    )


class RunStoreDeployment(NamedTuple):
    """The deployment the composition deploys the run store as, and what a deploy reads back.

    Attributes:
        name: The deployment's name in the resource group.
        account_output: Its output naming the run store's account.
        container_output: Its output naming the run store's container.
        identities_output: Its output listing each schema identity (``prefix``, ``id``, ``name``).
        location_parameter: Its parameter naming the region the groups are created in.
        subnet_parameter: Its parameter naming the schema-run subnet.
        registry_parameter: Its parameter naming the registry the images are imported into.
        registry_server_output: Its output naming that registry's login server.
    """

    name: str
    account_output: str
    container_output: str
    identities_output: str
    location_parameter: str
    subnet_parameter: str
    registry_parameter: str
    registry_server_output: str


class RunGroupBlock(NamedTuple):
    """One block whose read runs in a container group: generation facts.

    Attributes:
        client: The block's client: its run-store prefix, image and command.
        environment: The client's connection values known at generation and its verified TLS.
        user_variable: The variable naming the login the client connects as.
        login: The block's owner login the client connects as: on a flexible server, the
            role created as the block's schema identity's principal; on an external server,
            the block's owner login the operator provisioned.
        reads_owner_secret: Whether the client's credential fetch reads the block's owner
            secret from Key Vault (a block on an external server): the run then names the
            secret's URL in :data:`SCHEMA_OWNER_SECRET_VARIABLE`.
        reads_server_ca: Whether the client reads the CA certificate its block's server is
            verified against from Key Vault (a block on an external server that trusts the CA its
            operator supplies): the run then names the secret's URL in
            :data:`SCHEMA_SERVER_CA_VARIABLE`.
    """

    client: RunGroupClient
    environment: tuple[tuple[str, str], ...]
    user_variable: str
    login: str
    reads_owner_secret: bool
    reads_server_ca: bool


def _store_properties(
    az: Az,
    store: RunStoreDeployment,
    resource_group: str,
    failure: Callable[[str], Exception],
) -> Mapping[str, object]:
    """The run store's deployment as ARM keeps it: its parameters and its outputs."""
    result = az(
        (
            "deployment",
            "group",
            "show",
            "--resource-group",
            resource_group,
            "--name",
            store.name,
            "--query",
            "properties",
            "-o",
            "json",
            "--only-show-errors",
        )
    )
    if result.exit_status != 0:
        raise failure(
            f"The run store's deployment '{store.name}' of resource group '{resource_group}' could "
            "not be read; run 'deploy' first, which declares the run store every read goes "
            f"through. az reported: {result.stderr or result.stdout or 'no output'}"
        )
    properties = _parsed(
        result, f"Reading the run store's deployment '{store.name}'", failure
    )
    if not isinstance(properties, Mapping):
        raise failure(
            f"The run store's deployment '{store.name}' printed {result.stdout[:200]!r}, not a "
            "deployment's properties."
        )
    return properties


def _store_value(
    properties: Mapping[str, object],
    store: RunStoreDeployment,
    section: str,
    name: str,
    failure: Callable[[str], Exception],
) -> object:
    """The value of the parameter or output *name* (*section*) of the run store's deployment."""
    entry = _mapping(_mapping(properties.get(section)).get(name))
    if "value" not in entry:
        raise failure(
            f"The run store's deployment '{store.name}' has no {section} entry '{name}': it was "
            "deployed by another generation. Run 'deploy' again."
        )
    return entry["value"]


def _store_text(
    properties: Mapping[str, object],
    store: RunStoreDeployment,
    section: str,
    name: str,
    failure: Callable[[str], Exception],
) -> str:
    """The text value of *name* (*section*) of the run store's deployment."""
    value = _store_value(properties, store, section, name, failure)
    if not isinstance(value, str) or not value:
        raise failure(
            f"The run store's deployment '{store.name}' holds {value!r} as its {section} entry "
            f"'{name}', not a name. Run 'deploy' again."
        )
    return value


def _schema_identity(
    properties: Mapping[str, object],
    store: RunStoreDeployment,
    prefix: str,
    failure: Callable[[str], Exception],
) -> Mapping[str, object]:
    """The entry of the schema identity whose run-store prefix is *prefix*: its ``id`` is the
    identity's resource id."""
    listed = _store_value(
        properties, store, "outputs", store.identities_output, failure
    )
    matches = [
        _mapping(entry)
        for entry in _list(listed)
        if _mapping(entry).get("prefix") == prefix
    ]
    identity = matches[0] if len(matches) == 1 else {}
    identity_id = identity.get("id")
    if not (isinstance(identity_id, str) and identity_id):
        raise failure(
            f"The run store's deployment '{store.name}' lists {len(matches)} schema identities "
            f"for the run-store prefix '{prefix}', where exactly one with an id is expected. "
            "Run 'deploy' again."
        )
    return identity


def _secret_uri_environment(
    identity: Mapping[str, object],
    block: RunGroupBlock,
    store: RunStoreDeployment,
    failure: Callable[[str], Exception],
    *,
    field: str,
    variable: str,
    reads: bool,
    what: str,
) -> tuple[tuple[str, str], ...]:
    """The client's variable naming the URL of one secret of its block, for a block whose client
    reads it (*reads*); nothing otherwise.

    The URL is the identity's *field*, which the run store's deployment names exactly for an
    identity granted that one secret: *what* it is, for the messages.

    Raises:
        Exception: *failure*'s, when the entry names no secret URL for a block that reads one,
            names one for a block that reads none, or names something other than a Key Vault
            secret's HTTPS URL.
    """
    url = identity.get(field)
    prefix = block.client.run_store_prefix
    if not reads:
        if url is not None:
            raise failure(
                f"The run store's deployment '{store.name}' grants the schema identity of "
                f"'{prefix}' {what} ({field}), but this script's run of that block reads none: "
                "they were generated apart. Generate again and run 'deploy'."
            )
        return ()
    if not (isinstance(url, str) and _SECRET_URL.fullmatch(url)):
        raise failure(
            f"The run store's deployment '{store.name}' names {url!r} as {what} of the schema "
            f"identity of '{prefix}', where the HTTPS URL of a Key Vault secret is expected "
            f"({field}). Run 'deploy' again."
        )
    return ((variable, url),)


def _schema_secret_environment(
    identity: Mapping[str, object],
    block: RunGroupBlock,
    store: RunStoreDeployment,
    failure: Callable[[str], Exception],
) -> tuple[tuple[str, str], ...]:
    """The client's variables naming the URLs of the secrets its block's client reads: the owner
    secret (``RunGroupBlock.reads_owner_secret``) and the server CA certificate
    (``RunGroupBlock.reads_server_ca``), each only for a block whose client reads it."""
    return (
        *_secret_uri_environment(
            identity,
            block,
            store,
            failure,
            field=SCHEMA_IDENTITY_OWNER_SECRET_FIELD,
            variable=SCHEMA_OWNER_SECRET_VARIABLE,
            reads=block.reads_owner_secret,
            what="an owner secret",
        ),
        *_secret_uri_environment(
            identity,
            block,
            store,
            failure,
            field=SCHEMA_IDENTITY_SERVER_CA_FIELD,
            variable=SCHEMA_SERVER_CA_VARIABLE,
            reads=block.reads_server_ca,
            what="a server CA certificate",
        ),
    )


class RunStorePlace(NamedTuple):
    """Where every run of one deploy command goes, read back once from Azure.

    Attributes:
        subscription_id: The signed-in subscription, holding the resource group.
        resource_group: The resource group the groups are created in.
        location: The groups' region.
        subnet_id: The container-instance subnet's resource id.
        storage_account: The run store's account name.
        storage_container: The run store's container name.
        registry_name: The name of the registry the groups' images are imported into.
        registry_server: That registry's login server, which the groups pull from.
        app_tag: This application's value of :data:`RUN_GROUP_TAG`.
        properties: The run store's deployment as ARM keeps it, which names each block's schema
            identity.
    """

    subscription_id: str
    resource_group: str
    location: str
    subnet_id: str
    storage_account: str
    storage_container: str
    registry_name: str
    registry_server: str
    app_tag: str
    properties: Mapping[str, object]


def read_run_store_place(
    store: RunStoreDeployment,
    *,
    resource_group: str,
    app_tag: str,
    az: Az,
    failure: Callable[[str], Exception],
) -> RunStorePlace:
    """Where the runs go, read from Azure: the signed-in subscription, and the region, subnet,
    store and registry the run store's deployment names.

    Raises:
        Exception: *failure*'s, when the subscription or the deployment cannot be read, or the
            deployment lacks what a run needs.
    """
    subscription = az(
        ("account", "show", "--query", "id", "-o", "tsv", "--only-show-errors")
    )
    subscription_id = subscription.stdout.strip()
    if subscription.exit_status != 0 or not subscription_id:
        raise failure(
            "The signed-in subscription could not be read; run 'az login'. az reported: "
            f"{subscription.stderr or 'no output'}"
        )
    properties = _store_properties(az, store, resource_group, failure)
    return RunStorePlace(
        subscription_id=subscription_id,
        resource_group=resource_group,
        location=_store_text(
            properties, store, "parameters", store.location_parameter, failure
        ),
        subnet_id=_store_text(
            properties, store, "parameters", store.subnet_parameter, failure
        ),
        storage_account=_store_text(
            properties, store, "outputs", store.account_output, failure
        ),
        storage_container=_store_text(
            properties, store, "outputs", store.container_output, failure
        ),
        registry_name=_store_text(
            properties, store, "parameters", store.registry_parameter, failure
        ),
        registry_server=_store_text(
            properties, store, "outputs", store.registry_server_output, failure
        ),
        app_tag=app_tag,
        properties=properties,
    )


def run_group_place(
    block: RunGroupBlock,
    place: RunStorePlace,
    *,
    store: RunStoreDeployment,
    failure: Callable[[str], Exception],
) -> RunGroupPlace:
    """Where *block*'s run's group is created and what it reaches: *place*, and the schema
    identity the run store's deployment names for the block. The client presents that identity
    and connects as the block's login; a block on an external server also reads the URL of its
    owner secret, and the CA certificate its server is verified against when the block trusts
    one, from the identity's entry (:func:`_schema_secret_environment`).

    Raises:
        Exception: *failure*'s, when the deployment names no single schema identity for the
            block, or names its owner secret otherwise than the block reads it.
    """
    identity = _schema_identity(
        place.properties, store, block.client.run_store_prefix, failure
    )
    return RunGroupPlace(
        subscription_id=place.subscription_id,
        resource_group=place.resource_group,
        location=place.location,
        subnet_id=place.subnet_id,
        storage_account=place.storage_account,
        storage_container=place.storage_container,
        registry_name=place.registry_name,
        registry_server=place.registry_server,
        app_tag=place.app_tag,
        identity_id=str(identity["id"]),
        client_environment=(
            *block.environment,
            (block.user_variable, block.login),
            *_schema_secret_environment(identity, block, store, failure),
        ),
    )


def _api_url(resource_id: str) -> str:
    return f"{resource_id}?api-version={RUN_GROUP_API_VERSION}"


def registry_image(place: RunGroupPlace, image: RunGroupImage) -> str:
    """*image* as the run's group pulls it: from *place*'s registry, by its digest."""
    return f"{place.registry_server}/{image.repository}@{image.digest}"


def _container(
    name: str,
    image: str,
    command: Sequence[str],
    environment: Sequence[tuple[str, str]],
    mount_path: str,
) -> dict[str, object]:
    return {
        "name": name,
        "properties": {
            "image": image,
            "command": list(command),
            "environmentVariables": [
                {"name": key, "value": value} for key, value in environment
            ],
            "volumeMounts": [{"name": RUN_GROUP_VOLUME, "mountPath": mount_path}],
            "resources": {
                "requests": {"cpu": RUN_GROUP_CPU, "memoryInGB": RUN_GROUP_MEMORY_GB}
            },
        },
    }


def run_group_spec(
    run: RunFiles,
    workload: RunGroupWorkload,
    client: RunGroupClient,
    place: RunGroupPlace,
) -> dict[str, object]:
    """The ARM definition of the container group carrying out *run*.

    Copy-in, the client and copy-out are the group's main containers, each with its own
    resource request, since every one of them signs in as the group's identity and ACI serves
    it to main containers only. Their scripts order them on the volume: the client waits for
    copy-in's marker and copy-out for the client's, and the client's script exits 0 whatever
    the client did, so copy-out brings back what it left. Every value is a name, the run id, a
    client argument or a connection value; the client's environment also names the schema
    identity's resource id, which its credential fetch asks the identity endpoint for a token
    of. Every image is pulled by digest from *place*'s registry as that same identity
    (:func:`registry_image`).
    """
    copy_environment = (
        (RUN_ID_VARIABLE, run.run_id),
        (RUN_STORE_ACCOUNT_VARIABLE, place.storage_account),
        (RUN_STORE_CONTAINER_VARIABLE, place.storage_container),
        (RUN_STORE_PREFIX_VARIABLE, client.run_store_prefix),
        (SCHEMA_IDENTITY_VARIABLE, place.identity_id),
    )
    copy_image = registry_image(place, workload.copy_image)
    return {
        "location": place.location,
        "tags": {RUN_GROUP_TAG: place.app_tag, RUN_GROUP_RUN_TAG: run.run_id},
        "identity": {
            "type": "UserAssigned",
            "userAssignedIdentities": {place.identity_id: {}},
        },
        "properties": {
            "osType": "Linux",
            "restartPolicy": "Never",
            "subnetIds": [{"id": place.subnet_id}],
            "imageRegistryCredentials": [
                {"server": place.registry_server, "identity": place.identity_id}
            ],
            "volumes": [{"name": RUN_GROUP_VOLUME, "emptyDir": {}}],
            "containers": [
                _container(
                    RUN_GROUP_COPY_IN_CONTAINER,
                    copy_image,
                    (workload.shell, "-c", workload.copy_in_script),
                    copy_environment,
                    workload.mount_path,
                ),
                _container(
                    RUN_GROUP_CLIENT_CONTAINER,
                    registry_image(place, client.image),
                    (workload.shell, "-c", *client.command, *run.client_arguments),
                    (
                        (RUN_ID_VARIABLE, run.run_id),
                        (SCHEMA_IDENTITY_VARIABLE, place.identity_id),
                        *place.client_environment,
                    ),
                    workload.mount_path,
                ),
                _container(
                    RUN_GROUP_COPY_OUT_CONTAINER,
                    copy_image,
                    (workload.shell, "-c", workload.copy_out_script),
                    copy_environment,
                    workload.mount_path,
                ),
            ],
        },
    }


def _mapping(value: object) -> Mapping[str, object]:
    """*value* when it is a JSON object, else an empty one: ARM omits what it has not set."""
    return value if isinstance(value, Mapping) else {}


def _list(value: object) -> list[object]:
    """*value* when it is a JSON array, else an empty one: ARM omits what it has not set."""
    return value if isinstance(value, list) else []


def _parsed(result: AzRun, what: str, failure: Callable[[str], Exception]) -> object:
    """*result*'s JSON output, or the host's error naming *what* failed."""
    if result.exit_status != 0:
        raise failure(
            f"{what} failed (az exited {result.exit_status}): {result.stderr or 'no output'}"
        )
    try:
        return json.loads(result.stdout or "null")
    except json.JSONDecodeError as error:
        raise failure(
            f"{what} returned output that is not JSON ({error}): {result.stdout[:200]!r}"
        ) from error


def run_group_state(group: object) -> str | None:
    """The terminal state of the container group *group* (ARM's JSON), or ``None`` while it runs.

    A group Azure could not provision is terminal as ``Failed``.
    """
    properties = _mapping(_mapping(group).get("properties"))
    if properties.get("provisioningState") == RUN_GROUP_FAILED_PROVISIONING:
        return RUN_GROUP_FAILED_PROVISIONING
    state = _mapping(properties.get("instanceView")).get("state")
    return (
        state if isinstance(state, str) and state in RUN_GROUP_TERMINAL_STATES else None
    )


def _container_exit(container: object) -> tuple[str, object]:
    """One container's name and its exit code, or its state when it has none."""
    current = _mapping(
        _mapping(
            _mapping(_mapping(container).get("properties")).get("instanceView")
        ).get("currentState")
    )
    return str(_mapping(container).get("name")), current.get(
        "exitCode", current.get("state")
    )


def container_exits(group: object) -> dict[str, object]:
    """Each container of *group* (init containers too) by name, with its exit code or state."""
    properties = _mapping(_mapping(group).get("properties"))
    return dict(
        _container_exit(container)
        for key in ("initContainers", "containers")
        for container in _list(properties.get(key))
    )


#: The fields of a container's current or previous state the deploy reports, in this order.
_REPORTED_STATE_FIELDS: tuple[str, ...] = (
    "state",
    "detailStatus",
    "exitCode",
    "startTime",
    "finishTime",
)


def _shown(value: object) -> str:
    """*value* as the deploy prints it, ``none`` when ARM has not set it."""
    return "none" if value is None or value == "" else str(value)


def _describe_state(state: object) -> str:
    """One container state (``currentState`` / ``previousState``) as ``field value, ...``."""
    fields = _mapping(state)
    reported = [
        f"{field} {fields[field]}"
        for field in _REPORTED_STATE_FIELDS
        if _shown(fields.get(field)) != "none"
    ]
    return ", ".join(reported) or "none"


def _describe_event(event: object) -> str:
    """One ARM event as ``<type> <name> x<count> at <last time>: <message>``."""
    fields = _mapping(event)
    return (
        f"{_shown(fields.get('type'))} {_shown(fields.get('name'))} x{_shown(fields.get('count'))} "
        f"at {_shown(fields.get('lastTimestamp'))}: {_shown(fields.get('message'))}"
    )


def _describe_events(events: object) -> str:
    return "; ".join(_describe_event(event) for event in _list(events)) or "none"


def _describe_container(container: object) -> str:
    """One container's current and previous state, restart count and events."""
    view = _mapping(_mapping(_mapping(container).get("properties")).get("instanceView"))
    return (
        f"{_shown(_mapping(container).get('name'))}: current {_describe_state(view.get('currentState'))}; "
        f"previous {_describe_state(view.get('previousState'))}; restarts {_shown(view.get('restartCount'))}; "
        f"events {_describe_events(view.get('events'))}"
    )


def describe_run_group(group: object) -> str:
    """The instance view of the container group *group* (ARM's JSON), as the deploy reports it
    before it deletes a group whose run failed.

    ACI keeps nothing of a deleted group, so this is the only record of why its run did not
    end: the group's provisioning and instance state and its events, and for each container
    (init containers first) its current and previous state, restart count and events, where
    ACI says why an image was not pulled or a container was restarted. It names no environment
    variable and no command: only states and ACI's own messages.
    """
    properties = _mapping(_mapping(group).get("properties"))
    view = _mapping(properties.get("instanceView"))
    containers = [
        f"\n  {_describe_container(container)}"
        for key in ("initContainers", "containers")
        for container in _list(properties.get(key))
    ]
    return (
        f"provisioning {_shown(properties.get('provisioningState'))}, instance {_shown(view.get('state'))}; "
        f"group events {_describe_events(view.get('events'))}; containers:{''.join(containers) or ' none'}"
    )


def _container_names(group: object) -> list[str]:
    """The names of *group*'s containers, init containers first, as ARM lists them."""
    properties = _mapping(_mapping(group).get("properties"))
    return [
        str(_mapping(container).get("name"))
        for key in ("initContainers", "containers")
        for container in _list(properties.get(key))
    ]


def _container_log(az: Az, resource_id: str, container: str) -> str:
    """The last :data:`RUN_GROUP_LOG_TAIL_LINES` lines of *container*'s log, each on a line of
    its own, or why there are none: a log that cannot be read is reported, never raised, so it
    never hides the failure it would explain."""
    result = az(
        (
            "rest",
            "--method",
            "get",
            "--url",
            _api_url(f"{resource_id}/containers/{container}/logs"),
            "--uri-parameters",
            f"tail={RUN_GROUP_LOG_TAIL_LINES}",
            "-o",
            "json",
        )
    )
    if result.exit_status != 0:
        return f" not read (az exited {result.exit_status}): {result.stderr or 'no output'}"
    try:
        content = _mapping(json.loads(result.stdout or "null")).get("content")
    except json.JSONDecodeError:
        return f" not read: az printed {result.stdout[:200]!r}, not JSON"
    lines = content.strip().splitlines() if isinstance(content, str) else []
    return (
        "".join(f"\n    {_LOG_CONTROL_CHARACTER.sub('?', line)}" for line in lines)
        or " empty"
    )


def run_group_logs(az: Az, resource_id: str, group: object) -> str:
    """Each container's log of the group *resource_id* (*group* is its JSON as last read), as
    the deploy reports it, after :func:`describe_run_group`, before it deletes a group whose run
    failed.

    The instance view says *that* a container failed; why a container that started and exited
    non-zero failed is in its own output, which ACI serves only while the group exists. Each
    container's scripts are the generator's: the copy containers print only ``az``'s errors
    (``--only-show-errors -o none``), and the client's output and error are the run's ``out``
    and ``err`` files, so its log holds only what its shell printed. No script echoes its
    environment or traces its commands.
    """
    logs = [
        f"\n  {name}:{_container_log(az, resource_id, name)}"
        for name in _container_names(group)
    ]
    return f"Container logs (last {RUN_GROUP_LOG_TAIL_LINES} lines each):{''.join(logs) or ' none, the group has no container'}"


def finished_tagged_groups(resources: object, app_tag: str) -> list[str]:
    """The ids of the container groups in *resources* (``az resource list``'s JSON) tagged
    :data:`RUN_GROUP_TAG` = *app_tag*: the candidates of the sweep, whose state is read next."""
    return [
        str(_mapping(resource).get("id"))
        for resource in _list(resources)
        if str(_mapping(resource).get("type", "")).lower()
        == RUN_GROUP_RESOURCE_TYPE.lower()
        and _mapping(_mapping(resource).get("tags")).get(RUN_GROUP_TAG) == app_tag
    ]


def _show_group(
    az: Az, resource_id: str, failure: Callable[[str], Exception]
) -> object:
    return _parsed(
        az(("rest", "--method", "get", "--url", _api_url(resource_id), "-o", "json")),
        f"Reading the container group '{resource_id}'",
        failure,
    )


def _delete_group(az: Az, resource_id: str) -> AzRun:
    return az(_delete_group_arguments(resource_id))


def _delete_group_arguments(resource_id: str) -> tuple[str, ...]:
    return ("rest", "--method", "delete", "--url", _api_url(resource_id), "-o", "none")


def _read_run_group(
    az: Az, resource_id: str, failure: Callable[[str], Exception], retry: RunRetry
) -> object:
    """The run's group *resource_id* as ARM answers it, a transient failure sent again."""
    result, attempt = _az_retried(
        az,
        ("rest", "--method", "get", "--url", _api_url(resource_id), "-o", "json"),
        retry,
    )
    return _parsed(
        result,
        f"Reading the container group '{resource_id}'{_attempts(attempt)}",
        failure,
    )


def _delete_run_group(az: Az, resource_id: str, retry: RunRetry) -> AzRun:
    """Delete the run's group *resource_id*, a transient failure sent again."""
    result, _attempt = _az_retried(az, _delete_group_arguments(resource_id), retry)
    return result


def _run_group_exists(
    az: Az,
    resource_id: str,
    block: str,
    failure: Callable[[str], Exception],
    retry: RunRetry,
) -> bool:
    """Whether the run's group *resource_id* exists: after a create whose answer was lost, ARM
    may have made it anyway.

    Raises:
        Exception: *failure*'s, when the read fails for any other reason than the group's
            absence, so the deploy never guesses and never creates a second group.
    """
    read = ("rest", "--method", "get", "--url", _api_url(resource_id), "-o", "json")
    result, attempt = _az_retried(az, read, retry)
    if result.exit_status == 0:
        return True
    if RUN_GROUP_ABSENT_CODE in _az_output(result):
        return False
    raise failure(
        f"Reading the container group '{resource_id}' of block '{block}', to tell whether a create "
        f"that failed made it, failed{_attempts(attempt)} (az exited {result.exit_status}): "
        f"{result.stderr or 'no output'}"
    )


def sweep_finished_run_groups(
    place: RunStorePlace, *, az: Az, failure: Callable[[str], Exception]
) -> list[str]:
    """Delete every finished container group tagged for this application; the ids deleted.

    A tagged group still running is another deploy's run: it is kept, and ends by itself.
    The resource group's container groups are listed by type and the tag is matched by
    :func:`finished_tagged_groups`: ``az resource list`` refuses ``--tag`` together with
    ``--resource-group``, and ``--tag`` alone would list the whole subscription.

    Raises:
        Exception: *failure*'s, when the groups cannot be listed or read, or a finished one
            cannot be deleted.
    """
    listed = _parsed(
        az(
            (
                "resource",
                "list",
                "--resource-group",
                place.resource_group,
                "--resource-type",
                RUN_GROUP_RESOURCE_TYPE,
                "-o",
                "json",
            )
        ),
        f"Listing the schema run container groups of resource group '{place.resource_group}'",
        failure,
    )
    deleted: list[str] = []
    for resource_id in finished_tagged_groups(listed, place.app_tag):
        if run_group_state(_show_group(az, resource_id, failure)) is None:
            continue
        result = _delete_group(az, resource_id)
        if result.exit_status != 0:
            raise failure(
                f"The finished schema run container group '{resource_id}' could not be "
                f"deleted (az exited {result.exit_status}): {result.stderr or 'no output'}"
            )
        deleted.append(resource_id)
    return deleted


def _usages(
    place: RunStorePlace, az: Az, failure: Callable[[str], Exception]
) -> dict[str, tuple[float, float]]:
    """The Container Instances usages of *place*'s region: each usage's name, lower-cased, with
    its current value and its limit."""
    url = (
        f"/subscriptions/{place.subscription_id}/providers/Microsoft.ContainerInstance/locations/"
        f"{place.location}/usages?api-version={RUN_GROUP_API_VERSION}"
    )
    listed = _parsed(
        az(("rest", "--method", "get", "--url", url, "-o", "json")),
        f"Reading the Container Instances quota of region '{place.location}'",
        failure,
    )
    usages: dict[str, tuple[float, float]] = {}
    for entry in _list(_mapping(listed).get("value")):
        fields = _mapping(entry)
        name = _mapping(fields.get("name")).get("value")
        current, limit = fields.get("currentValue"), fields.get("limit")
        if (
            isinstance(name, str)
            and isinstance(current, (int, float))
            and isinstance(limit, (int, float))
        ):
            usages[name.lower()] = (float(current), float(limit))
    return usages


def run_group_concurrency(
    place: RunStorePlace, *, az: Az, failure: Callable[[str], Exception]
) -> int:
    """How many runs a deploy carries in container groups at once: :data:`RUN_GROUP_MAX_CONCURRENT_RUNS`,
    or as many as the region's Container Instances quota leaves room for when that is fewer.

    Each run's group takes one of the region's groups and :data:`RUN_GROUP_CORES` of its standard
    cores; the room is what the limits leave beside what is in use now.

    Raises:
        Exception: *failure*'s, when the quota cannot be read, lists no usage of
            :data:`RUN_GROUP_GROUPS_USAGE` or :data:`RUN_GROUP_CORES_USAGE`, or leaves room for no
            group.
    """
    usages = _usages(place, az, failure)
    missing = [
        name
        for name in (RUN_GROUP_GROUPS_USAGE, RUN_GROUP_CORES_USAGE)
        if name.lower() not in usages
    ]
    if missing:
        raise failure(
            f"The Container Instances quota of region '{place.location}' lists no usage {missing}, "
            "so how many schema runs fit in it is not known. az's answer may come from another API "
            f"version than {RUN_GROUP_API_VERSION}; update the Azure CLI and deploy again."
        )
    groups_used, groups_limit = usages[RUN_GROUP_GROUPS_USAGE.lower()]
    cores_used, cores_limit = usages[RUN_GROUP_CORES_USAGE.lower()]
    room = min(
        int(groups_limit - groups_used),
        int((cores_limit - cores_used) // RUN_GROUP_CORES),
    )
    if room < 1:
        raise failure(
            f"The Container Instances quota of subscription '{place.subscription_id}' in region "
            f"'{place.location}' leaves room for no schema run: {groups_used:g} of {groups_limit:g} "
            f"container groups and {cores_used:g} of {cores_limit:g} standard cores are in use, and "
            f"each run takes one group and {RUN_GROUP_CORES:g} cores. Wait for the running groups "
            "to end or raise the quota, then deploy again."
        )
    return min(RUN_GROUP_MAX_CONCURRENT_RUNS, room)


class RunStoreSession:
    """The run store as one deploy command reaches it: read back and swept once, for every run.

    The first call that needs the place, from any thread, reads it (:func:`read_run_store_place`)
    and deletes every finished group tagged for this application (:func:`sweep_finished_run_groups`)
    before any run of the command creates its group, so no run's group is ever swept by another
    run of the same command. A failed read is read again by the next call.
    """

    def __init__(
        self,
        store: RunStoreDeployment,
        *,
        resource_group: str,
        app_tag: str,
        az: Az,
        failure: Callable[[str], Exception],
    ) -> None:
        self._store = store
        self._resource_group = resource_group
        self._app_tag = app_tag
        self._az = az
        self._failure = failure
        self._lock = threading.Lock()
        self._place: RunStorePlace | None = None

    def place(self) -> RunStorePlace:
        """Where the command's runs go, read and swept on the first call."""
        with self._lock:
            if self._place is None:
                place = read_run_store_place(
                    self._store,
                    resource_group=self._resource_group,
                    app_tag=self._app_tag,
                    az=self._az,
                    failure=self._failure,
                )
                sweep_finished_run_groups(place, az=self._az, failure=self._failure)
                self._place = place
            return self._place

    def block_place(self, block: RunGroupBlock) -> RunGroupPlace:
        """Where *block*'s run's group goes (:func:`run_group_place`)."""
        return run_group_place(
            block, self.place(), store=self._store, failure=self._failure
        )

    def concurrent_runs(self) -> int:
        """How many runs the command carries at once (:func:`run_group_concurrency`)."""
        return run_group_concurrency(self.place(), az=self._az, failure=self._failure)

    def registry(self) -> tuple[str, str]:
        """The registry the command's runs import their images into: its name and resource group."""
        place = self.place()
        return place.registry_name, place.resource_group


def _blob_arguments(place: RunGroupPlace, *arguments: str) -> tuple[str, ...]:
    return (
        "storage",
        "blob",
        *arguments,
        "--auth-mode",
        "login",
        "--account-name",
        place.storage_account,
        "--container-name",
        place.storage_container,
        "--only-show-errors",
    )


def _copy_file(
    az: Az,
    arguments: tuple[str, ...],
    what: str,
    failure: Callable[[str], Exception],
    retry: RunRetry,
) -> None:
    """Upload or download one run file, a transient failure sent again.

    An upload refuses to overwrite (``--overwrite false``); when a re-sent upload is refused
    because the blob exists, the earlier attempt's upload landed and only its answer was lost
    (the run's prefix is its own, and a blob is committed whole or not at all).
    """
    result, attempt = _az_retried(az, (*arguments, "-o", "none"), retry)
    if result.exit_status == 0:
        return
    if attempt > 1 and BLOB_ALREADY_EXISTS in _az_output(result):
        return
    raise failure(
        f"{what} failed{_attempts(attempt)} (az exited {result.exit_status}): {result.stderr or 'no output'}"
    )


def _blob_names(listed: AzRun) -> list[str]:
    """The blob names ``az storage blob list --query [].name`` printed.

    Raises:
        ValueError: The listing failed or printed no JSON.
        TypeError: The listing printed JSON that is not an array.
    """
    if listed.exit_status != 0:
        raise ValueError(listed.stderr or "az printed no error")
    names = json.loads(listed.stdout or "null")
    if not isinstance(names, list):
        raise TypeError(f"az printed {listed.stdout[:200]!r}, not a list of blob names")
    return [str(name) for name in names]


def delete_run_files(az: Az, place: RunGroupPlace, prefix: str) -> list[str]:
    """Delete every blob under the run's *prefix*; what is left, listed again afterwards.

    Returns:
        The blobs still there, or ``[prefix]`` when the prefix cannot be listed.
    """
    listing = (
        *_blob_arguments(place, "list", "--prefix", prefix),
        "--query",
        "[].name",
        "-o",
        "json",
    )
    try:
        for name in _blob_names(az(listing)):
            az((*_blob_arguments(place, "delete", "--name", name), "-o", "none"))
        return _blob_names(az(listing))
    except (ValueError, TypeError):
        return [prefix]


def _await_group(
    az: Az,
    resource_id: str,
    failure: Callable[[str], Exception],
    timing: tuple[Callable[[], float], Callable[[float], None], float],
    retry: RunRetry,
) -> object:
    """The group's JSON once it is terminal, or as last read when the wait expired first
    (:func:`run_group_state` tells the two apart). A read that fails transiently is sent again
    (:func:`_read_run_group`) before it ends the wait."""
    clock, sleep, wait_seconds = timing
    deadline = clock() + wait_seconds
    while True:
        group = _read_run_group(az, resource_id, failure, retry)
        remaining = deadline - clock()
        if run_group_state(group) is not None or remaining <= 0:
            return group
        sleep(min(RUN_GROUP_POLL_SECONDS, remaining))


def _group_outcome(az: Az, resource_id: str, retry: RunRetry) -> str:
    deleted = _delete_run_group(az, resource_id, retry)
    if deleted.exit_status == 0:
        return "was deleted"
    return (
        f"could not be deleted ({deleted.stderr or 'no output'}): delete it with "
        f"'az rest --method delete --url \"{_api_url(resource_id)}\"'"
    )


def _described_exits(group: object) -> str:
    """Each of *group*'s containers with its exit code or state, for a message."""
    exits = container_exits(group)
    return (
        "; ".join(f"{name} {state}" for name, state in sorted(exits.items()))
        or "no containers"
    )


def _require_copied_out(
    az: Az,
    group: object,
    resource_id: str,
    block: str,
    failure: Callable[[str], Exception],
) -> None:
    if container_exits(group).get(RUN_GROUP_COPY_OUT_CONTAINER) == 0:
        return
    raise failure(
        f"The container group '{resource_id}' of block '{block}' did not bring the client's "
        f"files back: it ended {run_group_state(group)} ({_described_exits(group)}). "
        f"Last seen: {describe_run_group(group)}\n"
        f"{run_group_logs(az, resource_id, group)}"
    )


def _client_never_started(group: object) -> bool:
    """Whether *group*'s client script gave up waiting for copy-in: nothing reached the database."""
    return (
        container_exits(group).get(RUN_GROUP_CLIENT_CONTAINER)
        == RUN_GROUP_CLIENT_NOT_STARTED_STATUS
    )


def _start_group(
    run: RunFiles,
    resource_id: str,
    spec_file: Path,
    az: Az,
    failure: Callable[[str], Exception],
    retry: RunRetry,
) -> None:
    """Create the run's group *resource_id* from *spec_file*, passed to ``az rest`` by path.

    A create that fails transiently is sent again, at most :data:`RUN_AZ_ATTEMPTS` times in
    all, but only after the group is read: a create whose answer was lost (a gateway timeout)
    may have made the group, and then that group is the run's and is waited for, never created
    a second time. Any other failure ends the run at once.

    Raises:
        Exception: *failure*'s, when a create fails for a reason that does not settle, every
            attempt failed transiently, or the read before a re-send fails.
    """
    what = f"Creating the container group '{resource_id}' of block '{run.block}'"
    create = (
        "rest",
        "--method",
        "put",
        "--url",
        _api_url(resource_id),
        "--body",
        f"@{spec_file}",
        "-o",
        "json",
    )
    attempt = 1
    while True:
        created = az(create)
        if created.exit_status == 0:
            _parsed(created, what, failure)
            # One write per line: several runs print side by side.
            sys.stderr.write(
                f"Started container group {resource_id} for block '{run.block}'{_attempts(attempt)}.\n"
            )
            return
        if attempt >= RUN_AZ_ATTEMPTS or not retry.transient(_az_output(created)):
            raise failure(
                f"{what} failed{_attempts(attempt)} (az exited {created.exit_status}): {created.stderr or 'no output'}"
            )
        settle = RUN_AZ_RETRY_SECONDS * attempt
        sys.stderr.write(
            f"{what} failed on attempt {attempt} of {RUN_AZ_ATTEMPTS} with a fault that settles with "
            f"time; reading the group in {settle:g} seconds before sending it again.\n"
        )
        retry.sleep(settle)
        if _run_group_exists(az, resource_id, run.block, failure, retry):
            sys.stderr.write(
                f"Container group {resource_id} for block '{run.block}' exists: the create whose "
                "answer was lost made it, so the run waits for that group.\n"
            )
            return
        attempt += 1


def _collect(
    run: RunFiles,
    resource_id: str,
    location: tuple[RunGroupPlace, str],
    az: Az,
    failure: Callable[[str], Exception],
    timing: tuple[Callable[[], float], Callable[[float], None], float],
    retry: RunRetry,
    groups_left: int,
) -> bool:
    """Wait for the run's group to end and download what its client left from *location* (the run
    store and the run's prefix in it). ``False`` instead when the group's client never started and
    *groups_left* more groups may be created: what the group's containers said is written out,
    since ACI keeps nothing of a deleted group."""
    place, prefix = location
    group = _await_group(az, resource_id, failure, timing, retry)
    if run_group_state(group) is None:
        raise failure(
            f"The container group '{resource_id}' of block '{run.block}' was still running "
            f"after {timing[2]:g} seconds, the longest a run may take. Last seen: {describe_run_group(group)}\n"
            f"{run_group_logs(az, resource_id, group)}"
        )
    if groups_left > 0 and _client_never_started(group):
        sys.stderr.write(
            f"The client of block '{run.block}' never started in the container group '{resource_id}', "
            f"which ended {run_group_state(group)} ({_described_exits(group)}). Nothing reached the "
            f"database, so the run goes on in a new group. Last seen: {describe_run_group(group)}\n"
            f"{run_group_logs(az, resource_id, group)}\n"
        )
        return False
    _require_copied_out(az, group, resource_id, run.block, failure)
    for path in (run.output_file, run.error_file, run.exit_file):
        _copy_file(
            az,
            _blob_arguments(
                place, "download", "--name", f"{prefix}{path.name}", "--file", str(path)
            ),
            f"Downloading '{path.name}' of the run of block '{run.block}'",
            failure,
            retry,
        )
    return True


def _carry_out(
    run: RunFiles,
    verb: str,
    facts: tuple[RunGroupWorkload, RunGroupClient, RunGroupPlace],
    az: Az,
    failure: Callable[[str], Exception],
    timing: tuple[Callable[[], float], Callable[[float], None], float],
    retry: RunRetry,
) -> None:
    """Upload the run's files, create its group (named for *verb*), wait for it, download what
    it left and delete the group, whatever happened once it was created. A group whose client
    never started is followed by a new one under a name of its own, at most
    :data:`RUN_GROUP_ATTEMPTS` in all: the run's files stay in the run store until the run ends."""
    workload, client, place = facts
    prefix = f"{client.run_store_prefix}{run.run_id}/"
    for path in (run.input_file, run.directory / workload.ca_bundle_file):
        _copy_file(
            az,
            _blob_arguments(
                place,
                "upload",
                "--name",
                f"{prefix}{path.name}",
                "--file",
                str(path),
                "--overwrite",
                "false",
            ),
            f"Uploading '{path.name}' of the {verb} run of block '{run.block}'",
            failure,
            retry,
        )
    spec_file = run.directory / RUN_GROUP_SPEC_FILE
    with spec_file.open("x", encoding="utf-8") as handle:
        json.dump(run_group_spec(run, workload, client, place), handle)
    for attempt in range(1, RUN_GROUP_ATTEMPTS + 1):
        name_id = run.run_id if attempt == 1 else f"{run.run_id}-{attempt}"
        resource_id = run_group_id(place, run_group_name(verb, name_id, failure))
        _start_group(run, resource_id, spec_file, az, failure, retry)
        try:
            collected = _collect(
                run,
                resource_id,
                (place, prefix),
                az,
                failure,
                timing,
                retry,
                RUN_GROUP_ATTEMPTS - attempt,
            )
        except BaseException:
            sys.stderr.write(
                f"The container group '{resource_id}' {_group_outcome(az, resource_id, retry)}.\n"
            )
            raise
        deleted = _delete_run_group(az, resource_id, retry)
        if deleted.exit_status != 0:
            raise failure(
                f"The container group '{resource_id}' of block '{run.block}' could not be deleted "
                f"(az exited {deleted.exit_status}): {deleted.stderr or 'no output'}. The next deploy "
                "deletes it; delete it now to stop paying for it."
            )
        if collected:
            return


def container_group_run(
    run: RunFiles,
    *,
    verb: str,
    workload: RunGroupWorkload,
    client: RunGroupClient,
    place: RunGroupPlace,
    import_images: Callable[[Sequence[RunGroupImage]], None],
    az: Az,
    failure: Callable[[str], Exception],
    fetch_ca_bundle: Callable[[Path], None],
    wait_seconds: float,
    transient: Callable[[str], bool],
    clock: Callable[[], float] = time.monotonic,
    sleep: Callable[[float], None] = time.sleep,
) -> None:
    """Run *run*'s client at most once, in a container group of its own: the platform's channel.

    *verb* is the schema verb the run carries out (``schema-read``, ``schema-apply``); the
    group is named for it and the run's id (:func:`run_group_name`), and so are the run's
    messages. *place* comes from the command's :class:`RunStoreSession`, which swept the finished
    groups of earlier deploys before the command's first run. The group's images are made sure
    of in the registry through *import_images*, the command's ``RunImageImports``
    (``run_image_import_runtime``), which imports each image once per command; then the input
    and the CA bundle
    (*fetch_ca_bundle* writes it into the run's directory) are uploaded, the group is created
    and awaited for at most *wait_seconds* (the generator's ``RUN_GROUP_WAIT_SECONDS``), deleted
    when that wait expires, and ``out``, ``err`` and ``exit`` are downloaded into the run's
    directory. A group whose client never started, which proves nothing reached the database, is
    deleted and followed by a new one, at most :data:`RUN_GROUP_ATTEMPTS` in all, since one bad
    host or one bad answer of the identity endpoint must not throw the whole deploy away.
    Every file of the run is deleted from the run store, whatever happened. Runs of several
    blocks may be carried out side by side, from as many threads: a run touches only its own
    group, its own prefix of the run store and its own directory. A request of the run's path
    that fails in a way *transient* (the host's classifier over az's output) calls a fault that
    settles with time is sent again, at most :data:`RUN_AZ_ATTEMPTS` times, waiting longer each
    time (:func:`_start_group` reads the group first, so a run never creates two).

    Raises:
        Exception: *failure*'s, when any step fails, the group outlives the wait or does not
            bring the client's files back, or the run's files cannot be deleted after a run
            that was carried out.
    """
    import_images((workload.copy_image, client.image))
    fetch_ca_bundle(run.directory / workload.ca_bundle_file)
    carried_out = False
    try:
        _carry_out(
            run,
            verb,
            (workload, client, place),
            az,
            failure,
            (clock, sleep, wait_seconds),
            RunRetry(transient, sleep),
        )
        carried_out = True
    finally:
        left = delete_run_files(az, place, f"{client.run_store_prefix}{run.run_id}/")
        if left:
            message = (
                f"The run store '{place.storage_account}' still holds {left} of the {verb} run of "
                f"block '{run.block}': delete them, they hold the run's input and the client's output."
            )
            if carried_out:
                raise failure(message)
            sys.stderr.write(f"ERROR: {message}\n")


#: Seconds one CA certificate download may take.
CA_CERTIFICATE_FETCH_SECONDS: float = 30.0

#: The exit status of :func:`run_ca_bundle_fetch` when no bundle could be written.
CA_BUNDLE_FAILURE_STATUS: int = 2

_PEM_BEGIN: bytes = b"-----BEGIN CERTIFICATE-----"
_DER_SEQUENCE: bytes = b"\x30"
_HTTPS: str = "https://"


class CaBundleError(Exception):
    """No CA bundle could be written; the message names what to fix."""


def _pem_certificate(certificate: bytes) -> str:
    """*certificate*, PEM or DER as its publisher serves it, as one PEM block.

    Raises:
        ValueError: It is neither a PEM nor a DER X.509 certificate.
    """
    if certificate.lstrip().startswith(_PEM_BEGIN):
        text = certificate.decode("ascii").strip()
        return ssl.DER_cert_to_PEM_cert(ssl.PEM_cert_to_DER_cert(text)).strip()
    if certificate.startswith(_DER_SEQUENCE):
        return ssl.DER_cert_to_PEM_cert(certificate).strip()
    raise ValueError(
        "it starts with neither a PEM certificate header nor a DER sequence"
    )


def ca_bundle_pem(
    certificates: Sequence[bytes], failure: Callable[[str], Exception]
) -> bytes:
    """*certificates*, each PEM or DER as its publisher serves it, as one PEM bundle.

    Raises:
        Exception: *failure*'s, when there is none, or one is neither a PEM nor a DER
            certificate.
    """
    if not certificates:
        raise failure(
            "The CA bundle names no certificate; name at least one root to fetch."
        )
    blocks: list[str] = []
    for index, certificate in enumerate(certificates, start=1):
        try:
            blocks.append(_pem_certificate(certificate))
        except (UnicodeDecodeError, ValueError) as error:
            raise failure(
                f"CA certificate {index} of the bundle is not a certificate ({error}). "
                "Expected a PEM or DER X.509 certificate from its publisher."
            ) from error
    return ("\n".join(blocks) + "\n").encode("ascii")


def fetch_ca_bundle(
    urls: Sequence[str], destination: Path, failure: Callable[[str], Exception]
) -> None:
    """Fetch every root certificate of *urls* over verified HTTPS and write them to *destination*,
    a file that must not exist yet.

    Raises:
        Exception: *failure*'s, when a URL is not HTTPS, a download fails, or what it served
            is not a certificate.
    """
    refused = [url for url in urls if not url.startswith(_HTTPS)]
    if refused:
        raise failure(
            f"The CA certificate URLs {refused} are not HTTPS; a root is fetched over verified HTTPS only."
        )
    context = ssl.create_default_context()
    certificates: list[bytes] = []
    for url in urls:
        try:
            with urllib.request.urlopen(
                url, context=context, timeout=CA_CERTIFICATE_FETCH_SECONDS
            ) as response:
                certificates.append(response.read())
        except OSError as error:
            raise failure(
                f"The CA certificate {url} could not be fetched: {error}"
            ) from error
    bundle = ca_bundle_pem(certificates, failure)
    with destination.open("xb") as handle:
        handle.write(bundle)


def write_ca_bundle(arguments: Sequence[str]) -> None:
    """Fetch the roots named after the bundle's file in *arguments* (``<file> <url>...``) into
    that file, as :func:`fetch_ca_bundle` does.

    Raises:
        CaBundleError: The arguments name no file or no URL, or as :func:`fetch_ca_bundle`.
    """
    if len(arguments) < 2:
        raise CaBundleError(
            f"Expected the bundle's file and at least one root URL, got {list(arguments)}."
        )
    destination, *urls = arguments
    fetch_ca_bundle(urls, Path(destination), CaBundleError)


def run_ca_bundle_fetch() -> None:
    """A bootstrap's entry: :func:`write_ca_bundle` over the program's arguments. A failure is
    printed on standard error and ends the program with :data:`CA_BUNDLE_FAILURE_STATUS`, so a
    script under ``set -e`` stops before it connects."""
    try:
        write_ca_bundle(sys.argv[1:])
    except CaBundleError as error:
        print(f"ERROR: {error}", file=sys.stderr)
        sys.exit(CA_BUNDLE_FAILURE_STATUS)


