                'waited=0; until [ -e /work/.copied-in ]; do if [ -e /work/.abandoned ] || [ "$waited" -ge 600 ]; then : \u003e /work/.abandoned; echo \u0027client did not start: the step before it failed or did not finish within 600 seconds\u0027 \u003e\u00262; exit 75; fi; sleep 1; waited=$((waited + 1)); done; ( umask 077; trap \u0027rm -f /dev/shm/credential\u0027 EXIT; trap \u0027exit 2\u0027 HUP INT TERM; schema_credential=$(attempt=1; until response=$(wget -q -T 30 -O - --header \u0027Metadata: true\u0027 "http://169.254.169.254/metadata/identity/oauth2/token?api-version=2018-02-01\u0026resource=https%3A%2F%2Fossrdbms-aad.database.windows.net\u0026mi_res_id=${SCHEMA_IDENTITY_ID:?}"); do [ "$attempt" -lt 5 ] || exit 1; sleep $((attempt * 10)); attempt=$((attempt + 1)); done \u0026\u0026 printf \u0027%s\\n\u0027 "$response" | sed -n \u0027s/.*"access_token" *: *"\\([^"]*\\)".*/\\1/p\u0027) || { echo \u0027The schema client\u0027"\u0027"\u0027s credential could not be fetched.\u0027 \u003e\u00262; exit 2; }; [ -n "$schema_credential" ] || { echo \u0027The schema client\u0027"\u0027"\u0027s credential is empty: the block\u0027"\u0027"\u0027s owner secret is not set.\u0027 \u003e\u00262; exit 2; }; printf \u0027%s\\n\u0027 "$schema_credential" | sed -e \u0027s/\\\\/\\\\\\\\/g\u0027 -e \u0027s/:/\\\\:/g\u0027 -e \u0027s/^/*:*:*:*:/\u0027 \u003e /dev/shm/credential || { echo \u0027The schema client\u0027"\u0027"\u0027s credential file could not be written.\u0027 \u003e\u00262; exit 2; }; unset schema_credential; [ "$(wc -l \u003c /dev/shm/credential)" -eq 1 ] || { echo \u0027The schema client\u0027"\u0027"\u0027s credential holds a line break, which its file cannot.\u0027 \u003e\u00262; exit 2; }; export PGPASSFILE=/dev/shm/credential; timeout -k 10 600 psql -X -A -t -q -f - "$@" \u003c /work/in ) \u003e /work/out 2\u003e /work/err; echo $? \u003e /work/exit; : \u003e /work/.client-done',
                "sh",
