#: What every run's container group runs beside the block's client.
SCHEMA_RUN_WORKLOAD = RunGroupWorkload(
    copy_image=RunGroupImage(
        source="mcr.microsoft.com/azure-cli@sha256:933eb8dcb81aecb6f77e03c5b8660f0a1dfa9e1d16525763a27f86ff3b83a044",
        repository="schema-run/azure-cli",
        tag="sha256-933eb8dcb81aecb6f77e03c5b8660f0a1dfa9e1d16525763a27f86ff3b83a044",
        digest="sha256:933eb8dcb81aecb6f77e03c5b8660f0a1dfa9e1d16525763a27f86ff3b83a044",
    ),
    shell="sh",
    mount_path="/work",
    copy_in_script='if timeout 300 sh -c \u0027set -eu; case "${RUN_ID:-}" in ""|.*|*[!A-Za-z0-9._-]*) echo "RUN_ID must name the run: letters, digits, \u0027"\u0027"\u0027.\u0027"\u0027"\u0027, \u0027"\u0027"\u0027_\u0027"\u0027"\u0027 and \u0027"\u0027"\u0027-\u0027"\u0027"\u0027, not starting with \u0027"\u0027"\u0027.\u0027"\u0027"\u0027" \u003e\u00262; exit 2;; esac; attempt=1; until az login --identity --resource-id "$SCHEMA_IDENTITY_ID" --allow-no-subscriptions --only-show-errors -o none; do [ "$attempt" -lt 5 ] || exit 1; sleep $((attempt * 10)); attempt=$((attempt + 1)); done; attempt=1; until az storage blob download --auth-mode login --account-name "$RUN_STORE_ACCOUNT" --container-name "$RUN_STORE_CONTAINER" --only-show-errors -o none --name "$RUN_STORE_PREFIX$RUN_ID/in" --file "/work/in"; do [ "$attempt" -lt 5 ] || exit 1; sleep $((attempt * 10)); attempt=$((attempt + 1)); done; attempt=1; until az storage blob download --auth-mode login --account-name "$RUN_STORE_ACCOUNT" --container-name "$RUN_STORE_CONTAINER" --only-show-errors -o none --name "$RUN_STORE_PREFIX$RUN_ID/ca-bundle.pem" --file "/work/ca-bundle.pem"; do [ "$attempt" -lt 5 ] || exit 1; sleep $((attempt * 10)); attempt=$((attempt + 1)); done\u0027; then : \u003e /work/.copied-in; else : \u003e /work/.abandoned; exit 1; fi',
    copy_out_script='waited=0; until [ -e /work/.client-done ]; do if [ -e /work/.abandoned ] || [ "$waited" -ge 2210 ]; then : \u003e /work/.abandoned; echo \u0027copy-out did not start: the step before it failed or did not finish within 2210 seconds\u0027 \u003e\u00262; exit 1; fi; sleep 1; waited=$((waited + 1)); done; timeout 300 sh -c \u0027set -eu; case "${RUN_ID:-}" in ""|.*|*[!A-Za-z0-9._-]*) echo "RUN_ID must name the run: letters, digits, \u0027"\u0027"\u0027.\u0027"\u0027"\u0027, \u0027"\u0027"\u0027_\u0027"\u0027"\u0027 and \u0027"\u0027"\u0027-\u0027"\u0027"\u0027, not starting with \u0027"\u0027"\u0027.\u0027"\u0027"\u0027" \u003e\u00262; exit 2;; esac; attempt=1; until az login --identity --resource-id "$SCHEMA_IDENTITY_ID" --allow-no-subscriptions --only-show-errors -o none; do [ "$attempt" -lt 5 ] || exit 1; sleep $((attempt * 10)); attempt=$((attempt + 1)); done; attempt=1; until refused=$(az storage blob upload --auth-mode login --account-name "$RUN_STORE_ACCOUNT" --container-name "$RUN_STORE_CONTAINER" --only-show-errors -o none --name "$RUN_STORE_PREFIX$RUN_ID/out" --file "/work/out" --overwrite false 2\u003e\u00261); do printf \u0027"\u0027"\u0027%s\\n\u0027"\u0027"\u0027 "$refused" \u003e\u00262; case "$refused" in *BlobAlreadyExists*) [ "$attempt" -gt 1 ] \u0026\u0026 break; exit 1;; esac; [ "$attempt" -lt 5 ] || exit 1; sleep $((attempt * 10)); attempt=$((attempt + 1)); done; attempt=1; until refused=$(az storage blob upload --auth-mode login --account-name "$RUN_STORE_ACCOUNT" --container-name "$RUN_STORE_CONTAINER" --only-show-errors -o none --name "$RUN_STORE_PREFIX$RUN_ID/err" --file "/work/err" --overwrite false 2\u003e\u00261); do printf \u0027"\u0027"\u0027%s\\n\u0027"\u0027"\u0027 "$refused" \u003e\u00262; case "$refused" in *BlobAlreadyExists*) [ "$attempt" -gt 1 ] \u0026\u0026 break; exit 1;; esac; [ "$attempt" -lt 5 ] || exit 1; sleep $((attempt * 10)); attempt=$((attempt + 1)); done; attempt=1; until refused=$(az storage blob upload --auth-mode login --account-name "$RUN_STORE_ACCOUNT" --container-name "$RUN_STORE_CONTAINER" --only-show-errors -o none --name "$RUN_STORE_PREFIX$RUN_ID/exit" --file "/work/exit" --overwrite false 2\u003e\u00261); do printf \u0027"\u0027"\u0027%s\\n\u0027"\u0027"\u0027 "$refused" \u003e\u00262; case "$refused" in *BlobAlreadyExists*) [ "$attempt" -gt 1 ] \u0026\u0026 break; exit 1;; esac; [ "$attempt" -lt 5 ] || exit 1; sleep $((attempt * 10)); attempt=$((attempt + 1)); done\u0027',
    ca_bundle_file="ca-bundle.pem",
)
#: The roots the run's CA bundle holds, each fetched over verified HTTPS.
SCHEMA_CA_BUNDLE_URLS: tuple[str, ...] = (
    "https://cacerts.digicert.com/DigiCertGlobalRootG2.crt.pem",
    "https://cacerts.digicert.com/DigiCertGlobalRootCA.crt.pem",
    "https://www.microsoft.com/pkiops/certs/Microsoft%20RSA%20Root%20Certificate%20Authority%202017.crt",
    "https://www.microsoft.com/pkiops/certs/Microsoft%20ECC%20Root%20Certificate%20Authority%202017.crt",
)
#: This deployment's value of the runs' group tag: what the sweep selects by.
SCHEMA_RUN_APP_TAG = "helpdesk-system-dev"
#: The longest the deploy waits for one run's group: the kernel's run timings and the bounded
#: re-sends of what the group's containers ask the identity endpoint for.
SCHEMA_RUN_GROUP_WAIT_SECONDS: int = 2510
#: The deployment the run store is deployed as, and what a run's place is read back by.
RUN_STORE = RunStoreDeployment(
    name="run-store",
    account_output="storageAccountName",
    container_output="containerName",
    identities_output="schemaIdentities",
    location_parameter="location",
    subnet_parameter="schemaRunSubnetId",
    registry_parameter="containerRegistryName",
    registry_server_output="registryLoginServer",
)
#: The run store as this command reaches it, made on first use: one session for every run.
_SCHEMA_RUN_SESSIONS: list[RunStoreSession] = []
_SCHEMA_RUN_SESSION_LOCK = threading.Lock()


def schema_run_session() -> RunStoreSession:
    """The command's run store session: read back and swept once, before its first run."""
    with _SCHEMA_RUN_SESSION_LOCK:
        if not _SCHEMA_RUN_SESSIONS:
            _SCHEMA_RUN_SESSIONS.append(
                RunStoreSession(
                    RUN_STORE,
                    resource_group=SETTINGS.resource_group,
                    app_tag=SCHEMA_RUN_APP_TAG,
                    az=_schema_az,
                    failure=DeployError,
                )
            )
        return _SCHEMA_RUN_SESSIONS[0]


#: The images of this command's runs, imported on first use: each image once per command.
_SCHEMA_RUN_IMAGE_IMPORTS: list[RunImageImports] = []
#: Its own lock: making the imports reads the session, which takes the session's lock.
_SCHEMA_RUN_IMAGE_IMPORTS_LOCK = threading.Lock()


def schema_run_image_imports() -> RunImageImports:
    """The command's image imports: each image of its runs imported into the session's
    registry once, a source registry's rate limit waited out (``run_image_import_runtime``)."""
    with _SCHEMA_RUN_IMAGE_IMPORTS_LOCK:
        if not _SCHEMA_RUN_IMAGE_IMPORTS:
            _SCHEMA_RUN_IMAGE_IMPORTS.append(
                RunImageImports(
                    registry=schema_run_session().registry,
                    az=_schema_az,
                    failure=DeployError,
                    retry=RunRetry(is_transient_run_az_failure, time.sleep),
                )
            )
        return _SCHEMA_RUN_IMAGE_IMPORTS[0]


def is_transient_run_az_failure(output: str) -> bool:
    """Whether a failed request of a container-group run is safe and worth sending again.

    A resource provider's own 5xx -- as ``az rest`` reports it, by ARM's code, or by ARM's
    message -- or az's own connection to Azure dropping: Azure, not the run, failed.
    """
    return (
        is_az_rest_server_fault(output)
        or carries_arm_server_fault_code(output)
        or is_arm_server_fault_message(output)
        or is_az_transport_failure(output)
    )


def run_group_concurrent_runs() -> int:
    """How many container-group runs this command carries at once (``run_group_concurrency``)."""
    return schema_run_session().concurrent_runs()


#: The project's schema tool, relative to the project root.
SCHEMA_TOOL_SCRIPT = "scripts/schema/schema.py"


def run_project_schema_tool(arguments: Sequence[str]) -> SchemaToolRun:
    """Run one command of this project's schema tool."""
    return run_schema_tool(PROJECT_ROOT / SCHEMA_TOOL_SCRIPT, arguments)


def _schema_az(arguments: Sequence[str]) -> AzRun:
    """Run one ``az`` invocation of a run and return what it left."""
    result = az(*arguments)
    return AzRun(result.returncode, result.stdout, result.stderr)


def _fetch_schema_ca_bundle(destination: Path) -> None:
    """Fetch the run's CA bundle over verified HTTPS into *destination*."""
    fetch_ca_bundle(SCHEMA_CA_BUNDLE_URLS, destination, DeployError)


def container_group_schema_channel(verb: str) -> SchemaChannel:
    """The channel running a run's catalog client once, in a container group of its own.

    *verb* names the schema verb the runs carry out and, with each run's id, the
    run's container group. The command's run store session deletes the finished
    groups of earlier deploys before its first run; the input and the CA bundle
    go up to the run's prefix of the run store, the group runs the client under
    ``timeout`` and is deleted after it, and the client's standard output,
    standard error and exit status come back as files. No file's content travels
    as an argument, and every file of the run is deleted from the run store.
    Several blocks' runs are carried out side by side, each from its own thread.
    """

    def run_group(schema_run: SchemaRun) -> None:
        """Carry out *schema_run* in a container group named for *verb*.

        Raises:
            DeployError: If the run could not be carried out, or its files could
                not be deleted after a run that was.
        """
        block = SCHEMA_RUN_BLOCKS[schema_run.block]
        container_group_run(
            schema_run,
            verb=verb,
            workload=SCHEMA_RUN_WORKLOAD,
            client=block.client,
            place=schema_run_session().block_place(block),
            import_images=schema_run_image_imports().import_images,
            az=_schema_az,
            failure=DeployError,
            fetch_ca_bundle=_fetch_schema_ca_bundle,
            wait_seconds=SCHEMA_RUN_GROUP_WAIT_SECONDS,
            transient=is_transient_run_az_failure,
        )

    return run_group


def command_schema_read(block: str) -> None:
    """Print *block*'s verified live catalog on standard output, and nothing else.

    Raises:
        DeployError: If the read could not be carried out or the schema tool
            refused what the client returned, naming the cause.
    """
    schema_read(
        block,
        schema_tool=run_project_schema_tool,
        channel=container_group_schema_channel(VERB_SCHEMA_READ),
        failure=DeployError,
    )


def command_schema_apply(block: str, sql_file: str) -> None:
    """Apply *sql_file*, one of *block*'s plan files, and print the catalog it left.

    The schema tool refuses a file that is not one of the block's plan files;
    the file runs in one transaction as the block's owner login, in a container
    group of its own as a read runs, and a catalog changed since its plan stops
    it before any change.

    Raises:
        DeployError: If the file was refused, the apply failed (naming the
            statement and change it stopped at) or its output was not verified.
    """
    schema_apply(
        block,
        sql_file,
        schema_tool=run_project_schema_tool,
        channel=container_group_schema_channel(VERB_SCHEMA_APPLY),
        failure=DeployError,
    )


# ---------------------------------------------------------------------------
# Command line
# ---------------------------------------------------------------------------

#: Commands this platform adds beyond the shared lifecycle vocabulary. Each is
#: a stage of `deploy` exposed on its own, or a read-only probe -- not a
#: lifecycle state -- so --help lists them apart from the shared verbs.
PLATFORM_COMMANDS: dict[str, str] = {
    "canary": (
        "provision the full infrastructure minus API Management, to prove "
        "deployability fast."
    ),
    "code": (
        "deliver changed application code without re-running any "
        "infrastructure stage, guarded by an infrastructure-content-hash stamp."
    ),
    "verify": (
        "probe every already-deployed app's health without deploying "
        "anything -- the same check 'deploy' and 'code' run at their own tail."
    ),
}

#: 'deploy' takes the command line's approval or its client request and is dispatched
#: by main() directly; its entry here is for the coverage check alone, and a call
#: through this table, carrying neither, fails rather than deploys.
COMMANDS: dict[str, Callable[..., None]] = {
    VERB_DEPLOY: command_deploy,
    VERB_DOWN: command_down,
    VERB_DESTROY: command_destroy,
    "canary": command_canary,
    "code": command_code,
    "verify": command_verify,
}

#: This deployment's schema verbs, bound to their implementations, each taking
#: the block it acts on and then the verb's SCHEMA_VERB_OPERANDS. The keys are
#: exactly SCHEMA_VERBS, proved alongside.
SCHEMA_COMMANDS: dict[str, Callable[..., None]] = {
    VERB_SCHEMA_READ: command_schema_read,
    VERB_SCHEMA_APPLY: command_schema_apply,
}

#: Whether 'deploy' takes its schema flags to the plan below (``deploy --plan``):
#: exactly when the parser declares them, which ``require_command_coverage``
#: proves on every run, so a flag the parser accepts always reaches the plan.
DEPLOY_PLANS: bool = True

#: The blocks 'deploy --plan' plans, by their block keys: every block, or none
#: when this profile's migrations are disabled, since a deploy then changes no
#: schema.
PLAN_BLOCKS: tuple[str, ...] = (
    "helpdesk-ticket-service.ticket-db",
    "helpdesk-knowledge-service.knowledge-db",
    "helpdesk-notice-service.notice-db",
    "helpdesk-email-mock.email-db",
)


def require_command_coverage() -> None:
    """Fail loud unless every accepted command, flag and block has an implementation, and vice versa.

    The parser's choice set and the dispatch tables are two sides of one seam:
    argparse decides what is accepted, ``COMMANDS`` and ``SCHEMA_COMMANDS``
    decide what happens, and ``SCHEMA_RUN_BLOCKS`` how a block is reached. A
    command or block in one and not the other is a KeyError at the worst
    possible moment -- after an operator confirmed a destructive command -- or
    one that quietly cannot be reached at all. The schema flags of 'deploy'
    the parser takes (SCHEMA_DEPLOY_FLAGS) are declared exactly when the
    deploy dispatch plans (DEPLOY_PLANS), and every block it plans has a run.

    Raises:
        DeployError: If the sets differ, naming what is on each side.
    """
    accepted = set(REALIZED_VERBS) | set(PLATFORM_COMMANDS) | set(SCHEMA_VERBS)
    implemented = set(COMMANDS) | set(SCHEMA_COMMANDS)
    blocks = set(SCHEMA_BLOCKS)
    reached = set(SCHEMA_RUN_BLOCKS)
    declared_flags = set(SCHEMA_DEPLOY_FLAGS)
    planned = set(PLAN_BLOCKS)
    if (
        accepted == implemented
        and blocks == reached
        and bool(declared_flags) == DEPLOY_PLANS
        and planned <= reached
    ):
        return
    raise DeployError(
        f"This script accepts {sorted(accepted)} but implements "
        f"{sorted(implemented)}. Accepted-but-missing: "
        f"{sorted(accepted - implemented)}; implemented-but-unreachable: "
        f"{sorted(implemented - accepted)}. Blocks accepted without a run: "
        f"{sorted(blocks - reached)}; runs of no accepted block: "
        f"{sorted(reached - blocks)}. Deploy flags accepted: "
        f"{sorted(declared_flags)}, while the deploy dispatch "
        f"{'plans' if DEPLOY_PLANS else 'plans nothing'}; blocks planned without "
        f"a run: {sorted(planned - reached)}. This is a generator defect, not "
        f"something to work around here -- regenerate the project."
    )


def build_parser() -> argparse.ArgumentParser:
    """Build the command-line parser.

    The command positional, ``--force``, the PowerShell switch translation and
    the command listing come from the shared lifecycle preamble, so this CLI's
    surface cannot drift from every other CruftFree-generated deployment CLI's.
    Only this platform's own flags and environment overrides are added here.
    """
    parser = build_lifecycle_parser(
        f"Manage the {APP_NAME} Azure deployment.",
        PLATFORM_COMMANDS,
        extra_epilog=(
            "Environment overrides:\n"
            f"  RESOURCE_GROUP         Target resource group (default: "
            f"{DEFAULT_RESOURCE_GROUP})\n"
            f"  LOCATION               Azure region (default: {DEFAULT_LOCATION})\n"
            f"  ENVIRONMENT            Resource suffix / bicepparam selection; "
            f"must be {DEFAULT_ENVIRONMENT}, the label this project was "
            f"generated for\n"
            "  FORCE=true             Same as --force\n"
            "  NO_PURGE=true          Same as --no-purge\n"
            "  TURBO_SCALE=true       Same as --turbo-scale\n"
            "  DEPLOY_BUILD_DIR       Staging directory for the code-push phase\n"
            f"  DEPLOY_WEB_WAVE        Concurrent web-app pushes (default: "
            f"{DEFAULT_WEB_WAVE_SIZE})\n"
            f"  DEPLOY_FUNCTION_WAVE   Concurrent Function App pushes (default: "
            f"{DEFAULT_FUNCTION_WAVE_SIZE})\n"
            f"  DEPLOY_IMAGE_WAVE      Concurrent container image resolutions "
            f"(default: {DEFAULT_IMAGE_WAVE_SIZE})\n"
            f"  DEPLOY_LOG_DIR         Transcript directory (default: "
            f"{PROJECT_ROOT / TRANSCRIPT_LOG_DIRNAME})\n"
            f"  VERIFY_APP_TIMEOUT_SECONDS  Seconds 'verify' waits for one app "
            f"to become healthy (default: {DEFAULT_VERIFY_APP_TIMEOUT_SECONDS})\n"
            "\n"
            "--force on this platform:\n"
            "  Besides skipping a destructive command's confirmation, it makes\n"
            "  'deploy' redeploy every service, including one whose content\n"
            "  hash is unchanged.\n"
        ),
    )
    parser.add_argument(
        "--no-purge",
        action="store_true",
        help=(
            "deploy/canary: report blocking soft-deleted name collisions with "
            "purge and recover guidance instead of purging them automatically."
        ),
    )
    parser.add_argument(
        "--turbo-scale",
        action="store_true",
        help=(
            "deploy: temporarily scale the shared App Service plan up to "
            f"{TURBO_SCALE_SKU} for the code-push phase, restoring the original "
            "SKU afterward. Off by default: sites on the plan restart when the "
            "SKU changes, and this changes what the plan bills while scaled up."
        ),
    )
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    """Entry point: parse arguments, run the requested command, report failures.

    Every run -- success or failure -- opens a transcript before doing
    anything else and closes it after everything else is done, so a login
    failure, an argument-parsing success followed by a mid-run crash, and a
    clean exit are all captured identically.

    ``deploy --plan`` reads every block in PLAN_BLOCKS and prints the plan a
    deploy would apply to it, and does nothing else: no preflight, no
    infrastructure stage, no code push, no schema changed. ``deploy``
    converges every block in PLAN_BLOCKS around the release. Approval is the
    command line's ``--approved`` alone, handed to the deploy command
    directly; a call through ``COMMANDS`` never carries it.

    Returns:
        Process exit code -- 0 on success, 1 on any operator-actionable
        failure, 130 on an interrupt.
    """
    global SETTINGS
    try:
        require_command_coverage()
    except DeployError as error:
        print(f"ERROR: {error}", file=sys.stderr)
        return 1
    arguments = build_parser().parse_args(
        normalize_argv(list(sys.argv[1:] if argv is None else argv))
    )
    # A schema verb's standard output is its document alone, and 'deploy --plan''s its
    # plans: progress goes to stderr.
    OUTPUT.progress_to_stderr = arguments.command in SCHEMA_COMMANDS or arguments.plan
    sink_path = _open_transcript_sink(arguments.command)
    if sink_path is not None:
        note(f"Transcript: {sink_path}")
    try:
        SETTINGS = Settings.from_environment()
        require_generated_environment(SETTINGS.environment)
        SETTINGS.force = SETTINGS.force or arguments.force
        SETTINGS.no_purge = SETTINGS.no_purge or arguments.no_purge
        SETTINGS.turbo_scale = SETTINGS.turbo_scale or arguments.turbo_scale
        require_azure_login()
        if arguments.plan:
            plan_schema_blocks(
                PLAN_BLOCKS,
                arguments.approved,
                concurrent_runs=run_group_concurrent_runs,
                schema_tool=run_project_schema_tool,
                channel=container_group_schema_channel(VERB_SCHEMA_READ),
                failure=DeployError,
            )
        elif arguments.command == VERB_DEPLOY:
            command_deploy(arguments.approved, client_request(arguments))
        elif arguments.command == VERB_DOWN:
            command_down(arguments.scope)
        elif arguments.command in SCHEMA_COMMANDS:
            SCHEMA_COMMANDS[arguments.command](
                arguments.block,
                *(
                    getattr(arguments, operand)
                    for operand in SCHEMA_VERB_OPERANDS[arguments.command]
                ),
            )
        else:
            COMMANDS[arguments.command]()
    except DeployError as error:
        message = f"ERROR: {error}"
        print(message, file=sys.stderr)
        _write_to_sink(message)
        return 1
    except KeyboardInterrupt:
        message = "Interrupted."
        print(f"\n{message}", file=sys.stderr)
        _write_to_sink(message)
        return 130
    finally:
        _close_transcript_sink()
        if sink_path is not None:
            note(f"Transcript: {sink_path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
